export const approvedMnemonicRecords = {"3":{"word":"abash","mnemonics":[{"method":"abash / a blush","textZh":"把 abash 的形音联到 a blush（一阵脸红）：本来很自信的人，被指出一个明显错误，立刻不好意思地红了脸。由“让人窘得脸红”记“使尴尬”。","original":true,"kind":"invented_association","weak":false},{"method":"abash / a bash","textZh":"把 abash 近音联到 a bash（一记重击）：当众一句尖锐的纠正，像一记重击打掉了自信，让人窘得抬不起头。由“给自信一击，使人羞窘”，记 abash。","weak":false}]},"153":{"word":"aspersion","mnemonics":[{"method":"A + SPERS + ION · 向人喷脏水","textZh":"SPERS 连到 spray（喷洒），a- 表示“向”，-ion 把动作变成名词：向别人的名声喷脏水，就是散布恶意诋毁。","original":false,"weak":false,"kind":"reviewed mnemonic"},{"method":"ASS + PERSON · 恶意丑化别人","textZh":"ass 是“笨蛋”，person 是“人”：把一个能干的人恶意说成笨蛋，让别人看不起他。aspersion 就是这种损害名声的诋毁。","original":false,"weak":false,"kind":"reviewed mnemonic"}]},"175":{"word":"avarice","mnemonics":[{"method":"拼写联想｜avaRICE，米仓满了还要抢","textZh":"抓住词尾 RICE（米）：米商的仓库已经塞满，他还把别人待售的米袋往怀里抢，眼里想的全是钱。米越囤越多，贪心没有尽头。","original":false,"kind":"invented_association"}]},"197":{"word":"banal","mnemonics":[{"method":"BAN ALL · 新点子全被禁","textZh":"把整个词联想到 ban all（全部禁止）：策划会上，负责人把所有新点子都禁掉，只许照搬往年方案，结果陈腐乏味。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"PANEL → BANAL · 又是老一套","textZh":"banal 联到 panel（讨论小组）：几位嘉宾轮流发言，却都在重复去年同一套套话，听众闭着眼都猜得出下一句。这个毫无新意的 panel，让人记住 banal 的陈腐乏味。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"199":{"word":"banish","mnemonics":[{"method":"BAN + ISH · 禁令驱逐","textZh":"ban 是“禁止、禁令”；banish 的历史与 ban 相连，来自表示宣布驱逐的法语动词。把 BAN 接到本词的动词尾部 -ish：国王宣布禁令，不准某人再留在王国，于是命令他离开。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"VANISH → BANISH · 被迫离开","textZh":"vanish 是“消失”，ban 是“禁令”：国王下禁令，把一个人赶出王国，从此再也看不到他的身影。被强制赶走后消失在眼前，便把 vanish 连到 banish。","original":false,"weak":false,"kind":"root reviewed; private production"}]},"200":{"word":"banter","mnemonics":[{"method":"BANNER → BANTER · 横幅逗笑朋友","textZh":"banter 联到 banner（横幅）：朋友生日时，大家挂上一条善意逗趣的横幅，寿星看后笑着回敬一句，大家又接着打趣。横幅引出的有来有回的玩笑，就是 banter。","original":true,"weak":false,"kind":"root reviewed; private production"},{"method":"ban tears · 用笑话赶走眼泪","textZh":"想象两个朋友约好 ban tears（不许掉眼泪），于是轮流开善意的玩笑，一个接一个地逗笑对方。用双方轻松接话的画面记“友好打趣”。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"204":{"word":"bargain","mnemonics":[{"method":"BAR + GAIN · 拦住额外获利","textZh":"按完整拼写拆成 BAR + GAIN：bar 可表示“阻止”，gain 是“获利”。想买家不愿让卖家多赚那一截，于是提出较低价格，卖家再还价，双方讨价还价。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"bark in · 小狗加入还价","textZh":"想象集市上的会说话的小狗忽然 bark in（汪汪叫着加入）：买家报低价，小狗替摊主叫出另一个价，加入一来一往的还价。bark 是狗叫，in 表示进入这个场面。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"214":{"word":"belabor","mnemonics":[{"method":"BE + LABOR · 在同一点上苦干","textZh":"labor 是“劳动、费力工作”，如 Labor Day（劳动节）。belabor 确实由 be- 与 labor 构成；be- 在这里加强动作。想讲解者在同一个已经明白的要点上不停“下工夫”，越说越重复，就从“过度费力处理”记到“反复赘述”。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"B label · 标签讲个没完","textZh":"label 是“标签”。想一个盒子贴着清楚的 B label（B 标签），大家早已看懂，讲解者却一遍遍重说“这是 B，不是别的字母”。用这张被反复解释的标签记“说得过多”。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"219":{"word":"benign","mnemonics":[{"method":"BEN + IGN · 温厚的天性","textZh":"ben- 的“好”可联到 benefit（好处）；-ign 背后的古老词根涉及出生，与 gene（基因）的词源家族相通。拉丁语 benignus 的古义可理解为“生性良善”。用这条历史线索把完整 BEN + IGN 想成一个天性温厚、待人和善的人。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"BE NICE · 温和一点","textZh":"benign 联到 be nice（友善一点）：孩子不小心碰倒积木，爷爷仍微笑着安抚他，温和地陪他重新搭好。用这份和善的态度记住 benign。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"231":{"word":"blemish","mnemonics":[{"method":"blame-ish · 值得指责的小错","textZh":"blame 是“责备”，熟悉的 -ish 可表达“有点……”。把 blemish 联想到 blame-ish：一个本来表现很好的人出现一次值得指责的失误，让良好记录留下污点。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"BLEED + MISS · 失手留下血点","textZh":"blemish 联到 bleed（流血）和 miss（没对准）：裁缝缝白布时没对准，针扎到手，渗出的血在干净的布上留下一点污迹。把 bleed、miss 连到这处破坏洁净外观的小污点。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"237":{"word":"blunt","mnemonics":[{"method":"BLOND → BLUNT · 金发剪不动","textZh":"blunt 联到 blond（金色头发）：理发师要剪一绺金发，剪刀却钝得只会夹住头发，怎么也剪不断。看到这把剪不动 blond hair 的剪刀，记住 blunt 的“钝的”。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"BLANK → BLUNT · 直说到人发愣","textZh":"blunt 联到 blank（空白的、茫然的）：朋友问演出怎么样，他直接说“很难看，我没看完”，对方一下愣住，脸上只剩 blank look。用让人发愣的直白回答，记住 blunt 的“直言不讳、欠委婉”。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"313":{"word":"castigate","mnemonics":[{"method":"CAST + I + GATE · 门前挨训","textZh":"cast 是扔，I 是我，gate 是大门。想象我把垃圾扔在邻居的大门前，邻居当面严厉斥责：“怎么能往这里乱扔垃圾！”整幅门前挨训的画面带出 castigate。","original":false,"weak":false,"kind":"root exact-text reviewed; private only"},{"method":"INVESTIGATE → CASTIGATE · 查清后严厉批评","textZh":"看到 castigate 的 STIGATE，连回整个 investigate（调查）：记者调查发现有人伪造数据，查清后立即在报道中严厉批评。从“查明事实”走到“严厉斥责”，把两件连贯的事记在一起。","original":true,"weak":false,"kind":"root exact-text reviewed; private only"}]},"324":{"word":"censor","mnemonics":[{"method":"SENSOR → CENSOR · 检出后剪掉","textZh":"sensor（感应器）会发现异常，把开头换成 cut（剪掉）的 C，得到 censor。想象一台内容检查器逐页扫描稿件，发现禁发内容就剪去，再把余下的稿子交出去：它在审查删禁。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SEND SIR · 稿件先送审","textZh":"看到 censor，联到 send（送出）和 sir（先生）：稿件先送到一位严肃的审查先生桌上，他逐段检查，把不准公开的部分涂黑后才放行。censor 连着这个人，也连着他审查删禁的动作。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"350":{"word":"circuitous","mnemonics":[{"method":"CIRCUIT + OUS · 电路绕行","textZh":"circuitous 中完整的 circuit（电路）带你看一条电线：两个接点很近，电线却绕着零件走了好几弯。接上形容词尾 OUS，这种不直达、绕着走的路径就是 circuitous。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SIR, QUEUE WITH US","textZh":"“Sir, queue with us!”（先生，跟我们排队吧！）柜台近在眼前，队伍却绕过一排排货架，兜了几大圈才到窗口。把 circuitous 连到这句邀请，记住这条迂回曲折的路线。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"353":{"word":"circumspect","mnemonics":[{"method":"CIRCLE + INSPECT","textZh":"看到 circumspect，联到 circle（一圈）和 inspect（检查）：行动前先环顾一圈，检查周围条件和可能后果，再稳妥地迈出下一步。四周看清再行动，就是审慎周到。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SIR + COMES + PACKED","textZh":"先生（sir）来了（comes），包里已经装好（packed）雨伞和手电：他出门前就想过可能下雨、天黑。把 circumspect 连到这位周全准备再出门的先生，记住行动前考虑风险、做事审慎。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"355":{"word":"civility","mnemonics":[{"method":"CIVIL + ITY","textZh":"civil 是“有礼貌的”，连到熟悉的文明交往：先说“请”，得到帮助后说“谢谢”。接上表示性质的 ITY，civility 就是这种体现在言语和行动里的礼貌。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SEE VILLA TEA","textZh":"把 civility 连到 see、villa、tea：看见一栋 villa（别墅），主人走到门前欢迎你，请你入座，再客气地递上 tea（茶）。整套迎客礼节，让你记住 civility 的礼貌、周到。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"368":{"word":"clumsy","mnemonics":[{"method":"PLUMS + Y → CLUMSY","textZh":"clumsy 联到 plums（李子）：他拿着一堆李子，却因为 careless（粗心）手忙脚乱，一个也没接稳。把 PLUMS 的 P 换成 C，再添形容词尾 Y，记住这次笨拙的动作。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"COME SEE · 松动的椅腿","textZh":"“Come see!（来看看！）”他得意地招呼别人看新做的椅子，可一碰，loose leg（松动的椅腿）就晃来晃去，人根本坐不稳。喊人来看却露出松腿，带出 clumsy 的做工笨拙、不够精巧。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"370":{"word":"coalesce","mnemonics":[{"method":"CO + A LACE","textZh":"把 coalesce 连到 co（一起）和 a lace（一根鞋带）：原来分开的几个部件，用同一根鞋带联结成一个完整装置。分开的部分合到一起，成为一个整体，就是 coalesce。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"COAL + LESS","textZh":"coalesce 联到 coal（煤）和 less（更少）：原来分散的煤粒压合成一个整块，独立的块数变少了。记住“许多分散的小块，合成一个整体”的变化。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"378":{"word":"collude","mnemonics":[{"method":"CONCLUDE → COLLUDE","textZh":"conclude an agreement 是“达成协议”：两人关起门来达成一个秘密约定，要一起隐瞒事实。把完整的 conclude 连到 collude，记住这种为欺骗而暗中合作的“协议”。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CALL + DUDE","textZh":"call（打电话）给一个 dude（伙计）：他悄悄打给同伴，两人在电话里约好一起作弊，还商量不要让别人知道。把 collude 连到这通私下串通的电话，记住暗中勾结、共同做不正当的事。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"2747":{"word":"baffle","mnemonics":[{"method":"BATTLE → BAFFLE · 假信息搅乱战局","textZh":"battle（战斗）里混进 false facts（假信息）：桌面战斗游戏中，双方收到相互矛盾的假情报，越看越糊涂，完全弄不清战局。这场让人困惑的 battle，把 baffle 的意思带出来。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"bag full · 满袋拼片难住人","textZh":"把完整词的声音联想到 bag full（袋子满满的）：男孩倒出一袋混在一起的拼图片，试来试去都对不上，完全弄不清该怎么拼。bag /bæɡ/ 是袋子，full /fʊl/ 是满的。用满袋难以理清的拼片记“使困惑”。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"2755":{"word":"belligerent","mnemonics":[{"method":"BELLI + GER + ENT · 挑衅的手势","textZh":"belli- 的“战争”与 rebel（反叛者）里的 bel 同源；ger- 的“进行、承担”与 gesture（手势）背后的动作词根同源，-ent 是形容词结尾。想一个反叛者不断做出挑衅手势，把冲突主动带起来：完整 BELLI + GER + ENT 从“进行战争的”记到“好斗的”。手势是帮助理解词根的画面。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"BELL + I GET RENT · 凶横收租","textZh":"bell 是门铃，I get rent 是“我收租金”。想象房东猛按门铃，门刚开就挥着拳头叫嚷收租，不肯好好商量。bell、I get rent 连起这位动辄挑衅、准备吵架的房东，记住 belligerent 的好斗。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4943":{"word":"available","mnemonics":[{"method":"AVAIL + ABLE · 能用得上","textZh":"从熟悉的 value（价值、用处）搭桥：avail 与 value 的历史都可追溯到表示“有力量、有价值”的拉丁词。avail 表示“有用、起作用”，加 -able 形成 available。想一件有实用价值的工具，现在就在手边、允许取用，才真正能用得上。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"a whale, a bull · 两只玩具可借","textZh":"联想完整的 a whale, a bull（一只鲸鱼、一头公牛）：玩具角里这两只动物玩具都空着，管理员说现在可以借。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4944":{"word":"avert","mnemonics":[{"method":"A + VERT · 把危险转开","textZh":"convert 是“转换”，如把厘米转换成米；它与 avert 共享表示“转”的历史词根 VERT。avert 的 A- 在历史上表示“离开”，合起来是“转开”：目光转向别处，或让危险偏离原本会发生的路线，于是避免坏事发生。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"a vet · 及时避险","textZh":"联想完整的 a vet（一位兽医）：兽医看到宠物旁散落着玩具小零件，提醒主人收好，及时避免了误吞的意外。用这位提前发现危险的兽医，记“防止坏事发生”。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4945":{"word":"balanced","mnemonics":[{"method":"BALANCE + D · 天平不偏","textZh":"balance 可以指“天平、平衡”，balanced 是 balance 加 -d。想象把一件作品的优点与缺点都放上天平，认真衡量，不只盯着一边，于是形成 balanced assessment。由物理上的平稳，搭到评价上的公正全面。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"BALL DANCED · 球也能稳稳跳舞","textZh":"balanced 联到 ball danced（球跳起了舞）：童话里，一只球在细细的栏杆上跳舞，向左向右都能稳住，不会跌下。用这段稳稳的舞步记住“保持平衡的”。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4946":{"word":"balk at","mnemonics":[{"method":"WALK AT → BALK AT · 走近又退缩","textZh":"walk（走）到报名柜台，看见高得离谱的费用，立刻 back（往后退），不肯接受。由“走近又退缩”想到 balk at the cost：因为费用而打退堂鼓。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"Ball, cat! · 猫不肯追","textZh":"想象主人举球喊“Ball, cat!”（球，猫咪！），可球滚进小水洼，猫看见要弄湿爪子就停住，不肯追：it balks at getting wet。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4947":{"word":"baneful","mnemonics":[{"method":"PAINFUL 的近音 · 危害造成痛苦","textZh":"从完整的 painful（痛苦的）听到 baneful：/ˈpeɪnfəl/ 与 /ˈbeɪnfəl/ 只差开头 /p/ 和 /b/。想象污染毁坏村里的水源，给居民带来严重损失和痛苦，污染的影响就是 baneful。这里用痛苦的后果帮助记“严重有害”。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"brain full · 装满恶意谣言","textZh":"联想完整的 brain full（脑子装满）：故事里的造谣者脑中装满恶意谣言，又四处传播，破坏了朋友间的信任，造成严重伤害。brain 是脑，full 是满。危害来自传播谣言的行为。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4948":{"word":"barrier","mnemonics":[{"method":"BAR → BARRIER · 栏杆拦路","textZh":"bar 可以是“横杆、栏杆”。barrier 与它有真实的历史联系：法语 barre 加名词词尾形成 barrière，再借入英语；整词保留双 r 和结尾 -ier。想一根横杆横在路上，把通道拦住，就从熟悉的 bar 记住完整的 barrier：阻止通行的障碍物。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"CARRIER → BARRIER · 运送车挡路","textZh":"carrier（运载工具）本来负责送货，却横停在窄路上，block（阻挡）了别人的去路。这辆运送车成了一道 barrier：阻止通行的障碍。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4949":{"word":"baseless","mnemonics":[{"method":"BASE + LESS · 没有支撑","textZh":"base 是“基础”，-less 表示“没有”。把完整 BASE + LESS 看成一座没有底座的纸房子，轻轻一碰就倒；再把“底座”换成事实证据：指责下面没有事实支撑，就是 baseless。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"FACELESS → BASELESS · 空口指责","textZh":"baseless 联到 faceless（不露面的）：一个不露脸的账号指责别人作弊，追问证据时却什么也拿不出来。把这个空口指责的匿名账号，连到 baseless 的“毫无根据”。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4950":{"word":"bedrock","mnemonics":[{"method":"BED + ROCK · 地下的岩石床","textZh":"bed 不仅是睡觉的床，也可指底层，rock 是岩石。完整 BED + ROCK 指松散表土下面的坚实岩层，像大地的“岩石床”。从这种底层支撑，转到抽象的根基：信任支撑友谊，便是 the bedrock of friendship。","original":false,"weak":false,"kind":"root reviewed; private production"},{"method":"bread rock · 硬面包当底座","textZh":"想象一块硬得像石头的面包，被孩子戏称为 bread rock；他把玩具小屋搭在这块硬面包上，面包成了整座小屋赖以站稳的根基。bread（面包）与 rock（石头）都很具体。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4951":{"word":"beguile","mnemonics":[{"method":"big lie · 甜话包着谎言","textZh":"联想完整的 big lie（大谎话）：摊主笑着许诺“一买就发财”，用动听说辞诱骗顾客。用包在甜话里的大谎言记“诱骗”。","original":true,"weak":false,"kind":"root reviewed; private production"},{"method":"BE + GUIDE · 导游甜言诱骗","textZh":"be a guide（当导游），嘴里却全是 lies（谎言）：一个人假扮导游，笑着描述根本不存在的美景，诱使游客买票。这位用动听谎话诱骗人的“导游”，带出 beguile。","original":true,"weak":false,"kind":"root reviewed; private production"}]},"4952":{"word":"beneficence","mnemonics":[{"method":"BENE + FIC + ENCE · 把好事做出来","textZh":"bene- 的“好”可用 benefit（好处）来记；fic 的“做、制造”与 factory（工厂）的词源相通，-ence 构成名词。想一间工厂专门做保暖毯，再把毯子捐给有需要的人：完整 BENE + FIC + ENCE 就是把好事真正做出来的行善。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"BENE + FINANCE · 资金转作慈善","textZh":"bene- 用 benefit（好处）提示，finance 是“资金、资助”。把 beneficence 联到一笔专门做好事的资金：为缺少生活物资的人买毯子、送食物，把帮助真正落实下来。用这笔行善的资助记 beneficence。","original":false,"weak":true,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4953":{"word":"benevolent","mnemonics":[{"method":"BENE + VOL + ENT · 愿意做好事","textZh":"bene- 的“好”用 benefit（好处）搭桥，vol 的“愿意”可联到 volunteer（志愿者）；它们各自的词源关系是真实的。加上形容词结尾 -ent，完整 BENE + VOL + ENT 表示怀有好意、愿意助人。想志愿者主动说“谁需要帮助都可以来”，便能记住这种仁善的态度。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"be · never · lent · 送出去不讨还","textZh":"用 be、never（从不）、lent（lend 的过去分词，借出）拼成近音提示，想好心人明确说：这些礼物是送的，从不当作借出的东西要求归还。慷慨赠予的场景提示“乐善好施”。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4954":{"word":"betoken","mnemonics":[{"method":"BE + TOKEN · 凭证代表一件事","textZh":"token 可以是具体的凭证或代币，也可以表示象征。想寄存行李后拿到一枚 token：它代表行李已存放在那里。betoken 与 token 有真实词源联系，be- 是构成动词的前缀。完整 BE + TOKEN 便可从“作为一个标志”记到“表示、预示”。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"be taken · 空挂钩留下迹象","textZh":"be taken 表示“被拿走”。想原本挂着外套的钩子空了：空钩成为外套已被拿走的迹象。要记的是“空钩表示拿走这件事”，从迹象连到所表示的情况。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4955":{"word":"bias","mnemonics":[{"method":"BI / AS · 一分与五分","textZh":"把完整 BIAS 暂分成 BI / AS：大写 I 像数字 1，S 像数字 5，于是看成“B 得 1 分，A 得 5 分”。想两份同样好的作品，却只因评委偏爱 A，就给 A 五分、B 一分。整词的字母和分组一起提示不公平的偏向。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"buy us · 想收买评委","textZh":"buy us 可以理解为“收买我们”。想一个虚构比赛的评委说：“你不能 buy us，让我们偏袒你。”在 us 弱读为 /əs/ 时，整句片段 buy us /baɪ əs/ 与 bias /ˈbaɪəs/ 很接近。用收买会扭曲公平判断的场景记“偏见、偏向”。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4956":{"word":"blameless","mnemonics":[{"method":"BLAME + LESS · 没有可责备之处","textZh":"blame 是“责备、过错”，-less 表示“没有”。完整 BLAME + LESS 就是没有应当责备的过错。想目击者确认杯子是猫碰倒的，读书的男孩并没有做错，因而是 blameless。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"FLAMELESS → BLAMELESS · 灯不是火源","textZh":"blameless 联到 flameless（无火焰的）：男孩一直拿着一盏无火焰的小灯，目击者确认窗帘是被另一处蜡烛点燃的。火灾不是男孩造成的，他没有应受责备的过错，就是 blameless。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4957":{"word":"blighted","mnemonics":[{"method":"DELIGHTED → BLIGHTED · 花园毁了","textZh":"blighted 联到 delighted（高兴的）：园丁昨天还为盛开的花园高兴，今天病害却使大片花草枯坏。原先的 delighted 被毁坏的花园打断，记住 blighted 的“遭严重损害的”。","original":false,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"},{"method":"BITE + LEAF · 叶片遭虫咬毁坏","textZh":"bite（咬）落在 leaf（叶片）上：一盆幼苗的叶子被虫咬得满是破洞，幼苗随后严重枯坏。由虫咬叶片的损害，想到 blighted 的“遭严重损害的”。","original":true,"weak":false,"kind":"screened candidate; root exact-text approval pending; private only"}]},"4971":{"word":"capture","mnemonics":[{"method":"CAP + TURE · 帽子里的照片","textZh":"把 capture 看成 cap（帽子）和 picture（图片）里熟悉的 TURE：一只小玩具虫钻进帽子，男孩用帽子罩住它，再拍下图片。帽子把目标抓住，图片把这一刻留住，一起带出 capture 的“捕获、记录”。","original":false,"weak":false,"kind":"root exact-text reviewed; private only"},{"method":"CATCH HER · 警察抓住她","textZh":"capture 联到“Catch her!（抓住她！）”：警察追上正在逃跑的女窃贼，把她控制住。用这声追捕中的喊话，记住 capture 的成功抓获。","original":true,"weak":false,"kind":"root exact-text reviewed; private only"}]},"4972":{"word":"catalyst","mnemonics":[{"method":"CAT A LIST · 一只猫带来一串行动","textZh":"由 catalyst 想到 cat、a list：一只流浪猫来到楼下，原本互不来往的邻居开始联系、安排照料、一起清理院子，形成一长串行动。猫的到来促成了大家的改变，是这次变化的 catalyst。","original":false,"weak":false,"kind":"root exact-text reviewed; private only"},{"method":"CATCH A LIFT · 搭上车后动起来","textZh":"把 catalyst 连到 catch a lift（搭便车）：志愿者迟迟到不了活动地点，一位司机主动让他们搭车，清理行动终于迅速展开。这个主动帮忙的人推动了整件事，成为行动的 catalyst。","original":true,"weak":true,"kind":"root exact-text reviewed; private only"}]},"4973":{"word":"cede to","mnemonics":[{"method":"CODE TO → CEDE TO · 门禁管理权交接","textZh":"cede to 联到 code（代码）和 to（给）：原管理者把门禁代码交给接任者，同时把谁能进门的决定权也交出去。从此由对方管理，记住 cede to 的“把权力让给”。","original":true,"weak":false,"kind":"root exact-text reviewed; private only"},{"method":"SEED TO · 把种子交给你","textZh":"cede to 连到 seed to：种子原本属于我，现在我把整包 seed（种子）和种什么、怎么种的决定权都交给你，to 指向你。从此由你拥有和决定，记住“让与”。","original":false,"weak":false,"kind":"root exact-text reviewed; private only"}]},"4974":{"word":"celebrate","mnemonics":[{"method":"CELEBRITY → CELEBRATE · 像明星一样被赞扬","textZh":"从 celebrity（明星、名人）想到站在聚光灯下接受赞誉的人。CELEBRITY 和 CELEBRATE 共有 CELEBR；想象大家像赞扬明星一样，公开称颂一位普通志愿者的贡献：celebrate 就是赞颂，也能指用活动庆祝。","original":false,"weak":false,"kind":"root exact-text reviewed; private only"},{"method":"SELL A BRAVE · 讲述英勇事迹","textZh":"由 celebrate 想到 sell a brave story（向大家推介一个勇敢的故事）：讲述者热情介绍一位救人英雄的经历，反复称赞他的勇气，观众也为他喝彩。整个“传播英勇故事、公开赞扬”的画面，带出 celebrate 的赞颂义。","original":true,"weak":false,"kind":"root exact-text reviewed; private only"}]},"4975":{"word":"celerity","mnemonics":[{"method":"CELER + ITY · 油门加速","textZh":"从 celerity 中完整的 CELER + ITY，联到 accelerate（加速）中同样的 CELER：脚踩油门，车开始加速；换成 ITY，就把“快”装成一个名词，记住行动的迅速。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CELEBRITY 减 B · 明星飞快出场","textZh":"把 celebrity（明星）里的 B 当作 brake（刹车），拿掉 B 就得到 celerity。想象舞台上的明星脱下拖慢步子的刹车鞋，迅速跑到台前：整段动作突出一个“快”。","original":false,"weak":false,"kind":"root exact-text approved; private only"}]},"4976":{"word":"centralize","mnemonics":[{"method":"CENTER → CENTRAL + IZE · 归到中心","textZh":"从熟悉的 center（中心）想到 central（中心的），再接 IZE，把“在中心”变成“集中起来”的动作。想象几处分散的办事桌都搬到中心，统一由这里管理，就是 centralize。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SENT REPLIES · 回复都归一处","textZh":"把 centralize 联到 sent replies（发来了回复）：各地分部的回复不再各自存放，全都送到同一间办公室，由同一团队汇总和安排。分散事务归到一个中心，记住“集中、统一管理”。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4977":{"word":"cerebral","mnemonics":[{"method":"CERE(BR)AL · 麦片里的大脑","textZh":"看到 cerebral，找到 cereal（早餐麦片）中间多出的 BR，联到 brain（大脑）。想象一盒大脑形状的麦片，盒上画着一道需要动脑推理的棋题：cerebral，重思考、重智力的。","original":false,"weak":false,"kind":"candidate; root exact-text approval pending; private only"},{"method":"Siri + BRILLIANT · 靠脑力解题","textZh":"Siri + brilliant：给 Siri 出一道逻辑题，它逐项分析条件、推导答案，你忍不住赞叹：‘Brilliant!’——cerebral，重理性思考、重智力的。","original":false,"weak":false,"kind":"ROOT_APPROVED; root exact-text reviewed; private only"}]},"4978":{"word":"challenging","mnemonics":[{"method":"CHALLENGE ACCEPTED → CHALLENGING","textZh":"看到 challenging，想到游戏中熟悉的“Challenge accepted!（接受挑战！）”：这一关不能轻松过，必须换策略、练技巧。challenge 带上 ING，正好描述眼前这个考验能力、需要努力的关卡。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CHA(LLE)NGING · 改变旧习惯","textZh":"把 challenging 连到熟悉的 changing（正在改变）：习惯了随手乱放东西的人，开始改变旧习惯，每天收好、归位，坚持下来并不轻松。changing 旧习惯，需要不断练习，所以这件事很 challenging，考验耐心和努力。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4979":{"word":"chaotic","mnemonics":[{"method":"CHAO + TIC · 吵成一团","textZh":"看到 chaotic 中的 CHAO，联到拼音“吵”；再把完整的 chaos 连到“吵死啦”：大家同时说话，安排谁也听不清，现场乱成一团。chaos 的 S 换成形容词尾 TIC，chaotic 就是形容这片混乱的。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"K.O. + TICK · 错乱的记分板","textZh":"chaotic 连到游戏里的 K.O.（击倒）和 tick（勾号）：记分板出了错，每个人名字旁都乱打着 K.O. 勾号，选手和裁判七嘴八舌，谁赢谁输全弄不清。这个失去秩序的场面就是 chaotic。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4980":{"word":"charity","mnemonics":[{"method":"CHAIR + TY · 捐椅收到谢谢","textZh":"从 charity 想到 chair（椅子）和 TY（thank you，谢谢）：把家里完好的椅子捐给缺少家具的人，对方真诚道谢。捐出的 CHAIR 和收到的 TY 连着这次无偿帮助，记住 charity。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CHERRY TEA · 一杯爱心茶","textZh":"charity 连到 cherry tea（樱桃茶）：社区把一杯杯热茶免费送给暂时缺少生活物资的人，让他们暖暖身子；茶和服务都是无偿提供的。这份帮助就是 charity。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4981":{"word":"chastise","mnemonics":[{"method":"CHESS TIES · 串通平局受斥责","textZh":"chastise 连到 chess ties（棋局平局）：两名棋手偷偷串通，事先约好平局来骗取比赛利益。裁判查明后严厉斥责他们破坏公平，这个斥责动作就是 chastise。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CHAT SIZE · 聊天越闹越大","textZh":"把 chastise 联到完整的 chat size（聊天规模）：老师正在讲解，一名学生拉着越来越多同学大声闲聊，几次提醒后仍故意打断课堂。老师终于严厉斥责这种干扰行为。聊天闹大后受到的斥责，连到 chastise。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4982":{"word":"cheerless","mnemonics":[{"method":"CHEER + LESS · 没了欢笑","textZh":"从熟悉的“Cheers!”想到 cheer（欢乐、欢呼），接上 less（没有）：晚会结束，欢笑声消失，只剩灰暗空荡的大厅。cheerless，就是少了欢乐和暖意、让人提不起精神的。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CHAIRLESS · 椅子搬空以后","textZh":"把 cheerless 连到 chairless（没有椅子）：曾经坐满朋友的屋子，如今人走了，椅子也全搬空，只剩冷冷的灰墙。这个空荡、没有欢乐的房间，让人想到 cheerless。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4983":{"word":"cherish","mnemonics":[{"method":"CHERRY + SH · 珍藏樱桃小礼物","textZh":"cherish 连到 cherry（樱桃）和轻轻的一声 sh（嘘）：奶奶送的樱桃形小摆件放在盒里，男孩怕人碰坏，轻声“嘘”，再细心盖好盒子。因为这份礼物承载亲情，他一直珍爱它。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"HER WISH · 把她的愿望放在心上","textZh":"care（关心）着 her wish（她的愿望）：奶奶一直想去看看大海，孩子认真记住这件事，时时放在心上，盼着陪她实现。把这份长久珍视她心愿的感情，连到 cherish。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4984":{"word":"churlish","mnemonics":[{"method":"CURL + ISH · 撇嘴嘲笑","textZh":"churlish 联到 curl（卷起）：别人好心送来礼物，他却撇起嘴角，冷笑着嫌礼物太便宜。用这张卷起嘴角、粗鲁又不领情的脸，记住 churlish。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CHILDISH → CHURLISH","textZh":"churlish 唤起 childish（幼稚的）：一个成年人输了游戏，就像闹脾气的孩子一样冲别人说难听话。幼稚的发作变成了粗鲁无礼的表现，把 childish 连到 churlish。","original":false,"weak":false,"kind":"root exact-text approved; private only"}]},"4985":{"word":"circumstantial","mnemonics":[{"method":"CIRCUM + STANT + IAL","textZh":"CIRCUM 联到 circle（一圈），STANT 联到 stand（站着），IAL 收成形容词：天气、人手、场地等条件仿佛围着一件事站成一圈，共同影响安排。circumstantial 就把注意力放到这些具体情境上。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SIR, COME STAND + IAL","textZh":"“Sir, come stand!”（先生，过来站吧！）组织者要安排合影：晴天请他站在院里，下雨就请他站到屋檐下。把 circumstantial 连到这句随现场情况调整的邀请，记住影响站位的天气、场地等情境因素。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4986":{"word":"civic","mnemonics":[{"method":"CIVIL → CIVIC · 走进 CITY","textZh":"civic 联到 civil（有礼貌的）：这位居民平时待人有礼，现在又为 city（城市）的公共事务出力。结尾换成 city 的 C，把关注点从个人礼貌转向公民责任和城市生活。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"SEE VIC · 找维克谈社区","textZh":"把 civic 连到 see Vic（去见维克）：维克是社区居民代表，大家找他讨论公共公园的照明、长椅和清洁。看到 civic，就想起这场关乎城市居民和公共事务的会面。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4987":{"word":"clerical","mnemonics":[{"method":"CLERK → CLERICAL","textZh":"clerical 联到 clerk（办公室职员）：前台职员一边核对姓名，一边登记、整理文件。把职员 clerk 连到形容这些工作的 clerical，就记住“文书事务的”。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CLEAR RECALL","textZh":"clear recall 是“清楚地回想”：办公室职员把每次来电的姓名、事项记入表格，再按日期归档，日后回想细节时能查得清清楚楚。把 clerical 连到这套记录、整理档案的工作。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4988":{"word":"cloak","mnemonics":[{"method":"COAT → CLOAK","textZh":"cloak 联到 coat（外套）：把外套想得 long（长）一些，像一件从肩头垂下的宽大斗篷，里面的东西都被遮住。长长的外套连起“斗篷”与“遮盖”。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CLOCK → CLOAK","textZh":"看到 cloak，想到 clock（钟）被不透明的布盖起来，连钟面都看不见。钟从视线中藏了起来；cloak 就是这样把东西遮住。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4989":{"word":"cluster","mnemonics":[{"method":"CLOSER → CLUSTER","textZh":"cluster 联到 closer（更近）：合照时摄影师说“靠近一点”，大家便挪近脚步，站到 together（一起）。越来越近的人聚成一群，连起 closer 与 cluster。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CLASS TOUR","textZh":"把 cluster 连到 class tour（班级参观）：导游在一个有趣的展品前停下，全班同学从四周靠过来，聚成一小群听讲。看到 cluster，就想起参观时大家围到一起的动作。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4990":{"word":"coherent","mnemonics":[{"method":"CO + HE + RENT","textZh":"coherent 分成 co（共同）、he（他）、rent（房租）：共同租房时，他把每项费用和分摊依据一项项讲清楚，前后算得通，大家都听明白。这样的说明就是 coherent，连贯而有条理。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"GO + HEAR + ANT","textZh":"go（去）hear（听）一只 ant（蚂蚁）讲巢穴路线：先从入口进去，再经过分岔，最后到食物室。它一步步讲得前后衔接，听者不会迷糊；把 coherent 连到这段条理清楚的讲解。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4991":{"word":"collective","mnemonics":[{"method":"COLLECT + IVE","textZh":"collect 是“收集”：把大家各自的一份力量收集到一起，共同完成任务。collect 接上形容词尾 IVE，描写的就是这种属于整个群体、由大家共同作出的努力。","original":false,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CALL + ACTIVE","textZh":"一个 call（电话）把全组召集起来，大家都 active（积极行动）：有人准备工具，有人搬材料，有人协调进度。把 collective 连到“一个电话，全组行动”，记住集体共同参与。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]},"4992":{"word":"collide","mnemonics":[{"method":"COL + SLIDE","textZh":"COL 联到 co-（一起），后面的 LIDE 唤起 slide（滑动）：两件东西从两边一起滑来，到了中间撞上了。把 collide 连到两股滑行动作在同一点相撞。","original":true,"weak":false,"kind":"root exact-text approved; private only"},{"method":"CAR LIGHT","textZh":"collide 联到 car light（车灯）：两辆玩具车的灯光从不同方向接近同一个交叉点，随后车头撞到一起。看到这对越来越近的车灯，就想起 collide 的相撞。","original":true,"weak":false,"kind":"root exact-text approved; private only"}]}};

// Root-reviewed release189 records; exact full mnemonic matching remains mandatory.
Object.assign(approvedMnemonicRecords,{"5503":{"word":"unostentatious","mnemonics":[{"method":"OSTENSIBLE · 不把自己摆到台前","textZh":"从学过的 ostensible（表面上的）想到“展示给人看的这一面”：它与 ostentatious（炫耀的）属于同源词族。加上 un-，想象一位富有的收藏家不把名表、豪车摆出来引人注意，只穿普通衣服安静看展。这样不刻意显摆，就是 unostentatious，低调、不张扬的。","original":false,"weak":false,"kind":"candidate_method"},{"method":"HONEST AND TASTEFUL · 真诚而有品味","textZh":"把 unostentatious 联想到 honest and tasteful（真诚而有品味）：主人不夸耀自己的身家，也不靠金碧辉煌的排场招待客人，只端上用心做的家常菜，配上简洁雅致的餐桌。这样的待客风格就是 unostentatious，低调、朴实而不炫耀。","original":true,"weak":false,"kind":"candidate_method"}]},"5504":{"word":"unprecedented","mnemonics":[{"method":"UN- + PRESIDENT · 历任校长都没做过","textZh":"把 unprecedented 联想到 un-（没有）和 president（校长、主席）：在一个校园故事里，新校长第一次让学生投票决定校庆主题，历任 president 从没这样做过。这是该校前所未有的举措，an unprecedented move。","original":true,"weak":false,"kind":"candidate_method"},{"method":"UN- + PRESENTED · 从没展示过的作品","textZh":"把 unprecedented 联想到 un-（没有）和 presented（展示过）：班级历年的手工作品都是静止的模型，今年却第一次有人展示一座能自动开合的纸桥。以前从没有 presented 过这样的作品，这项设计在班级历史上是 unprecedented，前所未有的。","original":true,"weak":false,"kind":"candidate_method"}]},"5505":{"word":"unprepossessing","mnemonics":[{"method":"POSSESSING · 第一眼没占住目光","textZh":"possessing 是“占有、拥有”。把 unprepossessing 联想到一只没能“占住”你目光的花瓶：货架上的它灰白朴素，你第一眼就略了过去。它的外表 unprepossessing，不起眼、没给人很强的吸引力；插上鲜花后却可能很好看。","original":false,"weak":false,"kind":"candidate_method"},{"method":"UN- + PROCESSING · 没加工的朴素外表","textZh":"把 unprepossessing 联想到 un-（没有）和 processing（加工处理）：一块做桌面的木板还没经过精细处理，表面灰扑扑的，摆在店里一点也不吸引目光。这副平淡不起眼的外观，就是 unprepossessing。","original":true,"weak":false,"kind":"candidate_method"}]},"5506":{"word":"unravel","mnemonics":[{"method":"REVEAL · 线索揭开谜底","textZh":"把 unravel 和 reveal（揭示）放在一起记：侦探把分散的线索一一理清，终于 reveal 了失物的去向。线索原本像缠在一起的线团，如今谜底解开了，这就是 unravel a mystery，解开谜团。","original":false,"weak":false,"kind":"candidate_method"},{"method":"TRAVEL · 旅行箱里解开线团","textZh":"看到 unravel，联想到 travel（旅行）：出门前打开旅行箱，几根充电线缠成一团。你沿着每一根线慢慢找、慢慢解，终于把它们理开。这次 travel 前的整理动作，就是 unravel，解开缠绕。","original":false,"weak":false,"kind":"candidate_method"}]},"5507":{"word":"unseemly","mnemonics":[{"method":"UN- + SEEMLY · 与得体相反","textZh":"seemly 是学过的“得体的”，加上 un- 就转为不得体。婚礼上新人正在致辞，来宾却大声接电话、压过了他们的声音。这种不顾场合与礼仪的举动，就是 unseemly。","original":false,"weak":false,"kind":"candidate_method"},{"method":"unseemly · 俺失礼了","textZh":"把 unseemly 联想到一句“俺失礼了”：宴席上主人还没招呼，客人已经伸手抢走最后一块点心，见大家看着自己，赶紧道歉。这个抢食的举动 unseemly，不合礼仪、不得体。","original":true,"weak":false,"kind":"candidate_method"}]},"5508":{"word":"unsettle","mnemonics":[{"method":"UN- + SETTLE DOWN · 安定被打破","textZh":"settle down 是“平静下来、安定下来”。本来已经安静坐下准备读书，忽然收到临时搬家的消息，心一下乱了。unsettle 就是把原先安定的状态打破，使人不安，也可使局势不稳定。","original":false,"weak":false,"kind":"candidate_method"},{"method":"KETTLE · 出门后惦记水壶","textZh":"看到 unsettle，联想到 kettle（水壶）：已经走到车站，你突然记不清烧水壶是否关好了。这个念头让你一路心神不宁。它 unsettles you，使你担心、不安。","original":true,"weak":false,"kind":"candidate_method"}]},"5509":{"word":"unsurpassed","mnemonics":[{"method":"SURPASS + PASS · 纪录还没被超过","textZh":"把 surpass（超过、胜过）和熟悉的 pass（从旁超过）连起来记：跑道上有人从你身旁 pass 过去，就超过了你。unsurpassed 加上“没有被超过”的意思，想象一项纪录保持了十年，后来参赛的人仍没有超过它。这项纪录依然 unsurpassed。","original":false,"weak":false,"kind":"candidate_method"},{"method":"ANSWER FAST · 全场答题无人能及","textZh":"把 unsurpassed 联想到 answer fast（迅速作答）：知识竞赛里，一名选手每题都答对，而且答得比所有对手都快，没有人的成绩超过他。他在这场比赛中的表现 unsurpassed，无人能及。","original":true,"weak":false,"kind":"candidate_method"}]},"5510":{"word":"untether","mnemonics":[{"method":"UN- + TOGETHER · 不再绑在一起","textZh":"把 untether 联想到 un-（解除）和 together（在一起）：员工过去只能守着固定在办公桌上的电脑，仿佛人与桌子被绑在一起。改用便携设备后，他可以走到不同地方工作，不再受那张桌子束缚。这样的改变 untethers him from the desk，使他摆脱限制。","original":true,"weak":false,"kind":"candidate_method"},{"method":"UNTIE HER · 给小母羊解绳","textZh":"把 untether 联想到 untie her（给她解开绳子）：围栏内的小母羊仍由短绳拴在木桩边，主人请同伴给它松开牵绳。绳子解下后，它就能在围栏里自由走动。这就是 untether，解除拴系、使能自由活动。","original":true,"weak":false,"kind":"candidate_method"}]},"5511":{"word":"untrammeled","mnemonics":[{"method":"UNTRAINED · 没套进固定画法","textZh":"把 untrammeled 联想到 untrained（未经训练的）：train 是训练。这个孩子没有被训练成只会照统一范本画画，老师也让他按自己的想法创作；于是他大胆画出方形太阳、会飞的房子。他的想象力 untrammeled，不受固定形式束缚。","original":true,"weak":false,"kind":"candidate_method"},{"method":"UNTRAPPED · 从困住到自由","textZh":"把 untrammeled 联想到 untrapped（没有被困住）：trap 是陷阱。想象小兔从笼式陷阱里被放出来，前面没有围栏挡路，它可以向任何方向自由奔跑。这种不受阻拦的活动状态，就是 untrammeled，不受限制的。","original":true,"weak":false,"kind":"candidate_method"}]},"5512":{"word":"unwarranted","mnemonics":[{"method":"WARRANTY · 保修承诺内还乱收费","textZh":"把 unwarranted 联想到 warranty（保修承诺）：商店明明承诺某种故障免费保修，顾客也符合约定条件，店主却说不出理由，仍要收一笔全额维修费。这项无正当理由的要求就是 unwarranted。","original":false,"weak":false,"kind":"candidate_method"},{"method":"UNWANTED · 不喜欢也不该大动干戈","textZh":"把 unwarranted 联想到 unwanted（不想要的）：邻居误把一张你不想要的广告塞进信箱，你却为这一次小失误冲过去大骂一顿。广告是 unwanted，而这种没有必要、明显过头的反应是 unwarranted，不合理的。","original":true,"weak":false,"kind":"candidate_method"}]},"5513":{"word":"unwieldy","mnemonics":[{"method":"WIELD · 大工具不好使","textZh":"从学过的 wield（操持、使用工具）想到 unwieldy：一把锤子太大、柄又太长，拿在手里很难控制，想准确敲中木钉都不容易。un- 带来否定，难以顺手操持的东西，就是 unwieldy，笨大而难操作的。","original":false,"weak":false,"kind":"candidate_method"},{"method":"UN- + WHEEL · 大箱子没有轮子","textZh":"把 unwieldy 联想到 un-（没有）和 wheel（轮子）：一只又大又沉的旅行箱没有轮子，只能靠手搬；抱不稳，转身也费劲。这只箱子 unwieldy，笨重、难搬动。","original":false,"weak":false,"kind":"candidate_method"}]},"5514":{"word":"unyielding","mnemonics":[{"method":"ONE BUILDING · 厚墙推不动","textZh":"把 unyielding 联想到 one building（一座大楼）：这座楼有厚厚的石墙，你用双手推，墙面丝毫不凹、不弯。这样坚硬、不受压力改变形状的表面，就是 unyielding。","original":true,"weak":false,"kind":"candidate_method"},{"method":"unyielding · 俺一定不让步","textZh":"把 unyielding 联想到一句“俺一定不让步”：有人反复劝守门人让没票的朋友进去，他仍坚持人人都按同一规则进场，丝毫不改变决定。他的态度 unyielding，坚定不让步。","original":true,"weak":false,"kind":"candidate_method"}]},"5515":{"word":"upend","mnemonics":[{"method":"UP + END · 底端翻到上面","textZh":"up 是向上，end 是一端。想象把瓶子的底端从下面翻到上面，让瓶口朝下；原来直立的瓶子整个倒过来了。这个动作就是 upend，把物体倒置、翻转。","original":false,"weak":false,"kind":"candidate_method"},{"method":"OPENED · 打开后翻倒盒子","textZh":"看到 upend，联想到 opened（打开了）：你打开饼干盒，发现最后几块都落在深深的盒底，于是把整只盒子底朝上翻过来，让饼干倒进盘子。这个翻倒的动作，就是 upend。","original":true,"weak":false,"kind":"candidate_method"}]},"2573":{"word":"urbane","mnemonics":[{"method":"URBAN · 从城市社交想到文雅","textZh":"urbane 和 urban（城市的）同源，词义从城市社交生活中的老练、文雅发展而来。想象一位参加城市艺术沙龙的来宾，交谈从容，礼貌接住别人的话，也能自然化解小尴尬。他的社交风度就是 urbane，温文尔雅、得体老练。","original":false,"weak":false,"kind":"candidate_method"},{"method":"urbane · 耳边体贴地提醒","textZh":"把 urbane 联想到“耳边”：茶叙时，一位来宾误拿了别人的杯子，主人没有当众指责，只在他耳边从容提醒：“您的杯子在这边。”一句自然得体的话化解了尴尬，这样文雅周到的待人方式，就是 urbane。","original":true,"weak":false,"kind":"candidate_method"}]},"5516":{"word":"urgent","mnemonics":[{"method":"URGE · 催着马上处理","textZh":"urge 是催促，和 urgent 属于同源词族。房间的水管突然漏水，大家不断 urge 负责人赶快来关阀，因为再等就会淹湿地板。必须立即处理的这件事，就是 urgent，紧急的、刻不容缓的。","original":false,"weak":false,"kind":"candidate_method"},{"method":"AGENT · 代理发现时间快到了","textZh":"把 urgent 联想到 agent（代理人）：旅行代理发现你的航班提前起飞，登机手续马上截止，立刻打电话提醒你赶紧处理。这个不能再拖的消息，就是 an urgent message，紧急消息。","original":true,"weak":false,"kind":"candidate_method"}]},"5517":{"word":"utilitarian","mnemonics":[{"method":"UTILITY + USE · 有用放第一","textZh":"utilitarian 来自 utility（实用性），和熟悉的 use（使用）同源。选工作桌时，你不在意雕花漂不漂亮，只看桌面够不够大、能不能稳稳放工具。这种把实际用处放在首位的设计，就是 utilitarian，注重实用的。","original":false,"weak":false,"kind":"candidate_method"},{"method":"MILITARY · 军用背包重实用","textZh":"把 utilitarian 联想到 military（军用的）：一个军用背包没有亮片和花边，却有耐磨的布料、牢固的肩带和方便取物的口袋。每个设计都为了好用，这种风格就是 utilitarian，实用至上。","original":true,"weak":false,"kind":"candidate_method"}]},"5518":{"word":"utopia","mnemonics":[{"method":"ZOOTOPIA · 动物们向往的理想城","textZh":"从《疯狂动物城》的英文片名 Zootopia 想到 utopia。兔子朱迪向往一座不论出身、人人都能追求梦想的城市；这种没有偏见、大家和谐生活的完美社会理想，就是 utopia，乌托邦。","original":false,"weak":false,"kind":"candidate_method"},{"method":"utopia · 芋头皮呀也能变美食","textZh":"把 utopia 联想到一句“芋头皮呀，也能变成美食”：想象梦里有一座城，连扔掉的芋头皮都会变成丰盛饭菜，人人不愁吃穿，也从不争吵。这样的完美幻想世界，就是 utopia，现实中难以实现的理想国。","original":true,"weak":true,"kind":"candidate_method"}]},"2575":{"word":"utter","mnemonics":[{"method":"OUTER · 把心里话说到外面","textZh":"utter 与 out（向外）、outer（外面的）属于同源词族。原本藏在心里的话，从嘴里说出来，到了外面：你终于 utter a word，说出一个词。用“把话送到外面”记住 utter 的说出、发出声音义。","original":false,"weak":false,"kind":"candidate_method"},{"method":"BUTTER · 黄油全化成一摊","textZh":"把 utter 联想到 butter（黄油）：想给蛋糕裱花，却把整块黄油放在暖气边，结果完全化成一摊，花纹根本立不住。这次裱花成了 an utter failure，彻底的失败。utter 在这里加强程度，表示完全的。","original":true,"weak":false,"kind":"candidate_method"}]},"5519":{"word":"vacant","mnemonics":[{"method":"VACATION · 放假后教室空了","textZh":"vacant 和 vacation（假期）同源，都带着“空出来”的意思。假期到了，学生们全回家，教室里一个人也没有。这样的教室是 vacant，空着、无人使用的。","original":false,"weak":false,"kind":"candidate_method"},{"method":"vacant · 位空着","textZh":"把 vacant 联想到“位空着”：车厢里大部分座位都有人，只有窗边那一位空着，没有人坐，也没有行李占用。这个座位就是 a vacant seat，空座位。","original":true,"weak":false,"kind":"candidate_method"}]},"5520":{"word":"vacillation","mnemonics":[{"method":"VACATION · 假期去哪儿拿不定","textZh":"把 vacillation 联想到 vacation（假期）：你刚决定去海边，又觉得山里凉快，改了主意；看见海边照片，又想改回去。选择来回变，迟迟定不下来，这就是 vacillation，犹豫不决。","original":true,"weak":false,"kind":"candidate_method"},{"method":"VASE SELECTION · 花瓶选了又改","textZh":"把 vacillation 联想到 vase selection（挑选花瓶）：先觉得高花瓶好看，选定后又改口要矮花瓶，想一想还是高的好。这样在两个选择间反复摇摆、拿不定主意，就是 vacillation。","original":true,"weak":false,"kind":"candidate_method"}]},"2578":{"word":"vacuous","mnemonics":[{"method":"VACUUM · 话里像抽成了真空","textZh":"vacuous 和 vacuum（真空）同源，都带着“空”的意思。想象一篇讲话像被抽成了真空：漂亮口号说了一大堆，却没有一个实际想法。这样的讲话就是 vacuous，内容空洞、缺少思考。","original":false,"weak":false,"kind":"candidate_method"},{"method":"FACTS + USE · 一个事实也用不上","textZh":"把 vacuous 联想到 facts（事实）和 use（使用）：听完一场长篇分析，你想从中找几个事实来用，却发现对方只反复说“反正就是这样”，既没事实，也没推理。这种空洞无内容的分析，就是 vacuous。","original":true,"weak":false,"kind":"candidate_method"}]},"2580":{"word":"vague","mnemonics":[{"method":"WAVE · 挥挥手却没说清","textZh":"把 vague 联想到 wave（挥手）：别人问你把箱子放在哪里，你只朝一大片货架挥挥手，说“那边吧”，却没指明哪一格。这样的指示就是 vague，含糊、不明确。","original":true,"weak":false,"kind":"candidate_method"},{"method":"WAKE · 醒后只剩模糊印象","textZh":"把 vague 联想到 wake（醒来）：刚醒时还记得梦里好像去了海边，可人物、地点、经过都说不清。你只剩 a vague memory，一段模糊的记忆。","original":true,"weak":false,"kind":"candidate_method"}]},"5521":{"word":"vainglorious","mnemonics":[{"method":"VAIN + GLORY · 把荣耀全揽给自己","textZh":"vainglorious 可以连着 vain（虚荣的）和 glory（荣耀）记。一本书明明是大家合作完成的，一个人却把封面摆满自己的照片，逢人就说“全是我的功劳”。这样过分自我夸耀，就是 vainglorious。","original":false,"weak":false,"kind":"candidate_method"},{"method":"VICTORIOUS · 赢一次就自吹无敌","textZh":"把 vainglorious 联想到 victorious（获胜的）：一个棋手刚赢了一盘，就到处宣称自己天下无敌，谁都不配当他的对手。从一次获胜夸大成无边的自负，这副样子就是 vainglorious。","original":true,"weak":false,"kind":"candidate_method"}]},"2581":{"word":"valediction","mnemonics":[{"method":"WAVE + DICTIONARY · 查好“再见”再挥别","textZh":"把 valediction 联想到 wave（挥手）和 dictionary（词典）：临别时，你先翻词典查出对方语言里的“再见”，然后挥手，认真把这句告别的话说给对方听。这样的告别话语，就是 valediction。","original":true,"weak":false,"kind":"candidate_method"},{"method":"valediction · 为了辞行","textZh":"把 valediction 联想到“为了辞行”：毕业离校前，你特意去老师办公室，说“谢谢您这些年的照顾，我要走了，请多保重”。这一番临别的话，就是 valediction，告别、告别辞。","original":true,"weak":false,"kind":"candidate_method"}]},"5522":{"word":"vanish","mnemonics":[{"method":"FINISH · 吃完后不见了","textZh":"把 vanish 联想到 finish（吃完）：一盘饼干刚端上来还满满的，大家很快把它们吃完，再看盘子，饼干已经不见了。The cookies have vanished. 用 finish 后盘里空了，记住 vanish 的消失义。","original":true,"weak":false,"kind":"candidate_method"},{"method":"vanish · 哇，你消失了","textZh":"把 vanish 联想到“哇，你消失了”：朋友刚还站在眼前，转过街角，身影一下子不见了，你惊讶地喊出这句话。Vanish 就是从视线中消失、不见了。","original":false,"weak":false,"kind":"candidate_method"}]},"2586":{"word":"vaporize","mnemonics":[{"method":"EVAPORATE · 都走向水蒸气","textZh":"把 vaporize 和 evaporate（蒸发）连着记：两词同属 vapor（水蒸气）这一词族。浅盘里的水逐渐蒸发，液态水变成了气态；这个由液体变成蒸气的过程，也可以用 vaporize 表达。","original":false,"weak":false,"kind":"candidate_method"},{"method":"vaporize · 外婆晒","textZh":"把 vaporize 联想到“外婆晒”：外婆把湿床单晾在太阳下，过了一阵，水分变成水蒸气进入空气，床单慢慢干了。从“外婆晒”想到水分汽化，就能记住 vaporize。","original":true,"weak":false,"kind":"candidate_method"}]},"5523":{"word":"veracity","mnemonics":[{"method":"VERIFY + ACCURACY · 核实是否准确","textZh":"把 veracity 联想到 verify（核实）和 accuracy（准确性）：有人说展览有一百件作品，你逐项核对清单，发现确实是一百件。查证后确认这句话真实、准确，就是确认了它的 veracity。","original":false,"weak":false,"kind":"candidate_method"},{"method":"veracity · 为人实在","textZh":"把 veracity 联想到“为人实在”：卖家主动告诉你，这张旧桌子有一道裂缝，还指给你看，丝毫不夸大桌子的状况。这种如实说话、不隐瞒事实的品质，就是 veracity，诚实、真实。","original":true,"weak":false,"kind":"candidate_method"}]},"2602":{"word":"verbose","mnemonics":[{"method":"VERBAL · 一句话膨成一页","textZh":"verbose 和 verbal（言语的）同源，都与“词语”有关。想象一句“明天九点开会”，被写成整整一页，时间、地点和同一句提醒反复出现。词语堆得超过表达所需，这段话就变得 verbose，冗长啰嗦。","original":false,"weak":false,"kind":"candidate_method"},{"method":"YOUR BOSS · 老板一句讲十遍","textZh":"把 verbose 联想到 your boss（你的老板）：老板只需要说“周五前交报告”，却把同一个要求绕来绕去讲了十分钟，始终没有增加新信息。这样的讲话就是 verbose，用了太多不必要的词。","original":false,"weak":false,"kind":"candidate_method"}]},"2608":{"word":"versatile","mnemonics":[{"method":"VARIOUS STYLES · 各种风格都拿手","textZh":"把 versatile 联想到 various styles（各种风格）：同一位画家既能画细腻的人像，也能画简洁的漫画，换一种风格仍能画得好。他能胜任不同的创作方式，就是 versatile，多才多艺。","original":false,"weak":false,"kind":"candidate_method"},{"method":"REVERSE · 翻面后又有新用途","textZh":"versatile 和 reverse（翻转）同属“转”的词源家族。想象一块特制游戏板，正面是棋盘，翻过来又能玩迷宫，支起来还能作记分板。它能转成不同用途，是一件 versatile 的多功能用品。","original":false,"weak":false,"kind":"candidate_method"}]},"2613":{"word":"vestige","mnemonics":[{"method":"INVESTIGATE · 调查留下的痕迹","textZh":"vestige 和 investigate（调查）同源，都连着“踪迹”的意思。想象调查者走进一间已经搬空的老作坊，只在地上找到少量旧木屑。这一点残留，就是从前木工活动留下的 vestige。","original":false,"weak":false,"kind":"candidate_method"},{"method":"VEST + AGE · 旧戏服只剩背心","textZh":"把 vestige 联想到 vest（背心）和 age（年代）：一整套旧戏服早已散失，只留下一件褪色背心，让人想起那个年代的演出。这件小小的残留，是旧戏服留下的 vestige。","original":false,"weak":false,"kind":"candidate_method"}]}});

// Exact root-reviewed release 190 mnemonic records.
Object.assign(approvedMnemonicRecords,{"2625":{"word":"vigorous","mnemonics":[{"method":"BIG HORSE · 奔跑有劲","textZh":"把 vigorous 联想到 big horse（大马）：这匹大马迈开四蹄，沿着草地有力地奔跑，跑了一圈还精神十足。这股旺盛的精力和有力的动作，就是 vigorous。","original":true,"kind":"invented_association","weak":false},{"method":"RIGOROUS · 严格训练，动作有力","textZh":"vigorous 与 rigorous（严格的）只差开头的一个字母。教练要求每一组训练都认真完成，队员一下一下有力地划桨，展现充沛的体力：要求是 rigorous，运动时那股有力、有活力的劲头是 vigorous。","original":false,"kind":"adapted_whole_word_association","weak":false}]},"5524":{"word":"violate","mnemonics":[{"method":"VIOLET · 摘花违了规定","textZh":"把 violate 与 violet（紫罗兰）放在一起记：花园明确禁止采摘，一个游客却伸手摘走一朵 violet。他的动作违反了花园规定，就是 violate the rule。","original":true,"kind":"invented_association","weak":false},{"method":"WE ARE LATE · 错过约定时间","textZh":"把 violate 联想到 we are late（我们迟到了）。夏令营明确规定九点前回到营地，两名队员九点半才回来，互相说“we are late”。他们没有遵守这条约定，违反营地规则，就是 violate the rule。","original":true,"kind":"invented_association","weak":false}]},"5525":{"word":"virtue","mnemonics":[{"method":"VIRTUOUS · 好品行与好品质","textZh":"virtuous 表示有美德的，virtue 就是其中那份美德。一个人收到多找的零钱，主动交还店员：这样的行为是 virtuous，而他表现出的诚实是一种 virtue。","original":false,"kind":"word_family","weak":false},{"method":"VIRTUAL · 虚拟会议的优点","textZh":"把 virtue 与 virtual（虚拟的）联在一起：一次 virtual meeting 让分处两地的同事直接交流，省去了长途出差。节约时间和路费，就是这种会议方式的一项 virtue，也就是优点、好处。","original":true,"kind":"invented_association","weak":false}]},"5526":{"word":"visible","mnemonics":[{"method":"VISION · 视力够好，就看得见","textZh":"visible 与 vision（视力）同属“看”的词族。视力检查时，戴上合适的眼镜，原本模糊的小字变得看得见了：vision 是看的能力，visible 形容能被看到的东西。","original":false,"kind":"word_family","weak":false},{"method":"未遮蔽 · 窗外看得见","textZh":"把 visible 联想到“未遮蔽”：窗外的路灯没有被树叶或窗帘挡住，你坐在屋里就能看见它。路灯处在视线中，是 visible，看得见的。","original":true,"kind":"invented_association","weak":false}]},"2638":{"word":"vitriolic","mnemonics":[{"method":"WE THREE ALL LICK · 酸到嘴里的刻薄话","textZh":"把 vitriolic 联想到 we three all lick（我们三个都舔）：三个刻薄的美食评委同时舔了一口柠檬，嘴里酸，评语也酸得伤人。他们不谈菜哪里需要改，却说“你根本不配进厨房！”这种充满敌意、恶毒刻薄的话，就是 vitriolic。","original":true,"kind":"invented_association","weak":false},{"method":"PETROL LEAK · 恶语火上浇油","textZh":"把 vitriolic 联想到 petrol leak（汽油泄漏）。争论本来快平息了，一个人却接连说“你一无是处”，恶毒的话像漏出的汽油，让火气越烧越旺。vitriolic 形容的就是这种满含恶意、伤人的言语。","original":false,"kind":"adapted_whole_phrase_association","weak":true}]},"2640":{"word":"vivacious","mnemonics":[{"method":"VIVID + GRACIOUS · 鲜活又亲切","textZh":"把 vivacious 联想到 vivid（生动的）和 gracious（亲切有礼的）。迎新会的主持人把故事讲得活灵活现，又笑着热情招呼每位来宾；这种鲜活有趣、富有感染力的样子，就是 vivacious，活泼开朗的。","original":false,"kind":"adapted_whole_word_association","weak":false},{"method":"VACATION · 假日里活泼起来","textZh":"把 vivacious 与 vacation（假期）联在一起：海边度假时，她笑着组织小游戏，兴致勃勃地和新朋友聊天，整个聚会都被她带得活跃起来。这个 vacation 里的她很 vivacious，活泼开朗、讨人喜欢。","original":true,"kind":"invented_association","weak":false}]},"2642":{"word":"volatile","mnemonics":[{"method":"VOLLEYBALL · 飞进空气里","textZh":"volatile 与 volleyball（排球）中的 volley，都有“飞”的词源背景。排球在空中飞，容易挥发的液体也像很快“飞”进了空气里。想到酒精容易变成气体的特性，就能记住 volatile 的“易挥发的”这一义项。","original":false,"kind":"word_family","weak":false},{"method":"WALL TILE · 瓷砖价格忽涨忽跌","textZh":"把 volatile 联想到 wall tile（墙砖）。装修时想买同一种墙砖，报价却在几天内突然大涨、又猛跌，预算很难确定。这种剧烈而难以预测的变化，就是 volatile，不稳定、波动大的。","original":true,"kind":"invented_association","weak":false}]},"2644":{"word":"voluble","mnemonics":[{"method":"VOLUME · 调低音量，话还不停","textZh":"把 voluble 与 volume（音量）联在一起：电视解说员兴致勃勃地连讲不停，你调低了 volume，他仍一句接一句说下去。声音小了，话还是很多；这种滔滔不绝的说话方式就是 voluble。","original":false,"kind":"adapted_whole_word_association","weak":false},{"method":"VALUABLE · 一谈宝贝就停不下嘴","textZh":"把 voluble 与 valuable（珍贵的）放在一起记：收藏者拿出自己最珍贵的怀表，从来历讲到工艺，再讲到寻找它的经历，越说越兴奋，一口气说了许多。东西是 valuable，谈起它的人很 voluble，健谈而滔滔不绝。","original":true,"kind":"invented_association","weak":false}]},"3061":{"word":"wanting","mnemonics":[{"method":"WANT · 还想要，因为有欠缺","textZh":"从熟悉的 want（想要）联想到 wanting：审稿人说“I want more evidence”，因为文章现有的证据不够。文章的论证因此被评为 wanting，也就是欠缺的、不够好的。","original":false,"kind":"word_family_association","weak":false},{"method":"ONE THING · 还少一样","textZh":"把 wanting 联想到 one thing（一样东西）。参加自行车活动前，装备看似都装好了，却还缺 one thing：必需的头盔。准备仍有欠缺、没有达到要求，就是 wanting。","original":true,"kind":"invented_association","weak":false}]},"5527":{"word":"wealth","mnemonics":[{"method":"HEALTH · 健康也是财富","textZh":"wealth 与 health（健康）只有开头不同。想到“健康也是财富”：存款和房产是财富，能让你安心生活、自由活动的健康也十分珍贵。由 health 记住 wealth，财富。","original":false,"kind":"adapted_whole_word_association","weak":false},{"method":"WELLS · 水井带来资源","textZh":"把 wealth 联想到 wells（水井）。在一个干旱的村庄，几口出水充足的井让居民和农田有了可靠的水源；这些宝贵的水资源，就是村庄共同拥有的 wealth，财富。","original":true,"kind":"invented_association","weak":false}]},"5528":{"word":"well-defined","mnemonics":[{"method":"WELL + DEFINED · 规定得清楚","textZh":"well 是“好地”，define 是“界定、说明清楚”。一场比赛把怎样得分、什么时候结束都规定得明明白白，参赛者一看就懂。规则被 well defined，就是界定清楚、明确的。","original":false,"kind":"word_components","weak":false},{"method":"WELL-DESIGNED · 好设计画清界线","textZh":"把 well-defined 与 well-designed（设计精良的）放在一起记：一张精心设计的公园图，把花坛、步道和草坪的边界画得清清楚楚。设计是 well-designed，图上的边界则是 well-defined，轮廓分明的。","original":true,"kind":"invented_association","weak":false}]},"2668":{"word":"welter","mnemonics":[{"method":"WATER · 水把东西搅成一团","textZh":"把 welter 联想到 water（水）。院里的积水卷着落叶、小树枝和纸片旋转，最后把它们推到角落，混成难以分开的一堆。这一团杂乱的东西，就是 a welter。","original":false,"kind":"invented_association","weak":false},{"method":"WAITER · 点单混在一堆","textZh":"把 welter 与 waiter（服务员）联在一起：忙碌的服务员把几桌客人的点单和账单混在同一个托盘里，纸条互相压着，找不出哪张属于哪桌。这一堆混乱的单据，就是 a welter of papers。","original":false,"kind":"invented_association","weak":false}]},"5529":{"word":"wherewithal","mnemonics":[{"method":"WEAR IT ALL · 装备全带上","textZh":"把 wherewithal 联想到 wear it all（全都穿戴上）。出发前，徒步者把防雨衣、防晒帽和装好饮水、食物的背包都穿戴好，所需装备一应俱全。这些让旅程能够进行的物资，就是 wherewithal，做成事情所需的条件和资源。","original":false,"kind":"phrase_anchor","weak":false},{"method":"WHERE'S IT ALL? · 办事的钱在哪儿","textZh":"把 wherewithal 联想到 Where's it all?（这些都在哪儿？）。大家想办一次演出，负责人指着场租和设备的预算问：这些钱都在哪里？只有把必要的资金落实，演出才办得成。这里追问的正是 wherewithal，办事所需的资金。","original":true,"kind":"phrase_anchor","weak":false}]},"5530":{"word":"wide-ranging","mnemonics":[{"method":"WIDE + RANGE · 话题范围广","textZh":"wide 是“广的”，range 是“范围”。一本杂志既谈科学，又谈艺术、历史和体育，覆盖的 range 很 wide。这样的内容就是 wide-ranging，涉及范围广泛的。","original":false,"kind":"word_components","weak":false},{"method":"WIDE + RAINING · 一场雨影响许多方面","textZh":"把 wide-ranging 联想到 wide（广的）和 raining（下雨）。一场覆盖大片地区的暴雨，既影响道路通行，也影响农作物、供电和商店营业。它的影响跨了许多方面，就是 wide-ranging，涉及范围广泛的。","original":true,"kind":"invented_association","weak":false}]},"3069":{"word":"wistful","mnemonics":[{"method":"WISHFUL · 想去却去不了","textZh":"把 wistful 与 wishful（满怀愿望的）联在一起。她一直想和朋友去海边，却因时间冲突没能成行；看着大家寄来的明信片，想象自己也在那里，脸上露出带着遗憾的向往。这样的神情就是 wistful，惆怅而有所眷恋的。","original":false,"kind":"invented_association","weak":false},{"method":"WHISTLE · 口哨勾起旧时光","textZh":"把 wistful 联想到 whistle（口哨）。听见有人吹起童年伙伴常吹的曲调，你想起两人曾经并肩走过的小路，很想再回到那段日子，却知道时光已经过去。这份怀念中带着淡淡伤感的心情，就是 wistful。","original":true,"kind":"invented_association","weak":false}]},"5531":{"word":"witless","mnemonics":[{"method":"WIT + LESS · 把机智拿掉","textZh":"由 witty（机智风趣的）想到 wit（机智），less 表示没有。有人怕雨伞被雨淋湿，偏偏在下雨时把伞收起来，结果自己淋成了落汤鸡。这种缺少判断力、自作聪明的做法，就是 witless，愚蠢的。","original":false,"kind":"word_components","weak":false},{"method":"WITNESS · 证人面前的傻问题","textZh":"把 witless 与 witness（证人）放在一起记。证人刚说自己亲眼看见了事故，提问者却又问：“你亲眼看见的时候，人就在现场吗？”这个不经思考、答案不言而喻的问题，就是 a witless question，愚蠢的问题。","original":true,"kind":"invented_association","weak":false}]},"5532":{"word":"wondrous","mnemonics":[{"method":"WONDERFUL · 奇景令人惊叹","textZh":"wondrous 与熟悉的 wonderful 都属于 wonder（惊奇）这一家族。第一次看见极光像彩色帷幕铺满夜空，你不仅觉得好看，还惊叹大自然竟能形成这样的景象。这份令人惊奇、赞叹的美，就是 wondrous，奇妙的。","original":false,"kind":"word_family","weak":false},{"method":"ONE DRESS · 一条奇妙的裙子","textZh":"把 wondrous 联想到 one dress（一条裙子）。童话里只有一条裙子，却会随着舞步变出星空、花海和晨曦的颜色，让观众看得目瞪口呆。这条令人惊叹的裙子就是 wondrous，奇妙非凡的。","original":true,"kind":"phrase_anchor","weak":false}]},"5533":{"word":"woo","mnemonics":[{"method":"WOOD · 木雕传心意","textZh":"把 woo 联想到 wood（木头）。年轻人认真把一块木头雕成对方喜欢的小鸟，作为礼物送给心上人，希望赢得对方的爱。这番用心追求、争取好感的举动，就是 woo。","original":true,"kind":"invented_association","weak":false},{"method":"ZOO · 动物园争取游客","textZh":"把 woo 与 zoo（动物园）联在一起。动物园推出亲子讲解和优惠套票，用有吸引力的活动邀请家庭来参观。它这样主动争取游客，就是 woo visitors，设法吸引、赢得他们的青睐。","original":true,"kind":"invented_association","weak":false}]},"5534":{"word":"yield","mnemonics":[{"method":"FIELD · 田地产出庄稼","textZh":"把 yield 与 field（田地）放在一起记：春天在田里播种，秋天收获一筐筐玉米。field 里产出的庄稼，让你想到 yield 的“产出、产生”；这一季收获了多少，也就是这片田的 yield，产量。","original":false,"kind":"invented_association","weak":false},{"method":"SHIELD · 放下盾牌认输","textZh":"把 yield 联想到 shield（盾牌）。舞台上扮演骑士的演员原本举盾抵抗，后来放下盾牌，举手表示认输。他停止抵抗、向对方让步，就是 yield，屈服。","original":false,"kind":"invented_association","weak":false}]},"5535":{"word":"aback","mnemonics":[{"method":"BACK · 惊得往后退","textZh":"看见 aback，想到 back（向后）。你以为房间里没人，一开门，朋友们突然齐声喊生日快乐，你吃惊得往后退了一步。把这一下意外带来的震惊记成 be taken aback，大吃一惊。","original":false,"kind":"invented_association","weak":false},{"method":"A BAG · 袋子里竟有声音","textZh":"把 aback 联想到 a bag（一个袋子）。你以为购物袋里只有衣服，袋子却忽然动了，还传出一声猫叫；原来家里的猫偷偷钻了进去。你惊得愣住，就是 taken aback，出乎意料地吃了一惊。","original":true,"kind":"phrase_anchor","weak":false}]},"5536":{"word":"abase","mnemonics":[{"method":"A BASE · 把地位压到最底下","textZh":"把 abase 联想到 a base（底部、基座）。想象一个地位阶梯：有人被当众贬低，仿佛从台阶高处被压到了最底部，尊严也随之受损。这种降低人的地位、使人受辱，就是 abase。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ABUSE · 辱骂使人受辱","textZh":"把 abase 与 abuse（辱骂、虐待）放在一起记。一个主管当着同事的面，用侮辱性的语言嘲弄员工，把他说得一文不值。这番 abuse 伤害了他的尊严，也就是 abase him，贬低、羞辱他。","original":true,"kind":"invented_association","weak":false}]},"5537":{"word":"abdicate","mnemonics":[{"method":"DEDICATE · 从尽责到弃责","textZh":"把 abdicate 与 dedicate（奉献、致力于）对照着记。负责人原本把时间都 dedicate to the project，后来却说“这事我再也不管”，把本应承担的职责全推给别人。从投入到弃责，后一步就是 abdicate responsibility，放弃职责。","original":false,"kind":"invented_association","weak":false},{"method":"A DECADE · 十年约定后交出王位","textZh":"把 abdicate 联想到 a decade（十年）。童话里的国王本可终身在位，却主动承诺：执政十年后就让出王位。十年一到，他兑现承诺，正式放弃原本可以继续拥有的王权。这位国王主动退位，就是 abdicate。","original":true,"kind":"phrase_anchor","weak":false}]},"5538":{"word":"abhor","mnemonics":[{"method":"HORROR · 厌恶得想退开","textZh":"abhor 与 horror（恐惧、惊骇）有共同的词源。看到有人以欺凌弱者为乐，你惊骇得皱眉退开，心里对这种残忍行径充满强烈厌恶。这种带着排斥、深恶痛绝的感受，就是 abhor。","original":false,"kind":"word_family","weak":false},{"method":"A BORE · 听到恶行，深恶痛绝","textZh":"把 abhor 联想到 a bore（惹人厌烦的人）。聚会上，这人喋喋不休地炫耀自己怎样欺负弱者。听众越听越愤怒，对他那些残忍行为深恶痛绝。由 a bore 讲出的恶行，记住 abhor 的“强烈憎恶”。","original":false,"kind":"phrase_anchor","weak":false}]},"5539":{"word":"abject","mnemonics":[{"method":"REJECT · 困境中的再次拒绝","textZh":"把 abject 联想到 reject（拒绝）。故事里，一位失业者连续求职被拒，又用尽积蓄，连食物和住处都成了难题。他陷入的这种贫困到极点的处境，就是 abject poverty，赤贫。","original":false,"kind":"invented_association","weak":false},{"method":"OBJECT · 像物件般任人摆布","textZh":"把 abject 与 object（物件）放在一起记。戏里的臣子为了保住宠信，任由国王把自己当物件摆布；国王一皱眉，他便伏地连声求饶，完全不顾自尊。这种卑躬屈膝、低声下气的样子，就是 abject。","original":true,"kind":"invented_association","weak":false}]},"5540":{"word":"abolish","mnemonics":[{"method":"DEMOLISH · 把旧制度彻底拆掉","textZh":"把 abolish 联想到 demolish（拆毁）。工人拆掉旧围墙，让它不再阻挡道路；改革者也像拆墙一样，正式废除那项不公平的制度，让它彻底退出生活。对制度这样“拆掉”，就是 abolish，废除。","original":false,"kind":"invented_association","weak":false},{"method":"POLISH · 不只修饰，而是废除","textZh":"把 abolish 与 polish（抛光、润饰）对照着记。面对一项不公平的旧制度，有人只想 polish 一下，让它看起来好些；改革者却决定通过新法，彻底结束这项制度。把制度正式废除，是 abolish。","original":false,"kind":"invented_association","weak":false}]},"5541":{"word":"aboriginal","mnemonics":[{"method":"ORIGINAL · 最初就在这里","textZh":"看见 aboriginal，想到熟悉的 original（原来的、最初的）。在后来移民到来之前，就已在一片土地上世代生活的人群，是那里的 original inhabitants，最早的居民。Aboriginal 便能形容这些原住民及其文化。","original":false,"kind":"word_family","weak":false},{"method":"A REGIONAL · 把本土原生单列一类","textZh":"把 aboriginal 联想到 a regional map（一张本地区地图）。自然课上，学生给植物分类：一种蕨类原本就自然生长在本地，另一种花是后来从外地引进的。他把蕨类标进“本土原生”一栏：这些就是 aboriginal plants。","original":true,"kind":"phrase_anchor","weak":true}]},"5542":{"word":"abrade","mnemonics":[{"method":"A BLADE · 刀刃刮去表层","textZh":"把 abrade 联想到 a blade（一个刀刃）。木工让刀刃贴着旧木板反复刮擦，表面薄薄的一层木料逐渐被磨去。用摩擦刮去、磨损表层，就是 abrade。","original":true,"kind":"phrase_anchor","weak":false},{"method":"A BRAKE · 刹车片慢慢磨损","textZh":"把 abrade 联想到 a brake（一个刹车装置）。自行车每次刹车，刹车片都与轮圈摩擦；用得久了，刹车片逐渐变薄。记住 a brake 带来的这种反复摩擦和磨损：abrade。","original":true,"kind":"phrase_anchor","weak":false}]},"5543":{"word":"abreast","mnemonics":[{"method":"BREAST · 胸前齐成一线","textZh":"abreast 里的 breast 是“胸部”。想象两名跑者并排向前，两人的胸前始终齐成一条横线，谁也没有落到后面。这样的并肩、齐头并列，就是 abreast。","original":false,"kind":"word_components","weak":false},{"method":"A REST · 休息时跟上新闻","textZh":"把 abreast 联想到 a rest（一次休息）。她每次短暂休息，都看一会儿当天新闻，及时了解刚发生的变化。靠这些休息时的阅读，她能 keep abreast of the news，跟上新闻动态。","original":true,"kind":"phrase_anchor","weak":false}]},"5544":{"word":"abrogate","mnemonics":[{"method":"A BROKEN GATE · 收费旧规被废除","textZh":"把 abrogate 联想到 a broken gate（一扇坏掉的大门）。小镇的旧收费门坏了，镇议会决定不再修门收钱，而是正式废除进镇收费规定，从此自由通行。这次把旧规取消，就是 abrogate。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ARROGANT · 傲慢地废除约束","textZh":"把 abrogate 与 arrogant（傲慢的）联在一起。故事里，一位傲慢的新主管认为自己说了算，正式宣布废除“重大决定必须共同商议”的规则。他取消了约束自己的规定，这个动作就是 abrogate。","original":false,"kind":"invented_association","weak":false}]},"5545":{"word":"abscond","mnemonics":[{"method":"A SECOND · 一转眼，悄悄溜走","textZh":"把 abscond 联想到 a second（一秒、一转眼）。管账的人趁同事转身的一小会儿，拿着偷走的钱悄悄离开，随后藏了起来。别人再回头，他已不见踪影。这种偷偷逃走、躲避追查，就是 abscond。","original":false,"kind":"phrase_anchor","weak":false},{"method":"A SCANDAL · 丑闻曝光前潜逃","textZh":"把 abscond 联想到 a scandal（一桩丑闻）。有人挪用公款，眼看丑闻就要曝光，便瞒着所有人连夜逃离，躲到别人找不到的地方。由丑闻前的秘密逃离，记住 abscond，潜逃。","original":true,"kind":"phrase_anchor","weak":false}]},"5546":{"word":"abysmal","mnemonics":[{"method":"A BAD SMELL · 臭味暴露糟糕条件","textZh":"把 abysmal 联想到 a bad smell（一股臭味）。推开旅馆房门，扑鼻臭味来自堵塞的排水口，污水还漫到了地板上。这样的住宿条件糟透了，是 abysmal conditions。","original":true,"kind":"phrase_anchor","weak":false},{"method":"A BIT SMALL · 工资低得可怜","textZh":"把 abysmal 联想到 a bit small（有点小）。工人拿到一个小小的工资袋，打开却发现，辛苦干了一整天只换来一枚硬币，连回家的车费都不够。这份工资低得可怜，是 abysmal pay。","original":true,"kind":"phrase_anchor","weak":false}]},"5547":{"word":"abyss","mnemonics":[{"method":"A BASE · 望不到底的深坑","textZh":"把 abyss 联想到 a base（一个底部）。站在护栏后往深坑里望，你一直想找到它的底部，却只看到向下延伸的黑暗。这样仿佛深不见底的大坑，就是 an abyss，深渊。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ABYSMAL · 糟糕处境像深渊","textZh":"刚学过 abysmal（糟透的），它和 abyss 同源，都连着“深不见底”的意象。公司的经营状况 abysmal，债务越积越多，仿佛陷入一个没有尽头的深坑。abysmal 形容处境糟透了，abyss 则是这个“深渊”本身。","original":false,"kind":"word_family","weak":false}]},"5548":{"word":"accede","mnemonics":[{"method":"ACCEPT · 接受请求并答应","textZh":"把 accede 与 accept（接受）放在一起记。学生请求多借一天书，管理员考虑后接受了这个请求，点头答应。这里的“同意请求”，就是 accede to the request。","original":false,"kind":"invented_association","weak":false},{"method":"A SEAT · 正式登上王位","textZh":"把 accede 联想到 a seat（一个座位）。宫殿里那个特殊的座位是王座；继任者在登基典礼后坐上王座，正式成为新君主。记住这个就任的场面：accede to the throne，登上王位。","original":true,"kind":"phrase_anchor","weak":false}]},"5549":{"word":"acclimate","mnemonics":[{"method":"CLIMATE · 渐渐习惯新气候","textZh":"acclimate 里有熟悉的 climate（气候）。从温暖的地方搬到凉爽地区，刚开始总觉得冷；住过一段时间，身体逐渐习惯了当地气候。这就是 acclimate，适应新的气候或环境。","original":false,"kind":"word_family","weak":false},{"method":"A CLASSMATE · 同学帮你适应","textZh":"把 acclimate 联想到 a classmate（一位同学）。刚转学时，你不熟悉课程安排和校园生活；这位同学每天带你熟悉学校，几周后，你渐渐习惯了新的学习环境。他在帮助你 acclimate，适应新环境。","original":true,"kind":"phrase_anchor","weak":false}]},"5550":{"word":"aberrant","mnemonics":[{"method":"ABERRATION · 异常事件的形容词","textZh":"以前学过 aberration（偏离常态的异常）。一台机器平时每分钟转速稳定，某次却突然忽高忽低，这次异常是 an aberration；形容它这种偏离正常模式的运转，就用 aberrant。","original":false,"kind":"word_family","weak":false},{"method":"A PARENT · 家长会上反常举动","textZh":"把 aberrant 联想到 a parent（一位家长）。家长会上，大家轮流发言，这位家长却故意用鸭叫声回答每一个问题。这种明显偏离场合惯常模式的行为，是 aberrant behavior，反常的行为。","original":true,"kind":"phrase_anchor","weak":false}]},"5551":{"word":"abjure","mnemonics":[{"method":"A JURY · 当众宣布放弃","textZh":"把 abjure 联想到 a jury（陪审团）。一场法庭戏里，男子面对陪审团，郑重声明：“我放弃过去鼓吹暴力的信念，从此不再支持它。”这种当众明确宣布抛弃旧信念，就是 abjure。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ABANDON + CONJURE · 郑重告别旧魔法","textZh":"联想到已学的 abandon（放弃）和 conjure（变魔法）。故事里的巫师曾用魔法伤害别人，如今当众郑重宣布：“I will abandon conjuring.” 他决定放弃施法，从此不再伤人。这样明确宣布戒绝旧做法，就是 abjure。","original":true,"kind":"invented_association","weak":false}]},"5552":{"word":"abnegate","mnemonics":[{"method":"ABNEGATION · 把克己变成行动","textZh":"以前学过 abnegation（克己、舍弃）。她本想把奖金花在奢华旅行上，最后却主动舍弃这份享受，把钱用于帮助他人。这种克己是 abnegation；说她主动放弃自己的享受，就用动词 abnegate。","original":false,"kind":"word_family","weak":false},{"method":"NEGATIVE · 对自己的欲望说不","textZh":"从熟悉的 negative（否定的）联想到 abnegate。面对独占豪华房间的机会，他给自己的享受一个“No”，主动让出房间，自己住进简朴的小屋。把这个否定用在自己的欲望上，就是 abnegate，克制自己、放弃自身享受。","original":false,"kind":"word_family","weak":false}]},"5553":{"word":"abundant","mnemonics":[{"method":"A BUNDLE · 一捆接一捆","textZh":"把 abundant 联想到 a bundle（一大捆）：收获的麦子一捆接一捆，粮仓堆得满满当当。粮食 abundant，就是数量丰富、供应充足。","kind":"phrase_anchor","original":false,"weak":false},{"method":"ABOUND · 大量存在","textZh":"以前学过 abound（大量存在）。果园里苹果多得压弯树枝，可以说 Apples abound in the orchard；换成形容词，便是 Apples are abundant，苹果数量丰富。","kind":"word_family","original":false,"weak":false}]},"5554":{"word":"acquainted","mnemonics":[{"method":"ACQUAINTANCE · 新相识的人","textZh":"想起那位被邀请一起玩的 new acquaintance（新结识的人）。他是一位认识的伙伴；把两人已经彼此相识的状态说出来，就是 They are acquainted。","original":false,"kind":"word_family","weak":false},{"method":"A QUICK DATE · 短短约会，彼此相识","textZh":"把 acquainted 联想到 a quick date（一次短暂的约会）。两人第一次见面，只聊了十几分钟，却已互相介绍姓名和兴趣。约会结束，双方已经 acquainted，彼此相识了。","original":true,"kind":"phrase_anchor","weak":true}]},"5555":{"word":"accessory","mnemonics":[{"method":"EXCESS ACCESSORIES · 配饰戴得过量","textZh":"把 accessory 连到 excess accessories（过多的配饰）。衣服已经穿好，又一层层加上项链、手链，身上尽是额外的点缀。项链、手链是附在主体装束上的 accessories，配饰；加得太多，才成了 excess accessories。","original":false,"kind":"invented_association","weak":false},{"method":"NECESSARY · 必需之外的配件","textZh":"把 accessory 和 necessary（必需的）放在一起看。相机本身已经能拍照，再配一个装饰腕带，带来便利和好看，却不是拍照必需的部分。necessary 是必需的；这种附加在主体上的 accessory 则是配件。","original":true,"kind":"invented_association","weak":false}]},"5556":{"word":"accidental","mnemonics":[{"method":"ACCIDENT · 意外发生的事","textZh":"熟悉的 accident 是意外事件。原本只是伸手拿书，却碰倒了水杯，这场小意外是一件 accident；用 accidental 来形容，就是意外发生的、非故意的。","original":false,"kind":"word_family","weak":false},{"method":"AXE + DENT · 搬工具时磕出凹痕","textZh":"把 accidental 联想到 axe（斧头）和 dent（凹痕）。搬运工具时没留神，斧头碰到柜门，留下一个凹痕；他本来只想搬东西，并没打算弄坏柜子。这处损伤是 accidental：意外造成的。","original":true,"kind":"invented_association","weak":false}]},"5557":{"word":"accumulate","mnemonics":[{"method":"阿Q没理它 · 灰尘越积越厚","textZh":"把 accumulate 联想到“阿Q没理它”。桌上的灰尘一直没人清理，一天一层，渐渐积成厚厚一堆：accumulate，越积越多，逐渐堆积。","original":false,"weak":false,"kind":"invented_association"},{"method":"A CUTE MULE ATE · 吃多后渐积脂肪","textZh":"把 accumulate 联想到 A cute mule ate（一头可爱的小骡子吃了）。小骡子每天吃得过量，脂肪便一点点积累起来。每天多吃一点，体内逐渐积下脂肪，就是 accumulate。","original":true,"weak":true,"kind":"phrase_anchor"}]},"5558":{"word":"acme","mnemonics":[{"method":"ACE + ME · 最高的牌在我手里","textZh":"把 acme 联想到 ace（A牌）和 me（我）。一局比牌约定A最大，你翻出A牌，指着自己说“me”：这一局最高的牌在我手里。把最高一张牌的画面延伸到最高成就，acme 就是顶点、巅峰。","original":false,"kind":"invented_association","weak":false},{"method":"ASK ME · 向巅峰高手请教","textZh":"把 acme 联想到 ask me（问我）。棋手刚夺得生涯最重要的冠军，棋艺正处在最高水平；面对大家最难的残局问题，他自信地说“Ask me!”。这时他的技艺达到了 acme：巅峰。","original":true,"kind":"phrase_anchor","weak":false}]},"5559":{"word":"acquiesce","mnemonics":[{"method":"A QUICK YES · 不再争辩的好吧","textZh":"把 acquiesce 联想到 a quick yes。会议上他不愿再争，只低声回了句“好吧”，随即接受安排。这个不再抗议的 yes，连着 acquiesce：默许、顺从。","original":false,"weak":false,"kind":"phrase_anchor"},{"method":"QUIESCENT · 反对平息，接受安排","textZh":"学过的 quiescent 是“静止、不活跃的”，它与 acquiesce 同族。想象会上原本激烈的反对渐渐平息，大家停止争执，接受了安排。acquiesce 就是这样不再反对，默许接受。","original":false,"weak":false,"kind":"word_family"}]},"5560":{"word":"acrid","mnemonics":[{"method":"ACID · 嘴里泼出的酸水","textZh":"看到 acrid，联想到 acid（酸）。把刻薄的话想成“嘴里泼出的酸水”：一句句话都带刺，让听的人难受。acrid 可以形容这种尖刻、苦毒的言辞。","original":false,"kind":"invented_association","weak":false},{"method":"CRIED · 刺鼻烟气熏出眼泪","textZh":"把 acrid 联想到 cried（哭了）。面包烤焦了，刺鼻的烟熏得人直掉眼泪，像在说“I cried!”。acrid 描述这种强烈刺鼻、令人难受的气味。","original":false,"kind":"invented_association","weak":false}]},"5561":{"word":"acrimonious","mnemonics":[{"method":"ACRID + MONEY · 为钱吵得尖刻","textZh":"刚学过 acrid 可以形容言辞刻薄。把 acrimonious 连着 acrid 和 money（钱）记：两位合伙人为分钱互揭短处，句句带着怨恨。围绕 money 的争执充满 acrid 的话，整个场面就是 acrimonious，充满怨愤、言辞尖刻。","original":false,"kind":"invented_association","weak":false},{"method":"A CRIME + ONIONS · 洋葱引来恶语","textZh":"把 acrimonious 联想到 a crime（罪行）和 onions（洋葱）。吃饭的人嫌菜里洋葱太多，尖刻地讽刺“做成这样简直是犯罪！”；厨师也恶语反击，两人越吵越带怨气。这种充满敌意和刻薄言辞的争执，就是 acrimonious。","original":false,"kind":"invented_association","weak":false}]},"5562":{"word":"adamant","mnemonics":[{"method":"DIAMOND · 像钻石一样不动摇","textZh":"adamant 与 diamond（钻石）同源。想象一个人的决定像坚硬的钻石：别人反复劝说，他仍坚持原来的立场，不肯改变。adamant 就是坚定不移、不为劝说所动的。","original":false,"kind":"word_family","weak":false},{"method":"A DEMAND · 坚持到底的要求","textZh":"把 adamant 联想到 a demand（一个要求）。乘客要求退回多收的车费，对方一再劝他算了，他仍坚持“这笔钱必须退”，丝毫不改口。他的态度就是 adamant：坚决不让步的。","original":true,"kind":"phrase_anchor","weak":false}]},"5563":{"word":"adapt","mnemonics":[{"method":"APT · 改到合适","textZh":"apt 是“合适的”，和 adapt 同源。原来的办法不合新情况，就改一改，让它变得合适：adapt 就是“调整以适应”。","kind":"word_family","original":false,"weak":false},{"method":"ADOPT 拿来，ADAPT 改合适","textZh":"把别人的食谱拿来用，是 adopt（采用）；家里人吃不了辣，就减少辣椒，把食谱改得适合自家口味，是 adapt（调整、改编）。","kind":"invented_association","original":false,"weak":false}]},"5564":{"word":"addict","mnemonics":[{"method":"ADDICTION · 人和瘾","textZh":"学过的 addiction 是“成瘾”。一个人总被同一种欲望牵着走，难以停止：addiction 说的是“瘾”，addict 作名词说的是“有瘾的人、痴迷者”。","kind":"word_family","original":false,"weak":false},{"method":"ADD IT! · 加购停不下","textZh":"把 addict 联想到 Add it!（把它加进去！）。看到喜欢的商品就想加进购物车，一件接一件，停不下来，正是 a shopping addict（购物迷）。","kind":"phrase_anchor","original":false,"weak":false}]},"5565":{"word":"adjourn","mnemonics":[{"method":"A JOURNAL · 明日再议，记入日志","textZh":"adjourn 与 journal（日记、日志）有共同的“日”的词源。想象秘书在 a journal 中记下“今天休会，明日再议”。adjourn 就是让会议暂停、延期再继续。","original":false,"kind":"word_family","weak":false},{"method":"A JOURNEY · 出差回来再续会","textZh":"把 adjourn 联想到 a journey（一次旅程）。主讲人明天要出差，主席宣布今天先休会，等他结束旅程回来再继续讨论。一次 journey 让会议暂停、延期，就想起 adjourn。","original":false,"kind":"phrase_anchor","weak":false}]},"5566":{"word":"ad-lib","mnemonics":[{"method":"ADD + LIP · 张口临时添台词","textZh":"把 ad-lib 联想到 add（添加）和 lip（嘴唇）。演员忘了原稿，嘴唇动起来，当场添出一句新台词。临场现编现说，就是 ad-lib。","original":true,"kind":"invented_association","weak":false},{"method":"AT LIBERTY · 自由发挥一段","textZh":"把 ad-lib 联想到 at liberty（可以自由地）。乐手不用预先写好的旋律，自由地选择音符，当场弹出一段新音乐。这种随想随演，就是 ad-lib，即兴发挥。","original":false,"kind":"phrase_anchor","weak":true}]},"5567":{"word":"adore","mnemonics":[{"method":"A DOOR · 门一开，满是喜爱","textZh":"把 adore 联想到 a door（一扇门）。门一打开，小狗就扑来摇尾巴，你也蹲下温柔地抱住它，满心都是喜爱。推开这扇 door，就想起 adore：深深喜爱、疼爱。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ADORABLE · 可爱得让人疼爱","textZh":"adorable 是“可爱的、讨人喜欢的”，与 adore 同属一个词族。看到一只 adorable 的小猫，你忍不住轻轻抚摸、悉心照顾；把这份强烈的喜爱说成动作，就是 adore。","original":false,"kind":"word_family","weak":false}]},"5568":{"word":"adulate","mnemonics":[{"method":"ADULATION · 把吹捧做出来","textZh":"已学过 adulation（过度赞美、吹捧）；adulate 是对应动词。把普通作品夸成“举世无双”，这种夸得过头的奉承是 adulation，做出这种奉承就是 adulate。","original":false,"kind":"word_family","weak":false},{"method":"啊，绝了！","textZh":"把 adulate 联想到“啊，绝了！”：对方随手画两笔，他就连声喊“太绝了，您真是大师！”夸赞远超实际，这就是 adulate 的过度吹捧。","original":true,"kind":"invented_association","weak":false}]},"5569":{"word":"adumbrate","mnemonics":[{"method":"UMBRELLA 的影子","textZh":"从 umbrella（伞）联到 adumbrate：伞投下的影子只显出轮廓，没有细节。两词同源于“阴影”；adumbrate 可指粗略勾勒，也可指未来的事先露出一点“影子”，即隐约预示。","original":false,"kind":"etymology","weak":false},{"method":"A DUMB BRUTE · 只说个大概","textZh":"把 adumbrate 联想到 a dumb brute（粗鲁的笨家伙）：请他描述事情，他只含糊说出大概，细节全没有。这种只给出轮廓、不展开的描述，就是 adumbrate。","original":false,"kind":"phrase_anchor","weak":false}]},"5570":{"word":"adventitious","mnemonics":[{"method":"ADVENTUROUS · 旅途意外收获","textZh":"把 adventitious 联想到 adventurous（爱冒险的）。一位爱冒险的旅行者只打算翻山，却偶然遇上一场村庄庆典；这份计划之外的意外收获，体现 adventitious 的偶然、附带之意。","original":false,"kind":"invented_association","weak":false},{"method":"ADD WET TISSUES · 后来外加的纸巾","textZh":"把 adventitious 联想到 Add wet tissues（加几张湿纸巾）。野餐篮已装好食物，又从外面加进几张湿纸巾；它们是后来另添的东西，并非篮子原有的组成部分。用这次外加，记住 adventitious：外来的、非内在的。","original":true,"kind":"phrase_anchor","weak":false}]},"5571":{"word":"adversary","mnemonics":[{"method":"ADVERSARIAL · 对抗中的对手","textZh":"已学的 adversarial 是“对抗性的”。辩论双方观点对立，形成 adversarial 的关系；站在另一方、与你交锋的那个人，就是你的 adversary（对手）。","original":false,"kind":"word_family","weak":false},{"method":"ANNIVERSARY · 周年赛再遇老对手","textZh":"把 adversary 联想到 anniversary（周年纪念）。棋社周年赛上，你又遇到去年那位步步紧逼的老对手；这次 anniversary 里与你一较高下的人，就是 adversary。","original":false,"kind":"invented_association","weak":false}]},"5572":{"word":"advert","mnemonics":[{"method":"ADVERTISEMENT · 广告的短名字","textZh":"advertisement 是广告；在英式英语里，常把它简称为 advert。报纸上那块介绍商品、吸引人注意的版面，就是 an advert。","original":false,"kind":"word_family","weak":false},{"method":"AVERT 移开，ADVERT 转向","textZh":"已学的 avert 可以表示移开目光。讨论野餐时，你没有把目光从乌云上移开，而是指着它提醒同伴，把大家的注意力转向天气。advert to the weather，就是提到天气、把注意力转向它。","original":true,"kind":"invented_association","weak":false}]},"5573":{"word":"aggrandize","mnemonics":[{"method":"GRAND · 使更大、更显赫","textZh":"grand 是“宏大的”。aggrandize 与它同源，核心就是“使更大、更显赫”：把自己的权势越扩越大，或把自己的贡献吹得很了不起。","original":false,"kind":"word_family","weak":false},{"method":"A GRAND PRIZE · 大奖提升声望","textZh":"把 aggrandize 联想到 a grand prize（一项大奖）：获奖者登上领奖台，声望和地位随之提高。大奖让人更有名、更显赫，连到 aggrandize 的“提高声望、地位”。","original":false,"kind":"phrase_anchor","weak":false}]},"5574":{"word":"aggregate","mnemonics":[{"method":"GREGARIOUS · 爱合群，聚成群","textZh":"已学的 gregarious 是“爱合群的”，与 aggregate 同源。爱合群的人把分散的伙伴招呼到一起；聚起来形成一个整体，就是 aggregate。","original":false,"kind":"word_family","weak":false},{"method":"A GREY GATE · 到灰门集合","textZh":"把动词 aggregate 联想到 a grey gate（一扇灰色的大门）：约好在灰门集合，大家从各处赶来，聚成一个整体。","original":false,"kind":"phrase_anchor","weak":false}]},"5575":{"word":"aggressive","mnemonics":[{"method":"PROGRESSIVE · 一路向前推进","textZh":"progress 是进步，progressive 是向前发展的。aggressive 与它们同属“迈步、前进”的词源家族。想象销售员主动上前，紧追目标、有力推进业务；这种积极进取的劲头，可以用 aggressive 形容。","original":false,"kind":"word_family","weak":false},{"method":"A GREAT SAVE · 主动出击扑救","textZh":"把 aggressive 联想到 a great save（一次精彩扑救）：守门员没有被动等球，而是主动冲出球门，强有力地迎球扑救。这样的防守积极主动、势头强劲，体现 aggressive 的风格。","original":true,"kind":"phrase_anchor","weak":true}]},"5576":{"word":"aggrieve","mnemonics":[{"method":"AGGRAVATE · 从加重负担到添痛苦","textZh":"已学的 aggravate 是使问题加重，aggrieve 与它同源。把困难越压越重，会给人添上痛苦；aggrieve 就是使人苦恼、委屈，尤其是因不公平对待而受伤。","original":false,"kind":"word_family","weak":false},{"method":"AGREE · 被迫点头，心里委屈","textZh":"把 aggrieve 联想到 agree（同意）：明明自己也出了力，却被迫点头，把全部功劳让给别人。这种不公平的安排让你委屈难过，就是 aggrieve。","original":true,"kind":"invented_association","weak":false}]},"5577":{"word":"agitate","mnemonics":[{"method":"A GUITAR · 半夜琴声扰人","textZh":"把 agitate 联想到 a guitar（一把吉他）：半夜邻居还在大声弹奏，你翻来覆去，越来越烦躁不安。这阵琴声正在 agitate you，使你无法平静。","original":false,"kind":"phrase_anchor","weak":false},{"method":"啊，挤太紧了 · 挤得心烦","textZh":"把 agitate 联想到“啊，挤太紧了！”：车厢越来越拥挤，你被夹在中间，心里烦躁不安。拥挤让人无法平静，正是在 agitate you。","original":true,"kind":"invented_association","weak":false}]},"5578":{"word":"agog","mnemonics":[{"method":"GO, GO! · 兴奋地催出发","textZh":"把 agog 联想到连声喊“Go, go!（走吧，走吧！）”：马上要去期待已久的演出，你兴奋地催同伴快出发。agog 就是这样满怀期待、迫不及待的。","original":false,"kind":"phrase_anchor","weak":false},{"method":"A DOG · 急盼出门","textZh":"把 agog 联想到 a dog（一只狗）：主人刚拿起牵引绳，小狗就摇着尾巴守在门口，兴奋地等着出门。这种急切期待的状态就是 agog。","original":false,"kind":"phrase_anchor","weak":false}]},"5579":{"word":"airtight","mnemonics":[{"method":"AIR + TIGHT · 空气也过不去","textZh":"air 是空气，tight 是紧密的。把罐盖拧紧到连空气都进不去、出不来，就是 airtight；用于论证时，就像把漏洞全封住，找不到可攻破的地方。","original":false,"kind":"word_components","weak":false},{"method":"I TIED · 气球口系牢","textZh":"把 airtight 联想到 I tied（我系好了）：吹足气的气球，开口已经牢牢系住，空气不再从开口漏出。把这幅“系好就不漏气”的画面连到 airtight：密封不透气。","original":true,"kind":"phrase_anchor","weak":false}]},"5580":{"word":"alibi","mnemonics":[{"method":"俺礼拜去了 · 事发时在别处","textZh":"把 alibi 联想到“俺礼拜去了”：事发时，他一直在教堂做礼拜，牧师能证明他当时在那里。这样的不在场证明，就是 alibi。","original":false,"kind":"invented_association","weak":false},{"method":"A LIE? BYE! · 看穿托辞","textZh":"把 alibi 联想到“A lie? Bye!（谎话？再见！）”：他没赴约，却编了个借口；对方看穿后转身离开。这个为失约开脱的借口，就是 alibi 的“托辞”义。","original":false,"kind":"phrase_anchor","weak":false}]},"5581":{"word":"alienate","mnemonics":[{"method":"ALIEN · 把朋友变成局外人","textZh":"已学的 alien 可以指外星人，也有陌生、外来的意思；alienate 与它同源。把朋友晾在一旁，让他觉得自己像误入人群的外星人，便是 alienate：使他疏远、产生隔阂。","original":false,"kind":"word_family","weak":false},{"method":"ALIEN + ATE · 把点心全吃光","textZh":"把 alienate 联想到 alien（外星人）和 ate（吃了）：外星朋友每次都吃光留给大家分享的点心，别人渐渐不愿再与他来往。他的自私举动 alienated his friends，使朋友疏远。","original":false,"kind":"invented_association","weak":false}]},"5582":{"word":"align","mnemonics":[{"method":"A LINE · 对成一条线","textZh":"把 align 联想到 a line（一条线）：将高低错落的画框逐个调正，让上沿落在同一条线上。align 就是对齐、调到合适的位置。","original":false,"kind":"phrase_anchor","weak":false},{"method":"A LION · 小狮子排齐合影","textZh":"看到 align，想到 a lion（一头狮子）：合影前，狮子妈妈让几只小狮子站成笔直的一排，肩膀齐平。把它们的位置排齐，就是 align。","original":true,"kind":"phrase_anchor","weak":false}]},"5583":{"word":"allegiance","mnemonics":[{"method":"ALLEGIANCE · 啊，立正！","textZh":"把 allegiance 的声音联想到“啊，立正！”：宣誓仪式开始，大家立正站好，庄重承诺忠于自己的国家。这份效忠的承诺，帮助记住 allegiance 的“忠诚、效忠”。","original":false,"kind":"invented_association","weak":false},{"method":"A LEGEND · 退役后仍然支持","textZh":"把 allegiance 联想到 a legend（一位传奇人物）：那位传奇球员已经退役，新明星不断出现，你仍多年如一日地支持他，不轻易转向别人。对一个人持久的忠诚、拥护，就是 allegiance。","original":true,"kind":"phrase_anchor","weak":false}]},"5584":{"word":"allude","mnemonics":[{"method":"ALLUDE / ALOUD · 出声却不点名","textZh":"看到 allude，联想 aloud（出声地）：朋友又忘带钥匙了，你没直说，只开口说“有位朋友今天又进不了家门了。”把话说出口，却让人自己领会忘带钥匙这件事，就是 allude to the incident。","original":false,"kind":"invented_association","weak":false},{"method":"ELUDE · 绕开直说","textZh":"已学的 elude 是躲开；看到拼写、读音相近的 allude，想象说话时也绕开直说：不说是谁弄坏了花瓶，只提一句“刚才有人在屋里踢球。”这样间接提及、让人会意，就是 allude to the incident（间接提及这件事）。","original":false,"kind":"reviewed_method","weak":false}]},"5585":{"word":"ally","mnemonics":[{"method":"RALLY · 聚到同一方","textZh":"ally 与已学的 rally（聚集、召集）同源。邻居们 rally together，一起支持保留社区花园；和你站在同一边、共同出力的人，就是 ally，盟友或支持者。","original":false,"kind":"word_family","weak":false},{"method":"A LIE · 替你澄清谎言","textZh":"把 ally 联想到 a lie（一个谎言）：有人编造谎言冤枉你，朋友站出来提供证据，帮你澄清事实。这个在困难时支持你的人，就是你的 ally。","original":true,"kind":"phrase_anchor","weak":false}]},"5586":{"word":"aloft","mnemonics":[{"method":"A LIFT · 升到高处","textZh":"把 aloft 联想到 a lift（一部电梯）：观景电梯缓缓升高，载着你来到大楼高处。Aloft 就表示在高处、向高处，也常说物体高悬在空中。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ALOOF · 独自在高处","textZh":"看到 aloft，联想已学的 aloof（疏离的）：大家在草地上聚会，他不想与人交往，独自待在高高的树屋里。Aloof 写他的疏离态度，aloft 写他所在的高处。","original":true,"kind":"invented_association","weak":false}]},"5587":{"word":"amalgamate","mnemonics":[{"method":"AMALGAMATE · 阿妈跟妹","textZh":"把 amalgamate 联想到“阿妈跟妹”：阿妈经营布店，妹妹开裁缝铺，两人把两家店合成一家，一起经营。原本分开的店合并为一个整体，就是 amalgamate。","original":false,"kind":"invented_association","weak":false},{"method":"A MEAL GOT MADE · 混成一份炒饭","textZh":"把 amalgamate 联想到 a meal got made（一顿饭做好了）：厨师把米饭、鸡蛋和蔬菜一起拌炒，原来分开的食材混合成一份炒饭。把不同成分混合成一个整体，就是 amalgamate。","original":false,"kind":"phrase_anchor","weak":false}]},"5588":{"word":"ambiguous","mnemonics":[{"method":"UNAMBIGUOUS · 去掉“不”","textZh":"已学的 unambiguous 是“清楚无歧义的”，其中 un- 表示“不”。拿掉这个“不”，ambiguous 就回到“有歧义的”：同一句话可以有两种理解，让人不能确定说的是哪一种。","original":false,"kind":"word_family","weak":false},{"method":"AMBITIOUS · 一句话，两种理解","textZh":"把 ambiguous 和形近的 ambitious（有雄心的）对照：一个 ambitious 的候选人很想当上领队，承诺“我会照顾老队员”。听众却不清楚“老队员”指年纪大的人，还是入队时间长的人。这句承诺有两种理解，就是 ambiguous。","original":false,"kind":"reviewed_method","weak":false}]},"5589":{"word":"amble","mnemonics":[{"method":"安步当车 · 悠闲地走过去","textZh":"把 amble 联想到“安步当车”：只隔两条街，你不坐车，悠闲地走过去，沿路看看花草。这样慢悠悠地走，就是 amble。","original":true,"kind":"invented_association","weak":false},{"method":"SAMPLE · 边尝边逛","textZh":"把 amble 联想到 sample（试吃、尝尝）：周末逛食品集市，你不赶时间，慢慢走到一个个摊位前，尝一点，再悠闲地往前走。这样边逛边走，就是 amble。","original":true,"kind":"invented_association","weak":false}]},"5590":{"word":"ambrosial","mnemonics":[{"method":"AMBROSIAL · 想起安慕希","textZh":"想起安慕希酸奶使用过的英文名 AMBROSIAL。由一杯香甜浓郁的酸奶，记住 ambrosial：特别美味的，也可形容香气宜人。","original":false,"kind":"reviewed_method","weak":false},{"method":"A BRO’S MEAL · 哥们做的美餐","textZh":"把 ambrosial 联想到 a bro’s meal（一位哥们做的一餐）：朋友端出香气扑鼻的饭菜，你尝一口就惊叹“太美味了！”这样香气诱人、特别美味的饭菜，就是 ambrosial。","original":true,"kind":"phrase_anchor","weak":true}]},"5591":{"word":"amenity","mnemonics":[{"method":"MEN AT EASE · 设施让人自在","textZh":"把 amenity 联想到 men at ease（自在休息的人们）：旅馆里有热水、舒适座椅和游泳池，住客因此能轻松休息。这些让生活更舒适、便利的设施，就是 amenities。","original":false,"kind":"phrase_anchor","weak":false},{"method":"A MINUTE · 停一分钟","textZh":"把 amenity 联想到 a minute（一分钟）：赶路的人想停一分钟喝口水，车站刚好设有饮水机和休息座椅。这些让短暂停留也方便舒适的设施，就是 amenities。","original":true,"kind":"phrase_anchor","weak":false}]},"5592":{"word":"amiable","mnemonics":[{"method":"AM I ABLE · 主动帮一把","textZh":"把 amiable 看成 am I able?（我能做到吗？）。新邻居搬来时，他先问自己有没有能力帮上忙，随后笑着上前招呼，主动搭把手。这样待人亲切、好相处的人，就是 amiable。","original":false,"kind":"phrase_anchor","weak":false},{"method":"AMENABLE · 合作又亲切","textZh":"把 amiable 与已学的 amenable（愿意听取意见、乐于配合的）一起记：同事愿意接受你的建议，是 amenable；他听你说话时始终笑容温和、耐心有礼，则是 amiable。记住这个既肯配合、又待人亲切的同事：amenable 写合作态度，amiable 写好相处的性情。","original":true,"kind":"invented_association","weak":false}]},"5593":{"word":"amicable","mnemonics":[{"method":"A MIC CABLE · 轮流发言","textZh":"把 amicable 联想到 a mic cable（一根话筒线）：双方轮流用同一支接线话筒说明意见，耐心听完对方的话，再商量出彼此都能接受的方案。这样的讨论和结果友好、不伤和气，正是 amicable。","original":false,"kind":"phrase_anchor","weak":false},{"method":"INIMICAL · 从敌意到和睦","textZh":"把 amicable 和已学的 inimical（有敌意的）成对记：两词都与“朋友”的词源相连，inimical 的来源是否定朋友关系，amicable 则保留友好这一面。谈判双方从敌意相向变成平心静气地协商，关系就从 inimical 转向 amicable。","original":false,"kind":"word_family","weak":false}]},"5594":{"word":"amity","mnemonics":[{"method":"AMICABLE · 友好相处，结成友谊","textZh":"amity 与刚学过的 amicable（友好的、和睦的）同源。两家人商量怎样照料共有花园时，气氛是 amicable；日后他们也常常互相帮助。他们之间逐渐建立的友好关系，就是 amity。","original":false,"kind":"word_family","weak":false},{"method":"A MEETING · 一次会面交朋友","textZh":"把 amity 联想到 a meeting（一次会面）：两位原本不熟悉的邻居见面后聊得很投机，后来常来往、互相帮忙。这次会面带来的友谊与和睦关系，就是 amity。","original":true,"kind":"phrase_anchor","weak":false}]},"5595":{"word":"anodyne","mnemonics":[{"method":"AN OLD LINE · 一句老套的话","textZh":"把 anodyne 联想到 an old line（一句老套的话）：有人被问到尖锐的问题，只说“大家都要开心”，既不冒犯谁，也没提供什么新内容。这种温和却平淡无味的回应，就是 anodyne。","original":true,"kind":"phrase_anchor","weak":false},{"method":"俺脑袋 · 不疼了","textZh":"把 anodyne 联想到“俺脑袋不疼了”：故事里的人原先捂着头，疼痛缓解后终于松开眉头，说出这句话。Anodyne 可表示缓解疼痛的；作名词也指止痛药。","original":false,"kind":"invented_association","weak":false}]},"5596":{"word":"anarchist","mnemonics":[{"method":"AN- + HIERARCHICAL · 不要统治者","textZh":"已学的 hierarchical 表示等级分明，它与 anarchist 都有“统治者”这一词源线索。an- 表示“没有”：想象有人撤去国王高高在上的宝座，主张大家平等协作，不要统治者。这个人就是 anarchist，无政府主义者。","original":false,"kind":"etymology","weak":false},{"method":"AN ARTIST · 画家主张自治","textZh":"把 anarchist 联想到 an artist（一位艺术家）：这位画家画出一座没有统治者的城市，居民靠自愿协作处理公共事务；他也公开主张这样的社会。画家在这个故事里是一位 anarchist。","original":true,"kind":"phrase_anchor","weak":false}]},"5597":{"word":"anemic","mnemonics":[{"method":"ANEMIA → ANEMIC · 贫血到乏力","textZh":"已学过 anemia（贫血；比喻缺乏活力），anemic 是对应形容词：a person with anemia 是 anemic 的人；比喻一场没有活力的表演，也可说 an anemic performance。","original":false,"kind":"word_family","weak":false},{"method":"ANEMIC · A NEW MIC","textZh":"把 anemic 联想到 a new mic（新麦克风）：歌手换了新麦克风，唱出来仍然软绵绵、没有精神。这种缺乏活力的表演，就是 anemic。","original":true,"kind":"phrase_anchor","weak":false}]},"5598":{"word":"anesthetic","mnemonics":[{"method":"AESTHETIC · 从美感到无感觉","textZh":"已学的 aesthetic（审美的）与 anesthetic 都来自“感觉”这一词源；an- 表示“无”。Aesthetic 关乎对美的感受，anesthetic 则指使感觉消失的，或已经无感觉的。","original":false,"kind":"etymology","weak":false},{"method":"俺是铁的 · 碰了也没感觉","textZh":"把 anesthetic 联想到“俺是铁的”：童话里的铁皮人拍拍胳膊，别人轻触它，它一点感觉也没有。由铁皮人没有触觉，记住 anesthetic 的“麻木的、无感觉的”。","original":true,"kind":"invented_association","weak":false}]},"5599":{"word":"annoy","mnemonics":[{"method":"A NOISE · 噪声惹人烦","textZh":"把 annoy 联想到 a noise（一阵噪声）：你正在看书，旁边的敲笔声却一直响。a noise 会 annoy you，让你心烦。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ANNOY · 俺恼了","textZh":"把 annoy 的声音联想到“俺恼了”：别人反复打断你，你终于恼了。这种让人心烦、惹人生气的行为，就会 annoy someone。","original":false,"kind":"invented_association","weak":false}]},"5600":{"word":"antagonize","mnemonics":[{"method":"ANTAGONISTIC → ANTAGONIZE · 惹出敌意","textZh":"已学的 antagonistic 表示敌对的，antagonize 是同词族动词：本来愿意合作的同伴，因你反复讥讽而变得 antagonistic。这些讥讽 antagonize him，使他对你产生敌意。","original":false,"kind":"word_family","weak":false},{"method":"俺大哥恼了 · 挑衅惹反感","textZh":"把 antagonize 联想到“俺大哥恼了”：有人当众嘲弄大哥，还不断贬低他的作品，大哥终于恼火，不愿再与那人合作。这样的言行会 antagonize him，激怒他并引起敌意。","original":true,"kind":"invented_association","weak":false}]},"5601":{"word":"anterior","mnemonics":[{"method":"ANTI-REAR · 后面的相反","textZh":"把 anterior 联想到 anti-rear：rear 是后面，把“朝后”反过来就是朝前。脑中把指向背后的箭头转到面前，记住 anterior 表示前面的、位于前方的。","original":false,"kind":"phrase_anchor","weak":false},{"method":"ANTERIOR / INTERIOR · 前面与里面","textZh":"把 anterior 和 interior（内部）放在一座房子上记：房子的前侧是 the anterior part，屋子里面则是 the interior。anterior 来自表示“在前”的 ante：既可以在空间上靠前，也可以在时间上更早。","original":false,"kind":"invented_association","weak":false}]},"5602":{"word":"antic","mnemonics":[{"method":"ANTIQUE · 古董上的怪模样","textZh":"由 antique（古董）联想 antic：想象古董面具上夸张扭曲的脸，怪模怪样又滑稽。两词确实同源，antic 的含义从古代艺术中的怪异形象发展而来，记住它表示滑稽古怪的。","original":false,"kind":"etymology","weak":false},{"method":"ANTIC · 俺踢！","textZh":"把 antic 联想到“俺踢！”：小丑喊着这句话，穿着大鞋夸张地踢腿，转了一圈又向观众做鬼脸。这样的动作可以说 an antic gesture，antic 形容它滑稽古怪。","original":true,"kind":"invented_association","weak":false}]},"5603":{"word":"aphorism","mnemonics":[{"method":"A PHRASE · 短句有道理","textZh":"把 aphorism 联想到 a phrase（一个短语或简短说法）：一大段人生经验，被浓缩成“少即是多”这样短小而有道理的话。这样的警句，就是 an aphorism。","original":false,"kind":"phrase_anchor","weak":false},{"method":"A FAIR REASON · 一句话说明白","textZh":"把 aphorism 联想到 a fair reason（一个合理的理由）：朋友问为什么要坚持练习，你不用长篇解释，只答“熟能生巧”。一句简短的话讲出普遍道理，就是 aphorism。","original":true,"kind":"phrase_anchor","weak":false}]},"5604":{"word":"apocalyptic","mnemonics":[{"method":"A POCKET LIPSTICK · 写下末日警告","textZh":"把 apocalyptic 联想到 a pocket lipstick（一支便携口红）：末日电影里，女主角从口袋取出口红，在玻璃上留下“世界即将毁灭”的警告。这是一则 apocalyptic warning，预言末日的警告。","original":true,"kind":"phrase_anchor","weak":false},{"method":"APOCRYPHAL · 可疑的末日预言","textZh":"把 apocalyptic 与已学的 apocryphal（真实性可疑的）放在一则传闻里：有人声称明天世界就会毁灭，却拿不出可信来源。这是一则 apocalyptic prediction，预言末日；同时也是一则 apocryphal story，真假难辨。","original":true,"kind":"invented_association","weak":true}]},"5605":{"word":"apoplectic","mnemonics":[{"method":"POP + ELECTRIC · 一声响后气炸了","textZh":"把 apoplectic 联想到 pop（砰的一声）和 electric（电的）：电脑电源砰地一响，突然断电，整天没保存的成果全没了。主人气得满脸通红、厉声怒喊，简直 apoplectic，暴怒不已。","original":true,"kind":"invented_association","weak":false},{"method":"POP’S LECTURE · 老爸气急训话","textZh":"把 apoplectic 联想到 Pop’s lecture（老爸的训话）：老爸发现孩子故意毁掉别人辛苦做好的模型，气得脸涨红，激动地大声训斥。这位怒不可遏的老爸就是 apoplectic。","original":false,"kind":"phrase_anchor","weak":true}]},"5606":{"word":"apostasy","mnemonics":[{"method":"A POST SAYS · 帖子宣布离开","textZh":"把 apostasy 联想到 a post says（一篇帖子写道）：“我不再信奉原来的宗教了。”这个人明确放弃曾经的信仰，这一行为就是 apostasy。","original":false,"kind":"phrase_anchor","weak":false},{"method":"STASIS · 离开原来的立场","textZh":"已经学过 stasis，静止、停留。apostasy 中的“站立”词族与它相通，apo- 表示离开：把原先坚定站着的地方想成自己的信仰立场，如今转身离开、不再信奉，就是 apostasy，放弃原有信仰。","original":false,"kind":"word_family","weak":false}]},"5607":{"word":"appall","mnemonics":[{"method":"PALE · 吓得脸色发白","textZh":"appall 与 pale（苍白的）有词源联系。想象你推开厨房门，发现遍地污水、食物腐烂，惊得脸色发白：这样的情景会 appall you，使你惊骇不安。","original":false,"kind":"etymology","weak":false},{"method":"A FALL · 珍品跌落","textZh":"把 appall 联想到 a fall（一次跌落）：展架轰然倒下，珍贵的玻璃雕塑摔成碎片。亲眼看见这种惨状的人惊骇不已，这场跌落 appalls them。","original":false,"kind":"phrase_anchor","weak":false}]},"5608":{"word":"appeal","mnemonics":[{"method":"A PILL · 恳求帮忙找药","textZh":"把 appeal 联想到 a pill（一粒药）：旅人发现随身带的一粒药不见了，着急而诚恳地请同伴一起寻找。这声求助就是 an appeal for help，恳请别人帮忙。","original":true,"kind":"phrase_anchor","weak":false},{"method":"APPLE · 红苹果的吸引力","textZh":"看到 appeal，联想熟悉的 apple：一颗鲜红饱满的苹果摆在眼前，让人忍不住想咬一口。这种吸引人的力量，就是 appeal。","original":false,"kind":"invented_association","weak":false}]},"5609":{"word":"appealing","mnemonics":[{"method":"APPEAL → APPEALING · 有吸引力","textZh":"刚学过的 appeal 可以表示吸引力。温暖的灯光、柔软的靠垫和一本好书，让阅读角充满 appeal；所以这个角落很 appealing，吸引人想坐下来。","original":false,"kind":"word_family","weak":false},{"method":"PEELING · 剥开就诱人","textZh":"把 appealing 联想到 peeling（剥皮）：刚剥开的橘子露出鲜亮果肉，清甜果香让人忍不住想尝一瓣。这样的水果很 appealing，诱人、有吸引力。","original":false,"kind":"invented_association","weak":false}]},"5610":{"word":"applause","mnemonics":[{"method":"A PAUSE · 停下来，掌声响起","textZh":"把 applause 联想到 a pause（一次停顿）：演讲者讲完令人振奋的一段，停下来稍作等待，台下立刻响起热烈的掌声。这阵鼓掌声就是 applause。","original":true,"kind":"phrase_anchor","weak":false},{"method":"PLAUSIBLE · 说得有理，赢得掌声","textZh":"想起已学的 plausible（看似合理可信的），它与 applause 同出“拍手、赞同”的词源。演讲者提出一个说得通的方案，听众纷纷拍手赞同；这阵掌声就是 applause。","original":false,"kind":"word_family","weak":false}]},"5611":{"word":"appreciable","mnemonics":[{"method":"APPRECIATE · 能清楚察觉的变化","textZh":"已学的 appreciate 除了“感谢”，还可以表示充分认识到、察觉到。appreciable 与它同族：原本昏暗的屋子拉开窗帘后明显亮起来，变化大到你能清楚察觉，这就是 an appreciable increase in light，可察觉的光线增加。","original":false,"kind":"word_family","weak":false},{"method":"A PRICE TABLE · 价格表上一眼可见的降幅","textZh":"把 appreciable 联想到 a price table（一张价格表）：同一件商品原价100元，如今只要60元。对照表格，降价幅度一眼可见，这就是 an appreciable reduction，明显的减少。","original":true,"kind":"phrase_anchor","weak":false}]},"5612":{"word":"apprehension","mnemonics":[{"method":"APPREHEND · 担心会出差错","textZh":"已学的 apprehend 可以表示预想到坏事而忧惧。上台之前，你担心会忘词、说错话；这种还没发生就先担心起来的心情，就是 apprehension，忧虑、不安。","original":false,"kind":"word_family","weak":false},{"method":"COMPREHENSION · 阅读题前的担心","textZh":"看到 apprehension，想起课堂上熟悉的 reading comprehension（阅读理解）。考试还没开始，你担心长文章读不懂、题目做不完，心里越来越不安；这种对将来表现的担忧就是 apprehension。","original":true,"kind":"invented_association","weak":false}]},"5613":{"word":"apprise","mnemonics":[{"method":"A PRIZE · 通知获奖","textZh":"把 apprise 联想到 a prize（一项奖）：比赛结果公布后，工作人员打电话告知你已经获奖，并说明领奖时间。这个“把消息通知给你”的动作就是 apprise。","original":false,"kind":"phrase_anchor","weak":false},{"method":"SURPRISE · 提前告知就不意外","textZh":"看到 apprise，联想熟悉的 surprise（意外、惊讶）：如果没人通知，突然停电会让你吃惊；若管理员提前 apprise you of the power cut，告知停电安排，你就有了准备。","original":false,"kind":"invented_association","weak":false}]},"5614":{"word":"archetype","mnemonics":[{"method":"ARCHAIC + TYPE · 最初的样式","textZh":"已经学过 archaic，古老的、旧式的。archetype 和它同源的部分也与“最初”有关，再接上熟悉的 type（类型、式样）：最初作为范本、供后来者参照的样式，就是 archetype，原型；也可指一类事物最典型的代表。","original":false,"kind":"word_family","weak":false},{"method":"A KEY TYPE · 英雄的代表形象","textZh":"把 archetype 联想到 a key type（一个重要的类型）：童话有各种人物类型，其中勇敢、无私的英雄尤其重要。那位冒险救人、不求回报的骑士，把英雄的关键特征集中在一身，是英雄的 archetype，典型代表。","original":true,"kind":"phrase_anchor","weak":false}]},"5615":{"word":"ardor","mnemonics":[{"method":"ADORE · 喜爱化成热情","textZh":"把 ardor 联想到刚学过的 adore（非常喜爱）。她深深爱着舞蹈，一谈起舞台就双眼发亮，迫不及待地投入排练；这份强烈的热爱与激情，就是 ardor。","original":false,"kind":"invented_association","weak":false},{"method":"HARDER · 越练越有热情","textZh":"把 ardor 联想到 harder（更努力地）。长跑爱好者满怀热情，训练结束还兴致勃勃地说“我要再努力些”，主动加练；推动他投入的这股热忱就是 ardor。","original":false,"kind":"invented_association","weak":false}]},"5616":{"word":"arduous","mnemonics":[{"method":"HARD USE · 重活磨损工具","textZh":"把 arduous 联想到 hard use（高强度使用）：连续几天手工锯木，锯齿都磨钝了，干活的人也累得双臂酸痛。工具经受重度使用，人做的是 arduous work，艰苦费力的工作。","original":false,"kind":"phrase_anchor","weak":false},{"method":"啊，巨石 · 搬动它真费力","textZh":"把 arduous 联想到“啊，巨石！”：路中间横着一块大石头，几个人一起用力推了许久，才挪开一点。这样需要花很大力气的工作，就是 arduous，艰巨费力的。","original":true,"kind":"invented_association","weak":false}]},"5617":{"word":"arresting","mnemonics":[{"method":"ARREST · 抓住目光","textZh":"想起已学的 arrest（使停止、抓住）：一幅鲜明的画仿佛把你的目光拦住，让你停下脚步看个不停。能这样抓住注意力的，就是 arresting，引人注目的。","original":false,"kind":"word_family","weak":false},{"method":"A RED STRING · 一根红绳特别醒目","textZh":"把 arresting 联想到 a red string（一根红绳）：一身纯白衣服上，只用这根红绳系出一个鲜艳的大蝴蝶结，立刻吸引周围人的目光。这处醒目的装饰就是 arresting。","original":true,"kind":"phrase_anchor","weak":false}]},"5618":{"word":"arrhythmic","mnemonics":[{"method":"RHYTHM · 节拍失去规律","textZh":"看到 arrhythmic，先抓住完整的 rhythm（节奏）。它的词源表示“没有节奏”：鼓点一会儿挤在一起，一会儿隔很久才响，听不出稳定的拍子，就是 arrhythmic，节奏不规则的。","original":false,"kind":"etymology","weak":false},{"method":"ARITHMETIC · 算数打乱鼓点","textZh":"把 arrhythmic 联想到 arithmetic（算术）：鼓手一边打鼓一边心算，难题让他忽快忽慢，原本均匀的鼓点全乱了。这种失去稳定节奏的鼓声就是 arrhythmic。","original":true,"kind":"invented_association","weak":false}]},"5619":{"word":"arrogance","mnemonics":[{"method":"ARROGANT · 傲慢的态度","textZh":"想起已学的 arrogant（傲慢的）：别人提出建议，他却认定自己最懂，连听都不肯听。arrogant 形容这个人，arrogance 就是他表现出的傲慢、自大。","original":false,"kind":"word_family","weak":false},{"method":"A RUG DANCE · 只许我站中央","textZh":"把 arrogance 联想到 a rug dance（一场在地毯上的舞蹈）：领舞者认定别人都不如自己，把同伴赶到边上，独占中央。这份自以为高人一等的态度，就是 arrogance，傲慢、自大。","original":true,"kind":"phrase_anchor","weak":false}]},"5620":{"word":"ascendant","mnemonics":[{"method":"ASCENDING ORDER · 从小到大往上升","textZh":"把 ascendant 联到 ascending order（升序）：1、2、3、4 越排越大。再想一个新人职位不断上升、越来越能影响决定；他正处于 ascendant 的状态，地位上升、影响力增强。","original":false,"kind":"word_family","weak":false},{"method":"A SENTENCE · 一句话就能定调","textZh":"把 ascendant 联想到 a sentence（一句话）：原本没人听他的意见，如今他只说一句话，大家就照着安排。这变化显出他的影响力正在上升，他已 in the ascendant，占了上风。","original":true,"kind":"phrase_anchor","weak":false}]},"5621":{"word":"aseptic","mnemonics":[{"method":"ACCEPT IT · 合格才接收","textZh":"把 aseptic 联想到 accept it（接收它）：实验室只接收无菌材料，检验确认这批材料没有致病微生物后，负责人说“Accept it.” 被接收的材料是 aseptic，无菌的。","original":true,"kind":"phrase_anchor","weak":false},{"method":"A SCEPTIC · 冷冰冰的文字","textZh":"把 aseptic 联想到 a sceptic（一个怀疑者），想起已学的 skeptical。他只认数据，竟把朋友热情洋溢的故事改成一份毫无温度的报告。这种缺乏情感、冷冰冰的文风，可以用 aseptic 形容。","original":true,"kind":"phrase_anchor","weak":false}]},"5622":{"word":"aspect","mnemonics":[{"method":"INSPECT · 换着角度看","textZh":"aspect 与 inspect（仔细检查）同属“看”的词族。检查一座房子时，从外观、采光到隔音逐项查看；每一个被考察的方面，就是 an aspect。","original":false,"kind":"word_family","weak":false},{"method":"EXPECT · 期待之外的外观","textZh":"把 aspect 联想到 expect（期待）：住客期待一间明亮温馨的客房，推门却看见深色墙面和昏暗灯光。房间实际呈现出的阴沉样子，就是它的 gloomy aspect，阴沉的外观。","original":true,"kind":"invented_association","weak":false}]},"5623":{"word":"asperity","mnemonics":[{"method":"EXASPERATE · 恼火后的硬语气","textZh":"看到 asperity，联想学过的 exasperate（使人烦透）。反复被打断，把他惹得忍无可忍；他终于生硬地回了一句，语气里的粗暴和不耐烦就是 asperity。","original":false,"kind":"word_family","weak":false},{"method":"A SPARE KEY · 丢钥匙后的责怪","textZh":"把 asperity 联想到 a spare key（一把备用钥匙）。他翻遍抽屉仍找不到备用钥匙，急得冲家人说：“连钥匙都管不好！”话里的尖刻和粗暴，就是 asperity。","original":true,"kind":"phrase_anchor","weak":false}]},"5624":{"word":"aspirant","mnemonics":[{"method":"爱拼的人 · 立志争上游","textZh":"把 aspirant 联想到“爱拼的人”：别人只说想拿冠军，他却每天主动练习、朝冠军努力；这个有抱负、争取成功的人，就是 aspirant。","original":true,"kind":"invented_association","weak":true},{"method":"ASPIRIN · 立志研发有用的药","textZh":"看到 aspirant，联想到 aspirin（阿司匹林）：学生希望将来研发出像阿司匹林一样能帮助人的药，便以药物研究员为目标，认真学习药学。这个有志实现职业目标的人，就是 an aspirant。","original":true,"kind":"invented_association","weak":false}]},"5625":{"word":"assent","mnemonics":[{"method":"CONSENT · 双方点头同意","textZh":"把 assent 与 consent（同意、许可）这一同源词放在一起：家长在同意书上签名，孩子也点头赞同活动安排。双方都表达了同意，孩子的点头就是 assent。","original":false,"weak":false,"kind":"word_family"},{"method":"AS SENT · 原样同意刊登","textZh":"把 assent 联想到 as sent（按寄来时的原样）：编辑读完来稿，不要求修改，点头同意按寄来的原样刊登。这个明确的点头赞同，就是 assent。","original":false,"weak":false,"kind":"phrase_anchor"}]},"5626":{"word":"assertive","mnemonics":[{"method":"ASSERT · 清楚表达自己的主张","textZh":"回想已学的 assert：坚定地表达主张、维护权利。讨论时，一个人清楚地说‘我也想把意见讲完’，让别人认真听取自己的想法。这样主动而自信的表达方式，就是 assertive。","original":false,"weak":false,"kind":"word_family"},{"method":"UH, SORT OF? · 有话明确说","textZh":"把 assertive 近音联到“Uh, sort of…（呃，算是吧……）”，用反面对照来记。别人问能否占用你的展示时间，你明明不愿意，就别含糊附和，而是平静明确地说：“我需要这段时间展示自己的作品。”这样敢于清楚表达自己需要的态度，就是 assertive。","original":false,"weak":false,"kind":"phrase_anchor"}]},"5627":{"word":"assess","mnemonics":[{"method":"ASSET · 给资产估价","textZh":"把 assess 联到 asset（资产）：准备出售房屋时，先请人查看位置、面积和房屋状况，再估出这项资产值多少钱。给 asset 作这样的估价，就是 assess。","original":false,"weak":false,"kind":"invented_association"},{"method":"ACCESS · 先评估再准入","textZh":"把 assess 联到 access（进入、使用的机会）：攀岩馆教练先让新学员做几个基本动作，评估他的能力，再决定能否让他使用较难的攀岩区。取得 access 之前的这一步评估，就是 assess。","original":true,"weak":false,"kind":"invented_association"}]},"5628":{"word":"asunder","mnemonics":[{"method":"THUNDER · 雷雨劈开树干","textZh":"把 asunder 联到 thunder（雷声）：雷雨中电光一闪，闪电把一棵老树从中劈开。树干分成两半的结果，就是 split asunder，劈裂开。","original":false,"kind":"invented_association","weak":false},{"method":"啊，散了！· 拼图落地","textZh":"把 asunder 联想到“啊，散了！”：刚拼好的拼图掉到地上，原来连成一片的图案散成许多块。由这一声惊呼，记住 asunder 的分离开、化为碎片。","original":false,"kind":"invented_association","weak":false}]},"5629":{"word":"asylum","mnemonics":[{"method":"A SILENT ROOM · 躲进安静屋里","textZh":"把 asylum 联到 a silent room（一间安静的房间）：逃难者躲进屋里，屋主关门保护他；他保持 silent，免得引来追赶的人。这间让他免受伤害的屋子，就是 an asylum，避难所。","original":true,"kind":"phrase_anchor","weak":false},{"method":"A SAILOR · 暴雨中进港避难","textZh":"把 asylum 联到 a sailor（一位水手）：海上暴风雨来临，水手赶紧进港，躲进港边坚固的屋子。让他避开风暴、得到安全保护的地方，就是 an asylum，避难所。","original":true,"kind":"phrase_anchor","weak":false}]},"5630":{"word":"asymmetrical","mnemonics":[{"method":"A- + SYMMETRICAL · 镜子两边不一样","textZh":"symmetrical 是数学课里“对称的”：沿中线两边像照镜子一样相互对应。asymmetrical 前面的 a- 表示“没有”。想象一件外套，左边长袖、右边短袖，两边不再对应，就是不对称的 asymmetrical。","original":false,"weak":false,"kind":"word_components"},{"method":"A SIMPLE TRICK · 对折露出差别","textZh":"把 asymmetrical 联想到 a simple trick（一个简单的小办法）。检查纸面具时，沿中线一对折：一边眼孔高，一边低，怎么也重合不了。这个小办法一下找出不对称，面具就是 asymmetrical。","original":true,"weak":true,"kind":"phrase_anchor"}]},"5631":{"word":"atone","mnemonics":[{"method":"AT ONE · 补偿后重归于好","textZh":"atone 原来与 at one（和好、一致）有关。你弄坏朋友的椅子后，主动修好并承担材料费，两人终于重归于好。用行动弥补自己的过错，就是 atone。","original":false,"weak":false,"kind":"etymology"},{"method":"A TONE · 语气诚恳，更要补过","textZh":"把 atone 联想到 a tone（一种语气）。你先前说话伤了朋友的心，后来换成诚恳的语气道歉，还主动帮他完成困难的工作作为补偿。语气变了，行动也弥补了过错，这才是在 atone。","original":false,"weak":false,"kind":"phrase_anchor"}]},"5632":{"word":"atrocious","mnemonics":[{"method":"啊，臭死了！· 饭菜糟透了","textZh":"把 atrocious 联想到“啊，臭死了！”：午饭时打开忘在书包里几天的饭盒，一股臭味扑鼻而来，饭菜已经坏得无法入口。这种糟糕透顶的状态，就是 atrocious。","original":true,"weak":false,"kind":"invented_association"},{"method":"PRECOCIOUS · 小天才也会演砸","textZh":"把近形近音的 atrocious 与已学的 precocious（早熟的）成对记：早熟的小演员平时表演出色，这次却接连忘词、抢错节拍，演出糟糕透顶。孩子是 precocious，这次演出却是 atrocious。","original":false,"weak":false,"kind":"known_word_rhyme"}]},"5633":{"word":"augur","mnemonics":[{"method":"AUGUST · 提前看八月收成","textZh":"把 augur 联想到 August（八月）。七月还没过完，果农看到枝头已经挂满幼果，便预计八月有望丰收。眼前这些迹象 augur well for the harvest，预示收成不错。","original":false,"weak":false,"kind":"invented_association"},{"method":"熬过 · 好迹象预示能撑过去","textZh":"把 augur 联想到“熬过”。寒冬还没结束，温室里的幼苗已经恢复生机；园丁据此判断，它们有望熬过接下来的寒冷。这些迹象 augur well，预示好结果。","original":true,"weak":false,"kind":"invented_association"}]},"5634":{"word":"authentic","mnemonics":[{"method":"AUTHOR + TICK · 作者验真打勾","textZh":"把 authentic 联到 author（作者）和 tick（打勾）：作家翻看几页珍藏的手稿，认出自己的字迹和修改痕迹，便在作品清单上打勾，确认它们都是自己的亲笔原稿。这些由作者本人确认的真品，就是 authentic。","original":false,"weak":false,"kind":"invented_association"},{"method":"ALL TEN TICKETS · 十张票都验真","textZh":"把 authentic 联想到 all ten tickets（全部十张票）：十位朋友入场前，把十张演出票交给检票员逐张扫码，每一张都是官方发行的真票。这些经过核验的票，都是 authentic，货真价实的。","original":true,"weak":false,"kind":"phrase_anchor"}]},"5635":{"word":"authority","mnemonics":[{"method":"AUTHOR · 写出权威著作的人","textZh":"authority 和 author（作者）同出一个历史词族。想起一位研究鸟类多年的作者：他写的鸟类图鉴人人都拿来查证，他本人也被视为这一领域的权威。这样的专家就是 an authority on birds。","original":false,"weak":false,"kind":"etymology"},{"method":"ALL THIRTY · 全体成员共同授权","textZh":"把 authority 联想到 all thirty（三十人全体）。社团的三十名成员共同授权一位负责人决定活动日程，从此由他安排各项事务；他得到的这项决定权，就是 authority。","original":true,"weak":false,"kind":"phrase_anchor"}]},"5636":{"word":"autocracy","mnemonics":[{"method":"AUTO + -CRACY · 权力归自己","textZh":"autocracy 的 auto- 表示“自己”，像自动模式 AUTO 那样由自己运转；-cracy 表示统治。想象全国事务全由一个统治者自己决定，无人能制约他的权力。这就是 autocracy，独裁统治。","original":false,"weak":false,"kind":"word_components"},{"method":"AUTO + CRAZY · 爱车的独裁者","textZh":"把 autocracy 联到 auto（汽车）和 crazy（疯狂的）两个熟词。一个爱车成狂的国王，看中谁的车就下令收归自己，任何人都无权阻止；从他一人说了算的无限权力，记住 autocracy，独裁统治。","original":false,"weak":false,"kind":"invented_association"}]},"5637":{"word":"averse","mnemonics":[{"method":"AVERSION · 从厌恶到不愿做","textZh":"回想已学 aversion（厌恶）：面对自己反感的冒险活动，总想避开。大家邀请你攀岩，你仍不愿参加；aversion 是心里的厌恶，averse 描写这种不情愿的态度，如 averse to taking risks。","original":false,"weak":false,"kind":"word_family"},{"method":"A VERSE · 一段也不想唱","textZh":"把 averse 联想到 a verse（一段歌词）。你不喜欢当众唱歌，主持人说“只唱一段就行”，你还是摇头，不愿上台；这种对做某事的排斥就是 averse。","original":false,"weak":false,"kind":"phrase_anchor"}]},"5638":{"word":"bale","mnemonics":[{"method":"背了 · 不幸带来悲苦","textZh":"借“背了，真倒霉！”记 bale。辛苦保存的旧照片被水浸毁，他一边说这句话，一边难过地收拾残页。这场不幸带来的悲哀，就是旧时 bale 所指的苦痛。","original":false,"weak":false,"kind":"invented_association"},{"method":"BALL · 压紧捆成大包","textZh":"bale 的“一大捆”义与 ball（球）有共同历史来源。想象把松散干草聚拢成圆滚滚的一大团，再压紧、捆牢；这样便得到 a bale of hay，一大捆干草。","original":false,"weak":false,"kind":"etymology"}]},"5639":{"word":"baleful","mnemonics":[{"method":"BALE · 会带来灾祸的","textZh":"刚学的 bale 有“灾祸、悲苦”义。童话里一股黑烟飘过，原本茂盛的花草纷纷枯萎；baleful 描写这种会带来祸害的力量，baleful effects 就是有害的影响。","original":false,"weak":false,"kind":"word_components"},{"method":"BANEFUL · 阴狠目光里的威胁","textZh":"回想已学 baneful（有害的），把相近的完整词 baleful 连到一幅新画面：童话里的守门人阴沉地盯住来客，目光让人感到他随时可能加害。这样的 baleful look，就是带着恶意、令人不安的目光。","original":false,"weak":false,"kind":"invented_association"}]},"5640":{"word":"balk","mnemonics":[{"method":"WALK · 叫它走，它偏不走","textZh":"把 balk 联想到 walk（走）。主人催马继续走，马却在栅栏前猛地停住，怎么叫也不肯前进：它 balks，突然停下并拒绝继续。","original":false,"weak":false,"kind":"invented_association"},{"method":"BLOCK · 挡住整个计划","textZh":"把 balk 联想到 block（阻挡）。本来准备当天开业，出口却被一道封死的门挡住，整个计划因此受阻。Balk 也可表示阻挠，使某人的行动或计划受挫。","original":false,"weak":false,"kind":"invented_association"}]},"5641":{"word":"balky","mnemonics":[{"method":"BALK · 动不动就不肯配合","textZh":"上一词 balk 是突然停下、拒绝继续。小狗听见回家的招呼就坐住不动，每次催它都不肯走；这种倔强、不听使唤的样子就是 balky。Balky 由 balk 加 -y 构成。","original":false,"weak":false,"kind":"word_family"},{"method":"BAD KEY · 琴键偏不听使唤","textZh":"把 balky 联想到 a bad key（一枚失灵的琴键）。想好好弹琴，偏有一枚键总卡住，按下去时响时不响；整架琴都变得不听使唤。这样的钢琴就是 a balky piano。","original":true,"weak":false,"kind":"invented_association"}]},"5642":{"word":"balderdash","mnemonics":[{"method":"BALD + DASH · 冲刺能长出头发？","textZh":"把 balderdash 联想到 bald（秃头的）和 dash（猛冲）。一位秃头男子扬言，只要每天猛冲一百米，头发就能一夜长到脚边。众人听后说：Balderdash！这种荒唐的说法就是一派胡言。","original":false,"weak":false,"kind":"invented_association"},{"method":"饱得打嗝，还说没吃？","textZh":"把 balderdash 联想到“饱得打嗝”。一个人刚吃完大餐，撑得打嗝，却一本正经地说自己一整天滴米未进。旁人听见这番明显不实的话，直说：Balderdash，一派胡言！","original":false,"weak":true,"kind":"invented_association"}]},"5643":{"word":"balm","mnemonics":[{"method":"CALM · 让心平静的安慰","textZh":"把 balm 联到 calm（平静）。朋友难过时，你安慰几句，让他慢慢 calm down；这些舒缓心情的话就是 a balm。药膏舒缓身体的不适，安慰则像心里的药膏。","original":false,"weak":false,"kind":"invented_association"},{"method":"PALM · 掌心里的药膏","textZh":"把 balm 联想到 palm（手掌）：掌心干裂，取一点药膏轻轻抹开，让干痛的皮肤得到舒缓。记住 balm on your palm，手掌上涂的是 balm，舒缓用的膏剂。","original":false,"weak":false,"kind":"invented_association"}]},"5644":{"word":"bane","mnemonics":[{"method":"BANEFUL · 有害事物的祸根","textZh":"回想已学 baneful（有害的）：有毒废水带来 baneful effects，鱼虾纷纷死亡；这股造成危害的废水就是当地河流的 bane，祸害之源。Baneful 形容有害，bane 指带来危害的东西。","original":false,"weak":false,"kind":"word_family"},{"method":"PAIN · 带来痛苦的根源","textZh":"Bane 与 pain（痛苦）押韵。夏夜蚊子不停叮咬，让人又痒又睡不好；这群不断带来烦恼的蚊子，就是你夏夜的 bane。用 bane brings pain 记住：bane 是痛苦或麻烦的来源。","original":false,"weak":false,"kind":"invented_association"}]},"5645":{"word":"barb","mnemonics":[{"method":"BARBER · 胡茬像小刺","textZh":"Barb 与 barber（理发师）都与“胡须”同源。想到理发师摸到一片硬硬的胡茬，短毛像小刺一样扎手：barb 就是尖刺、倒刺，也能指刺伤人感受的尖刻话。","original":false,"weak":false,"kind":"word_family"},{"method":"BARK · 一句话刺痛人","textZh":"把 barb 联想到 bark（吠叫、厉声说）。他冲着同伴的画嚷道：“这也叫画？三岁小孩都比你强！”这句话像刺一样扎人，便是一句 barb，尖刻挖苦的话。","original":true,"weak":false,"kind":"invented_association"}]},"5646":{"word":"barefaced","mnemonics":[{"method":"BARE + FACE · 连脸都不遮","textZh":"Bare 是“无遮盖的”，face 是“脸”。想到一个人做了亏心事，连脸都不遮，还若无其事地当众撒谎。Barefaced 形容公然的、厚颜无耻的；a barefaced lie 就是毫不掩饰的谎言。","original":false,"weak":false,"kind":"word_components"},{"method":"BEAR FEAST · 大熊吃了还抵赖","textZh":"把 barefaced 联想到 bear feast（大熊的盛宴）。童话里的大熊独吞了一桌蜂蜜点心，嘴边还沾着蜜，却当着大家说：“我一口都没吃！”这就是 barefaced，明目张胆地做坏事、撒谎也毫不羞愧。","original":true,"weak":false,"kind":"invented_association"}]},"5647":{"word":"baroque","mnemonics":[{"method":"BROKE · 装饰得花光钱","textZh":"把 baroque 联想到 broke（身无分文）。为了把大厅装点得金碧辉煌，他给柱子加满雕花，给天花板镶满金饰，最后花得一文不剩。Broke 提醒你：baroque 可以形容装饰繁复、雕琢过度。","original":false,"weak":false,"kind":"invented_association"},{"method":"BARE ROCK · 裸石也要雕满花","textZh":"把 baroque 联想到 bare rock（光秃秃的石头）。雕刻师嫌石面太素，把每一寸都刻上层层卷花，连一点留白都不肯留。原本简单的裸石被装饰得极其繁复，成了 baroque 的设计。","original":true,"weak":false,"kind":"invented_association"}]},"5648":{"word":"barrage","mnemonics":[{"method":"BAR + RAGE · 怒气变成连珠炮","textZh":"把 barrage 联想到 bar（酒吧）里的 rage（怒火）。球迷看见球队失利，气得接二连三地大喊质问，声音像炮火一样密集袭来。这样一阵劈头盖脸的连番攻击，就是 a barrage。","original":false,"weak":false,"kind":"invented_association"},{"method":"BARRIER · 炮火筑成屏障","textZh":"Barrage 和 barrier（屏障）同源。密集炮火一道接一道落下，像筑起一道屏障，阻止对方前进；这样的火力网就是 barrage。它也可指拦住河水的堰坝。","original":false,"weak":false,"kind":"word_family"}]},"5649":{"word":"barren","mnemonics":[{"method":"BARE · 光秃秃，长不出庄稼","textZh":"把 barren 联想到 bare（光秃秃的）。这片地土层贫瘠，播下种子也难长出庄稼，放眼望去只有裸露的地面。Bare 的空裸画面带出 barren，贫瘠、不毛的。","original":false,"weak":false,"kind":"invented_association"},{"method":"BARREL · 种了几年，果篮仍空","textZh":"把 barren 联想到 barrel（桶）。一个大木桶里种着果树，主人照料了几年，树却始终不结果；到了收获季，旁边的果篮还是空的。这棵树是 barren 的，不结果、没有产出。","original":true,"weak":false,"kind":"invented_association"}]},"5650":{"word":"barricade","mnemonics":[{"method":"BARRIER · 横在路上的障碍","textZh":"把 barricade 联想到 barrier（障碍物）：施工人员把一排护栏横放在路口，车辆无法通过。这道阻路的屏障就是 barricade，也可以说他们 barricade the road，把路封住。","original":false,"weak":false,"kind":"invented_association"},{"method":"BARREL GATE · 木桶堵住大门","textZh":"把 barricade 联想到 barrel gate（木桶围成的门障）。居民把几个大木桶紧挨着排在门口，人无法穿过；这些木桶构成 barricade，挡住了通路。","original":true,"weak":false,"kind":"invented_association"}]},"5651":{"word":"barter","mnemonics":[{"method":"BARBER · 理发换面包","textZh":"把 barter 联想到 barber（理发师）：面包师替他烤面包，他替面包师理发，双方不用钱，以服务和货物交换。这就是 barter。","original":false,"weak":false,"kind":"invented_association"},{"method":"BUTTER · 黄油换蔬菜","textZh":"把 barter 联想到 butter（黄油）：农夫提着自家黄油去集市，用它换回一篮蔬菜，没有付钱。拿东西换东西，就是 barter。","original":false,"weak":false,"kind":"invented_association"}]},"5652":{"word":"bathetic","mnemonics":[{"method":"PATHETIC · 悲情演过了头","textZh":"把 bathetic 与学过的 pathetic（令人怜悯的）对照：小狗受伤让人心疼；演员却为掉了一根铅笔抱头痛哭、长篇告别，煽情过火，令人觉得矫情可笑。这种故作感伤就是 bathetic。","original":false,"weak":false,"kind":"invented_association"},{"method":"BATH TICKET · 壮烈出征去洗澡","textZh":"把 bathetic 联想到 bath ticket（洗澡票）。他挥着票慷慨激昂地说“我要踏上伟大的征程！”结果只是去澡堂泡澡。庄严气势突然落到琐事，令人啼笑皆非，就是 bathetic。","original":false,"weak":false,"kind":"invented_association"}]},"5653":{"word":"bedeck","mnemonics":[{"method":"BED + DECK · 床边与甲板挂满花","textZh":"把 bedeck 联想到 bed（床）和 deck（甲板）：婚礼前，屋里的床边挂满花环，船上的甲板也铺上彩带。把这些地方装点得漂亮，就是 bedeck。","original":false,"weak":false,"kind":"invented_association"},{"method":"BEAD + NECK · 颈间珠饰","textZh":"把 bedeck 联想到 bead（珠子）和 neck（脖子）：她把一串彩珠戴在颈间，又搭上鲜花，打扮得光彩夺目。用珠饰和花朵装点自己，就是 bedeck。","original":true,"weak":false,"kind":"invented_association"}]},"5654":{"word":"beneficent","mnemonics":[{"method":"BENEFIT · 让别人真正受益","textZh":"Beneficent 与 benefit（使人受益）同源。志愿者送来热饭、修好漏雨的屋顶，把好处实实在在送到有需要的人手里。Beneficent 就是积极行善、帮助别人的。","original":false,"weak":false,"kind":"word_family"},{"method":"BEEN EFFICIENT · 高效送去救助","textZh":"把 beneficent 联想到 been efficient（一直很高效）。救援志愿者迅速把饭菜和毛毯送到受灾家庭，大家感叹他们办事真高效；这些实际帮助人的善举是 beneficent。","original":false,"weak":false,"kind":"invented_association"}]},"5655":{"word":"berate","mnemonics":[{"method":"BE LATE · 迟到挨训","textZh":"把 berate 联想到 be late（迟到）：队员总是迟到，教练忍无可忍，接连数落他不守时、耽误全队。这样严厉而持续地责骂他，就是 berate him。","original":false,"weak":false,"kind":"invented_association"},{"method":"BERRY + ATE · 偷吃莓果被痛斥","textZh":"把 berate 联想到 berry（莓果）和 ate（吃了）：孩子偷偷吃光了留给客人的莓果，大人发现后气得连声责骂。大人这样接连痛斥他，就是 berate him。","original":false,"weak":false,"kind":"invented_association"}]},"5656":{"word":"beseech","mnemonics":[{"method":"SEEK · 急切寻求帮助","textZh":"Beseech 与 seek（寻求）同源，be- 加强语气。想象你四处 seek help，终于找到能帮忙的人，急切地求他：“请一定帮帮我！”这种恳切而迫切的请求，就是 beseech。","original":false,"weak":false,"kind":"etymology"},{"method":"BE SICK · 生病时恳求陪伴","textZh":"把 beseech 联想到 be sick（生病）：孩子生病后特别不安，拉住妈妈的手，一遍遍恳求：“请再陪我一会儿！”这种急切的恳求，就是 beseech。","original":false,"weak":false,"kind":"invented_association"}]},"5657":{"word":"besmirch","mnemonics":[{"method":"BE SMART · 耍聪明却抹黑别人","textZh":"把 besmirch 联想到 be smart（聪明行事）：一个竞争者自以为聪明，捏造对手作弊的谣言，想借此胜出。他做的却是 besmirch someone’s reputation，把别人的名声抹黑。","original":true,"weak":true,"kind":"invented_association"},{"method":"BASE + MARCH · 泥靴踩脏地毯","textZh":"把 besmirch 联想到 base（基地）和 march（行进）：队伍从泥泞的基地走进大厅，沾满泥的靴子一路踩过，把干净的地毯弄脏了。泥脚印使地毯失去洁净，就是 besmirch the carpet。","original":true,"weak":false,"kind":"invented_association"}]},"5658":{"word":"bifurcate","mnemonics":[{"method":"FORK · 一条路分成两岔","textZh":"Bifurcate 与 fork（叉子、岔路）同源，开头的 bi- 表示二。想象一条路到了路口，分成左、右两支，像一把两齿叉。Bifurcate 就是分成两支，或把一个整体一分为二。","original":false,"weak":false,"kind":"etymology"},{"method":"BEFORE THE GATE · 门前岔成两路","textZh":"把 bifurcate 联想到 before the gate（在大门前）：一条小路到了大门前，分成左、右两条，绕向花园两侧。一条路分成两支，就是 bifurcate。","original":true,"weak":false,"kind":"invented_association"}]},"5659":{"word":"bigot","mnemonics":[{"method":"BIG GOAT · 只容得下自己的羊","textZh":"把 bigot 联想到 big goat（大山羊）：童话里的大山羊坚持“只有和我一样的羊才配进村”，把其他动物统统赶走。这样固守偏见、排斥异己的角色，就是 bigot。","original":false,"weak":false,"kind":"invented_association"},{"method":"BE GOD · 自封唯一的真理","textZh":"把 bigot 联想到 be God（当上帝）：一个人把自己当成绝不会错的最高裁判，认定只有自己的信念正确，凡是持不同意见的人都该被排斥。这个自封正确、容不下异见的人，就是 bigot。","original":false,"weak":false,"kind":"invented_association"}]},"5660":{"word":"blandishment","mnemonics":[{"method":"BLAND DISH · 无味的菜也被夸上天","textZh":"把 blandishment 联想到 bland dish（清淡无味的菜）：客人明明觉得菜没滋味，却不断夸主人厨艺高超，好让主人答应帮忙。这种带着劝诱目的的奉承话，就是 blandishment。","kind":"invented_association","original":false,"weak":false},{"method":"BRANDISH · 挥着礼物哄人","textZh":"联想到已学的 brandish（挥动展示）：有人挥着两张演出票，笑着夸朋友最懂音乐，想哄朋友陪自己去。这些讨好、诱劝的话语和举动，就是 blandishments。","kind":"invented_association","original":false,"weak":false}]},"5661":{"word":"blasé","mnemonics":[{"method":"BLAH + SAY · 听腻了的反应","textZh":"把 blasé 联想到 blah（吧啦吧啦）和 say（说）：影星每天听到同样的赞美，渐渐不再兴奋，心里只想说“blah, blah, blah”。这种听惯了、见惯了而无动于衷的态度，就是 blasé。","original":false,"weak":false,"kind":"invented_association"},{"method":"BE LAZY · 玩具多得懒拆","textZh":"把 blasé 联想到 be lazy（懒得动）：孩子天天收到新玩具，起初开心，后来见惯了，新的礼盒摆到面前也懒得拆。享受太多而提不起兴趣，就是 blasé。","original":true,"weak":false,"kind":"invented_association"}]},"5662":{"word":"blast","mnemonics":[{"method":"BLOW · 一阵猛风","textZh":"blast 与 blow（吹）同源。想到窗外猛地吹来一股强风，窗帘一下被掀起；这样突然袭来的强劲气流，就是 a blast of wind。","kind":"word_family","original":false,"weak":false},{"method":"LAST BLAST · 最后一声号响","textZh":"把 blast 联想到 last（最后的）：演出最后，号手吹出一声响亮的长音，声音猛地传遍全场。这最后一声号响，记作 the last blast。","kind":"invented_association","original":true,"weak":false}]},"5663":{"word":"blatant","mnemonics":[{"method":"LATENT · 从暗藏到明目张胆","textZh":"已学 latent 是潜藏、没有显露的。一个人起初把偏见藏在心里，后来竟当众拒绝让某群人进门，完全不掩饰；原先 latent 的偏见变成 blatant discrimination，公然明显的歧视。","kind":"invented_association","original":false,"weak":false},{"method":"BLAST + TENT · 帐篷里震耳的音乐","textZh":"把 blatant 联想到 blast（大声播放）和 tent（帐篷）：别人已经睡下，帐篷里却仍把音乐放得震耳欲聋，毫不顾忌邻居。这种肆无忌惮、惹人反感的喧闹，就是 blatant。","kind":"invented_association","original":false,"weak":false}]},"5664":{"word":"blazon","mnemonics":[{"method":"摆阵 · 盾徽齐齐朝外","textZh":"把 blazon 联想到“摆阵”：队伍列好阵势，把绘有家徽的盾牌齐齐朝外，让远处的人也看清。这样醒目地展示徽章，就是 blazon。","original":true,"weak":false,"kind":"invented_association"},{"method":"PLAY ZONE · 玩乐区的大招牌","textZh":"把 blazon 联想到 play zone（玩乐区）：游乐场把 PLAY ZONE 几个字放大涂满入口墙面，让路人远远就能看清。这样把文字醒目地展示出来，就是 blazon。","original":true,"weak":false,"kind":"invented_association"}]},"5665":{"word":"bliss","mnemonics":[{"method":"BLESS · 被祝福包围的幸福","textZh":"把 bliss 联想到 bless（祝福）：婚礼上，亲友围着新人送上祝福，两人握着手，觉得此刻幸福圆满。这样的极大幸福，就是 bliss。","kind":"invented_association","original":false,"weak":false},{"method":"BLITHE · 欢乐无忧的状态","textZh":"已学 blithe 是欢乐无忧的，它与 bliss 同源。想到 blithe 的孩子在花园里自在玩耍，心里没有烦恼，只有满满的快乐；这种幸福的状态，就是 bliss。","kind":"word_family","original":false,"weak":false}]},"5666":{"word":"blueprint","mnemonics":[{"method":"BLUE + PRINT · 图上先画好","textZh":"blue 是蓝色，print 是印制的图。想到一张蓝底白线的建筑图，房间、门窗和尺寸都先画得清清楚楚，工人按图施工。这样的详细设计图是 blueprint，也可用来指指导行动的周密计划。","kind":"etymology","original":false,"weak":false},{"method":"BLUE PRINCE · 蓝衣王子先规划","textZh":"把 blueprint 联想到 blue prince（蓝衣王子）：王子想建花园，先在纸上规划小路、花坛和水池，再让工人动工。他事先详细规划这座花园，就是 blueprint the garden。","kind":"invented_association","original":false,"weak":false}]},"5667":{"word":"blunder","mnemonics":[{"method":"BLENDER · 忘盖盖子的大失误","textZh":"把 blunder 联想到 blender（搅拌机）：他倒进果汁，却忘记盖好盖子就启动，果汁飞得到处都是。这个本可避免的粗心失误，就是 a blunder。","kind":"invented_association","original":false,"weak":false},{"method":"BLIND · 看不清，乱闯进去","textZh":"把 blunder 联想到 blind（看不见的）：停电后，他看不清方向，摸索着乱走，误闯进别人的房间。这样迷迷糊糊、跌跌撞撞地走进去，就是 blunder into a room。","kind":"invented_association","original":false,"weak":false}]},"5668":{"word":"blurt","mnemonics":[{"method":"BLUR · 没想清，嘴先说了","textZh":"联想到已学的 blur（模糊）：脑子还一片模糊，没想清什么能说，嘴已经抢先把秘密说出来。这样未经思考便脱口而出，就是 blurt。","kind":"invented_association","original":false,"weak":false},{"method":"BURST · 话像气球突然爆出","textZh":"联想到 burst（爆开）：气球突然爆开，正像话一下冲出嘴。别人话还没说完，他就没经思考地把秘密说出来，这叫 blurt。","kind":"invented_association","original":false,"weak":false}]},"5669":{"word":"boggle","mnemonics":[{"method":"BOTTLE · 瓶里是什么，不敢喝","textZh":"把 boggle 联想到 bottle（瓶子）：桌上有一瓶来历不明的饮料，颜色和气味都很奇怪。他把瓶子拿到嘴边，又因疑虑停下来，迟迟不敢喝。这样因怀疑、害怕而犹豫退缩，就是 boggle。","kind":"invented_association","original":false,"weak":false},{"method":"GOOGLE · 越搜越想不通","textZh":"把 boggle 联想到 Google（谷歌）：想查清一个问题，却搜到一长串相互矛盾的解释，看得越来越困惑，脑子一时转不过来。这些复杂信息让人困惑不解，正是 boggle 的“使困惑”义。","kind":"invented_association","original":false,"weak":false}]},"5670":{"word":"boisterous","mnemonics":[{"method":"BOYS STIR US · 男孩们把大家也带动起来","textZh":"把 boisterous 联想到 boys stir us（男孩们让我们也兴奋起来）：生日聚会上，男孩们欢呼起舞，把旁人也带得又唱又跳。这样喧闹、兴奋、充满活力的场面，就是 boisterous。","kind":"invented_association","original":false,"weak":false},{"method":"BOLSTER · 大声为队友鼓劲","textZh":"把 boisterous 联想到已学的 bolster（支持、鼓励）：看台上的人一起跳起来，挥着旗，大声为队员鼓劲。这样喧闹、兴奋、精力充沛的场面，就是 boisterous。","kind":"invented_association","original":true,"weak":false}]},"5671":{"word":"bombast","mnemonics":[{"method":"BOMB + BLAST · 空话像爆炸","textZh":"想到 bomb（炸弹）和刚学的 blast（爆炸）：演讲者把几句空泛口号喊得像炸弹爆响，声势惊人，却连一个可行办法都说不出。这种声势大、内容空的浮夸言辞，就是 bombast。","kind":"invented_association","original":false,"weak":false},{"method":"BOAST · 把小事吹成壮举","textZh":"把 bombast 联想到 boast（夸耀）：一个人只是搬了两把椅子，却宣称自己“以无与伦比的力量，奠定了伟大事业的基石”。这样把小事包装成宏大壮举的空洞辞令，就是 bombast。","kind":"invented_association","original":false,"weak":false}]},"5672":{"word":"bonhomie","mnemonics":[{"method":"BORN HAPPY · 天生乐呵呵","textZh":"把 bonhomie 联想到 born happy（天生快乐）：他总是笑呵呵的，见到新朋友也自然地招呼、聊天，让人很快放松下来。这份乐天又亲切的友善，就是 bonhomie。","kind":"invented_association","original":true,"weak":false},{"method":"BUNS ON ME · 面包我请，大家来坐","textZh":"把 bonhomie 联想到 buns on me（面包我请）：刚认识的人坐在一起，他笑着请大家吃面包，主动搭话，让整桌人很快有说有笑。这份自然、愉快的亲切友善，就是 bonhomie。","kind":"invented_association","original":true,"weak":false}]},"5673":{"word":"boo","mnemonics":[{"method":"不！· 拉长声的反对","textZh":"把 boo 联想到拉长声音的“不——！”：观众看到明显不公平的判罚，齐声发出不满的嘘声，向裁判喝倒彩。这样的反对声就是 boo。","kind":"invented_association","original":true,"weak":false},{"method":"BOOK · 书后突然冒出来","textZh":"把 boo 联想到 book（书）：弟弟把脸藏在一本大书后，等姐姐走近，突然探出头喊“Boo！”，想吓她一跳。记住这声突然冒出的“吓你一下”。","kind":"invented_association","original":true,"weak":false}]},"5674":{"word":"boorish","mnemonics":[{"method":"BOOKISH · 读过很多书仍不懂礼貌","textZh":"把 boorish 联想到已学的 bookish（书卷气的）：一个满屋藏书的人，却当面讥笑来访者的问题，还不让客人把话说完。他读书很多，待人却粗鲁无礼，表现得很 boorish。","kind":"invented_association","original":true,"weak":false},{"method":"BOO + RUSH · 嘘声后冲上来抢话","textZh":"把 boorish 联想到刚学的 boo（喝倒彩）和 rush（猛冲）：别人还没讲完，他先发出嘘声，又冲到前面抢话，完全不顾对方的感受。这种粗鲁无礼的举止，就是 boorish。","kind":"invented_association","original":false,"weak":false}]},"5675":{"word":"bootless","mnemonics":[{"method":"BOOT + LESS · 忘了靴子，白忙一场","textZh":"把 bootless 联想到 boot（靴子）和 less（没有）：兴冲冲带着滑雪板到了雪场，才发现没带滑雪靴，怎么摆弄装备也没法开始滑雪。这番准备落了空，正好记住 bootless 的“徒劳、无成效”。","kind":"invented_association","original":false,"weak":false},{"method":"BOTTLES · 空瓶倒不出水","textZh":"把 bootless 联想到 bottles（瓶子）：你想给花浇水，把桌上的瓶子一只只倒过来，却发现它们全是空的，一滴水也倒不出。这样的尝试没有任何收获，就是 bootless。","kind":"invented_association","original":true,"weak":false}]},"5676":{"word":"bound","mnemonics":[{"method":"BOUNCE · 像球一样弹跳","textZh":"把 bound 联想到 bounce（弹跳）：小狗追着弹起的皮球，自己也一蹦一跳地向前冲。记住这种轻快的大步跳跃：bound 可作动词“跳跃前进”，也可作名词“一跃”。","kind":"invented_association","original":false,"weak":false},{"method":"BOUNDARY · 球越过了边线","textZh":"想到已学的 boundary（边界）：球一滚过场边的白线，裁判就判 out of bounds（出界）。boundary 让你抓住 bound 的“界限”义；这个意思常用复数 bounds。","kind":"word_family","original":true,"weak":false}]},"5677":{"word":"boycott","mnemonics":[{"method":"BOYCOTT 先生 · 大家拒绝和他来往","textZh":"boycott 来自一位姓 Boycott 的土地代理人的名字。他企图驱逐拒付地租的农户后，工人和仆人不再替他做事，社区也拒绝和他往来。人们用这种集体不合作来抗议，后来就把“抵制”叫作 boycott。","kind":"word_family","original":false,"weak":false},{"method":"BOY + CUT · 男孩们切断消费","textZh":"把 boycott 联想到 boy（男孩）和 cut（切断）：几个男孩发现一家店欺负顾客，便一起停止去买东西，还约定店家改正后才再光顾。这样用拒绝交易来表达抗议，就是 boycott。","kind":"invented_association","original":true,"weak":false}]},"5678":{"word":"bracing","mnemonics":[{"method":"RACING · 跑起来，精神也醒了","textZh":"把 bracing 联想到 racing（赛跑）：清凉的早晨和朋友沿河赛跑，活动开身体后，原先的困意全消了，整个人精神起来。这样令人焕发活力的活动，就是 bracing。","kind":"invented_association","original":true,"weak":false},{"method":"EMBRACING · 张开双臂拥抱海风","textZh":"把 bracing 联想到已学的 embrace（拥抱），进行形式 embracing：来到海边，你张开双臂拥抱迎面吹来的清凉海风，深吸一口气，整个人精神一振。这股使人神清气爽的劲儿，就是 bracing。","kind":"invented_association","original":true,"weak":false}]},"5679":{"word":"brash","mnemonics":[{"method":"BRUSH · 抓起画笔就夸口","textZh":"把 brash 联想到 brush（画笔）：新来的同学刚抓起画笔，就宣布“你们都让开，我闭着眼也比你们画得好！”这种过分自信、说话不顾别人的傲慢劲儿，就是 brash。","kind":"invented_association","original":true,"weak":false},{"method":"CRASH · 不听提醒就撞倒布景","textZh":"把 brash 联想到 crash（碰撞）：排练时，一个演员不听“先看看身后”的提醒就猛地转身，撞倒了旁边的布景。这样不考虑后果、贸然行动，就是 brash。","kind":"invented_association","original":true,"weak":false}]},"5680":{"word":"brassy","mnemonics":[{"method":"BRASS · 铜管声又亮又冲","textZh":"brass 是黄铜，也指铜管乐器。想象一支铜管乐队在近处吹奏，声音亮得刺耳，听众忍不住捂住耳朵。Brassy 可以形容这种响亮、带金属感而显得刺耳的声音。","kind":"word_family","original":false,"weak":false},{"method":"BRASH · 冒失之后还理直气壮","textZh":"联想刚学过的 brash（冒失、自以为是的）：一个人不看排队顺序就冲到最前面，被提醒后还大声说“我就是要先办！”Brash 帮你想起冒失的行为；brassy 则抓住他不顾别人、厚着脸皮张扬的态度。","kind":"invented_association","original":true,"weak":false}]},"5681":{"word":"bravado","mnemonics":[{"method":"BRAVE · 勇敢只是做给人看","textZh":"看到 bravado，联想 brave（勇敢的）：明明害怕跳水，却在朋友面前拍胸口说“这有什么，我闭着眼都敢跳！”这种故意显得无所畏惧、给别人看的胆量，就是 bravado。","kind":"invented_association","original":false,"weak":false},{"method":"BRAVADO · 嘴上说“不怕的”","textZh":"把 bravado 近音联想成“不怕的”：进鬼屋前，他一直对朋友说“不怕的！”，门刚打开却先躲到了别人身后。嘴上装得胆大、实际心虚的劲儿，就是 bravado。","original":true,"weak":true,"kind":"invented_association"}]},"5682":{"word":"bravura","mnemonics":[{"method":"BRAVO · 技艺让全场叫好","textZh":"看到 bravura，联想观众叫好的 bravo：钢琴家把一段又快又难的曲子弹得流畅精彩，最后一个音落下，全场鼓掌喊“Bravo！”让人惊叹的精湛技艺，就是 bravura。","kind":"invented_association","original":false,"weak":false},{"method":"BRAVERY·艺高人胆大","textZh":"把 bravura 联想到 bravery（勇气），再想到“艺高人胆大”：杂技演员敢在高空做复杂动作，靠的是练得极熟的高超技艺。Bravura 抓住这种令人赞叹的技巧展示。","kind":"invented_association","original":false,"weak":false}]},"5683":{"word":"brazen","mnemonics":[{"method":"BRASS · 一张不知羞的铜脸","textZh":"brazen 和 brass（黄铜）属于真实词族，本来就可表示“黄铜制的”。想象一个人脸像黄铜一样，被当场揭穿撒谎还毫不脸红，反而说“我就这样，怎么了？”这副公开做错事却毫不羞耻的样子，就是 brazen。","kind":"word_family","original":false,"weak":false},{"method":"BRAINS · 聪明没用在正道上","textZh":"把 brazen 联想到 brains（脑子、聪明才智）：一个人动脑筋设计了作弊办法，被人抓住后还当众夸耀自己“真聪明”，一点也不觉得丢脸。记住这种明目张胆、厚颜无耻的表现，就是 brazen。","kind":"invented_association","original":true,"weak":false}]},"5684":{"word":"breach","mnemonics":[{"method":"BREAK · 把约定打破了","textZh":"breach 和 break 属于真实词族。两人本来约好保守秘密，其中一人却把秘密告诉了别人；他“打破”了约定，也造成了信任的裂口。Breach 因而既可表示违反约定，也可表示关系中的裂痕。","kind":"word_family","original":false,"weak":false},{"method":"BEACH · 沙堡被冲出缺口","textZh":"看到 breach，联想 beach（海滩）：孩子在海滩堆了一圈沙堡城墙，一波海水冲来，把墙冲开一个大口子。这个被冲破的缺口，就是 a breach；海水也可以 breach the wall，冲破城墙。","kind":"invented_association","original":false,"weak":false}]},"5685":{"word":"bribe","mnemonics":[{"method":"BRIDE · 红包换放行","textZh":"看到 bribe，联想 bride（新娘）：婚礼迟到了，新娘身边的人把红包塞给门卫，求他破例放车进去。用财物换对方违规帮忙，就是 bribe：贿赂、收买。","kind":"invented_association","original":false,"weak":false},{"method":"BRIDGE · 塞钱过桥","textZh":"把 bribe 联想到 bridge（桥）：一辆超载货车被拦在桥前，司机偷偷给检查员塞钱，想让他违规放行。用钱换取本不该得到的通行，就是 bribe。","original":true,"kind":"invented_association","weak":false}]},"5686":{"word":"brisk","mnemonics":[{"method":"RISK · 再磨蹭就误车","textZh":"看到 brisk，联想 risk（风险）：再磨蹭就有误车的风险，他立刻快步走向车站，步子轻快而有力。Brisk 形容这种迅速、精神十足的行动。","kind":"invented_association","original":false,"weak":false},{"method":"BREEZE · 清风一吹精神来","textZh":"把 brisk 联想到 breeze（微风）：清晨一阵清凉的风吹来，他深吸一口气，困意消散，整个人精神起来。Brisk 也形容清新、令人振奋的空气或天气。","kind":"invented_association","original":true,"weak":false}]},"5687":{"word":"brittle","mnemonics":[{"method":"BRISTLE · 硬毛一弯就断","textZh":"联想已学 bristle（硬毛）：旧刷子上的一根硬毛已经干脆，想把它弯一下，它却啪地折断。Brittle 强调硬却缺乏韧性、受力容易断裂。","kind":"invented_association","original":true,"weak":false},{"method":"BOTTLE · 玻璃瓶硬却易碎","textZh":"把整个 brittle 联想到 bottle（瓶子）：一只薄玻璃瓶摸起来很硬，却经不起碰撞，落地便碎裂。Brittle 抓住的正是这种坚硬却容易破碎的性质。","kind":"invented_association","original":true,"weak":false}]},"5688":{"word":"broach","mnemonics":[{"method":"APPROACH · 走近后开口谈","textZh":"联想 approach（走近）：他走近老师，终于开口说“我想讨论一下小组分工。”从走近对方到主动开启话题，broach 就是提出话题供讨论。","kind":"invented_association","original":false,"weak":false},{"method":"BREACH · 给封桶打开缺口","textZh":"联想刚学的 breach（缺口）：一只封着的酒桶被第一次钻开孔，酒从孔中流出。Broach 本就可指给酒桶开孔、开封取酒；把封口打开，也就能记住它开启话题的用法。","kind":"invented_association","original":false,"weak":false}]},"5689":{"word":"bromide","mnemonics":[{"method":"BRO MIGHT · 哥们可能又说那句","textZh":"把 bromide 近音联想到一句“Bro might say it again.”（哥们可能又要说那句了）。每逢朋友遇到困难，他就重复“时间会解决一切”，听众连下一句都猜得到。这种听腻了的老套安慰话，就是 bromide。","kind":"invented_association","original":true,"weak":false},{"method":"BORED MIND · 套话听得脑袋发困","textZh":"把 bromide 联想到 bored mind（感到无聊的脑袋）：演讲者又说“成功离不开努力”，听众觉得毫无新意，听得昏昏欲睡。这种令人厌倦的陈词滥调，就是 bromide。","original":true,"kind":"invented_association","weak":true}]},"5690":{"word":"browbeat","mnemonics":[{"method":"eyeBROW + BEAT · 横眉压人","textZh":"看到 browbeat，想到 eyebrow（眉毛）里的 brow 和 beat（打击）：对方横眉怒目，拍着桌子逼你答应，话语像一拳拳压过来。这种靠凶狠态度和言语威逼人屈服，就是 browbeat。","kind":"word_family","original":false,"weak":false},{"method":"BRO, BEAT IT! · 凶声赶人","textZh":"把 browbeat 近音联想成“Bro, beat it!”（伙计，滚开！）：霸道的人堵住门，恶狠狠地逼你离开。记住这句带威胁的喝斥，browbeat 就是用强硬言语恐吓、逼迫。","kind":"sound_association","original":false,"weak":false}]},"5691":{"word":"bruit","mnemonics":[{"method":"FRUIT · 水果谣言传开","textZh":"看到 bruit，联想形近的 fruit（水果）：有人说“这批水果里全有虫”，大家没核实就一传十、十传百。把消息到处散播，就是 bruit。","kind":"invented_association","original":true,"weak":false},{"method":"BRUTE · “野兽”传遍全村","textZh":"bruit 和 brute 同音。村里有人传“新邻居是个 brute（残暴的家伙）”，没见过他的人也跟着到处说。记住大家把这条说法传开的动作，就是 bruit。","kind":"sound_association","original":true,"weak":false}]},"5692":{"word":"buck","mnemonics":[{"method":"BACK · 顶回不合理要求","textZh":"把 buck 联想到 back（回去）：有人要求他无偿替别人干完所有活，他把这个不合理要求顶回去，明确表示反对。Buck 在这里表示抵制、反抗。","kind":"invented_association","original":true,"weak":false},{"method":"BOOK · 一本书一块钱","textZh":"把 buck 联想到 book（书）：旧书摊上，一本书只卖一美元，他拿出一块钱买下它。口语里，a buck 就是一美元。","kind":"invented_association","original":true,"weak":false}]},"5693":{"word":"budge","mnemonics":[{"method":"BUDGET · 预算一分也不让","textZh":"把 budge 联想到 budget（预算）：双方商量活动经费，他坚持原来的预算，别人再劝也不肯加一分钱。He won't budge，表示他不肯改变立场、让步。","kind":"invented_association","original":true,"weak":false},{"method":"JUDGE · 裁判终于松口","textZh":"把 budge 联想到 judge（裁判）：裁判起初坚持不调整安排，听完队员充分的理由，终于松口同意改动。Budge 在这里就是改变原先坚持的立场。","kind":"invented_association","original":true,"weak":false}]},"5694":{"word":"bulge","mnemonics":[{"method":"BULB · 鼓起的灯泡肚","textZh":"把 bulge 联想到 bulb（灯泡）：灯泡中间圆鼓鼓，向外突出的肚子十分显眼。Bulge 就像这样的鼓起部分，也可作动词表示鼓起来。","kind":"invented_association","original":true,"weak":false},{"method":"BUDGET · 钱袋装鼓了","textZh":"联想 budget（预算）；它和 bulge 都可追到“皮袋”这个词源。把预算里的硬币全放进皮袋，袋面被撑得鼓起来。Bulge 抓住这个向外鼓起的形状。","kind":"word_family","original":false,"weak":false}]},"5695":{"word":"bully","mnemonics":[{"method":"BULL · 仗着牛劲欺负人","textZh":"看到 bully，想到 bull（公牛）：把恶霸想成一头仗着自己力气大、专挑弱小动物欺负的公牛。记住“强的欺负弱的”，bully 就是欺凌者，也可表示欺凌。","kind":"spelling_association","original":false,"weak":false},{"method":"BELLY · 冲着肚子威胁","textZh":"把 bully 和形近的 belly（肚子）连起来：恶霸盯着小孩的肚子威胁说，不交出点心就要动手。belly 这幅受威胁的画面，把 bully 的“欺凌、威逼”钩回来。","kind":"spelling_association","original":false,"weak":false}]},"5696":{"word":"bumptious","mnemonics":[{"method":"BUMP US · 撞开别人抢着指挥","textZh":"把 bumptious 近音联想到 bump us（撞我们）：一个人觉得自己最了不起，撞开挡路的人，还抢着指挥大家。这种不顾别人、自以为是的强势，就是 bumptious。","kind":"sound_association","original":false,"weak":false},{"method":"PUMP + SHOW · 吹胀自己再显摆","textZh":"把 bumptious 近音联想到 pump + show（打气后炫耀）：他先给自己的气球头像打足气，再站上桌高声宣布“全听我的！”那股把自己看得过大的专横劲，就是 bumptious。","kind":"sound_association","original":false,"weak":true}]},"5697":{"word":"buoyant","mnemonics":[{"method":"BUOY · 从浮标到振作","textZh":"联想学过的 buoy（浮标；托起）：浮标稳稳浮在水面，把东西托住。buoyant 就是能浮起来、有浮力；人的心情像被托起来，也可说 buoyant，表示乐观振作。","kind":"word_family","original":false,"weak":false},{"method":"BOY + ANT · 男孩送蚂蚁过水","textZh":"把 buoyant 近音拆成 boy + ant（男孩和蚂蚁）：男孩让蚂蚁坐上小木片，木片载着它浮过水面。记住能浮起来的小木片，buoyant 就是有浮力、能漂浮的。","kind":"sound_association","original":false,"weak":false}]},"5698":{"word":"burnish","mnemonics":[{"method":"BURN · 烧黑后擦亮","textZh":"看到 burnish，联想到 burn（烧）：金属锅被火烧黑了，主人反复用布摩擦，终于把它擦得发亮。记住烧黑之后要擦亮，burnish 就是擦亮、磨光，不是烧。","kind":"spelling_association","original":false,"weak":false},{"method":"BROWN · 棕色铜器擦出光泽","textZh":"把 burnish 和 brown（棕色）连着记：它的词源与棕色有关。想象棕黄色铜器反复擦拭后泛出亮光，记住擦亮、磨光。","kind":"etymology","original":false,"weak":false}]},"5699":{"word":"byzantine","mnemonics":[{"method":"拜占庭 · 宫廷里层层牵连","textZh":"Byzantine 就是“拜占庭的”。借这个中文名字联想旧宫廷：一道命令牵涉几派人马，各有暗中安排，绕来绕去才办得成。由这层语义来历记住 byzantine：错综复杂，也可带诡秘权谋的意味。","kind":"etymology","original":false,"weak":false},{"method":"BUSY TEEN · 少年忙于层层手续","textZh":"把 byzantine 的一种美式读音近音联想到 busy teen（忙碌的少年）：少年办张借阅证，却被相互牵连的盖章和复核手续弄得团团转。让少年忙乱的不是事情多，而是流程错综复杂，这就是 byzantine。","kind":"sound_association","original":true,"weak":false}]},"5700":{"word":"cache","mnemonics":[{"method":"CASH · 把现金藏好","textZh":"cache 与 cash（现金）同音。想到把一沓 cash 藏进秘密小箱：藏好的这批钱是一份 cache，箱子也可作藏物处。","kind":"sound_association","original":false,"weak":false},{"method":"CATCH · 藏好才抓不到","textZh":"把 cache 和近音的 catch（抓到）连起来：松鼠把备用坚果藏进窄树洞，来抢食的猫怎么伸爪也 catch 不到。树洞里的秘密储备，就是 cache。","kind":"sound_association","original":false,"weak":false}]},"5701":{"word":"cacophony","mnemonics":[{"method":"Cacophony · 开口就封麦","textZh":"把 cacophony 近音联想成“开口，封你！”：几个人同时抢麦尖叫，声音又乱又刺耳，主持人只好封麦。记住的不是说话本身，而是这片刺耳的嘈杂声。","kind":"chinese_sound_association","original":false,"weak":false},{"method":"CACO + PHONY · 坏声音撞在一起","textZh":"caco- 有“坏”的意思，-phony 与 phone（电话）的“声音”词根相通。想象几部 phone 同时放不同铃声，混成一团难听的声音，就是 cacophony。","kind":"etymology_word_family","original":false,"weak":false}]},"5702":{"word":"calcify","mnemonics":[{"method":"CALCIUM · 从钙化到僵化","textZh":"看到 calcify，连起 calcium（钙）：钙盐沉积让东西变硬。再把思想想成也结了一层硬壳，怎么也不肯改变，就记住 calcify 的“使僵化、变僵化”。","kind":"etymology_word_family","original":false,"weak":false},{"method":"Calcify · 规矩成了“卡死法”","textZh":"把 calcify 近音联想成“卡死法”：旧规定把各种新办法都卡死，环境变了也不许调整。规矩越定越死，就把做事方式弄僵化了。","kind":"chinese_sound_association","original":true,"weak":false}]},"5703":{"word":"calibrate","mnemonics":[{"method":"CALIBR- · 标准口径","textZh":"calibrate 里的 calibr- 来自“口径”的词源。想到拿已知的标准尺寸核对枪管口径，再联想到拿标准核对仪器读数：不是随便量一量，而是把测量的准头校好。","kind":"etymology_word_family","original":false,"weak":false},{"method":"CALCULATE · 算钱之前先校秤","textZh":"把 calibrate 与形近的 calculate（计算）连起来：卖水果时，即使 calculate 一分钱也不差，秤若多报半斤，价格仍然算错。先按标准砝码把秤 calibrate，才能放心算账。","kind":"spelling_association","original":false,"weak":false}]},"5704":{"word":"calligraphy","mnemonics":[{"method":"CALLI + GRAPHY · 把字写成美","textZh":"calli- 表示“美”，-graphy 表示“书写”。想到书法家把同一个字写出讲究的粗细和线条：不是只写得清楚，而是把书写变美，合起来就是 calligraphy。","kind":"etymology_word_family","original":false,"weak":false},{"method":"CALLI · 楷隶两种书法","textZh":"把 calligraphy 开头的 calli 近音联想到“楷隶”：书桌上摆着楷书、隶书两本字帖，都是练书法的。看到 calli，想到楷隶，便带回“书法”。","kind":"chinese_sound_association","original":false,"weak":false}]},"5705":{"word":"calumniate","mnemonics":[{"method":"COLUMN · 专栏里编谎话","textZh":"把 calumniate 的前半联想到 column（报刊专栏）：有人在专栏里编造“他偷了钱”的谎话，故意毁掉别人的名声。这样的恶意诽谤就是 calumniate。","kind":"spelling_association","original":false,"weak":false},{"method":"CALL ME A… · 别诬称我","textZh":"把 calumniate 近音联想到 call me a liar（说我是骗子）：明知我说的是真话，却到处说我是骗子，让别人不再信任我。这不是普通称呼，而是造谣中伤。","kind":"sound_association","original":false,"weak":true}]},"5706":{"word":"catharsis","mnemonics":[{"method":"CATHARSIS · 靠它释怀","textZh":"把 catharsis 近音联想到“靠它释怀”：把憋着的心事写满一页纸，终于哭出委屈，靠这次表达释放了积压的情绪。记住的是宣泄后的松一口气。","kind":"sound_association","original":false,"weak":false},{"method":"CATHAR- · 给心情洗个澡","textZh":"cathar- 来自希腊语中“清洁、净化”的词。想象哭出来的眼泪像一场心灵淋浴，把积压的悲伤冲出去：从清洗身体，联想到情绪的宣泄和净化。","kind":"verified_etymology","original":false,"weak":false}]},"5707":{"word":"camouflage","mnemonics":[{"method":"CAME + FLAG · 假旗藏身份","textZh":"把 camouflage 的拼写联想到 came（来了）和 flag（旗帜）：敌人举着我方的旗帜走来，让人错认了身份。借一个假的外表掩饰真相，就是 camouflage。","kind":"spelling_association","original":false,"weak":false},{"method":"CAM + FLASH · 镜头也被骗","textZh":"把 camouflage 的声音联想到 camera（相机）的开头和 flash（闪光）：相机闪光一亮，照片里仍差点把穿绿褐迷彩服的人当成树丛。外表融进背景，让人难以辨认，就是伪装。","kind":"sound_association","original":false,"weak":false}]},"5708":{"word":"candor","mnemonics":[{"method":"CAN DO · 能不能都直说","textZh":"看到 candor，联想到 can do（能做）：别人问能否完成时，能做就说能做，做不到也坦白说，不为面子吹嘘。这样诚实、直接地表达，就是 candor。","kind":"spelling_association","original":false,"weak":false},{"method":"CANDle · 把心里话照亮","textZh":"candor 和 candle（蜡烛）有共同的“发亮、洁白”词源。想象点亮蜡烛，把原来藏在暗处的心里话摆到光下，不遮掩地说出来：由明亮联想到坦诚。","kind":"verified_word_family","original":false,"weak":false}]},"5709":{"word":"canon","mnemonics":[{"method":"CANON · 标尺变准则","textZh":"canon 的希腊语源头原指直杆、标尺，也指规则。把一根用来量长短的标尺，想成判断作品或行为是否合格的准绳：实物的标尺，变成公认的准则、标准。","kind":"verified_etymology","original":false,"weak":false},{"method":"Canon · 只印作者真作","textZh":"想象用 Canon（佳能）复印机整理作者原作集：只复印作者本人写的书，把别人续写的留在旁边。这样整理出的正式作品集合，就是该作者的 canon。","kind":"familiar_brand_association","original":false,"weak":false}]},"5710":{"word":"canvass","mnemonics":[{"method":"CANVAS · 帆布棚下拉票","textZh":"canvass 与 canvas（帆布）同音。想象候选人站在帆布棚下，逐个请求来人投自己一票：由帆布棚记住主动游说拉票，而不是投票已经成功。","kind":"熟词同音联想","original":false,"weak":false},{"method":"CANVASS · 像筛谷一样细查","textZh":"canvass 与 canvas（帆布）有关。一种词源解释把“细查”联系到用帆布抖筛：像把谷物中的杂物筛出来一样，把问题逐项检查、充分讨论。","kind":"简明词源联想","original":false,"weak":false}]},"5711":{"word":"caprice","mnemonics":[{"method":"CAP + RICE · 帽子盛米","textZh":"把 caprice 看成 cap（帽子）加 rice（米饭）：饭碗明明就在旁边，却突然想拿帽子盛饭。这种没来由的一时兴起，就是 caprice。","kind":"完整熟词拼形联想","original":false,"weak":false},{"method":"caPRICE · 随心改价","textZh":"看到 caprice 中完整的 price（价格），想象店主没有成本变化，却心情一变就把价签改来改去。由随意改价记住反复无常，不把正常市场波动算成任性。","kind":"可见熟词联想","original":false,"weak":false}]},"5712":{"word":"careworn","mnemonics":[{"method":"CARE + WORN · 忧虑磨出倦容","textZh":"care 在这里是忧虑，worn 是磨损、疲惫。烦心事天天磨着人，脸上终于显出憔悴：careworn，就是忧虑把人磨出了倦容。","kind":"真实合成词拆解","original":false,"weak":false},{"method":"CARE WORKER · 照护者的愁容","textZh":"看到 careworn 的 care wor，联想到 care worker（照护者）：她担心病人的病情，连日难眠，脸上满是忧劳后的憔悴。用这段相近词形，记住那张 careworn 的脸。","kind":"熟悉词组近形联想","original":true,"weak":false}]},"5713":{"word":"cardinal","mnemonics":[{"method":"CARDIN- · 门靠它转","textZh":"cardinal 的拉丁词源指门轴：门轴虽小，整扇门都靠它转。由这个不可缺的关键支点，记住首要、根本、极重要。","kind":"简明真实词源","original":false,"weak":false},{"method":"CARD · 最要紧的准考证","textZh":"看到 cardinal 开头完整的 card（卡片），想象一场必须凭卡入场的考试：笔可以借，缺了准考证却进不了考场。由这张关键卡片，记住 cardinal 的首要、极重要。","kind":"可见熟词联想","original":false,"weak":false}]},"5714":{"word":"carnal","mnemonics":[{"method":"CARN- · 回到肉身","textZh":"carn- 的拉丁词源是肉。把会感到饿、渴、欲望的肉身，与思考和精神生活分开：carnal 着重肉体欲求，常特指肉欲。","kind":"简明真实词源","original":false,"weak":false},{"method":"CARNAL · 只想着啃了","textZh":"把 carnal 近音联想到“啃了”：一个成年人原想静心，却只惦记着把眼前的烤肉啃了。由口腹之欲，记住肉体欲望而不是精神追求。","kind":"整体近音联想","original":true,"weak":false}]},"5715":{"word":"carouse","mnemonics":[{"method":"CAROUSE · 可闹死","textZh":"近音“可闹死”：成年人围桌喝酒，越喝越热闹，举杯唱歌“可闹死了”，记住狂饮作乐。","kind":"中文近音联想","original":false,"weak":false},{"method":"CAROUSE · 干杯喝个精光","textZh":"carouse 来自意为“完全喝干”的德语饮酒说法，后来指纵酒狂欢。想象大家把满杯喝到见底，再继续热闹说笑。","kind":"简明词源联想","original":false,"weak":false}]},"5716":{"word":"carp","mnemonics":[{"method":"CARPet · 地毯上挑小毛病","textZh":"carp 就藏在 carpet（地毯）开头。地毯已经很干净，对方却揪住一根细毛不停抱怨：不是认真检查，而是吹毛求疵。","kind":"熟词词形联想","original":false,"weak":false},{"method":"CARP · 卡破一点也挑","textZh":"近音“卡破”：贺卡只在边角破了一丁点，对方却反复挑剔、抱怨个没完。把“卡破”连到抓着小毛病不放。","kind":"中文近音联想","original":true,"weak":false}]},"5717":{"word":"cast","mnemonics":[{"method":"broadCAST · 把东西投出去","textZh":"broadcast（广播）中的 cast 是“投、撒”。广播把声音送出去；cast 把东西投出去，cast aside 则把不要的东西抛到一边。","kind":"熟词词形与词义联想","original":false,"weak":false},{"method":"CAST · 卡死就扔掉","textZh":"近音“卡死”：旧风扇已经彻底卡死，修不好了，主人把它丢掉不用。由“卡死就扔”记住丢弃义，而不只是随手抛着玩。","kind":"中文近音联想","original":true,"weak":false}]},"5718":{"word":"catalyze","mnemonics":[{"method":"CATALYST · 催化剂动起来","textZh":"回想已学的 catalyst（催化剂、促成变化的人或事）：带头捡纸的男孩是 catalyst，他促成大家一起行动，就是 catalyze。名词指出推动者，动词说它促成了什么变化。","kind":"已学词族对照","original":false,"weak":false},{"method":"CAT LIES · 谎话引发行动","textZh":"近音联想 cat lies（猫撒谎）：一只猫谎称“狗来了”，原本懒洋洋的猫群立刻一起逃跑。由这句谎话促成整群猫的行动，记住 catalyze 的“引发、促成”。","kind":"熟词短语近音联想","original":true,"weak":false}]},"5719":{"word":"catastrophe","mnemonics":[{"method":"CATASTROPHE · 整个翻覆","textZh":"词源表示“翻倒、向下翻转”，曾指悲剧的结局。想象洪水让原本安稳的村庄彻底变样，记住大灾难，不是小意外。","kind":"简明词源联想","original":false,"weak":false},{"method":"CAT + TROPHY · 颁奖全砸了","textZh":"近音联想 cat（猫）和 trophy（奖杯）：颁奖前猫闯进展台，把整排奖杯全撞碎，仪式彻底办砸。由这一场“大失败”记住 catastrophe。","kind":"熟词近音联想","original":false,"weak":false}]},"5720":{"word":"categorical","mnemonics":[{"method":"CATEGORY · 一类也不例外","textZh":"category 是类别。把所有类别的糖果都归入“现在不许吃”，连最小的一颗也不例外，记住 categorical 的绝对、不留例外。","kind":"熟词词形联想","original":false,"weak":false},{"method":"CATEGORICAL · 卡得够严格","textZh":"近音“卡得够严格”：门口规定不许入内，连“只进去一分钟”也被断然拒绝。由严格卡住、不留例外记住绝对的。","kind":"中文近音联想","original":true,"weak":true}]},"5721":{"word":"catholic","mnemonics":[{"method":"CAT LICK · 各种口味都爱","textZh":"把 catholic 近音联想成 cat（猫）lick（舔）：卡通猫对各种口味都想尝一尝，不只偏爱一种。记住口味、兴趣广泛，兼收并蓄。","kind":"熟词近音联想","original":true,"weak":false},{"method":"HOL · 从整体看","textZh":"词源中的 hol- 表示整体，catholic 原有普遍、全面的意思。把整排不同门类的书都纳入阅读兴趣，而不只守着一个小格子。","kind":"简明词源联想","original":false,"weak":false}]},"5722":{"word":"caustic","mnemonics":[{"method":"CAUS(E) + 啼哭","textZh":"把 caus 看作 cause（使），tic 近音联想“啼哭”：尖酸讽刺的话把人说哭了，记住刻薄、挖苦。","kind":"熟词与中文近音联想","original":false,"weak":false},{"method":"CAUST · 言语也灼人","textZh":"caust- 的词源与烧灼有关。腐蚀性物质灼伤表面，尖刻讽刺的话则像灼人一样刺痛听者。","kind":"简明词源联想","original":false,"weak":false}]},"5723":{"word":"caveat","mnemonics":[{"method":"CAVE AT · 洞口先提醒","textZh":"cave 是洞穴，at 是在。到洞口时向导说“可以进去，但里面会滴水”，把这个具体限制先提醒清楚，记住 caveat。","kind":"熟词词形联想","original":false,"weak":false},{"method":"CAVEAT / CAUTION · 同源的提醒","textZh":"caution 是“小心、警告”，与 caveat 同源，都来自拉丁语中“当心”的动词。用熟悉的 caution 唤起提醒：事情可以做，但有一点要特别留意。","kind":"熟词同源联想","original":false,"weak":false}]},"5724":{"word":"cavil","mnemonics":[{"method":"CAVIL · 咖味儿也挑","textZh":"近音“咖味儿”：咖啡已经合口味，他却拿“杯子的颜色不对”来反对再来这家店。由咖啡旁无关紧要的挑刺，记住吹毛求疵。","kind":"中文近音联想","original":true,"weak":false},{"method":"CAVE + ILL · 硬说洞有毛病","textZh":"联想 cave（洞穴）与 ill（有毛病）：溶洞明明适合参观，他却拿“洞口不够圆”硬说它有毛病，提出不值一提的反对理由。记住吹毛求疵。","kind":"熟词近音联想","original":false,"weak":false}]},"5725":{"word":"cataclysmal","mnemonics":[{"method":"CLYSM · 洪水冲毁","textZh":"cataclysmal 中的 clysm 可追溯到希腊语中“冲洗、淹没”的词源。想象洪水不只是冲过地面，而是冲毁整片街区，记住灾难性、巨大破坏。","kind":"简明词源联想","original":false,"weak":false},{"method":"CATASTROPHE · 从灾难到灾难性的","textZh":"看到 cataclysmal 开头的 cata，回想刚学过的 catastrophe（大灾难）：一场大灾难留下的毁灭性影响，可以用形容词 cataclysmal 描述。用熟词唤回灾难画面，同时分清名词与形容词。","kind":"已学熟词词形联想","original":false,"weak":false}]},"5726":{"word":"cement","mnemonics":[{"method":"SEE MEND · 看见粘补","textZh":"把 cement 近音联想成 see mend：看见有人把裂开的盘子粘补好，两半牢牢连在一起。由看见修补，记住粘合、使牢固。","kind":"熟词近音联想","original":true,"weak":false},{"method":"CEMENT · 碎石合成整体","textZh":"cement 的词源原指制作砂浆所用的碎石。把零散石块经胶结连成牢固整体的画面记下来，再联想到把人与人的关系巩固起来。","kind":"简明词源联想","original":false,"weak":false}]},"5727":{"word":"concomitant","mnemonics":[{"method":"CON + COME · 一起到来","textZh":"con- 表示一起，再把 com 近音联想成 come（来）：画展开幕，配套的音乐也一起到来。由两件事相伴出现，记住 concomitant。","kind":"词形与熟词近音联想","original":false,"weak":false},{"method":"COMMITMENT · 承诺与责任相伴","textZh":"把 comitant 近音联想成 commitment（承诺）：答应承办活动，安排场地的责任也随之而来。用承诺与相伴责任的画面，记住相伴发生。","kind":"熟词近音联想","original":false,"weak":false}]},"5728":{"word":"cessation","mnemonics":[{"method":"CEASE · 停止的名词家族","textZh":"从 cease fire（停火）里的 cease 记住“停止”。cease 与 cessation 同源：前者说停止这个动作，后者把它变成可讨论的“停止、终止”这一现象。","kind":"熟词词族联想","original":false,"weak":false},{"method":"SEE STATION · 到站停下","textZh":"把 cessation 近音联想成 see station：看到车站，列车驶入站台并停稳。用到站停止的画面，记住停止、暂停。","kind":"熟词近音联想","original":false,"weak":false}]},"5729":{"word":"chaff","mnemonics":[{"method":"CHAFF / LAUGH · 打趣逗笑","textZh":"chaff 与 laugh 的韵尾相同；想到 chaffed 和 laughed 这对押韵词：朋友打趣一句，大家一起笑起来。用打趣带来的笑声记住开玩笑、逗弄。","kind":"熟词押韵联想","original":false,"weak":false},{"method":"CHAFF / CHEF · 厨师打趣","textZh":"把 chaff 近音联想成 chef（厨师）：厨师端出一张歪饼，笑着对朋友说“这是你的皇冠”，朋友也笑起来。由厨师的友善打趣，记住开玩笑。","kind":"熟词近音联想","original":false,"weak":false}]},"5730":{"word":"chameleon","mnemonics":[{"method":"CHAMELEON · 可没脸","textZh":"把 chameleon 近音联想成“可没脸”：为了讨好眼前的人，刚对甲说赞成，转身又对乙说反对。用这副见人就改口的样子，记住随情境改变立场的人。","kind":"中文近音联想","original":true,"weak":false},{"method":"CAMEL + LION · 见谁就变成谁","textZh":"看到 chameleon，联想熟词 camel（骆驼）和 lion（狮子）混在一起：一个角色见到骆驼就变骆驼，见到狮子又变狮子。借这种为了适应眼前对象而换模样的画面，记住随情境改变立场的人。","kind":"熟词词形联想","original":false,"weak":false}]},"5731":{"word":"chary","mnemonics":[{"method":"CARE · 多留个心眼","textZh":"chary 与 care 同源，先想熟悉的 take care（小心）：走到一座摇晃的桥前，先看看是否安全，不贸然迈步。用 care 提醒自己留心风险，记住谨慎、不轻易冒险。","kind":"熟词词族联想","original":false,"weak":false},{"method":"CHERRY · 小心樱桃核","textZh":"把 chary 近音联想成 cherry（樱桃）：吃樱桃时不敢一口猛咬，先留意里面的硬核。由小心避开樱桃核，记住谨慎、留心风险。","kind":"熟词近音联想","original":false,"weak":false}]},"5732":{"word":"chase","mnemonics":[{"method":"CATCH / CHASE · 追得跑出去","textZh":"chase 与 catch（抓住）同源。想象保安想 catch 一个闯入者，紧追过去，闯入者被逼得跑出仓库：追赶是 chase，把人赶出去就是 chase him out。不必真的抓到他。","kind":"熟词词族联想","original":false,"weak":false},{"method":"CHEESE · 赶走偷吃奶酪的老鼠","textZh":"把 chase 近音联想成 cheese（奶酪）：老鼠刚凑近奶酪，主人就挥手追上去，把它赶出厨房。看到 cheese，就想起 chase the mouse away，把老鼠赶走。","kind":"熟词近音联想","original":false,"weak":false}]},"5733":{"word":"chasm","mnemonics":[{"method":"CHAOS / CHASM · 从大空隙到鸿沟","textZh":"借 chaotic（混乱的）中见过的 chaos 来记 chasm：两词同源，都连着“张开的大空隙”。把大空隙放在两种观点之间，记住明显而巨大的差距、鸿沟。","kind":"已学词同源联想","original":false,"weak":false},{"method":"CASH SUM · 金额差出一道沟","textZh":"把 chasm 近音联想成 cash sum（现金总额）：一边只有十元，另一边有十万元，两笔数额相差悬殊。用这道巨大的金额差距，记住明显的差距、鸿沟。","kind":"熟词近音联想","original":true,"weak":false}]},"5734":{"word":"cherubic","mnemonics":[{"method":"CHERUBIC · 吃肉饼","textZh":"把 cherubic 近音联想成“吃肉饼”：小孩捧着肉饼，小圆脸上露出天真满足的笑容。用这个可爱的圆脸孩子，记住小天使般的。","kind":"中文近音联想","original":true,"weak":true},{"method":"CHERRY + RUB · 红润的小圆脸","textZh":"cherubic 的开头让人联想到 cherry（樱桃），中间还有完整的 rub（揉）：轻轻揉一揉小孩圆圆的脸颊，他笑起来，双颊像樱桃一样红润。由这张天真可爱的小脸，记住小天使般的。","kind":"熟词词形联想","original":false,"weak":false}]},"5735":{"word":"chicanery","mnemonics":[{"method":"CHICANERY · 是坑你","textZh":"把 chicanery 的声音联想成“是坑你”：卖家把裂缝遮住，说得天花乱坠，其实是设法坑你。由这句揭穿骗局的话，记住“欺骗、巧诈手段”。","kind":"中文近音联想","original":true,"weak":false},{"method":"CHICANERY · 假鸡肉","textZh":"chicanery 的开头让人想到 chicken（鸡肉）。想象商家把便宜替代品包装成真鸡肉，故意让买家认错；抓住这场鸡肉买卖里的欺诈，记住 chicanery。","kind":"熟词词形与情境联想","original":false,"weak":false}]},"5736":{"word":"chide","mnemonics":[{"method":"CHIDE · CHILD 犯小错","textZh":"把 chide 与熟悉的 child（孩子）并排记：孩子犯了小错，妈妈皱眉提醒他改正。相近的词形让你从 child 想起 chide，即“责备”。","kind":"熟词词形联想","original":false,"weak":false},{"method":"cHIDE · 想躲责备","textZh":"chide 里能直接看到 hide（躲藏）。想象孩子做错事，想 hide 一下躲开妈妈的责备；由“躲责备”把 hide 连回 chide。","kind":"熟词词形联想","original":false,"weak":false}]},"5737":{"word":"choleric","mnemonics":[{"method":"CHOLERIC · COLOR RED","textZh":"把 choleric 的声音连到 color red（红色）：一点小事就气得满脸通红，颜色立刻变红。用这个“一惹就红脸”的画面记住“易怒的”。","kind":"熟词近音联想","original":false,"weak":false},{"method":"CHOLERic · 胆汁与火气","textZh":"先抓住 choleric 中完整的 choler：它的古义是“黄胆汁”。古人的体液学说把黄胆汁过多和易怒联系起来，像把火爆脾气归到一罐黄胆汁上；用这段旧观念记住“易怒”，不把它当作现代医学结论。","kind":"简明词源联想","original":false,"weak":false}]},"5738":{"word":"chord","mnemonics":[{"method":"CHORD · CORD 一条绳","textZh":"chord 和 cord（绳子）同音。想象两人抓着同一根绳，商量好朝同一方向拉，动作彼此配合；用“一条绳、一个方向”记住动词“相一致”。","kind":"熟词同音联想","original":true,"weak":false},{"method":"CHORD · 扣得上","textZh":"把 chord 的声音联想成“扣得上”：卡扣的两半形状正好对上，轻轻一扣就合在一起。计划与想法也能这样“扣得上”，就是相符合、相一致。","kind":"中文近音与动作联想","original":false,"weak":false}]},"5739":{"word":"chromatic","mnemonics":[{"method":"CHROMatic · 彩色 Chrome","textZh":"看到 chromatic 的 chrom-，联想熟悉的 Chrome 浏览器彩色圆形图标：红、黄、绿围着蓝色中心。由这个有颜色的图标，直接记住“彩色的、与色彩有关的”。","kind":"熟悉名称与视觉联想","original":true,"weak":false},{"method":"CHROMATIC · 色彩家族","textZh":"chromatic 中的 chrom- 来自表示“颜色”的希腊词。把它连到中文已熟悉的“染色体”：英语 chromosome 也带 chrom-，命名与容易着色有关；同一段 chrom- 把“染色”和“色彩”串起来。","kind":"词源与词族联想","original":false,"weak":true}]},"5740":{"word":"chronic","mnemonics":[{"method":"CHRON · 拖了很久","textZh":"chronic 的 chron- 来自表示“时间”的希腊语词根。把它连到一张翻过许多页的日历：时间过去很久，同一个老毛病还不断回来，便是长期、反复的 chronic。","kind":"词根与时间图像","original":false,"weak":false},{"method":"CHRONIC · 又克隆了","textZh":"chronic 开头的声音让人联想到“克隆”。想象刚解决的老问题又像被克隆一样出现，一个月接着一个月；由反复复制的麻烦，记住 chronic 的长期反复。","kind":"中文近音与情境联想","original":true,"weak":false}]},"5741":{"word":"cipher","mnemonics":[{"method":"CIPHER · 猜对方法","textZh":"把 cipher 的声音联想成“猜法”：一封信的字母被按规则打乱，得先猜对加密的方法，才读得出消息。由这套藏住原意的规则，记住 cipher。","kind":"中文近音联想","original":true,"weak":false},{"method":"CIPHER · CYBER 保密","textZh":"cipher 与 cyber（“赛博”里的“网络”）声音很接近。想象网络聊天先把文字变成旁人读不懂的内容，再传给朋友；负责这种变换的密码方法就是 cipher。","kind":"熟词近音与情境联想","original":false,"weak":false}]},"5742":{"word":"clarion","mnemonics":[{"method":"CLARION · CLEAR 的清亮","textZh":"看到 clarion 的 clar-，连到熟悉的 clear（清楚的）；两者同源。这个词先指能吹出清亮声音的号角，后来也用来形容像号角那样清楚响亮的声音。把 clear 的“清楚”放进耳朵里，记住 clarion 的清亮。","kind":"熟词词族与词源","original":false,"weak":false},{"method":"CLARION · 课铃音","textZh":"把 clarion 的声音联想到上课铃的声音：“课铃音”。铃声清楚响亮地传过操场，远处的学生也听得清；用这阵清亮的声音记住 clarion。","kind":"中文近音与声音联想","original":false,"weak":false}]},"5743":{"word":"clarity","mnemonics":[{"method":"CLARITY · CLEAR 的状态","textZh":"看到 clarity 的 clar-，连到熟悉的 clear（清楚的）。两者同源；-ity 常构成表示性质的名词。一个说明很 clear，它的“清楚易懂”这一性质便是 clarity。","kind":"熟词词族与词缀","original":false,"weak":false},{"method":"CLARITY · 克拉与剔透","textZh":"听到 clarity，联想一克拉、晶莹剔透的钻石。同样一克拉，有的瑕疵明显，有的更纯净；这里 clarity 指净度。再把这份清楚无杂的感觉带到思路、表达上，记住“清晰”。","kind":"中文近音与图像联想","original":false,"weak":false}]},"5744":{"word":"clasp","mnemonics":[{"method":"CLASP · CLAP 后握住","textZh":"clasp 很像 clap（拍手），只是多了 s。先想象 clap 时双手合上，再让两手留在一起、手指握住，不再分开拍动：从拍手的合拢动作转到 clasp 的合握。","kind":"熟词近形与动作联想","original":true,"weak":false},{"method":"CLASP · 考拉死抱","textZh":"把 clasp 的声音联想成“考拉死抱”：考拉用四肢紧紧抱住树干，不轻易松开。记住这个牢牢环抱的动作，就能想起 clasp 的紧握、紧抱。","kind":"中文近音与图像联想","original":false,"weak":false}]},"5745":{"word":"clement","mnemonics":[{"method":"CLEMENT · 去掉恶劣的 IN-","textZh":"想起学过的 inclement：冷风暴雨的恶劣天气。去掉表示否定的 in-，剩下 clement，就让风雨退去、天气恢复温和；对人也像这样不严酷，愿意宽待。","kind":"已学反义词与词缀","original":false,"weak":false},{"method":"CLEMENT · 可怜嘛","textZh":"把 clement 的声音联想到“可怜嘛”：看见犯错的人懊悔，老师动了恻隐之心，决定从宽处理。由这句求情的话，记住宽容、仁慈的 clement。","kind":"中文近音与情境联想","original":true,"weak":false}]},"5746":{"word":"cliché","mnemonics":[{"method":"CLICHÉ · 一块印版反复印","textZh":"cliché 原是法语印刷用语，指能反复印出同样内容的印版。想象同一块版印了一遍又一遍，话和故事也像照版复制，终于失去新意：这就是 cliché。","kind":"简明词源与图像联想","original":false,"weak":false},{"method":"CLICHÉ · CLICK 同款照片","textZh":"看到 cliché 开头的 cli-，联想到 click 的相机咔嚓声。人人都照着同一张网红照片摆同一姿势，咔嚓一次又一次，拍出来毫无新意；借这种用滥的拍照套路记住 cliché。","kind":"熟词近形与情境联想","original":false,"weak":false}]},"5747":{"word":"clog","mnemonics":[{"method":"cLOG · 木头卡住水道","textZh":"clog 里完整藏着 log（原木）。想象一根原木卡在狭窄水道里，后面的杂物越积越多，水过不去；由这根堵路的 log，记住 clog 的阻碍、堵塞。","kind":"熟词嵌入与图像联想","original":false,"weak":false},{"method":"CLOG · 卡喽","textZh":"把 clog 近音联想成“卡喽”：水管里的杂物越积越多，水流终于卡住不动了。听到这声“卡喽”，就想起通道被堵塞的 clog。","kind":"中文近音与动作联想","original":true,"weak":false}]},"5748":{"word":"cordial","mnemonics":[{"method":"CORDIAL · 从心里欢迎","textZh":"cordial 中的 cord- 来自拉丁语的“心”。把心里的善意变成真诚的笑容和欢迎，便是 cordial：不是只走礼貌程序，而是让人感到热情友好。","kind":"简明词源与情境联想","original":false,"weak":false},{"method":"CORDIAL · CARD 邀请卡","textZh":"cordial 开头的 cord- 让人联想到 card（卡片）。想象朋友亲手递来一张邀请卡，笑着欢迎你来做客；把卡片连到热情的邀请，记住 cordial。","kind":"熟词近形与情境联想","original":false,"weak":false}]},"5749":{"word":"clout","mnemonics":[{"method":"CLOUT · CLOUD 改变安排","textZh":"clout 和 cloud（云）只差最后一个字母，声音也相近。想象乌云一来，整座球场的活动安排都得改变；借云能左右安排的画面，记住 clout 是能影响决定、改变结果的力量。","kind":"熟词近形近音与情境联想","original":false,"weak":false},{"method":"CLOUT · CALL OUT 的裁判","textZh":"把 clout 近音联想成 call out。球场上裁判喊出“出局”，这一声能改变比赛结果，不是因为嗓门大，而是因为他有裁决权；由这种说话算数的分量，记住 clout 的权力、影响力。","kind":"熟词近音与权威情境联想","original":false,"weak":false}]},"5750":{"word":"coagulate","mnemonics":[{"method":"CO-AGULATE · 驱到一起成凝块","textZh":"coagulate 的词源中，co- 是“一起”，ag- 与“驱动”有关，合起来有“驱到一起”的意思。想象奶液中分散的细小成分被聚拢成团，不再像原来那样流动；由一起聚成凝块，记住凝结、变稠。","kind":"简明词源与过程联想","original":false,"weak":false},{"method":"COAGULATE · COLGATE 浓膏","textZh":"把 coagulate 的声音和拼写联想到 Colgate（高露洁）牙膏。牙膏挤出来是浓稠的一条，而不像水那样流走；借这种稠厚的形态，记住 coagulate 是使液体变稠、凝结。","kind":"熟悉物品近音近形联想","original":false,"weak":false}]},"5751":{"word":"coax","mnemonics":[{"method":"COAX · COKES 好好商量","textZh":"coax 听起来像 Cokes（几杯可乐）。想象朋友不愿参加活动，你递上可乐，坐下来好声好气地劝他，而不是强迫；由这番柔和的劝诱记住 coax。","kind":"熟词同音与情境联想","original":false,"weak":false},{"method":"COAX · COACH 耐心鼓励","textZh":"coax 与 coach（教练）形近、音近。想象小球员紧张得不敢上场，教练耐心说“试试看，我相信你”，终于把他劝上场；这种温柔劝动就是 coax。","kind":"熟词近形近音与人物联想","original":false,"weak":false}]},"5752":{"word":"coda","mnemonics":[{"method":"CODA · 乐曲的小尾巴","textZh":"coda 原是意大利语的“尾巴”。把整首曲子想成一只动物：主体结束后还有一条连着身体的小尾巴；这段为同一首曲子收尾的音乐就是 coda。","kind":"简明词源与图像联想","original":false,"weak":false},{"method":"CODA · 够啦，收尾","textZh":"把 coda 的声音近似联想成“够啦”。主要旋律已经说够了，钢琴再弹一段收束，让整首曲子落定；听见这句“够啦”，便想起结尾的 coda。","kind":"中文近音与音乐情境联想","original":true,"weak":false}]},"5753":{"word":"coerce","mnemonics":[{"method":"COERCE · CURSE 威胁","textZh":"coerce 的声音让人联想到 curse（诅咒）。想象巫师威胁“不照办就诅咒你”，对方只好屈服；由这种用威胁迫人服从的情境记住 coerce。","kind":"熟词近音与威胁情境联想","original":false,"weak":false},{"method":"COERCE · FORCE 逼人让步","textZh":"把 coerce 与 force（强迫）对照看：两词的整体字形和末尾声音相近。想象对方用强力逼你交出不愿交出的东西；由 force 的强迫感联到 coerce 的胁迫。","kind":"熟词近形近音联想","original":false,"weak":false}]},"5754":{"word":"coeval","mnemonics":[{"method":"COEVAL · 共享一段年代","textZh":"coeval 中 co- 表示共同，后面的部分来自拉丁语表示“年龄、时代”的词。想象两个孩子的年龄卡写着相同数字，共享同一段成长年岁；由共同的年龄记住 coeval。","kind":"简明词源与同龄图像联想","original":false,"weak":false},{"method":"COEVAL · CO-EVOLVE 同期发展","textZh":"想起学过的 evolve（逐渐发展）。把 coeval 近形、近音联想到 co-evolve：两种事物在同一段年代中发展，时间轴并排。借这个“同期”的画面记住 coeval。","kind":"已学熟词近形近音联想","original":false,"weak":false}]},"5755":{"word":"cognizant","mnemonics":[{"method":"COGNIZANT · RECOGNIZE 认出危险","textZh":"把 cognizant 与 recognize（认出）放在一起看，共同的 cogniz- 带来‘知道、认出’的联系。认出地上的水会让人滑倒，心里已经知道这个危险，就是 cognizant of the danger。","original":false,"weak":false,"kind":"词族或词源与情境联想"},{"method":"COGNIZANT · COGENT 说清才知道","textZh":"想起学过的 cogent（令人信服的）：朋友给出清楚有力的解释，你才知道桥上有危险。把形近的 cogent 与 cognizant 连成这个画面：理由令人信服，听者意识到风险。","original":false,"weak":true,"kind":"近形近音与情境联想"}]},"5756":{"word":"collapse","mnemonics":[{"method":"colLAPSE · 失去支撑一起落下","textZh":"学过的 lapse 含有‘滑落、失误’的联系；collapse 中也完整含有 lapse，词源是一起滑落。把计划想成搭好的积木：关键支撑一失，整套安排一起垮掉，由倒塌记住计划彻底失败。","original":false,"weak":false,"kind":"词族或词源与情境联想"},{"method":"COLLAPSE · CLAPS 掌声落空","textZh":"collapse 的后半声响像 claps（拍手声）。本来准备为计划成功鼓掌，结果事情全垮了，掌声也落空；把期待的 claps 和失败的 collapse 对照着记。","original":false,"weak":false,"kind":"近形近音与情境联想"}]},"5757":{"word":"coltish","mnemonics":[{"method":"COLT-ish · 小马驹的顽皮劲","textZh":"colt 是小马驹，-ish 表示带有这种样子。想象小马驹精力充沛地蹦跳，腿脚还有点不听使唤；把这种活泼又笨拙的顽皮劲放到男孩身上，就是 coltish。","original":false,"weak":false,"kind":"词族或词源与情境联想"},{"method":"COLTISH · CHILDISH 孩子气的嬉闹","textZh":"把 coltish 与形近的 childish（孩子气的）对照看。孩子在草地上蹦蹦跳跳、做鬼脸逗人笑，这种带孩子气的活泼劲就是 coltish；重点是爱嬉闹，不是 childish 常带的任性、不成熟的批评。","original":false,"weak":false,"kind":"近形近音与情境联想"}]},"5758":{"word":"coma","mnemonics":[{"method":"COMA · 磕懵后的昏迷","textZh":"把 coma 的声音近似联想到“磕懵”。画面里的人严重撞伤后被医生确诊昏迷，躺在病床上一直没有清醒过来；由受伤后的昏迷画面记住 coma。","original":false,"weak":false,"kind":"中文近音与情境联想"},{"method":"COMA · COMMA 不再接话","textZh":"coma 与 comma（逗号）字形相近。逗号后，说话的人还会继续；而病床上已经确诊 coma 的人不能有意识地接话。借这组对照，记住 coma 是深度无意识，而不是日常谈话的一次停顿。","original":false,"weak":false,"kind":"近形近音与情境联想"}]},"5759":{"word":"combustible","mnemonics":[{"method":"COMBUST-ible · 能燃烧","textZh":"combust- 来自表示‘烧尽’的词，-ible 表示‘能够被……的’。想象炉内的木材被火点着，渐渐烧成灰；由能被火烧掉，记住 combustible 是可燃的。","original":false,"weak":false,"kind":"词族或词源与情境联想"},{"method":"COMB…TIBLE · 木梳与木桌","textZh":"看到 combustible，联想到 comb（梳子）和 table（桌子）的字形。想象木梳放在木桌上：它们都是能被火烧掉的木制品。借这两个可燃物的画面，记住 combustible 的可燃性质。","original":true,"weak":false,"kind":"近形近音与情境联想"}]},"5760":{"word":"commend","mnemonics":[{"method":"reCOMMEND · 推荐前先称赞","textZh":"recommend 是“推荐”，里面完整含有 commend。你向朋友推荐一位老师时，先称赞“她讲得特别清楚”；把推荐中的这句赞扬，连到 commend。","original":false,"weak":false,"kind":"词族与情境联想"},{"method":"comMEND · 修好了就表扬","textZh":"看到 commend 里的 mend（修补），想象同学把你破掉的书包仔细补好，你当面夸他“修得真好！”由 mend 后得到表扬，记住 commend。","original":false,"weak":false,"kind":"字形与情境联想"}]},"5761":{"word":"commingle","mnemonics":[{"method":"com-MINGLE · 混到一起","textZh":"mingle 表示混合，com- 带有共同、一起的联系。两种颜色不是各占半杯，而是搅进同一杯，充分混在一起；由 com＋mingle 记住 commingle。","original":false,"weak":false,"kind":"词族与情境联想"},{"method":"COMMINGLE · 不再 SINGLE 单独放","textZh":"把 commingle 与形近的 single（单个的）对照。单色珠子原本一颗颗单独摆开，倒进同一个碗里搅匀，就不再各自分开，而是 commingle，混合在一起。","original":true,"weak":false,"kind":"字形与情境联想"}]},"5762":{"word":"commitment","mnemonics":[{"method":"COMMIT-ment · 把自己投入进去","textZh":"commit 有“承诺、投入”的意思，-ment 把动作变成名词。想象你答应负责班级花坛，接着把时间和精力交给这件事；commitment 既可指那份承诺，也可指持续的投入。","original":false,"weak":false,"kind":"词族与情境联想"},{"method":"COMMITMENT · 不止 COMMENT 一句","textZh":"把 commitment 与形近的 comment（评论）对照：“花坛真漂亮”只是 comment；“以后我负责浇水”则是 commitment。从随口评论变成承担责任的承诺，记住这个更有分量的词。","original":true,"weak":false,"kind":"字形与情境联想"}]},"5763":{"word":"committed","mnemonics":[{"method":"COMMIT-ted · 已把心力交给它","textZh":"commit 有承诺、投入的意思；committed 用来形容已经把自己投入其中的状态。不是只说“我喜欢这支队伍”，而是困难时仍肯花心力支持它，这就是 committed 的忠诚、坚定。","original":false,"weak":false,"kind":"词族与情境联想"},{"method":"COMMITTED · COMMITTEE 尽责委员","textZh":"把 committed 与形近的 committee（委员会）连起来：委员会里那位总是认真完成分工、困难时也不退出的成员，是 a committed member。由尽责的委员形象，记住忠诚而肯投入的 committed。","original":true,"weak":false,"kind":"字形与情境联想"}]},"5764":{"word":"commodious","mnemonics":[{"method":"COMMODIOUS · ACCOMMODATE 容得下","textZh":"想起学过的 accommodate（容纳），两词都有醒目的 commod。一个房间容纳全家后，大家还有地方伸腿、走动，这种宽敞舒适就是 commodious；不是勉强挤得下。","original":false,"weak":false,"kind":"词族与情境联想"},{"method":"COMMODIOUS · 客，莫挤呀","textZh":"把 commodious 的声音近似联想到“客，莫挤呀”。客人进门，主人指着宽敞的客厅说不用挤，大家都能舒舒服服坐下；用这句声音联想记住宽敞舒适。","original":true,"weak":false,"kind":"中文近音与情境联想"}]},"5765":{"word":"commonsensical","mnemonics":[{"method":"COMMON SENSE · 常识派得上用场","textZh":"common sense 就是常识，commonsensical 把它变成“符合常识的”。出门看见下雨就带伞，不用复杂推导，也知道这样做合理；由熟悉的 common sense 记住这个长词。","original":false,"weak":false,"kind":"词形与情境联想"},{"method":"COMMONSENSICAL · 不说 NONSENSE","textZh":"把 commonsensical 和 nonsense（胡话、荒唐话）对照着记：下雨却说“拿筛子挡雨”是 nonsense，改成拿雨伞，才是 commonsensical。两词都带 sens 这一醒目的部分，一个荒唐，一个合乎常识。","original":true,"weak":false,"kind":"词形与情境联想"}]},"5766":{"word":"commotion","mnemonics":[{"method":"com-MOTION · 大家一下乱动起来","textZh":"motion 是运动、移动。看到 commotion，想起人群突然一齐转身、挤动、叫喊：不再是有序移动，而是一阵骚动。用单词里完整的 motion 抓住“乱动、喧闹”的画面。","original":false,"weak":false,"kind":"词形与情境联想"},{"method":"COMMOTION · EMOTION 喊出来","textZh":"把 commotion 与形近、尾音相同的 emotion（情绪）连起来。球迷情绪激动，纷纷起身喊叫，心里的 emotion 变成看得见、听得见的 commotion；记住后者是现场的骚动，不只是心情。","original":true,"weak":false,"kind":"词形与情境联想"}]},"5767":{"word":"compendium","mnemonics":[{"method":"comPENdium · 一支笔摘精华","textZh":"看到 compendium 中完整的 pen（笔），想象拿笔把厚书各章的关键内容摘到一本薄册子里。笔下留下的是要点，不是全文抄写；这本浓缩要点的简编就是 compendium。","original":false,"weak":false,"kind":"词形与情境联想"},{"method":"COMPENDIUM · 省篇幅，留要点","textZh":"compendium 沿用了拉丁语的同形词，那个词既有“节省、捷径”，也有“摘要”的意思。把它记成阅读的捷径：不走完厚书的每一页，把主要知识收进一本简编，省下篇幅和时间。","original":false,"weak":true,"kind":"简短词源联想"}]},"5768":{"word":"complacency","mnemonics":[{"method":"COMPLACENT → COMPLACENCY","textZh":"想起学过的 complacent（自满的）：一次考好就认定自己不会再出错，连检查也省掉。这种对自己过于满意、忽略隐患的心态，变成名词就是 complacency。","original":false,"weak":false,"kind":"词形与情境联想"},{"method":"comPLACEncy · 满足于原地","textZh":"抓住 complacency 里完整的 place（地方）。想象一个人取得一点成绩，就觉得待在这个 place 已经够好，不再改进，也不看前面的风险；由“自满地停在原地”记住 complacency。","original":false,"weak":false,"kind":"词形与情境联想"}]},"5769":{"word":"complaisance","mnemonics":[{"method":"comPLAISance · PLEASE 别人","textZh":"complaisance 中的 plais 让人联想到 please（使人高兴），读音也接近。别人提出小请求，你乐意迁就，让对方满意；把“愿意 please 别人”连到 complaisance 的和顺、殷勤。","original":false,"weak":false,"kind":"词形与情境联想"},{"method":"COMPLAISANCE · 不 COMPLAIN","textZh":"把 complaisance 与形近的 complain（抱怨）对照：客人请你换个座位，你不抱怨，还笑着答应。由“没有 complain，反而乐意迁就”记住 complaisance；重点是愿意配合，不只是沉默。","original":true,"weak":false,"kind":"词形与情境联想"}]},"5770":{"word":"compliant","mnemonics":[{"method":"COMPLIANT · 愿意 COMPLY","textZh":"comply 是按要求去做，compliant 则形容愿意这样做的人。老师要求先穿围裙，他爽快地照做：动作是 comply，态度是 compliant；两词共同的 compli-/comply 发音把“遵从”连在一起。","original":false,"weak":false,"kind":"词族联想"},{"method":"COMPLIANT · 不 COMPLAIN","textZh":"把 compliant 和形近的 complain（抱怨）放在一起记。别人提出合理要求，他不 complain，反而点头配合；由“不抱怨，还肯照做”的态度记住 compliant 的顺从。","original":false,"weak":false,"kind":"词形与情境联想"}]},"5771":{"word":"compliment","mnemonics":[{"method":"COMPLIMENT · 好听的 COMMENT","textZh":"comment 是评论，compliment 和它的词首、词尾都很像。把“这幅画色彩真漂亮”这样的好评看成一条让人开心的 comment，就能连到 compliment：说出对别人的欣赏与称赞。","original":true,"weak":false,"kind":"词形与情境联想"},{"method":"COMPLIMENT · 不是 COMPLAINT","textZh":"compliment 和 complaint（抱怨、投诉）长得很像，话的方向却相反：说“服务太慢”是在提 complaint，说“你招待得真周到”是在给 compliment。把一脸不满换成由衷欣赏，记住后者是称赞。","original":true,"weak":false,"kind":"词形对照联想"}]},"5772":{"word":"compose","mnemonics":[{"method":"com-POSE · 把部分放在一起","textZh":"compose 的 com- 表示一起，pose 这部分来自法语 poser（放置）。想象把零散音符放在一起成为乐曲，把各个部分安排成整体；由“一起放好”记住组成、创作。","original":false,"weak":false,"kind":"简短词源联想"},{"method":"COMPOSE · 找回 COMPOSED","textZh":"想起学过的 composed（镇定的）：上台前心慌，先停下来平稳呼吸，重新变得 composed。使自己恢复这种状态，就用 compose oneself；熟悉的镇定状态帮你记住这个动作。","original":false,"weak":false,"kind":"词族联想"}]},"5773":{"word":"compound","mnemonics":[{"method":"COMPOUND · 放到一起","textZh":"compound 中的 com- 表示一起，后半部分的词源可追到表示放置的拉丁语 ponere：把成分放在一起，形成混合物；把新错误又叠到老问题上，就进一步加重了麻烦。由“一起放上去”串起混合与加重。","original":false,"weak":false,"kind":"简短词源联想"},{"method":"com-POUND · 麻烦又重一磅","textZh":"pound 是磅，完整地藏在 compound 后半段。想象肩上已经有一袋麻烦，又添上一磅重物，负担更重了；用“再加一磅”记住 compound 作动词时加重已有问题的意思。","original":false,"weak":false,"kind":"词形与情境联想"}]},"5774":{"word":"compress","mnemonics":[{"method":"com-PRESS · 一起压紧","textZh":"press 是按、压，compress 里能直接看到完整的 press。想象双手把蓬松睡袋往袋里压紧：东西还在，占的空间却小了；这就是 compress 的压缩。","original":false,"weak":false,"kind":"词形与情境联想"},{"method":"COMPRESS · 字母也挤紧","textZh":"先把 c o m p r e s s 松松地写开，再想象从两侧挤向中间，变成紧凑的 compress。字母一个没少，整行却占得更窄，用这个拼写画面记住压缩是让东西占更小的空间。","original":true,"weak":false,"kind":"拼写图像联想"}]},"5775":{"word":"concatenate","mnemonics":[{"method":"con-CATEN-ate · CHAIN 串起来","textZh":"concatenate 中的 caten 来自表示“链条”的拉丁语 catena，熟悉的 chain（链条）也来自它。把 caten 与 chain 对着记：不是堆在一起，而是一环接一环，连成一条更长的链。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"conCATenate · 小猫连成一串","textZh":"抓住 concatenate 中完整的 cat（猫）：把几只纸猫的前爪与后一只的尾巴依次扣起来，原本分开的纸猫就连成了一长串。由 cat 的连串画面，记住“把各部分接起来”。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5776":{"word":"conceal","mnemonics":[{"method":"conCEAL · SEAL 住秘密","textZh":"conceal 的 ceal 与 seal（封住）读音相同。把秘密信件放进不透明信封，再 seal 住，内容就被藏起来，不让别人看到；由“封起来保密”记住隐藏、隐瞒。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONCEAL · 肯羞，就藏起来","textZh":"把 conceal 的声音近似联想为“肯羞”：肯定害羞，不愿让人看见，就用手遮住涨红的脸。由“羞得藏起来”的画面记住 conceal。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5777":{"word":"concentrate","mnemonics":[{"method":"con-CENTR-ate · 向 CENTER 聚集","textZh":"centr 与熟悉的 center（中心）同源。想象散在四周的人都朝中心走，最后聚在一处；concentrate 就可以表示聚集。注意力也能这样集中到一件事上。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"conCENTRate · 把 CENT 收拢","textZh":"看到 concentrate 中完整的 cent（分币），想象将桌上分散的硬币全部收进一个小罐子：钱没有变多，却从四散变成集中。用“把零钱聚到一处”记住 concentrate，不只把它记成专心。","original":true,"weak":false,"kind":"词形、词音与情境联想"}]},"5778":{"word":"concerted","mnemonics":[{"method":"CONCERT-ed · 合奏要配合","textZh":"concert 是音乐会。想象乐手盯着同一个指挥，按约定一起进入、一起停下，才能完成合奏；由 concert 记住 concerted 的“共同策划、协调完成”，不是碰巧同时动起来。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONCERTED · 不只 CONCERNED","textZh":"把形近的 concerned（担心的）和 concerted 对照：几个人都担心漏雨，还只是 concerned；他们商量分工，一人接水、一人补漏，才成为 concerted 的共同行动。由共同担心走到共同配合，分清这两个词。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5779":{"word":"conciliate","mnemonics":[{"method":"CONCILIATORY → CONCILIATE","textZh":"想起学过的 conciliatory（安抚的、调和的）：先放软语气，提出双方都能接受的办法。表示这种态度用 conciliatory；把安抚对方的事做出来，就是动词 conciliate。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONCILIATE · COUNCIL 坐下谈","textZh":"把 conciliate 与 council（议事会）放在一起看，两词都源于拉丁语中表示议事会的 concilium。想象把对立双方请到议事桌前，听取意见、化解不满；由 council 的协商画面记住 conciliate 的安抚、调和。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5780":{"word":"concord","mnemonics":[{"method":"con-CORD · 心在一起","textZh":"concord 中的 con- 表示一起，cord 来自表示“心”的拉丁语。把这个词记成“心在一起”：两个人心意相通，不再各唱各的调，就是一致、和睦。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONCORD ↔ DISCORD","textZh":"想起学过的 discord（不和、不一致）：大家各执一词，争个不停；把对立换成共同商量，最后心平气和地达成一致，就是 concord。两词保留同一段 cord，前面的 con- 与 dis- 帮你分清和与不和。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5781":{"word":"condole","mnemonics":[{"method":"con-DOLE · 分担悲痛","textZh":"condole 中的 con- 表示一起，dol 源于表示悲痛的拉丁语。想象不是远远说一句“别难过”，而是坐到失去亲人的朋友身旁，与他一起承受悲痛；这就把 condole 的“表达同情、慰问”连起来了。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONDOLE 与 CONSOLE","textZh":"把形近的 condole 和 console（安慰）放在一起记：朋友遭遇丧亲之痛，你先向他表达哀伤与同情，是 condole with him；设法让他得到安慰，是 console him。相近的词形帮你联想到同情，再用 with 分清句式。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5782":{"word":"cantankerous","mnemonics":[{"method":"CANTANKEROUS · 看坦克惹事","textZh":"把 cantankerous 近似听成“看坦克惹事”：别人安静参观，一个人却嫌排队慢、嫌解说差，看个坦克也不停与人争吵。用这位爱找茬的参观者，记住“脾气坏、好争吵”。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CANTANKEROUS · CAN’T TAKE IT","textZh":"把 cantankerous 的开头近音联想到 can’t take it（受不了了）：一点小事就嚷着“受不了”，接着抱怨、顶嘴、不肯配合。由这句熟悉的抱怨，记住 cantankerous 的坏脾气。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5783":{"word":"confluence","mnemonics":[{"method":"con-FLU-ence · 水流到一起","textZh":"con- 表示一起，flu 来自表示流动的拉丁语，与 fluent（流利的）同源。讲话流利像水流顺畅；两股这样的水流汇到一处，就是 confluence。记住重点是“流到一起”，不只是流动。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONFLUENCE · CONFERENCE 汇聚","textZh":"把形近的 confluence 和 conference（会议）放在一起看：各地代表来到同一会场，各种意见也在这里汇聚。由 conference 的“人和想法来到一起”，记住 confluence 的汇合、汇集，不把它误记成会议本身。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5784":{"word":"congeal","mnemonics":[{"method":"conGEAL · 像 JELLY 凝起来","textZh":"congeal 的 geal 让人联想到 jelly（果冻）的声音：原本能倒出来的液体，冷却后成了会颤动却不再四处流淌的果冻。由 jelly 的凝结状态，记住 congeal。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"conGEAL · CHILL 后凝固","textZh":"把 congeal 后半段的近音与 chill（冷却）相联：一碗热肉汁放凉，表面的油脂逐渐凝成一层。由 chill 带来的凝固变化记住 congeal。","original":true,"weak":false,"kind":"词形、词音与情境联想"}]},"5785":{"word":"congenial","mnemonics":[{"method":"con + GENIAL · 在一起很亲切","textZh":"先认出学过的 genial（和蔼友善的），再把 con 的“一起”加进画面：两位亲切的人坐到一起，越聊越投缘。congenial 不仅友好，还让人觉得相处合得来。","original":false,"weak":false,"kind":"熟词家族联想"},{"method":"conGENIal · 友好的 GENIE","textZh":"congenial 中的 geni 让人想到 genie（神灯精灵）：精灵一出来就亲切地招呼你，愿意听你的心愿，与你聊得很投机。把这位好相处的精灵和 congenial 连起来。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5786":{"word":"connive","mnemonics":[{"method":"con + nive · 眨眼打暗号","textZh":"connive 的词源与闭眼、眨眼有关。把 con 的“一起”放进画面：两人互相眨眼打暗号，心照不宣地合谋；看见同伙做坏事又故意闭眼不管，也就是纵容。","original":false,"weak":false,"kind":"简明词源与情境联想"},{"method":"conNIVE · 藏起 KNIVES","textZh":"connive 的 nive 近似 knives（刀）的声音：两个阴谋者表面握手，背后却各藏着刀，低声商量怎样暗算别人。由共同藏刀的秘密计划，记住“共谋”。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5787":{"word":"connoisseur","mnemonics":[{"method":"connoisseur · 靠你筛","textZh":"把 connoisseur 近音联想成“靠你筛”：一桌真假优劣混杂的艺术品，大家把挑选工作交给你，说“靠你筛！”能凭眼力筛出好作品的，就是鉴赏家。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"connoiSSEUR · KNOW-SIR","textZh":"读 connoisseur 时联想到 know（懂得）和 sir（先生）：别人只会说一幅画好看，这位懂行的先生却能指出用色、笔触的妙处。把“真正懂得欣赏的先生”记作 connoisseur。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5788":{"word":"conscientious","mnemonics":[{"method":"CONSCIENCE → CONSCIENTIOUS","textZh":"conscience 是“良心”；conscientious 保留了明显的 conscien- 词形。想象一个人准备敷衍交差时，良心提醒他“这是你的责任”，于是重新认真检查：由“良心”联想到“认真尽责”。","original":false,"weak":false,"kind":"词族与情境联想"},{"method":"conSCIENTious · 像 SCIENTIST 一样核查","textZh":"看到 conscientious 中的 scient，就联想到 scientist（科学家）：他把每一项实验数据仔细复核，连一个小误差也不敷衍。用这位认真负责的研究者，记住“一丝不苟”。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5789":{"word":"consequence","mnemonics":[{"method":"con + SEQUENCE · 跟着发生的结果","textZh":"认出 sequence（顺序、一连串）：先做一件事，后面的事情沿着因果顺序接着发生。consequence 就是由前面的行为引出来、跟着发生的结果。","original":false,"weak":false,"kind":"词族与因果联想"},{"method":"短 CAUSE，长 CONSEQUENCE","textZh":"把 cause（原因）和 consequence 并排看：cause 短，consequence 长。想象只按错一下按钮，却引出后面一长串麻烦；这个长长的词提醒你“小原因，也会拖出一长串后果”。","original":true,"weak":true,"kind":"词形、词音与情境联想"}]},"5790":{"word":"conservative","mnemonics":[{"method":"CONSERVE → CONSERVATIVE","textZh":"conserve 是“保存、保护”。看到 conservative 中几乎完整的 conserve，就想象一个人把旧规矩原样保存下来，不愿换成新办法：保留旧样，就是保守。","original":false,"weak":false,"kind":"熟词词族联想"},{"method":"RESERVED → CONSERVATIVE · 从言语低调想到衣着低调","textZh":"把 conservative 与学过的 reserved（内敛的）并排联想：reserved 的人说话不张扬；想象他的衣着也选朴素款，就有了 conservative dress 的低调。相近的 serv 词形与声音，把两种克制的画面连起来。","original":false,"weak":false,"kind":"已学全词检索与跨情境联想"}]},"5791":{"word":"conservatory","mnemonics":[{"method":"CONSERVE + -ATORY · 保护植物的地方","textZh":"conserve 表示“保存、保护”，-atory 让人想到一个场所。想象把怕冷的植物集中保护在玻璃房里：保住植物的地方，就是 conservatory 温室。","original":false,"weak":false,"kind":"词根与场所联想"},{"method":"CONCERT + LABORATORY · 音乐实验室","textZh":"看到 conservatory 的 conser…atory，联想到 concert（音乐会）和 laboratory（实验室）：学生在“音乐实验室”里一遍遍练习演奏，为音乐会做准备。把这个培养演奏人才的地方记作艺术学院。","original":true,"weak":false,"kind":"词形、词音与情境联想"}]},"5792":{"word":"console","mnemonics":[{"method":"conSOLE · 抚慰 SOUL","textZh":"console 的重读部分听起来像 soul（心灵）。想象朋友伤心时，你不急着讲道理，而是陪着他，让受伤的心灵慢慢平静：console 就是安慰。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"SOLACE → CONSOLE · 把慰藉送给他","textZh":"回想学过的 solace（慰藉）：solace 和 console 都有醒目的 sol，属于同一词源家族。把 solace 从心里的一份慰藉，变成走过去安慰别人的动作，就把 console 记牢了。","original":false,"weak":false,"kind":"已学词家族联想"}]},"5793":{"word":"consolidate","mnemonics":[{"method":"con + SOLID + ate · 变得坚实","textZh":"在 consolidate 中直接认出 solid（坚实的）：把松散的土压紧，让它变成稳固的一整块。由“使坚实”记住巩固，再想到把零散部分整合为一体。","original":false,"weak":false,"kind":"熟词词根联想"},{"method":"SOLIDARITY → CONSOLIDATE · 把团结巩固起来","textZh":"把 consolidate 与学过的 solidarity（团结一致）并排看，醒目的 solida 让你想起同伴走过来、一起承担困难的团结。solidarity 是大家相互支持的状态；consolidate 则是让这个已经形成的整体更加稳固的动作。","original":false,"weak":false,"kind":"已学全词检索与状态动作联想"}]},"5794":{"word":"constringe","mnemonics":[{"method":"conSTRINGe · 拉紧 STRING","textZh":"constringe 中藏着完整的 string（绳子）。想象拉紧布袋口的一根绳，袋口马上向内收拢、变窄：由拉绳收口记住“使紧缩”。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"ASTRINGENT → CONSTRINGE · 涩得嘴发紧","textZh":"回想学过的 astringent（有收敛性的；涩的）：未熟果子的涩味让嘴里有发紧、收缩的感觉。两词共有 string，把这种收敛作用变成动词 constringe，就是使收紧、使收缩。","original":false,"weak":false,"kind":"已学词家族联想"}]},"5795":{"word":"construct","mnemonics":[{"method":"CON + STRUCTURE · 组出结构","textZh":"structure 是“结构”。看到 construct 中的 struct，就想象把积木一块块组合起来，搭出一个有结构的房子：由结构想到建造。","original":false,"weak":false,"kind":"熟词词根联想"},{"method":"conSTRUCT · TRUCK 运来建材","textZh":"construct 的重读部分让人联想到 truck（卡车）。想象卡车把砖和木料运到工地，工人马上把它们拼建成房子：听到这段声音，就想到正在建造。","original":true,"weak":false,"kind":"词形、词音与情境联想"}]},"5796":{"word":"contaminate","mnemonics":[{"method":"CON + TAMIN · 接触带来污染","textZh":"contaminate 的词源与“接触”有关，con- 有“一起”的意思。想象干净的纱布碰到脏手，病菌随接触进入：从“碰在一起，混入脏东西”记住污染。","original":false,"weak":false,"kind":"词源动作联想"},{"method":"conTAMINate · 一起抬煤","textZh":"把 con 想成“一起”，tamin 的声音联想到“抬煤”。几个人一起抬煤，煤灰落进旁边的清水里：抬煤扬灰，把水污染了。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5797":{"word":"content","mnemonics":[{"method":"conTENT · 帐篷里面有什么","textZh":"tent 是“帐篷”，在 content 中完整可见。掀开帐篷，看到里面装着睡袋、背包和水壶：帐篷所包含的东西，就是它的 contents。再由所含之物想到文章所包含的内容。","original":false,"weak":false,"kind":"词形、词音与情境联想"},{"method":"CONTENT · 肯疼她","textZh":"把动词 content 的声音联想到“肯疼她”：她不求昂贵礼物，只希望家人肯疼她；真心的关爱就能使她满足。由“肯疼她，使她满足”记住这个动词。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5798":{"word":"contiguous","mnemonics":[{"method":"CONTAGIOUS → CONTIGUOUS · 接触在一起","textZh":"回想学过的 contagious（有传染性的）：它提示接触后可能传开。contiguous 与它的整体词形很像，这次把注意力留在“接触”本身，想象两块地边贴着边：接壤、相邻。","original":false,"weak":false,"kind":"已学整词对照联想"},{"method":"CONTINUOUS → CONTIGUOUS · 连续拼成一片","textZh":"continuous 是“连续不断的”，和 contiguous 的整体形状、声音都很接近。想象连续铺开的拼图，每一块边缘都贴住下一块，没有空隙：连续的画面靠相接的地块组成，由此记住 contiguous 的接壤。","original":false,"weak":false,"kind":"词形、词音与情境联想"}]},"5799":{"word":"contort","mnemonics":[{"method":"DISTORT → CONTORT · 扭得更厉害","textZh":"回想学过的 distort（使变形、歪曲），认出两词相同的 tort。把 distort 中扭歪的直线，想成被拧得七弯八绕的软铁丝：contort 更突出强烈、不自然地扭曲。","original":false,"weak":false,"kind":"已学词家族联想"},{"method":"COMFORT → CONTORT · 舒服的样子扭歪了","textZh":"把 contort 联想到形近的 comfort（舒服、舒适）：原本舒服地躺着，忽然腿抽筋，身体一下扭得走了样。用“舒服变成扭曲”的反差，把这两个近形词分开。","original":true,"weak":true,"kind":"词形、词音与情境联想"}]},"5800":{"word":"contumacious","mnemonics":[{"method":"conTUMAcious · 吐沫抗命","textZh":"把中间的 tuma 近似联想到“吐沫”：想象一个顽固的人面对命令，不但不照办，还朝命令书上吐唾沫，以示抗拒。由这个明确的抗命动作，记住 contumacious 不服从权威。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"TENACIOUS → CONTUMACIOUS","textZh":"已学 tenacious 是“抓住不放、顽强坚持”。把两个结尾相近的词并排记：tenacious 紧抓目标不放；contumacious 则紧抱自己的做法，即使权威明确命令他停止，也固执地不肯服从。","original":true,"weak":false,"kind":"invented_association"}]},"5801":{"word":"convalesce","mnemonics":[{"method":"VAL＋ESCE · 力量渐渐回来","textZh":"val 带有“强健”的词源含义，-esce 带出“开始变得”的过程。把它想成病后力量一点点回来：昨天只能坐起，今天能缓慢走几步。convalesce 就是逐渐恢复健康和体力。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"CONVULSION＋EASE · 抽搐后渐渐缓过来","textZh":"把已学的 convulsion（抽搐）和 ease（缓解）联想到 convalesce：病人经历抽搐后，病情逐渐缓和，再经过一段休养，力气慢慢回来。由发病到缓解、恢复，记住 convalesce 是病后逐渐康复。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5802":{"word":"convention","mnemonics":[{"method":"CON＋VENT · 大家一起来","textZh":"con- 有“一起”的意思，vent 与“来”的词源有关。想象各地代表一起来到同一座会场，参加一场大会：convention 的集会义由此很好记。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"CONVENTION · 肯纹身","textZh":"近音联想“肯纹身”：想象某个虚构小镇有成年时纹一个小图案的习俗，年轻人都肯按老规矩纹身。“肯纹身”的共同习俗，帮助记住 convention 的惯例、习俗义。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5803":{"word":"converge","mnemonics":[{"method":"CON＋VERGE · 转向同一点","textZh":"con- 表示“一起”，verge 与“倾向、转向”的词源有关。想象四条道路从四面转向同一个中心，越往前距离越近：converge 就是朝共同的一点汇聚。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"CONVERGE · COME AND MERGE","textZh":"近音联想 come and merge（过来并合）：两股车流从不同道路驶向同一汇入口，靠近后合流。由“来到同一点再合流”，记住 converge，重点在汇聚的方向。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5804":{"word":"convert","mnemonics":[{"method":"CON＋VERT · 转成另一种","textZh":"vert 有“转”的词源含义。想象把废纸转成纸浆，再做成新纸：原来的东西经过变化，转成另一种形态。convert 的核心就是这种转变、转化。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"COVER → CONVERT · 盖布改成提袋","textZh":"借熟悉的 cover（覆盖物）联想近形的 convert：同一块布，原先是盖在篮子上的盖布，后来折好、缝上提手，变成装东西的布袋。由 cover 改了用途，记住 convert 把原物转成另一种形式或用途。","original":true,"weak":false,"kind":"invented_association"}]},"5805":{"word":"consort","mnemonics":[{"method":"CON＋SORT · 同一份命运","textZh":"consort 的词源包含“一起”和“份额、命运”。想象两个人一起分担同一份生活，彼此成了常来常往的伙伴：由“同伴”记住 consort 的结交、与人为伍。","original":false,"weak":false,"kind":"etymology"},{"method":"CONCERTED → CONSORT · 一起合作，常常来往","textZh":"已学 concerted 是协调一致的。联想那群经常一起排练、共同配合的人：他们不只合作一次，还常常相聚来往。由近形近音的 concerted，记住 consort with 是与这些人为伴、来往。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5806":{"word":"conviction","mnemonics":[{"method":"CONVINCE → CONVICTION · 信服后深信","textZh":"convince 是“使信服”。想象一个人听完论证，原先的疑虑消退，内心真正信服，并把这个看法坚定地坚持下去：这种深信的状态就是 conviction。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"FICTION ↔ CONVICTION · 虚构，还是坚信？","textZh":"把近形的 fiction（虚构）和 conviction（坚信）放在一起联想：朋友说故事是 fiction，他却坚信真的发生过，毫不动摇。fiction 说的是内容虚构，conviction 说的是他信得坚定，并不保证他信对了。","original":true,"weak":false,"kind":"invented_association"}]},"5807":{"word":"convoke","mnemonics":[{"method":"CON＋VOKE · 叫到一起","textZh":"con- 表示“一起”，vok 与“呼叫”的词源有关。想象主持人发出通知，把分散在各处的代表叫到一起议事：convoke 就是召集开会。","original":false,"weak":false,"kind":"etymology"},{"method":"CONVOKE · COME, FOLKS!","textZh":"近音联想 come, folks（大家来吧）：主持人在会议室门口招呼大家进来，代表们接到召集后围桌就座。由这一声“大家来吧”，记住 convoke 把人召到一起开会。","original":true,"weak":false,"kind":"invented_association"}]},"5808":{"word":"coop","mnemonics":[{"method":"CUP → COOP · 杯下困住了","textZh":"借 cup（杯子）联想 coop：想象把透明杯倒扣在小虫上，小虫只能在杯下打转，活动范围一下被限制住。杯子像一个临时小笼子，由 cup 记住 coop 的关住、困住。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"COOP · 箍住，动不开","textZh":"coop 的声音近似“箍”。想象狭窄房间像一圈紧箍，人在里面连转身都不自在：被“箍”在小空间里，正是 coop 所强调的受拘束、活动不开。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5809":{"word":"coquette","mnemonics":[{"method":"COQ · 小公鸡招摇","textZh":"coquette 所属词族来自法语 coq（公鸡），原先借小公鸡招摇的姿态比喻卖弄吸引力。想象公鸡挺胸踱步、处处吸引注意，由这一姿态记住调情、卖弄风情。","original":false,"weak":false,"kind":"etymology"},{"method":"COQUETTE · 靠客套逗人","textZh":"近音联想“靠客套”：一个人靠甜甜的客套话逗得对方开心，却没有认真交往的打算。记住这种只逗弄、不认真投入的态度，便能联想到 coquette 的调情和玩玩而已。","original":true,"weak":true,"kind":"invented_association"}]},"5810":{"word":"countervail","mnemonics":[{"method":"COUNTER＋VAIL · 以力相抗","textZh":"counter- 表示“相反、对抗”，vail 的词源与“有力量、有价值”有关。想象天平另一侧放上足够的砝码，原先偏重的一侧受到抗衡：countervail 就是以相反力量抵消作用。","original":false,"weak":false,"kind":"etymology"},{"method":"COUNTERVAIL · 抗他威","textZh":"近音联想“抗他威”：对方凭威势步步逼近，大家联合起来与他抗衡，让他的威势不再压倒一切。由“抗他威”记住 countervail 的抗衡、抵消。","original":true,"weak":false,"kind":"invented_association"}]},"5811":{"word":"cornucopia","mnemonics":[{"method":"CORNU＋COPIOUS · 盛满的丰饶角","textZh":"cornu 的词源义是“角”；cornucopia 的后半部分与已学 copious（丰富的）同源，都与拉丁语中“丰富”之意有关。想象角形篮里盛满各种收成，满得快要溢出来：cornucopia 就是丰饶角，也引申为丰富供应。","original":false,"weak":false,"kind":"etymology_and_adopted_word"},{"method":"CORN＋COPIES · 玉米复制成堆","textZh":"借 corn（玉米）和 copies（复制品）联想 cornucopia：想象一根玉米进入复制机器，出口接连出现许多玉米，转眼装满一大筐。由“玉米复制成堆”记住大量、丰富的供应。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5812":{"word":"coronation","mnemonics":[{"method":"CORONA · 王冠加在头上","textZh":"coronation 来自表示“加冠”的拉丁词，corona 意为“王冠”。想象礼官在正式典礼中把王冠戴到君主头上，由 corona 的王冠记住 coronation 的加冕礼。","original":false,"weak":false,"kind":"etymology"},{"method":"COORDINATION → CORONATION · 协调好，再加冕","textZh":"把 coronation 与 coordination（协调）并排看，两词整体很像。想象礼官、乐队先做好 coordination，再把王冠稳稳戴到新君主头上，完成 coronation。记住：协调的是各方动作，加冕的是新君主。","original":true,"weak":false,"kind":"invented_whole_word_contrast"}]},"5813":{"word":"corporeal","mnemonics":[{"method":"CORPOR · 身体的形体","textZh":"corpor- 来自表示“身体”的拉丁词。想到身体有形体、占空间，会饥饿和疲倦：corporeal 既可指肉体的，也可指具有实际形体的。","original":false,"weak":false,"kind":"etymology"},{"method":"CORE＋REAL · 核心也实实在在","textZh":"把 corporeal 的外形联想到 core（核心）和 real（实在的）：想象手里有一个实心球，外表摸得着，连内部核心也实实在在；旁边的球影却捧不起来。由“实在的核心”记住 corporeal 的有实体。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5814":{"word":"corrosive","mnemonics":[{"method":"ROS · 像啃咬一样蚀损","textZh":"corrosive 的词源与“啃咬、咬坏”有关，ros 与 rod 是这一词根的不同形式。想象金属表面被一点点“啃”出坑洞，就能记住腐蚀性的；尖刻话语也仿佛在“啃伤”人。","original":false,"weak":false,"kind":"etymology"},{"method":"CAR RUST · 汽车被锈蚀","textZh":"借 car rust（汽车生锈）联想 corrosive：海边的汽车长期处在潮湿、含盐的环境里，车身逐渐锈蚀。生锈是结果，有腐蚀性的环境才是 corrosive 所形容的对象。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5815":{"word":"corrugated","mnemonics":[{"method":"RUGA · 褶皱排成波浪","textZh":"corrugated 的词源可追溯到拉丁语 ruga（褶皱、沟槽）。想象把平纸一折一反折，压出一排凸棱和沟槽：这些褶皱连起来，就是 corrugated 的波纹状、瓦楞状。","original":false,"weak":false,"kind":"etymology"},{"method":"RUGGED ↔ CORRUGATED · 从崎岖山地到波纹纸板","textZh":"把 corrugated 与 rugged（崎岖不平的）并排联想：起伏的山脊和山谷，缩小后像纸板上的一排凸棱与凹槽。rugged 是不平整，corrugated 则把这幅起伏图收拢成有规律的瓦楞。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5816":{"word":"countermand","mnemonics":[{"method":"COUNTER＋COMMAND · 反令撤回原令","textZh":"counter- 表示“相反、对抗”，mand 与 command（命令）中的部分同源。先有“向前走”的命令，随后发布“停下，原命令取消”：用反向命令撤销原令，就是 countermand。","original":false,"weak":false,"kind":"etymology_and_familiar_word"},{"method":"COUNTER＋MAN · 柜台前撤单","textZh":"借 counter（柜台）和 man（男子）联想：经理刚让厨房准备一份餐食，又走回柜台，对店员明确说“取消刚才那单，不做了”。把柜台前男子撤回原指令的画面，与 countermand 连起来。","original":false,"weak":true,"kind":"adapted_public_method"}]},"5817":{"word":"covetous","mnemonics":[{"method":"COVET＋OUS · 想要变成贪求的","textZh":"接回已学 covet（强烈想拥有，觊觎）：covet 说“想把别人的东西变成自己的”，covetous 用来形容抱着这种贪求心态的人或目光。动词是觊觎，形容词是贪求的。","original":false,"weak":false,"kind":"adopted_word_family"},{"method":"COVERED EYES · 眼馋得捂住眼","textZh":"借 covered eyes（被遮住的眼睛）的近音联想 covetous：邻居开来漂亮新车，他想据为己有，越看越眼馋，索性捂住眼睛。由“眼馋得遮住双眼”记住贪求别人东西的心态。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5818":{"word":"cowardice","mnemonics":[{"method":"COWARD · 夹尾巴的怯懦","textZh":"cowardice 与 coward（懦夫）同属一个词族；coward 的历史来源与“尾巴”有关，可能让人联想到害怕时夹着尾巴的动物。用“夹尾退缩”的画面记住：coward 是懦弱的人，cowardice 是怯懦。","original":false,"weak":false,"kind":"etymology"},{"method":"COWER ↔ COWARDICE · 从畏缩动作到怯懦","textZh":"接回已学 cower（害怕得畏缩），它与 cowardice 开头的声音相近。想象有人本该站出来承认错误，却缩肩退到角落：cower 描写畏缩的动作，cowardice 点明这里缺乏担当的怯懦。","original":false,"weak":false,"kind":"adopted_whole_word_comparison"}]},"5819":{"word":"cozen","mnemonics":[{"method":"COUSIN ↔ COZEN · 冒认表亲来骗钱","textZh":"cozen 与 cousin（堂表兄弟姐妹）读音相同。想象陌生人自称你的 cousin，热情套近乎，实际想骗走钱财：由假表亲的骗局记住 cozen，诱骗。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"DOZEN ↔ COZEN · 十二个却谎称两个","textZh":"cozen 与 dozen（一打，十二个）押韵。想象试卷上错了整整一打题，学生却把卷子藏起来，骗家长说只错两题。用隐瞒 dozen 的小骗局记住 cozen，欺骗。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5820":{"word":"cramped","mnemonics":[{"method":"CRAM ↔ CRAMPED · 塞满后伸不开","textZh":"cram 是把许多东西硬塞进去。把 cram 与 cramped 并排看：想象行李和人塞满小车，膝盖顶着前排，转身都困难。塞进去是 cram，挤得伸不开的状态是 cramped。","original":false,"weak":false,"kind":"adapted_familiar_word_comparison"},{"method":"CAMPED ↔ CRAMPED · 帐篷挤得转不开","textZh":"把 cramped 与 camped（露营过、扎营了）的近似外形并排记：四个人挤在一顶小帐篷里，睡袋互相顶着，谁都伸不直腿。露营 camped 的画面，连到狭小挤促的 cramped。","original":true,"weak":false,"kind":"invented_whole_word_comparison"}]},"5821":{"word":"craven","mnemonics":[{"method":"BRAVE ↔ CRAVEN · 字形相近，胆量相反","textZh":"把 brave（勇敢的）和 craven 并排看，它们中间的 rave 很像，意思却相反。想象面对同一件该承担的责任，brave 的人站出来，craven 的人躲到别人身后：一进一退，记住极其懦弱。","original":false,"weak":false,"kind":"adapted_public_method"},{"method":"CAVE IN ↔ CRAVEN · 一受压就屈服","textZh":"借 cave in（屈服、让步）的近音联想 craven。想象一个人明知不该签假证明，却不敢坚持，一受压力就缩肩点头。这里的 craven，是因胆怯而彻底退让的样子。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5822":{"word":"contingency","mnemonics":[{"method":"CONTINGENT → CONTINGENCY · 从不确定到可能情况","textZh":"接回已学 contingent（取决于条件的、可能发生但不确定的）。原先说某件事 contingent，现在把这件可能发生的情况叫 contingency：例如天气会不会突变还不确定，先把雨衣备好。","original":false,"weak":false,"kind":"adopted_word_family"},{"method":"EMERGENCY ↔ CONTINGENCY · 先备可能，后应紧急","textZh":"把 contingency 与 emergency（紧急情况）的相似结尾并排联想：桌上先放好应急包，是为可能出现的 contingency 做准备；若严重事故真的发生，就要处理 emergency。用“未必发生，先作准备”记住 contingency。","original":true,"weak":false,"kind":"invented_whole_word_contrast"}]},"5823":{"word":"credence","mnemonics":[{"method":"CREDIT → CREDENCE · 从信用到相信","textZh":"接回已学 credit 的“信用”：银行愿意让你先买后付，因为相信你会还款。credit 和 credence 都带着“相信”的词源线索；把这种信任转到一个说法上，就是给予它 credence。","original":false,"weak":false,"kind":"adopted_word_family"},{"method":"EVIDENCE → CREDENCE · 有了证据，更愿意信","textZh":"把 evidence（证据）与 credence 的近似外形并排联想：起初不信窗边来过猫，看到脚印这份 evidence 后，对这个说法多了一分 credence。证据是依据，credence 是由此增加的相信；证据仍可能不充分。","original":false,"weak":false,"kind":"adapted_public_method"}]},"5824":{"word":"creep","mnemonics":[{"method":"KEEP QUIET → CREEP · 安静地慢慢挪","textZh":"先想到 keep quiet（保持安静），再借 keep 与 creep 的近音相连：房间里有人睡觉，你放轻脚步，一点点挪过门边。由 keep 的声音接到 creep，记住缓慢、悄悄地移动。","original":true,"weak":false,"kind":"invented_whole_word_sound"},{"method":"CREEPY → CREEP · 吓人的小东西悄悄爬","textZh":"creepy 表示“怪异吓人的”。想象一只小蜘蛛悄无声息地沿墙慢慢爬来，让人起鸡皮疙瘩：creepy 说的是吓人的感觉，creep 说的是它缓缓爬来的动作。","original":false,"weak":false,"kind":"adapted_familiar_word_family_scene"}]},"5825":{"word":"crescendo","mnemonics":[{"method":"短词源 · 声音也会长大","textZh":"crescendo 来自意大利语，原意是“正在增长”。想象指挥的手势越抬越高，鼓声从轻到重不断长大，最后冲到高潮：从“增长”记住“渐强”，再连到渐强后的顶峰。","original":false,"weak":false,"kind":"adapted_short_etymology"},{"method":"近音“可升多” · 音量还可升很多","textZh":"借 crescendo 的近音“可升多”来记：指挥示意音量还可升很多，鼓手不是突然猛敲一下，而是一拍比一拍响，直到高潮。用“可升多”的声音，串起渐强和最后的顶峰。","original":false,"weak":false,"kind":"adapted_chinese_sound"}]},"5826":{"word":"crest","mnemonics":[{"method":"REST → CREST · 到山顶再休息","textZh":"把 rest（休息）和 crest 并排看，crest 几乎就是 rest 前面多了一个字母。想象登山的人约好到山顶才 rest，终于在 crest 坐下喘气：休息的终点，就是山顶。","original":false,"weak":false,"kind":"adapted_public_familiar_word"},{"method":"短词源 · 头顶羽冠，山顶如冠","textZh":"crest 的词源指一簇羽毛、羽饰，今天也仍有鸟的羽冠这一义。先看公鸡头顶高高立起的冠，再看山脊或浪最上面凸起的一线：把“顶上的冠”连到顶部、山顶和浪尖。","original":false,"weak":false,"kind":"adapted_short_etymology"}]},"5827":{"word":"cronyism","mnemonics":[{"method":"短词史 · 友谊走进招聘室","textZh":"cronyism 最初表示“友谊”，后来出现了不顾能力任用朋友的贬义。把这段变化想成一张老同学合影走进招聘室，压住了成绩更好的简历：私人友谊压过了任职能力，就成了 cronyism。","original":false,"weak":false,"kind":"adapted_short_word_history"},{"method":"近音“靠你一生” · 靠老友拿职位","textZh":"借 cronyism 的近音“靠你一生”来记：一个人对掌权的老朋友说“工作就靠你一生啦”，不凭本事，却总能得到好职位。从这句靠交情的话，记住偏袒好友、任用亲信。","original":false,"weak":false,"kind":"adapted_chinese_sound"}]},"5828":{"word":"crook","mnemonics":[{"method":"HOOK ↔ CROOK · 弯得像钩子","textZh":"把 hook（钩子）和 crook 的相近声音一起记。伸直食指，再把指尖弯回来，形状就像一只小 hook；把手指弯成这样，就是 crook a finger。","original":false,"weak":false,"kind":"adapted_familiar_word_sound"},{"method":"CROOKED → CROOK · 从弯的状态回到弯的动作","textZh":"crooked 作形容词时读 /ˈkrʊkɪd/，表示“弯曲的、不直的”，如一根歪弯的枝条。把 crooked 与 crook 并排：前者说已经弯了的样子，后者说让它弯起来的动作。记住“弯的状态”和“使弯曲”的对应。","original":false,"weak":false,"kind":"adapted_familiar_word_family"}]},"5829":{"word":"croon","mnemonics":[{"method":"MOON ↔ CROON · 月下轻轻唱","textZh":"moon（月亮）与 croon 押韵。想象安静的月夜，妈妈怕吵醒隔壁的人，抱着宝宝柔声唱摇篮曲：由 moon 的声音想到 croon，记住轻轻地、温柔地唱。","original":false,"weak":false,"kind":"adapted_familiar_word_rhyme"},{"method":"短词源与发声 · 低吟变成轻唱","textZh":"croon 的词源与“呻吟、哀吟”有关。轻轻读 croon，把中间的长音拖成一声低吟，再让它连上温柔的曲调：低吟变成轻唱，记住 croon 是柔声低唱或低语，不是高声喊叫。","original":false,"weak":true,"kind":"adapted_short_etymology_and_voicing"}]},"5830":{"word":"culminate","mnemonics":[{"method":"culmination 变成动作","textZh":"已学 culmination 是“顶点、高潮”；同族的 culminate 把那个终点变成“达到终点”的动作：研究成果是 culmination，研究最终取得成果就是 culminate。","original":false,"weak":false,"kind":"verified_word_family"},{"method":"culmin- 登上峰顶","textZh":"culmin- 的词源意象是“峰顶”。想象一路登山，最后一步站上山顶：不是随便停下，而是整个过程终于到顶。","original":false,"weak":false,"kind":"short_etymology"}]},"5831":{"word":"crucial","mnemonics":[{"method":"cruc- 十字路口","textZh":"cruc- 的词源意象是“十字”。想象走到岔路口，一次选择就决定后面的方向；crucial 便是这种会决定走向的“关键的”。","original":false,"weak":false,"kind":"short_etymology"},{"method":"crucial 近音“苦修”","textZh":"把 crucial 近音联想成“苦修”：选手反复苦修最后那一招，因为它决定比赛成败。那一招不是普通动作，而是关键的一招。","original":false,"weak":false,"kind":"chinese_sound_association"}]},"5832":{"word":"crumple","mnemonics":[{"method":"crumble 碎，crumple 皱","textZh":"对照已学 crumble：饼干一捏，碎成渣；换成近形的 crumple，纸一捏，皱成团。把“饼干碎、纸团皱”并排记，避免把两词混成同一个意思。","original":false,"weak":false,"kind":"verified_near_form_contrast"},{"method":"crump- 反复卷曲","textZh":"crumple 的词史与“卷曲、弯曲”相连，这个词可能由表示反复卷曲的形式发展而来。想象纸边一处接一处卷折进去，整张纸便揉得皱巴巴。","original":false,"weak":false,"kind":"short_etymology"}]},"5833":{"word":"crutch","mnemonics":[{"method":"clutch 抓住，crutch 撑住","textZh":"已学 clutch 是“紧抓”。把近形、押韵的两个词放在同一动作里：手 clutch 紧抓手柄，crutch 拐杖替身体提供支撑。","original":false,"weak":false,"kind":"verified_near_form_association"},{"method":"crutch 近音“可拄”","textZh":"把 crutch 近音联想成“可拄”：受伤的腿不敢用力，好在旁边这根杖可拄，身体有了支撑才站得稳。","original":false,"weak":false,"kind":"chinese_sound_association"}]},"5834":{"word":"crux","mnemonics":[{"method":"crux 与 cross 的交会点","textZh":"crux 的拉丁语本义是“十字”。借 cross（十字交叉）的图形想象：众多线索交会在同一点，抓住这个交会的关键点，就抓住问题的 crux。","original":false,"weak":false,"kind":"etymology_visual_association"},{"method":"crux 近音 cracks","textZh":"把 crux 与 cracks（裂缝）近音联系：房屋为何不稳？检查后发现承重墙上的裂缝正是问题关键。看到 cracks，就想到必须先解决的 crux。","original":false,"weak":false,"kind":"familiar_whole_word_sound"}]},"5835":{"word":"cultivate","mnemonics":[{"method":"culture 靠培养","textZh":"culture 是“文化、修养”，和 cultivate 同源。把心智想成一块园地：读书、练习、细心照料，才能培养出修养；cultivate 就是这种用心栽培的动作。","original":false,"weak":false,"kind":"familiar_word_family"},{"method":"cultivate 先栽培，captivate 再迷住","textZh":"对照已学 captivate“迷住”：园丁先 cultivate 花草，花园长得漂亮，才 captivate 游客。近形词放在前后两个动作里：前者用心培养，后者吸引住人。","original":false,"weak":false,"kind":"verified_near_form_contrast"}]},"5836":{"word":"curmudgeon","mnemonics":[{"method":"curmudgeon 近音“可骂紧”","textZh":"把 curmudgeon 近音联想成“可骂紧”：茶热了嫌烫，放凉又嫌冷，嘴里可抱怨得紧。记住的不是一次发火，而是那个总爱挑剔、坏脾气的人。","original":false,"weak":false,"kind":"chinese_sound_association"},{"method":"curmudgeon 不肯 budge","textZh":"已学 budge 有“让步”的意思。用它的尾音去提醒 curmudgeon 的重读音节：怎么劝都不肯 budge，还不停嫌这嫌那，眼前就是一个爱抱怨的坏脾气家伙。","original":false,"weak":true,"kind":"verified_partial_sound_scene"}]},"5837":{"word":"dabble","mnemonics":[{"method":"dabble 近音“打波儿”","textZh":"把 dabble 近音想成“打波儿”：只在水面拨两下水波，不往深处去。学画也只是试两笔就放下，这种只碰一点、不深入的参与就是涉猎。","original":false,"weak":false,"kind":"chinese_sound_association"},{"method":"babble 嘴上聊，dabble 动手试","textZh":"已学 babble 是“喋喋不休”。把近形、押韵的两词分开：babble 是一直聊画画，dabble 是终于拿起笔，却只随手试几笔；从嘴上说转到浅浅做。","original":false,"weak":false,"kind":"verified_near_form_contrast"}]},"5838":{"word":"daft","mnemonics":[{"method":"deft 手巧，daft 主意傻","textZh":"对照已学 deft“灵巧的”：手很巧，能折出精细纸伞；却打算拿纸伞接水，主意就很 daft。两个近形短词，一个夸手巧，一个说判断不明智。","original":false,"weak":false,"kind":"verified_near_form_contrast"},{"method":"daft 近音“打发他”","textZh":"把 daft 近音记成“打发他”：有人来提醒纸箱漏水，却不听内容就把人打发走。连提醒都不听就赶人，这个决定实在不明智。","original":false,"weak":false,"kind":"chinese_sound_association"}]},"5839":{"word":"dazzling","mnemonics":[{"method":"dizzy 的人，dazzling 的光","textZh":"dizzy 是“头晕的”。把两词相近的声音和模样连起来：强光晃得人 dizzy，让人目眩的那束光就是 dazzling；别把发晕的人和耀眼的光混为一谈。","original":false,"weak":false,"kind":"familiar_whole_word_association"},{"method":"darling 耀眼登场","textZh":"darling 是“亲爱的”，也就是常说的“达令”。把近形的 darling 和 dazzling 并排记：亲爱的穿亮片礼服登场，灯光一照，整身耀眼夺目。darling 是亲爱的人，dazzling 是礼服闪出的夺目光彩。","original":false,"weak":false,"kind":"familiar_whole_word_visual_contrast"}]},"5840":{"word":"dally","mnemonics":[{"method":"dally 近音“大理”","textZh":"把 dally 近音联想成“大理”：返程该出发了，你却还在大理街头闲逛，迟迟不走。误了正事的闲逛，就是 dally。","original":false,"weak":false,"kind":"chinese_sound_association"},{"method":"delay 延迟，dally 磨蹭","textZh":"把熟词 delay（延迟）和近形的 dally 并排记：delay 说时间被推迟，dally 说人自己慢吞吞地拖着。不是车晚点，而是你还不肯出门。","original":false,"weak":false,"kind":"familiar_whole_word_contrast"}]}});

// Exact root-reviewed complete release through 2600.
Object.assign(approvedMnemonicRecords,{"5841":{"word":"damper","mnemonics":[{"method":"dampen 动作，damper 因素","textZh":"已学 dampen 是“使减弱、使扫兴”；同族的 damper 指造成这种结果的人或事：坏消息让热情减弱，那条坏消息就是一个 damper。","original":false,"weak":false,"kind":"verified_word_family"},{"method":"dam 水坝挡住兴头","textZh":"先看完整熟词 dam（水坝）：水坝拦水。把这个阻挡画面放进 damper，想象热情正往前涌，却被一个坏消息拦住；那就是扫兴的抑制因素。","original":false,"weak":false,"kind":"familiar_word_visual_association"}]},"5842":{"word":"dandy","mnemonics":[{"method":"daddy 爱打扮","textZh":"dandy 与 daddy（爸爸）近形近音。想象爸爸出门前反复挑领带、照镜子，连小小的搭配都不肯马虎：这位格外讲究外表的爸爸就是一个 dandy。","original":false,"weak":false,"kind":"familiar_whole_word_sound"},{"method":"dainty 精致，dandy 讲究","textZh":"对照已学 dainty 的“小巧精致”：从一件精致的饰物，想到那位对饰物、领巾和整套穿搭格外挑剔的男子。物件是 dainty，人则是爱讲究外表的 dandy；只借近形对照。","original":false,"weak":false,"kind":"verified_near_form_association"}]},"5843":{"word":"dank","mnemonics":[{"method":"damp 潮湿，dank 阴湿","textZh":"已学 damp 是“潮湿的”。把近形的 dank 记成更令人不舒服的湿冷场所：毛巾有些 damp，阴冷的地下室则让人觉得 dank。","original":false,"weak":false,"kind":"verified_near_form_contrast"},{"method":"tank 水箱的阴湿内壁","textZh":"dank 与 tank（水箱）押韵、近形。想象阴凉旧水箱的内壁挂着水珠，空气又湿又冷；这个不舒服的湿冷感就是 dank。","original":false,"weak":false,"kind":"familiar_whole_word_sound"}]},"5844":{"word":"dapper","mnemonics":[{"method":"dapper 近音“搭配儿”","textZh":"把 dapper 近音联想成“搭配儿”：衣领平整、领结合适、鞋子擦净，整套搭配儿利落得体，看上去就是 dapper。","original":false,"weak":false,"kind":"chinese_sound_association"},{"method":"rapper 换上整洁西装","textZh":"dapper 与 rapper（说唱歌手）押韵，只换开头一个辅音。想象一位 rapper 换上合身整洁的西装，仪表利落：他今天很 dapper。记的是这次穿搭，不是说歌手都这样穿。","original":false,"weak":false,"kind":"familiar_whole_word_sound"}]},"5845":{"word":"dappled","mnemonics":[{"method":"dAPPLEd：苹果皮上的点","textZh":"dappled 中能直接看到 apple（苹果）。想象红苹果皮上散布着浅色小点：底色之上有一片片不同颜色，正是 dappled 的斑点感。","original":false,"weak":false,"kind":"familiar_whole_word_visual"},{"method":"dappled 近音“打破了”","textZh":"把 dappled 近音联想成“打破了”：小墨水瓶打破了，白纸上溅出许多细小墨点。记住纸上深浅相间的小斑点，而不是瓶子的碎片。","original":false,"weak":false,"kind":"chinese_sound_association"}]},"5846":{"word":"daredevil","mnemonics":[{"method":"dare + devil：连魔鬼都敢挑战","textZh":"dare 是“敢于、挑战”，devil 是“魔鬼”。合在一起，想象一个连魔鬼都敢挑战的人：胆子大到不顾危险，就是 daredevil。","original":false,"weak":false,"kind":"transparent_compound"},{"method":"Daredevil：“无畏之人”","textZh":"借漫威角色 Daredevil 的“无畏之人”称号，想起他迎着危险行动的画面。再给日常词义补上“鲁莽、爱冒险”：daredevil 不只是勇敢，更是敢冒危险的人。","original":false,"weak":true,"kind":"verified_cultural_retrieval"}]},"5847":{"word":"dart","mnemonics":[{"method":"dart 飞镖：又快又尖","textZh":"先抓住 dart 的具体义“飞镖”：飞镖一下射出去，就能带回动词“突然快速移动”；话像飞镖一样刺过来，则是名词“伤人的讥讽”。","original":false,"weak":false,"kind":"concrete_to_figurative_bridge"},{"method":"start 一响，dart 冲出","textZh":"把熟词 start（开始）和近形押韵的 dart 连起来：赛跑刚一开始，选手立刻 dart 出起跑线。记住那一下突然冲出的速度。","original":true,"weak":false,"kind":"familiar_whole_word_rhyme"}]},"5848":{"word":"daunt","mnemonics":[{"method":"daunting 的动作就是 daunt","textZh":"已学 daunting 是“令人畏惧的”。一项 daunting 的艰巨任务让人没了信心，这个“使人畏缩”的作用就是 daunt；形容任务的性质，转为说它对人的影响。","original":false,"weak":false,"kind":"verified_word_family"},{"method":"haunt 闹鬼，daunt 吓退","textZh":"已学 haunt 可以说鬼魂出没；它和 daunt 只差开头一个字母，也押韵。想象你本想进老屋，却听见闹鬼的传闻，立刻没了勇气：这传闻 daunts you，使你胆怯。","original":false,"weak":false,"kind":"verified_whole_word_sound"}]},"5849":{"word":"dawdle","mnemonics":[{"method":"dawdle 近音“踱踱”","textZh":"把 dawdle 近音联想成“踱踱”：该赶紧出发了，你却还慢悠悠地踱来踱去。重点不是散步本身，而是该快的时候仍在磨蹭。","original":false,"weak":false,"kind":"chinese_sound_association"},{"method":"doodle 涂鸦，dawdle 拖拉","textZh":"doodle（随手涂鸦）与 dawdle 近形近音。想象该填好的表格还空着，你却不断在边角涂鸦，迟迟填不完；这种拖拖拉拉就是 dawdle。","original":false,"weak":false,"kind":"familiar_whole_word_sound"}]},"5850":{"word":"deadpan","mnemonics":[{"method":"dead + pan：板着一张脸","textZh":"dead 是“死的、无生气的”；pan 在这个词里来自“脸”的俚语。把它想成一张表情纹丝不动的脸：嘴里说着笑话，脸上却像按了暂停键。","original":false,"weak":false,"kind":"short_etymology"},{"method":"deadpan 近音“呆板”","textZh":"把 deadpan 近音联想成“呆板”：讲笑话的人脸上呆板得看不出笑意，旁人却已经笑起来。记住呆板的是外在表情，不是笑话一定无聊。","original":true,"weak":false,"kind":"chinese_sound_association"}]},"5851":{"word":"debark","mnemonics":[{"method":"de + bark：从船上下来","textZh":"这个词的词源中，de- 表示离开，bark 对应“船”。想象乘客沿跳板离开船，最后双脚落到码头：debark，完成下船。这里的 bark 不是狗叫。","original":false,"weak":false,"kind":"short_etymology"},{"method":"debark 近音 the bank","textZh":"把 debark 的整体声音联想到 the bank（河岸）。小船停稳后，乘客不再留在船上，而是迈到河岸上；想到 the bank，就记住下船上岸的动作。","original":true,"weak":false,"kind":"familiar_phrase_sound"}]},"5852":{"word":"debilitate","mnemonics":[{"method":"ability 被削弱了","textZh":"借熟词 ability（能力）来联想 debilitate：原来轻松就能提起的包，生病后却提不动了。能力和力量被削弱，便是 debilitate。","original":false,"weak":false,"kind":"public_ability_association"},{"method":"rehabilitate 恢复，debilitate 削弱","textZh":"对照已学 rehabilitate“使恢复功能”：疾病让人越来越无力，是 debilitate；康复训练帮助他重新站稳、恢复功能，是 rehabilitate。两个长词相似，却把身体带向相反方向。","original":false,"weak":false,"kind":"verified_whole_word_contrast"}]},"5853":{"word":"debris","mnemonics":[{"method":"debris 近音“堆玻璃”","textZh":"把 debris 近音联想成“一堆玻璃”：窗户已经打碎，地上剩下一堆碎玻璃。这些破碎后散落的残片就是 debris。","original":false,"weak":false,"kind":"chinese_sound_association"},{"method":"debris 与 the breeze","textZh":"把 debris 与 the breeze（微风）的整体声音联系起来：风一吹，地上的轻纸屑和碎叶便四散飘动。记住风吹散的是遗留下来的碎屑 debris，不是完好的东西。","original":false,"weak":false,"kind":"familiar_phrase_sound"}]},"5854":{"word":"decadence","mnemonics":[{"method":"decay 延伸到文化衰落","textZh":"联想已学 decay“腐朽、衰败”。decadence 与 decay 在词源上相关；把木头逐渐失去坚实状态的 decay，换成一个文化环境逐渐失去创造力和活力，就抓住 decadence 的衰落义。","original":false,"weak":false,"kind":"verified_whole_word_bridge"},{"method":"decade：荒废十年后的剧院","textZh":"用近形的 decade（十年）带出 decadence：这座从前热闹的剧院，一个 decade 都疏于经营，演出渐少、观众散去，终于失去往日活力。把“十年荒废后的衰落”连起来记。","original":false,"weak":false,"kind":"familiar_whole_word_form_association"}]},"5855":{"word":"detest","mnemonics":[{"method":"detest 近音 the test","textZh":"把 detest 的整体声音联想到 the test（那场考试）：刚考完一场，又被安排同一套题，令人一看到试卷就厌恶不已。由“极其讨厌那场 test”记住 detest。","kind":"public_familiar_phrase_sound","original":false,"weak":false},{"method":"detestation 的动词 detest","textZh":"已学 detestation 是“强烈憎恶”这种感情。把词尾 -ation 收起，就留下 detest：原来是“对乱扔垃圾的憎恶”，现在说“我憎恶乱扔垃圾”。同一种强烈反感，换成动词表达。","kind":"verified_whole_word_family","original":false,"weak":false}]},"5856":{"word":"decipher","mnemonics":[{"method":"de + cipher：解开密码","textZh":"回想已学 cipher“密码、加密方法”。de- 在这里表示逆转：cipher 把原意藏在变换规则里，decipher 则解开它，让消息重新读得懂。","kind":"verified_whole_word_plus_reversal","original":false,"weak":false},{"method":"decipher 近音“得细分”","textZh":"把 decipher 的声音近似联想到“得细分”：一行潦草字挤在一起，得把连着的笔画仔细分清，才终于读懂。这幅费力辨字的画面帮助记住 decipher。","kind":"chinese_sound_association","original":true,"weak":true}]},"5857":{"word":"decode","mnemonics":[{"method":"de + code：把编码解开","textZh":"code 是“编码、代码”；de- 在这里表示反向处理。想象扫码后，原来的一块二维码变成可读的店名和地址：从 code 回到能理解的信息，就是 decode。","kind":"public_transparent_morphology","original":false,"weak":false},{"method":"decode 近音 the coat","textZh":"把 decode 的整体声音联想到 the coat（外套）：想象原话被一件“密码外套”包住，打开外套后，里面的原话才露出来。由揭开包裹、读出内容，记住 decode。","kind":"familiar_phrase_sound","original":true,"weak":false}]},"5858":{"word":"decorous","mnemonics":[{"method":"decorous：待客有礼","textZh":"听到 decorous，借开头的近音想到“待客”。客人来时认真听、不抢话、礼貌回应，待客的言行有分寸，就很 decorous。","kind":"public_chinese_sound_association","original":false,"weak":false},{"method":"decorate 房间，decorous 举止","textZh":"借熟词 decorate（装饰）联想：装饰房间，要让它看起来体面；把注意力换到待人接物，言谈举止也要体面合宜。看到相近的 decor- 外形，就从“房间体面”转到“行为得体”。","kind":"public_familiar_word_form_analogy","original":false,"weak":false}]},"5859":{"word":"decrepit","mnemonics":[{"method":"decrepitude 换成形容词 decrepit","textZh":"回想已学 decrepitude“老朽、破败的状态”：那间屋顶下垂、木头腐朽的旧木屋，处于 decrepitude；直接形容这间屋子，就说 decrepit。长词的整段词形和旧木屋画面一起带回意思。","kind":"verified_whole_word_family","original":false,"weak":false},{"method":"decrepit：scrap it，报废吧","textZh":"把 decrepit 的重读后半段联想到 scrap it（把它报废）。一辆用了多年的旧车，车门松垮、车身锈坏，只能被建议 scrap it；它已经破旧不堪，就是 decrepit。","kind":"public_familiar_phrase_sound","original":false,"weak":false}]},"5860":{"word":"default","mnemonics":[{"method":"default 近音 the fault","textZh":"把 default 的声音联想到 the fault（这个过失）：约好今天还钱，到了期限却没还。这个过失不是算错数，而是该履行的还款义务没履行，由此记住 default。","kind":"public_familiar_phrase_sound","original":false,"weak":false},{"method":"default：默认背后的“没做”","textZh":"借熟悉的电脑 default（默认设置）搭桥：你没有主动选择，系统就采用默认值。转到义务上，该付款、该到场却没有做，就会出现 default，违约或弃权。一个是没有另作选择，一个是没有履行义务；默认设置本身不是过错。","kind":"public_polysemy_bridge","original":false,"weak":false}]},"5861":{"word":"defer","mnemonics":[{"method":"prefer to defer：宁愿晚点做","textZh":"prefer（宁愿）和 defer 押韵。遇到一项还没准备好的决定，就想 prefer to defer：宁愿先推迟，等准备好了再作决定。由“宁愿晚点做”记住 defer。","kind":"public_familiar_word_rhyme","original":false,"weak":false},{"method":"differ 与 defer：改到更晚","textZh":"differ 是“不同”，与 defer 词形相近。想象日程上的时间变得不同：原定今天的事，挪到明天再做。defer 不是任意改时间，而是改到更晚，推迟。","kind":"familiar_whole_word_form_contrast","original":false,"weak":false}]},"5862":{"word":"document","mnemonics":[{"method":"documentary 的证据变成动作","textZh":"回想已学 documentary 的搭配 documentary evidence（文件证据）：合同、信件和记录能给说法作证。收起词尾 -ary，改用动词 document，就是把这些材料拿出来，用证据证实。","kind":"verified_whole_word_family","original":false,"weak":false},{"method":"document 近音“多抠门”","textZh":"借 document 的近音想到“多抠门”：这位老板连一元钱的报销也要看发票。拿出发票，用凭证 document（证实）这笔开销。记住的是“用证据证实”，不是抠门或索要发票本身。","kind":"public_chinese_sound_adaptation","original":false,"weak":false}]},"5863":{"word":"deficiency","mnemonics":[{"method":"defect：缺了该有的东西","textZh":"已学 defect 的书包有一条肩带断了，是个缺陷。再看缺了什么：本来要两条可用肩带，现在只有一条，不够用。把这个“该有的没够”连到同族 deficiency：defect 泛指毛病，deficiency 强调缺乏、不足。","kind":"verified_whole_word_family","original":false,"weak":false},{"method":"efficiency 再高，也有 deficiency","textZh":"efficiency（效率）与 deficiency 声音、词形相近，留意 deficiency 开头的 d。十个人的活只来了三人，干得再利索，人手仍然不足：高 efficiency 也补不上人手 deficiency。用“效率高，但人手少”的反差记住不足，不把两词当反义词。","kind":"familiar_whole_word_sound_form_contrast","original":true,"weak":false}]},"5864":{"word":"defuse","mnemonics":[{"method":"de + fuse：拆掉引线","textZh":"fuse 是“引信、导火线”；de- 在这里表示去掉。把导火线拆掉，危险就不再一触即发。由解除爆炸危险，联想到让一场快要爆发的争吵降温：defuse，缓和紧张。","kind":"public_transparent_morphology","original":false,"weak":false},{"method":"diffuse 柔光，defuse 缓和","textZh":"回想已学 diffuse 的磨砂玻璃：集中的光散开后，变得柔和。把这幅“紧聚变柔和”的图像换到人的火气：原本紧绷的两人听过劝解，神情放松、语气缓和，就是 defuse。不是让争吵传播出去，而是让火气缓下来。","kind":"public_verified_whole_word_contrast","original":false,"weak":false}]},"5865":{"word":"dehydrate","mnemonics":[{"method":"dehydrate：把水去掉","textZh":"抓住 de-（除去）和 hydr（水）：一片饱满的鲜苹果，水分被慢慢除去，变薄、变皱，成为苹果干。dehydrate 不是把苹果毁掉，而是把其中的水去掉。","kind":"public_morphology_image","original":false,"weak":false},{"method":"dehydrate 近音“海带”","textZh":"听到 dehydrate，抓住其中近似“海带”的声音：湿润的新鲜海带摊在阳光下，渐渐晒成干海带。海带从湿到干，直接带回“去除水分、使干燥”。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5866":{"word":"deject","mnemonics":[{"method":"conjecture 的 ject 向下了","textZh":"记起已学的 conjecture（推测）：把线索“投到一起”来推测，里面的 ject 带出“投”的线索。deject 换成 de-（向下），像把人的精神往下抛，让人垂头丧气。","kind":"adopted_helper_morphology","original":false,"weak":false},{"method":"reject 作品，deject 作者","textZh":"把形近的 reject（拒绝）和 deject 放在一幕里：作品被 reject，作者听到结果后肩膀一沉，消息使他 dejected。记住被拒的是作品，被打击的是人的心情。","kind":"public_familiar_word_causal_contrast","original":false,"weak":false}]},"5867":{"word":"delicacy","mnemonics":[{"method":"delicate 的“精致”变名词","textZh":"从熟悉的 delicate（精巧的、细致的）入手：细线织成的蕾丝很 delicate；把这种“精致的性质”说成名词，就是 delicacy。形容物品，和说出它的精细之处，连在一起记。","kind":"public_word_family","original":false,"weak":false},{"method":"delicious 糕点，delicacy 糖花","textZh":"由形近的 delicious（美味的）想到精美糕点，再把目光移到上面薄薄的糖花：花瓣细、花纹巧，这种结构上的精细就是 delicacy。糕点可以是一道美味，但这里记的是糖花做得精致，不只是“好吃”。","kind":"public_adapted_food_to_structure_bridge","original":false,"weak":false}]},"5868":{"word":"delirium","mnemonics":[{"method":"delirium 近音“地理”","textZh":"把 delirium 开头的声音近似联想到“地理”：病中的人突然认不清自己在哪里，明明在诊室，却把地点和时间说乱了。用“所在何地都混乱”去带回急性神志混乱，不是说地理学不好就有病。","kind":"public_adapted_chinese_approximate_sound","original":false,"weak":true},{"method":"deliberate 有条理，delirium 混乱","textZh":"并排回想已学的 deliberate（仔细考虑）：清醒地把理由一条条排好，再作判断。换到 delirium，病中的思路乱了，连眼前的问题也难以跟住。用“仔细想”与“想不清”的反差，提醒自己分开这两个形近词。","kind":"adopted_helper_shape_semantic_contrast","original":false,"weak":true}]},"5869":{"word":"delusion","mnemonics":[{"method":"illusion 看似，delusion 信真","textZh":"用形近的 illusion 搭桥：水里的直吸管看起来弯了，可以是视觉 illusion；事实已说明没有弯，却仍坚信它真的弯了，用这幅对照记 delusion 的错误信念。只是帮助区分侧重点，illusion 本身也能表示错误观念。","kind":"public_familiar_word_semantic_contrast","original":false,"weak":false},{"method":"solution 失败，还信就是 delusion","textZh":"把声音相近的 solution（解决办法）和 delusion 对照：一个方案反复测试都失败，提出者却坚持它一定有效。它没有真正解决问题，只剩被信以为真的错误想法。用“真能解决”与“错信有效”记住区别。","kind":"familiar_word_rhyme_semantic_contrast","original":false,"weak":false}]},"5870":{"word":"deluge","mnemonics":[{"method":"deluge 近音“地流急”","textZh":"大雨像整桶水倒下，地上的雨水流得急。把 deluge 近似听成“地流急”，由满地急流回想造成它的倾盆大雨。","kind":"public_adapted_chinese_approximate_sound","original":false,"weak":false},{"method":"deluge，雨量 huge","textZh":"deluge 后半段的声音接近 huge（巨大的）。把平常细细的雨，放大成遮住庭院的厚雨帘：雨量大得惊人，就是这里的 deluge。","kind":"public_adapted_familiar_word_sound_scale","original":false,"weak":false}]},"5871":{"word":"delve","mnemonics":[{"method":"shelves 里 delve","textZh":"把 delve 和声音相近的 shelves（书架）连起来：为了查清一个问题，沿着书架一本本找书，再把旧记录交叉核对。不是逛书架，而是在资料里深入寻找。","kind":"public_familiar_word_sound_scene","original":false,"weak":false},{"method":"dive 下潜，delve 深查","textZh":"由形近的 dive（潜入水中）想到往深处去：游泳者潜到水下找东西，研究者则 delve，潜入资料深处找线索。记住一个是具体下潜的画面，一个是深入查究；不要把两词当成所有用法都一样。","kind":"public_adapted_whole_word_shape_analogy","original":false,"weak":false}]},"5872":{"word":"demagogue","mnemonics":[{"method":"democracy 的民众，被 demagogue 带偏","textZh":"从熟悉的 democracy（民主）抓住“民众”这条线索。demagogue 的词源也是“带领民众的人”，但现代用法要记住贬义：他不靠可靠理由，而靠煽起恐惧或空头许诺，把人带向自己的权力。","kind":"public_word_family_etymology","original":false,"weak":false},{"method":"demagogue 近音“得骂够”","textZh":"把 demagogue 近似听成“得骂够”：虚构政客不肯拿出事实，反而说“得骂够，才能让他们支持我！”借骂声煽起愤怒，再为自己拉支持，记住这种蛊惑民心的政客。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5873":{"word":"demolition","mnemonics":[{"method":"abolition 废制度，demolition 拆砖屋","textZh":"记起已学 abolish 页里的 abolition（废除）：取消的是制度；形近的 demolition，则把眼前的旧砖屋拆掉。前者让旧规矩不再实行，后者让旧建筑不再站立。","kind":"adopted_helper_whole_word_semantic_contrast","original":false,"weak":false},{"method":"deMOLition：建起来，再拆下","textZh":"词源里的 moli- 连着“建造”，de- 带出“向下、移去”：原本砌成的一堵墙，被拆成落地的砖块。把“建起的东西拆下”这幅反向图记在 demolition 里。","kind":"public_accurate_etymology_action_image","original":false,"weak":false}]},"5874":{"word":"demonstrate","mnemonics":[{"method":"demo：拿结果证明","textZh":"想起产品的 demo（演示）：不是只说机器有效，而是让它实际运转，把结果给人看。由熟悉的 demo 带回 demonstrate，记住本页重点是用看得见的结果证明说法。","kind":"public_familiar_word_family_evidence_bridge","original":false,"weak":false},{"method":"deMONSTRate，拿出 monster 的证据","textZh":"看到 demonstrate 中的 monstr，联想到形近的 monster（怪物）。在虚构故事里，光喊“有怪物”不够；拿出清楚拍到它的影像，才能证明这句话。借怪物的证据记“证明”，这是形近联想，不是说词源意为怪物。","kind":"public_adapted_familiar_word_shape_evidence","original":false,"weak":false}]},"5875":{"word":"demoralize","mnemonics":[{"method":"demoralize：抽走 morale","textZh":"morale 是“士气”。把 de- 的去除方向和这个整词连起来：原本挺胸准备再试的一队人，士气像被抽走一样，纷纷垂下肩膀。demoralize 就是使人泄气、失去信心。","kind":"public_word_family_removal_image","original":false,"weak":false},{"method":"demoralize，听多了 more lies","textZh":"demoralize 后半段的声音让人想到 more lies（更多谎言）：一次次被许诺“下一回一定会好”，却发现又是谎话，人渐渐没了盼头。借这个近音场景记“使人失去信心”，不是词源拆解。","kind":"authored_familiar_phrase_approximate_sound","original":true,"weak":true}]},"5876":{"word":"demotic","mnemonics":[{"method":"demotic 与 democracy：都想到民众","textZh":"从熟悉的 democracy（民主）想到“民众”：两个词背后都有希腊语“人民”的线索。demotic 不是说制度民主，而是把镜头移到普通人平常说的话、爱看的戏，记住“通俗的、大众化的”。","kind":"public_familiar_word_family_etymology","original":false,"weak":false},{"method":"demotic，像 domestic 的家常话","textZh":"把 demotic 和形近的 domestic（家庭的）放在一起：不是端着架子念公文，而像在家里聊天那样，说普通人天天用的大白话。由“家常话”抓住 demotic 的通俗语言义；两词不是同义词，也不是同源词。","kind":"authored_whole_word_shape_everyday_scene","original":true,"weak":false}]},"5877":{"word":"denigrate","mnemonics":[{"method":"denigrate，deny 他很 great","textZh":"把 denigrate 的音形联想到 deny（否认）和 great（出色的）：明明别人做得好，却偏把他的本事和成果说得一文不值。这个“偏不承认人家好”的近音组合，帮助记住贬低、诋毁，不是真实词源。","kind":"public_adapted_whole_words_sound_shape","original":false,"weak":false},{"method":"deNIGRate：往名誉上抹黑","textZh":"词源中的 nigr- 与“使变黑”有关。想象往别人好好的名誉上泼一团黑墨：不是认真讨论优缺点，而是把他的形象抹坏。由这个短词源图直接记“抹黑、诋毁”。","kind":"public_accurate_etymology_reputation_image","original":false,"weak":false}]},"5878":{"word":"dent","mnemonics":[{"method":"dent 与 rent：房租削掉积蓄","textZh":"dent 和 rent（房租）押韵。想象刚付完一笔房租，原来满满的钱包明显薄了一截：这笔支出 dent 了积蓄，让它变少，但不一定花光。","kind":"authored_familiar_whole_word_rhyme","original":true,"weak":false},{"method":"dent 像 bent：信心被压瘪","textZh":"看到 dent，联想形近的 bent（弯了的）：挺直的金属被压得弯下去，饱满的信心也像挨了一下，被压瘪一块。由具体的受损画面记本页“削弱”的引申义，不必真的有金属出现在句子里。","kind":"public_adapted_whole_word_shape_metaphor","original":false,"weak":false}]},"5879":{"word":"denude","mnemonics":[{"method":"deNUDE：露出原来的表面","textZh":"nude 是“裸露的”。看到 denude 中完整的 nude，就想树叶这件外衣被除去，下面的枝条露出来。denude 是让它变裸露的动作，不是“把裸露去掉”。","kind":"public_whole_word_family_exposure_image","original":false,"weak":false},{"method":"denude 近音“地露”","textZh":"把 denude 近似听成“地露”：草木这层覆盖被剥掉，地表露了出来。由这个画面记“除去覆盖、使裸露”的动作，不是只说土地本来就光秃。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5880":{"word":"deplore","mnemonics":[{"method":"deplore，发出 deep roar","textZh":"把 deplore 近似联想到 deep roar（低沉的怒吼）：看见有人故意毁坏别人的作品，你沉声说“这样做太不应该！”借这声明确反对恶劣行为的怒吼，记“强烈反对、谴责”。这只是近音联想，词本身不要求吼叫。","kind":"public_adapted_familiar_phrase_sound","original":false,"weak":false},{"method":"deplore 与 adore：态度反过来","textZh":"adore 是喜爱、崇拜，和 deplore 的结尾押韵。原来很崇拜某位选手，一见他故意作弊，就从赞赏转为强烈反对：不再 adore 他的表现，而是 deplore 这种行为。借相近声音和相反态度记词，不是词源拆解。","kind":"authored_whole_word_rhyme_contrast","original":true,"weak":false}]},"5881":{"word":"deploy","mnemonics":[{"method":"deploy 接在 employ 之后","textZh":"employ 可指雇用。把形近的两个整词排成工作流程：先 employ 人手，再 deploy 到各自岗位，让人力真正用于任务。由“雇到人，再部署到位”记 deploy；它不限于雇员，也可调度设备和资源。","kind":"public_adapted_whole_word_workflow","original":false,"weak":false},{"method":"deploy，像 play 前排阵","textZh":"deploy 的后半声音让人想到 play（比赛、玩）。球队开赛前，教练把队员安排到前锋、后卫、守门员的位置：不是随便站散，而是为了打好这一场，有目的地部署。借熟词声音和排阵画面记词，不是真实词源。","kind":"public_adapted_familiar_word_sound_scene","original":false,"weak":false}]},"5882":{"word":"deportation","mnemonics":[{"method":"dePORTation：被送离国境","textZh":"port 在 transport（运输）里也能看见，词根有“搬运”的意思；de- 在这里给出离开的方向。把人强制送离一个国家，这个行为就是 deportation。记的是被迫送离，不是把人当货物，也不把 port 的港口义当真实词根。","kind":"public_adapted_accurate_root_familiar_family","original":false,"weak":false},{"method":"deportation，不能自己选的 depart","textZh":"depart 是离开，和 deportation 开头的 deport 音形很近。把普通的“我决定离开”改成“当局要求我离境”：这种被强制离开国家的事情，就是 deportation。借整词形近加“非自愿”的对比记住，不把两词当作同义词。","kind":"public_adapted_whole_word_shape_contrast","original":false,"weak":false}]},"5883":{"word":"depose","mnemonics":[{"method":"dePOSE：举手作证的 pose","textZh":"pose 是姿势。看见 depose 中完整的 pose，就想证人举起右手，郑重保证只说事实，随后讲出自己亲眼见到的事。用这一套宣誓作证的姿态记 depose，不是只摆个样子，也不是词源拆解。","kind":"authored_familiar_whole_word_oath_posture","original":true,"weak":false},{"method":"depose 与 expose：把事实说出来","textZh":"expose 是揭露、把事实揭开。看到形近的 depose，想到证人把自己所知正式说出来，并宣誓所言属实。用 expose 的整词形和“揭出事实”作入口，记住 depose 的宣誓作证义；作证不一定揭露秘密，两词不能随意互换。","kind":"authored_familiar_whole_word_shape_testimony_bridge","original":true,"weak":false}]},"5884":{"word":"deposit","mnemonics":[{"method":"dePOSIT：向下放，积成一层","textZh":"deposit 与 position（位置）共享“放置”的词源线索。把“向下放”画成泥沙慢慢落下，留在底部积成一层：这层自然留下的物质，就是一个 deposit。它不是先存钱再硬转到泥沙。","kind":"public_adapted_accurate_root_settling_image","original":false,"weak":false},{"method":"deposit 近音“底铺积土”","textZh":"把 deposit 近似听成“底铺积土”：浑水放静，细土慢慢沉下去，在杯底铺成一层。这层积下来的土就是 deposit，直接记“沉积物”。只是声音联想，不是词源或精确读音。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5885":{"word":"depravity","mnemonics":[{"method":"depravity 想到 gravity：道德往下坠","textZh":"gravity 是重力，会把东西往下拉；它和 depravity 的后半声音很近。把“下坠”换成品行的堕落：为了牟利，连救命的物资都偷走。这样的严重道德败坏，就是 depravity。这是押韵联想，不是词源。","kind":"public_adapted_whole_word_rhyme_image","original":false,"weak":false},{"method":"dePRAVity：把做人准则扭歪","textZh":"prav 的词源线索是“歪曲”，de- 在这里加强程度。想象本该笔直的做人准则被彻底扭歪：明知会伤害别人，还故意欺骗、牟利。由“道德被扭曲”记 depravity，不是把普通弯曲或外貌特征当作邪恶。","kind":"public_adapted_accurate_short_etymology","original":false,"weak":false}]},"5886":{"word":"depreciate","mnemonics":[{"method":"depreciate 与 appreciate：价值方向相反","textZh":"已学的 appreciate 可指欣赏价值，也可指增值。把同样的作品放到相反态度中：appreciate 是认可它的价值，depreciate 是贬低它的价值；谈资产时，则是升值与贬值。抓住整个熟词作对照，不把 appreciate 的所有义项都机械取反。","kind":"public_adapted_verified_whole_word_contrast","original":false,"weak":false},{"method":"dePRECIate：把 price 往下调","textZh":"preci 与 price（价格）有共同的词源线索，de- 在这里表示向下。想象估价员把一件物品的估价向下调：它被认为没那么值钱了。由价格或估值降低记 depreciate，也能延伸到贬低作品、贡献的价值。","kind":"public_adapted_accurate_root_price_image","original":false,"weak":false}]},"5887":{"word":"depressed","mnemonics":[{"method":"dePRESSED：心情被 press 下去","textZh":"press 是按、压；depressed 的词源也与向下压有关。把心情想成被按低的琴键：原本有兴致，遇到失望的事后低落下去。由“心情被压低”记消沉、沮丧，不是给一个人下医学诊断。","kind":"public_adapted_accurate_root_familiar_word","original":false,"weak":false},{"method":"depressed 与 stressed：低落还是紧绷","textZh":"stressed 是压力大、紧绷，和 depressed 押韵。想两种表情：赶截止时间时紧张得坐不住，是 stressed；盼望的事情落空后垂头丧气，是 depressed。借熟词声音和情绪对照记“低落”，不把有压力等同于消沉。","kind":"public_adapted_whole_word_rhyme_contrast","original":false,"weak":false}]},"5888":{"word":"deprivation","mnemonics":[{"method":"deprivation：private 的必需品被拿走","textZh":"private 是个人的、私有的，和 deprivation 中间的形状相近。想象一个人自己的食物、饮水和被褥被拿走，连日常必需品都没有：这种匮乏就是 deprivation。借熟词和失去必需品的画面记忆，不把它机械拆成现代英语的 de + private。","kind":"public_adapted_familiar_whole_word_loss_scene","original":false,"weak":false},{"method":"deprivation 近音“得配卫生”","textZh":"把 deprivation 近似听成“得配卫生”：住处连最基本的卫生设施都没有，大家说“这些得配齐”。缺少本应具备的基本生活条件，就是 deprivation。只是声音联想；它也可指食物、睡眠等必需品不足，不限于卫生设施。","kind":"authored_chinese_approximate_sound","original":true,"weak":true}]},"5889":{"word":"deracinate","mnemonics":[{"method":"deRACINate：连根拔出来","textZh":"racin 的词源是法语里表示“根”的部分；de- 在这里表示移除。把一株草整棵向上拔，连土里的根一起带出来，而不只是剪掉叶子：这就是 deracinate 的根除、拔根义。","kind":"public_adapted_accurate_short_etymology","original":false,"weak":false},{"method":"deRACINate：racing 比赛拔根","textZh":"racing 是竞赛；deracinate 中的 racin 与 racing 的拼写几乎相同。想一场拔杂草比赛：谁把草连根拔出来，才算完成。借熟悉的竞赛和“连根拔出”的动作记 deracinate，不是把它解释成 racing 的派生词。","kind":"public_adapted_near_whole_word_shape_action_scene","original":false,"weak":false}]},"5890":{"word":"descend","mnemonics":[{"method":"descend：沿梯向下爬","textZh":"de- 在这里是“向下”，scend 源于表示“爬”的拉丁词。想象人面对梯子，手脚配合着一格格往低处移动：把“向下”接到“爬”上，就是 descend。这个词也可用于电梯等不需要攀爬的下降。","kind":"public_adapted_accurate_etymology_scene","original":false,"weak":false},{"method":"descend，近音“地陷”","textZh":"把 descend 的声音近似联想到“地陷”：原本平整的一块地面向下沉，位置从高处降到了低处。借“地陷、下沉”的声音和方向记“下降”，不表示所有 descend 都像地陷一样突然或危险。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5891":{"word":"divination","mnemonics":[{"method":"DIVINation：向神明求预示","textZh":"divination 与 divine（神的）属于同一词族。想象占卜者把抽出的签解释为神明给的启示，想从中问出未来：从“求神示”走到“占卜”。词源线索是神明启示，不意味着真有预测能力。","kind":"public_adapted_divine_inspiration_family","original":false,"weak":false},{"method":"divination 与 division：算数换成算命","textZh":"division 是除法，与 divination 的整体拼写很相近。想象一边在纸上算数字，另一边拿着数字为人算明天的运势：前者是算数，后者是在占卜。借“算数变算命”的对照记 divination，不把两词当同源词，也不说算命结果可靠。","kind":"authored_familiar_whole_word_shape_contrast","original":true,"weak":false}]},"5892":{"word":"desecrate","mnemonics":[{"method":"desecrate：把 sacred 的地位踩坏","textZh":"把 desecrate 近似听成 de-sacred；sacred 是神圣的。想象本应受到敬重的圣地，被人当作垃圾堆来糟蹋：反着对待神圣之物，便是“亵渎”。这是借熟词作的音形联想，词源也确与神圣这一词族有关。","kind":"public_adapted_sacred_reversal","original":false,"weak":false},{"method":"desecrate 不是 decorate","textZh":"decorate 是装饰，和 desecrate 的整体音形相近。给纪念地献花、认真布置，是带着敬意装饰；故意在同一处涂污羞辱，却是在 desecrate。借“尊重地装点”和“侮辱地糟蹋”的反差，记住亵渎而不是装饰。","kind":"authored_familiar_whole_word_contrast","original":true,"weak":false}]},"5893":{"word":"desiccate","mnemonics":[{"method":"desiccate：把思想也“彻底弄干”","textZh":"词源中 de- 在这里表“彻底”，sicc 表“干”。把这一干燥形象移到表达上：原本鲜活的故事，被枯燥讲法抽干了情感和趣味。这样让思想或情感失去生气，就是本页的 desiccate，不是身体脱水。","kind":"public_adapted_accurate_etymology_figurative_image","original":false,"weak":false},{"method":"desiccate 与 dedicate：投入心力，还是耗掉生气","textZh":"dedicate 是投入时间和精力，读音与 desiccate 很近。创作者用心投入作品，是 dedicate；刻板要求却把作品中的情感和想象力磨没了，是 desiccate。借‘投入心力’与‘耗掉生气’的反差，记住 desiccate 的活力枯竭义；不是说努力投入本身有害。","kind":"public_adapted_whole_word_sound_contrast","original":false,"weak":false}]},"5894":{"word":"designate","mnemonics":[{"method":"designate：选人来完成 design","textZh":"联想已学的 design（设计）：一个设计方案已经准备好，负责人接下来明确指定你完成它。design 是设计，designate 是“选定谁来承担这件事”。用完整熟词接上分工场景，不把两词直接当同义词。","kind":"public_adapted_verified_whole_word_workflow","original":false,"weak":false},{"method":"deSIGNate：给当选者做记号","textZh":"sign 是记号；designate 的词源与“标出来”有关。想象负责人在候选名单上圈出一个名字，再把队长职责交给这个人：被明确标出来承担任务，就是“指定”。不只看见记号，还要连到被选定的角色。","kind":"public_adapted_accurate_sign_etymology_selection","original":false,"weak":false}]},"5895":{"word":"despicable","mnemonics":[{"method":"despicable：片名里的“卑鄙”","textZh":"《神偷奶爸》的英文片名是 Despicable Me，也有《卑鄙的我》这个中文片名。想到那个以干坏事为荣、打算偷走月亮的格鲁：despicable 说的正是“卑鄙的、可鄙的”，而不是“可爱的”或“神偷”。","kind":"public_adapted_familiar_film_title","original":false,"weak":false},{"method":"deSPICable：让人看不起","textZh":"词源中的 de- 是“向下”，spic 与“看”有关。想象一个人专挑弱小者欺负，旁人看穿后都瞧不起这种行径：不是身高矮，而是品行低劣、令人鄙视。用“看不起他的行为”记 despicable。","kind":"public_adapted_accurate_etymology_scene","original":false,"weak":false}]},"5896":{"word":"despise","mnemonics":[{"method":"despise，闻到 spice 就嫌弃","textZh":"spice 是香料，声音与 despise 的重读部分相近。想象一个特别讨厌这股香料味的人，一闻到就皱眉把碗推开：不是一般不爱吃，而是强烈厌恶。借 spice 的声音记 despise，不是把香料说成有道德问题。","kind":"public_adapted_spice_sound_scene","original":false,"weak":false},{"method":"despise：向下看，心里很反感","textZh":"despise 的历史构词有“向下看”的意思：de- 表“向下”，后面一部分与“看”有关。想到有人对一件事嗤之以鼻，连正眼都不愿看，心里非常反感。由“看不起”联到“强烈厌恶”；现代用法也能说极讨厌某种食物，不一定是在谴责道德。","kind":"public_adapted_accurate_etymology_scene","original":false,"weak":false}]},"5897":{"word":"despotic","mnemonics":[{"method":"DESPOTic：暴君把国家当家产","textZh":"despotic 里完整可见 despot，指拥有绝对权力的统治者、暴君；其词源最早与“家主人”有关。想象暴君把整个国家当成自己的家产，人人必须服从，他想怎么管就怎么管。用这一词族和“任意支配”的画面记“专制的、暴虐的”。","kind":"public_adapted_accurate_etymology_scene","original":false,"weak":false},{"method":"despotic：this pot 成了锅王","textZh":"把 despotic 的前面部分近似听成 this pot（这口锅）。想象这口锅戴着王冠，谁能吃饭、谁得挨饿都由它独断，别人一提意见就被赶走。借“这口锅当暴君”的声音画面记“专制的”；不是这个词的真实构词。","kind":"public_adapted_this_pot_sound_scene","original":false,"weak":true}]},"5898":{"word":"detach","mnemonics":[{"method":"detach 与 attach：拆下和接上","textZh":"attach 是把东西接上，detach 则把原来的连接解除。想象把钥匙扣接在包上是 attach，再解开扣子，把钥匙扣完整取下就是 detach：原先连在一起，现在分开了。","kind":"public_adapted_familiar_antonym_pair","original":false,"weak":false},{"method":"detach，近音“得拆”","textZh":"把 detach 的声音近似联想到“得拆”：这个连在包上的小扣件，得拆下来才好单独清洗。打开连接处，拿开之后两件东西分离，用这一动作记 detach，不要求一定拆坏。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5899":{"word":"detain","mnemonics":[{"method":"deTAIN：扣住，不许离开","textZh":"detain 的 tain 来自表示“拿住、留住”的词根，整个词历史上有“扣住不放”的意思。想象警员把人留在问询室，暂时不准离开：重点是人被扣留、行动受到限制，不只是事情做慢了。","kind":"public_adapted_accurate_etymology_custody","original":false,"weak":false},{"method":"detain，近音“得停”","textZh":"把 detain 的声音近似联想到“得停”：警员拦下一个人，说他“得停在这里，接受问询，不能走”。把停留与不准自由离开连起来，记住拘留、扣留；单纯在路口等灯不算这个意思。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5900":{"word":"detour","mnemonics":[{"method":"deTOUR：旅程临时改线","textZh":"tour 是旅行、游览。原本按计划一路往前，却临时改走另一段再回到原安排，这次偏离就是 detour。把这个“离开既定路线”的画面移到做事流程上：原定直接组装，却先插入额外检查，也可以是一次 detour。","kind":"public_adapted_familiar_tour_semantic_bridge","original":false,"weak":false},{"method":"detour，近音“得兜”","textZh":"把 detour 近似听成“得兜”：原本按常规直接办下去，现在得先兜个弯、做一项临时检查，再回到原来的步骤。用“得兜一圈”记偏离正常路线或程序；这个弯可以是办事方式，不必真在路上绕行。","kind":"authored_chinese_approximate_sound","original":true,"weak":false}]},"5901":{"word":"devoted","mnemonics":[{"method":"deVOTED：一直把票投给你","textZh":"devoted 里可以看见 voted（投了票）。想象一位忠实支持者，不只是赢的时候来庆祝，低谷时仍一次次把支持票投给同一个人。用“始终支持”的投票画面记 devoted 的忠诚、投入，不把一次投票本身当作忠诚的证明。","kind":"public_adapted_vote_loyal_support_scene","original":false,"weak":false},{"method":"devoted 与 demoted：降职，仍尽心","textZh":"demoted 是“被降职”，与 devoted 只差中间一个辅音，读起来也很近。想象有人虽然被降职，却依然认真照顾团队、不离不弃：职位变低是 demoted，心意与投入没有变是 devoted。借这组整词近音记“忠诚、尽心”。","kind":"authored_whole_word_sound_contrast","original":true,"weak":false}]},"5902":{"word":"devout","mnemonics":[{"method":"devout 与 devote：把心投入信念","textZh":"devote 是把时间、精力投入某人或某事，devout 与它同源。想象一个人不是嘴上赞同，而是一直把心力交给自己的信念：这种真诚而坚定的信奉，就是 devout。可以是宗教虔诚，也可以是对原则或事业的忠诚。","kind":"public_adapted_devote_family","original":false,"weak":false},{"method":"devout 对照 doubt：笃信，还是怀疑","textZh":"doubt 是怀疑；把它和音形相近的 devout 放在一起。面对同一种信念，一边迟疑地问“真是这样吗”，另一边真心相信并持续遵循。用“怀疑”与“笃信”的反差记 devout；这里只是助记对照，不说所有质疑都不忠诚。","kind":"authored_whole_word_sound_semantic_contrast","original":true,"weak":false}]},"5903":{"word":"diabolic","mnemonics":[{"method":"diabolic 与 devil：恶魔般的恶","textZh":"diabolic 与 devil（恶魔）有共同的词源。看到 diabolic，就把它连到恶魔故意伤害他人、以残酷为乐的形象：不是普通淘气，而是恶魔般邪恶。现代用法可以形容人或阴谋，不必真的出现超自然生物。","kind":"public_adapted_devil_etymology","original":false,"weak":false},{"method":"diabolic：die 与 bully 的残酷联想","textZh":"把 diabolic 的开头像 die（死），后半段近似联想到 bully（欺凌者）。想象一个恶霸明知会害人性命，仍残酷地施害：这样的恶令人想到魔鬼。借两个完整熟词的近音记“恶魔般邪恶”，不是说 diabolic 一定涉及死亡。","kind":"public_adapted_die_bully_sound_synthesis","original":false,"weak":false}]},"5904":{"word":"diaphanous","mnemonics":[{"method":"diaphanous：薄到一眼看穿","textZh":"dia- 表“穿过”，phan 与“显现”有关，词源是“能透过去看到”。从薄到几乎没有实质，联想一个没有具体内容的构想：diaphanous 在这里是模糊、非实在的。","kind":"public_adapted_accurate_etymology_figurative_bridge","original":false,"weak":false},{"method":"diaPHANous：像 phantom 幻影的想法","textZh":"phantom 是幻影；diaphanous 中的 phan 与它的开头音形相近。脑海里似乎浮着一栋房子，细问大小、结构和怎样建，却一点也说不清：这个构想像幻影，没有可把握的实质。用 phantom 这个整体形象记 diaphanous 的模糊、非实在。","kind":"public_adapted_phantom_whole_word_insubstantial_idea","original":false,"weak":false}]},"5905":{"word":"digress","mnemonics":[{"method":"digress 与 progress：话题往旁边走","textZh":"progress 是向前推进；digress 与它共享表示“走”的 gress，但 di- 在这里表示离开。把讨论想成一条路：沿着主题推进是 progress，说着说着拐去另一个话题就是 digress。","kind":"public_adapted_progress_family","original":false,"weak":false},{"method":"digress 与 tigress：讲着讲着聊母虎","textZh":"tigress 是母虎，音形都与 digress 接近。原本正在讲明天的出游安排，有人忽然大讲动物园里那只母虎，越讲越远。用“突然聊起 tigress，话题跑偏”记 digress，偏离的是讲话主题，不是老虎走错路。","kind":"public_adapted_tigress_sound_topic_scene","original":false,"weak":false}]},"5906":{"word":"dilate","mnemonics":[{"method":"dilate：向外分开，开口变宽","textZh":"dilate 的词源把“分开”和“宽”连在一起：di- 表分开，lat 来自表示宽的拉丁词。想象圆孔的边缘向四周退开，孔径越来越大；这个“向外展开、变宽”的画面就是 dilate。","kind":"public_adapted_accurate_etymology_opening","original":false,"weak":false},{"method":"dilate 与 inflate：都能变大","textZh":"inflate 是充气鼓起，与 dilate 有相近的结尾音形。先想充气球变大的 inflate，再看不靠充气也能变宽的瞳孔：后者是 dilate。用这个熟悉的膨胀画面记扩大，同时记住 dilate 不要求充气。","kind":"public_adapted_inflate_whole_word_contrast","original":false,"weak":false}]},"5907":{"word":"dilute","mnemonics":[{"method":"dilute：用水冲开，浓度降低","textZh":"dilute 的词源中，di- 表分开，lu 与洗、冲有关。想象向一杯浓果汁里加水，把原本集中的果汁成分冲散到更多液体里；总量增加，每一口却淡了，这就是 dilute，稀释。","kind":"public_adapted_accurate_etymology_wash_apart","original":false,"weak":false},{"method":"dilute 对照 pollute：加水变淡，加污变脏","textZh":"pollute 是污染，与 dilute 的后半段音形很近。往果汁里加清水使它变淡，是 dilute；混入脏东西使它受污染，是 pollute。用两个整词的对照记“稀释”，别把浓度降低自动当成变脏。","kind":"public_adapted_pollute_whole_word_contrast","original":false,"weak":false}]},"5908":{"word":"disquisition","mnemonics":[{"method":"disquisition 连到 question：把问题论透","textZh":"question 是问题，和 disquisition 有共同的词源，均连到“问、探究”。不是问一句就结束，而是把一个专题分成若干问题，逐项查证、分析，再写成详尽论述。用“把问题系统论透”记 disquisition，专题论文或正式论述。","kind":"public_adapted_question_etymology_written_analysis","original":false,"weak":false},{"method":"disquisition 对照 discussion：讨论长成论文","textZh":"discussion 是讨论，和 disquisition 的整体音形相近。想象一次简短讨论被认真整理，补齐依据、分析和结论，最后变成厚实的专题论文。用“discussion 的正式详尽版”记 disquisition；这里是整词联想，不是说两个词词源相同。","kind":"public_adapted_discussion_whole_word_expansion","original":false,"weak":false}]},"5909":{"word":"dingy","mnemonics":[{"method":"dingy 连到 dim、dirty：暗且脏","textZh":"dim 是已学过的“昏暗”，dirty 是“脏”；dingy 的开头音形能把这两个熟词拉到一起。想象窗玻璃积灰，挡住光，室内也蒙着灰污：不只是暗，也不只是旧，而是灰暗脏旧的 dingy。","kind":"authored_dim_dirty_whole_word_synthesis","original":true,"weak":false},{"method":"dingy 与 stingy：省掉清洁，留下灰污","textZh":"stingy 是吝啬，和 dingy 押韵。想象一位有钱却吝啬的店主，连必要的清洁也舍不得做，灰尘遮住窗上的光，店里又暗又脏。人的吝啬是 stingy，房间的灰暗脏旧是 dingy；这只是一个助记情景，不是说节俭就等于脏。","kind":"public_adapted_stingy_rhyme_authored_causal_scene","original":false,"weak":false}]},"5910":{"word":"diocesan","mnemonics":[{"method":"diocesan：一位主教的 diocese","textZh":"diocese 是一位主教管辖的教区，diocesan 就是这个名词对应的形容词。把它记成一张辖区地图：范围里的几座教堂归同一位主教负责，属于这一教区的活动、人员和机构，都可以用 diocesan 修饰。","kind":"public_adapted_diocese_family","original":false,"weak":false},{"method":"diocesan 与 ocean：海边教区的地图","textZh":"把 diocesan 的音形与 ocean（海洋）联系起来：想象一位主教在海边展开地图，圈出自己负责的几座教堂。这一圈是他的教区，属于其中的事务就是 diocesan。海边只是联想场景，不表示教区必须靠海。","kind":"public_adapted_ocean_scene_corrected","original":false,"weak":true}]},"5911":{"word":"diplomatic","mnemonics":[{"method":"diplomat 加 -ic：外交官的说话分寸","textZh":"diplomat 是外交官，diplomatic 也能形容像优秀外交官那样有分寸的应对。面对难以接受的提议，不直说“太糟了”，而是说明顾虑并给出双方可接受的建议：这种顾及关系、又处理问题的机智，就是 diplomatic。","kind":"public_adapted_diplomat_family","original":false,"weak":false},{"method":"diplomatic 对照 automatic：别让话自动冲出口","textZh":"automatic 是自动的；它和 diplomatic 的后半段音形相近。把两种回应并排想：一句话不经思考就自动冲出口，可能伤人；先顾及对方感受、选好说法再回应，才是 diplomatic。用整词反差记“应对得体”，不是说所有自动反应都失礼。","kind":"authored_whole_word_automatic_contrast","original":true,"weak":false}]},"5912":{"word":"demography","mnemonics":[{"method":"demo + graphy：把人口写进统计图","textZh":"demo- 表人民，-graphy 与书写、描述有关。想象把一个地区有多少人、年龄如何分布、出生和迁入怎样改变人数，都记录成资料和图表。研究这些人口特征及其变化，就是 demography，人口统计学。","kind":"public_adapted_demo_graphy_etymology","original":false,"weak":false},{"method":"demography 对照 geography：看人，不只看地","textZh":"geography 是地理学；把音形相近的 demography 放在旁边。同一张城市图，地理课可以看山川与位置，人口学则追问“住了多少人、年龄怎样分布、人数如何变化”。用熟悉的 geography 作对照，把 demography 的研究对象锁定为人口。","kind":"public_adapted_geography_whole_word_contrast","original":false,"weak":false}]},"5913":{"word":"disabuse","mnemonics":[{"method":"dis + abuse：解除被误导的状态","textZh":"abuse 过去也有“欺骗、误导”的意思；dis- 在这里表示解除。有人被错误说法带偏了，你拿出事实，帮他把那个错误念头放下，就是 disabuse。记住它解除的是误解，不要按今天常见的 abuse 把它直译成“不虐待”。","kind":"public_adapted_verified_abuse_old_sense","original":false,"weak":false},{"method":"disabuse，近音 this bus：看线路，纠正误会","textZh":"把 disabuse 的声音近似联到 this bus（这辆公交车）。你以为这辆车能到博物馆，司机指给你看线路图，说明它根本不走那里，让你放下这个误解。用“这辆车，纠正误会”的场景记 disabuse；这是近音联想，不是词源解释。","kind":"public_adapted_this_bus_sound_corrected","original":false,"weak":false}]},"5914":{"word":"disaffected","mnemonics":[{"method":"disaffected：对组织失去 affection","textZh":"affection 是喜爱、感情，disaffected 的中间能看见相近的 affect。想象原本支持队伍的人，被负责人一次次忽视后，对这个组织不再认同，连支持也撤回。用“感情和忠诚退了场”记它对权威或组织的不满、疏离。","kind":"public_adapted_dis_affection_association","original":false,"weak":false},{"method":"disaffected 不是 unaffected：不是没受影响","textZh":"unaffected 是不受影响的；disaffected 与它共用 affected，却不是同一个意思。前者可能仍照常支持，后者则是受够了某个组织或权威，已经心生不满、不愿支持。把两词整词对照，看到 disaffected 就记“关系疏远了”，而非“没有受到影响”。","kind":"authored_whole_word_unaffected_contrast","original":true,"weak":false}]},"5915":{"word":"disarm","mnemonics":[{"method":"dis- + arm：放下心里的武器","textZh":"arm 可表示武装；disarm 的基本画面是撤去武装。把这幅画面用在争执中：原本准备反击的人听到真诚的道歉，放下心里的武器，不再那么生气。这里记的是消解敌意，不是要求对方真的交出武器。","original":false,"weak":false,"kind":"public_adapted_form_meaning"},{"method":"charm 与 disarm：亲和力化解防备","textZh":"把押韵的 charm（吸引人的亲和力）和 disarm 连起来：坦诚又有亲和力的回应，让原本板着脸的人不再防备。用 charm 的尾音牵住 disarm，再把意思落到使对方息怒；这只是联想，不是词源。","original":true,"weak":false,"kind":"original_whole_word_contrast"}]},"5916":{"word":"disarray","mnemonics":[{"method":"dis- + array：整齐的排列被打乱","textZh":"array 可表示整齐排列；加上表示反向的 dis-，便从排列有序变成混乱。记住一排按顺序摆好的文件被碰散，顺序不再，就是 disarray。","original":false,"weak":false,"kind":"public_adapted_form_meaning"},{"method":"disarray 与 display：陈列变成一团乱","textZh":"把外形和尾音相近的 display（陈列）与 disarray 对照：display 是排好给人看，disarray 是散乱没法看。想起一台整齐的陈列突然被碰散，便从展示变成混乱。这是整词音形联想，不是词源；display 本身也不保证整齐，这里借的是精心布置的陈列场景。","original":true,"weak":false,"kind":"original_whole_word_contrast"}]},"5917":{"word":"disavow","mnemonics":[{"method":"dis- + avow：不肯公开承认","textZh":"avow 是公开承认、表明；disavow 是公开否认或撇清关系。把两词并排记：前者说自己承认或支持，后者明确说自己不承认、不负责或不支持。disavow 不要求此前先承认过，也不一定是撤回原话。","original":false,"weak":false,"kind":"public_adapted_form_meaning"},{"method":"disavow 与 disallow：一个不认，一个不许","textZh":"disavow 和 disallow 外形接近，都像在说不。用两个不同回答分开它们：disallow 是不允许这样做；disavow 是不承认这话、这行为代表自己。看到 avow 的结尾，记住这里否认的是自己的承认、责任或支持，不是禁止别人行动。","original":false,"weak":false,"kind":"public_adapted_whole_word_contrast"}]},"5918":{"word":"discharge","mnemonics":[{"method":"dis- + charge：卸下岗位上的职责","textZh":"charge 有负担、职责的意思；discharge 可从卸下负担来记。放到雇用关系里，是雇主把这个人从岗位职责中撤下来，让他离职，也就是解雇；不是员工主动辞职。","original":false,"weak":false,"kind":"public_adapted_form_meaning"},{"method":"fire 的两义桥：开火，也开除","textZh":"fire 既能指开火，也能指开除；discharge 同样能用于发射枪械和解除雇用。借这个熟悉的双义桥，把 discharge 的人事用法牢牢记成解雇。看到员工这个宾语时，不要误读成放电或排水。","original":true,"weak":false,"kind":"original_whole_word_contrast"}]},"5919":{"word":"discombobulate","mnemonics":[{"method":"discomfort 与 discombobulate：不舒服到不知所措","textZh":"先用 discomfort（不适、不安）这个完整词牵住相近的 discombobulate：两者都可能让人不自在，但 discombobulate 还把思路和节奏弄乱，让人不知该怎么办。记成不只是难受，而是被弄懵了。这是近形词的意义对照，不把 discomfort 当作词源。","original":false,"weak":false,"kind":"public_adapted_form_meaning"},{"method":"discompose 的诙谐长版本","textZh":"discompose 是使人失去镇定。词典认为 discombobulate 很可能是它的诙谐变体：保留前面的 discom-，后半段像故意把词说乱了一样拉长，正好记住把人弄得失去镇定、困惑失措。这里只说可能的来源，不把新增音节编成独立词根。","original":false,"weak":true,"kind":"public_adapted_whole_word_contrast"}]},"5920":{"word":"discommode","mnemonics":[{"method":"discommode 对照 accommodate：方便变麻烦","textZh":"accommodate 可以表示照顾别人的需要、提供方便；discommode 与它共享醒目的 commod 音形，却是给人添不便。把“替客人腾出位置”和“把箱子放在通道上，让客人绕路”并排想，后者就是 discommode。","kind":"public_adapted_accommodate_family_contrast","original":false,"weak":false},{"method":"discommode 里的 commode：厕所偏偏不能用","textZh":"commode 可以指马桶。看到 discommode 里完整的 commode，就想急着上厕所，却发现门口挂着维修牌，只好跑去另一层：这件事给你添了不便。用这个小麻烦记住 discommode，不是说这个动词专指厕所故障。","kind":"authored_whole_word_commode_inconvenience","original":true,"weak":false}]},"5921":{"word":"discompose","mnemonics":[{"method":"dis + compose：镇定被打乱","textZh":"compose 除了“作曲”，也可表示使人镇定；compose yourself 就是让自己平静下来。discompose 把这种镇定打乱：原本能从容说话的人，听到突如其来的消息后慌了神。","kind":"public_adapted_dis_compose_calm","original":false,"weak":false},{"method":"discompose 对照 decompose：心态仿佛散了架","textZh":"decompose 是分解、腐烂，与 discompose 的音形很接近。想象并非东西分解，而是一个人的镇定被坏消息弄得“散了架”，说话也乱了。这幅心理上的散架图帮助记住 discompose：使人失去镇定。两词不能互换。","kind":"public_adapted_decompose_mental_breakup","original":false,"weak":false}]},"5922":{"word":"disconcert","mnemonics":[{"method":"disconcert 里的 concert：演出突然出了岔子","textZh":"concert 是音乐会。想象你准备好独奏，台上却突然响起完全不对的伴奏，一下把你弄得尴尬、失措。由整个 concert 场景记 disconcert：意外的事情使人不安，而不只是取消一场演出。","kind":"public_adapted_concert_surprise_scene","original":false,"weak":false},{"method":"disconcert 对照 concern：从担心到当场失措","textZh":"concern 可以表示使人担忧；把它与音形相近的 disconcert 并排记。担心演出会出错是一回事，被意外的提问弄得愣住、一时不知怎样回应，则可以说是被 disconcert。用这个整词对照，记住它强调镇定或自信被打乱，而不只是一般的担忧。","kind":"authored_whole_word_concern_contrast","original":true,"weak":false}]},"5923":{"word":"discretion","mnemonics":[{"method":"discretion 与 discreet：谨慎的品质","textZh":"discreet 是言行谨慎、有分寸的，discretion 是相应的品质。朋友告诉你一件私事，你先想清楚能不能说，而不是随口传出去；这种知道何时该克制、怎样说才妥当的谨慎，就是 discretion。","kind":"public_adapted_discreet_family","original":false,"weak":false},{"method":"discretion 对照 discussion：讨论也要有分寸","textZh":"discussion 是讨论，与 discretion 的音形相近。讨论不是知道什么就说什么：谈到朋友的私事，先判断哪些适合说、哪些应当保留，再决定怎样回应。这份约束言行的审慎就是 discretion；用“讨论之前先掂量”把两个整词分开记。","kind":"authored_whole_word_discussion_contrast","original":true,"weak":false}]},"5924":{"word":"discriminate","mnemonics":[{"method":"discriminate 联想 criminal：靠证据分清","textZh":"criminal 是罪犯；discriminate 中的 crimin 很容易让人想到这个完整单词。想象侦探不凭外表认人，而是核对证据，分清真正作案者与无辜者。由“分清谁是谁”记 discriminate 的辨别义；这只是音形联想，不是说这个词由 criminal 构成。","kind":"public_adapted_criminal_evidence_distinction","original":false,"weak":false},{"method":"discriminate 对照 eliminate：辨别，不是排除","textZh":"eliminate 是排除，与 discriminate 的后半段音形相近。挑选两件相似物品时，先看清差异、把它们分辨出来，这是 discriminate；随后决定不要其中一件，才是 eliminate。用整词对照记住“辨别差异”，不把它误记成“淘汰”。","kind":"authored_whole_word_eliminate_contrast","original":true,"weak":false}]},"5925":{"word":"disengage","mnemonics":[{"method":"dis + engage：让连接松开","textZh":"engage 可以表示让机械部件接合；前面的 dis- 把方向倒过来。想象两个咬合的齿轮松开，不再互相带动：disengage 就是使原本连着、卡着的东西脱开。","kind":"public_adapted_dis_engage","original":false,"weak":false},{"method":"disengage 对照 disentangle：脱开，不一定解结","textZh":"disentangle 是解开缠结，和 disengage 的开头、结尾音形相近。绳子打成一团，要 disentangle；背包带只是挂在木栓上，轻轻一提便能 disengage。由“解结”和“脱钩”的对照，记住后者重在摆脱连接。","kind":"authored_whole_word_disentangle_contrast","original":true,"weak":false}]},"5926":{"word":"dignified","mnemonics":[{"method":"dignified 联结 dignity：把尊严带在举止里","textZh":"dignity 是尊严；dignified 与它共享 digni 这一醒目部分。想象一个人遭到嘲笑，仍平静地说明事实，不失态、不羞辱别人：这种维护尊严的端庄举止，就是 dignified。","kind":"public_adapted_dignity_family","original":false,"weak":false},{"method":"dignified 对照 magnified：庄重不是放大排场","textZh":"magnified 是被放大的，尾部音形与 dignified 相近。把两幅画面并排记：一边把奖章、头衔夸张放大，另一边没有排场，却沉稳有礼。后者才是 dignified，庄重来自举止，不等于声势很大。","kind":"authored_whole_word_magnified_contrast","original":true,"weak":true}]},"5927":{"word":"disinfect","mnemonics":[{"method":"dis + infect：把感染风险压下去","textZh":"infect 是使感染；disinfect 把方向反过来。想到被病原微生物污染的桌面，再想到消毒处理把它们消灭或减少，就能记住 disinfect 是消毒，不只是把灰尘擦掉，也不保证达到绝对无菌。","kind":"public_adapted_dis_infect","original":false,"weak":false},{"method":"disinfect 对照 inspect：检查之后还要消毒","textZh":"inspect 是检查，和 disinfect 的后半段音形接近。想象检查员仔细 inspect 一张桌子，肉眼看不到污渍，却仍要 disinfect：检查是看一看，消毒才是处理看不见的病原微生物。两词不是同义词。","kind":"authored_whole_word_inspect_contrast","original":true,"weak":false}]},"5928":{"word":"disjointed","mnemonics":[{"method":"dis + jointed：前后没有接好","textZh":"joint 表示接合处，jointed 是连接起来的；disjointed 则像连接处断开了。把一句一句话想成车厢，前一句谈风筝，下一句突然谈晚饭，中间没有连接，就是前后不连贯。","kind":"public_adapted_dis_jointed","original":false,"weak":false},{"method":"disjointed 对照 disappointed：失连，不是失望","textZh":"disappointed 是失望的，与 disjointed 的整体字形容易看混。记住一组对照：听众 disappointed，是听完很失望；叙述 disjointed，是内容东一句西一句、前后接不上。先分清“人失望”和“话失连”，便不会只记住一个模糊的负面意思。","kind":"authored_whole_word_disappointed_contrast","original":true,"weak":false}]},"5929":{"word":"disinter","mnemonics":[{"method":"dis + inter：把安葬的遗骸取出","textZh":"inter 是安葬，把遗体埋入墓中；disinter 把这个动作反过来。想象为迁葬而从墓中取出原先安葬的遗骸，便能记住“掘出”。这里不是随便挖土，更不是挖宝。","kind":"public_adapted_dis_inter","original":false,"weak":false},{"method":"disinter 联想 enter：不是入墓，而是出墓","textZh":"enter 是进入，读音与 inter 接近。看到 disinter，就想墓门上的箭头反了方向：先前进入墓中的遗骸，现在被小心取出。这是借 enter 的声音和方向作联想，不把它当作 disinter 的真实词源。","kind":"public_adapted_enter_sound_reversal","original":false,"weak":false}]},"5930":{"word":"disjunctive","mnemonics":[{"method":"dis-JUNCT-ive：断开连接","textZh":"junct 表示连接，与 join 同源；dis- 在这里表示分开。把本该连起来的几段断开，就得到 disjunctive：分离、缺乏连贯性的。","kind":"词根联想","original":false,"weak":false},{"method":"disjunctive：从 or 的分列选项记","textZh":"语法里的 or 常称为 disjunctive conjunction，表示不同选项之间的选择或对立。看到 disjunctive，借“选项分列”的熟悉用法记住“分开”：本条说的是片段彼此分离、缺少联系，不是说含 or 的句子不连贯，也不把所有 or 都限定成只能选一个。","kind":"熟悉用法迁移","original":false,"weak":false}]},"5931":{"word":"dismay","mnemonics":[{"method":"dis-MAY：可能性被打掉","textZh":"把 may 的“可能”当拼写提示：本来觉得“也许能成”，坏消息一来，这点希望被打掉，让人失去勇气、又惊又不安。这是拼写联想，不把现代 may 当作直接词源。","kind":"拼写联想","original":false,"weak":false},{"method":"dismal 的消息让人 dismay","textZh":"dismal 是“惨淡的、令人沮丧的”，dismay 在本条是“使人灰心或不安”。只差词尾的两个词连着记：消息很 dismal，听到它的人便可能被 dismay。前者形容情势，后者说情势对人的打击。","kind":"全词对照","original":true,"weak":false}]},"5932":{"word":"dispose","mnemonics":[{"method":"disPOSE：把心放向一边","textZh":"pose 提醒“放置、姿态”；dispose 的历史也与安排、放置有关。想象一句体贴的话把人的心意放向“愿意帮忙”这一边：不是强迫，而是使人倾向于。","kind":"词源与画面联想","original":false,"weak":false},{"method":"impose 强加，dispose 使倾向","textZh":"impose 是把要求强加给别人，dispose 是影响心态，使人倾向于某种行动。把相近词放在一起对照：命令让人不得不做，体贴的态度则使人愿意做。","kind":"全词对照","original":true,"weak":false}]},"5933":{"word":"dissect","mnemonics":[{"method":"dis-SECT：分开来细看","textZh":"dis- 表示分开，sect 与“切”有关。像把一个复杂论证切成几个部分，逐点检查证据与漏洞：这里不是动手术，而是仔细剖析。","kind":"词根联想","original":false,"weak":false},{"method":"inspect 检查，dissect 剖析","textZh":"inspect 是仔细检查，dissect 更突出把内容分成部分逐一分析。看到相近的词尾，记住这个区别：检查整份报告叫 inspect，逐个拆开论点审视则可说 dissect。","kind":"全词对照","original":true,"weak":false}]},"5934":{"word":"disseminate","mnemonics":[{"method":"dis-SEMIN-ate：四处撒种","textZh":"semin 源自“种子”，dis- 在这里表示散向各处。把知识像种子一样撒到更多人那里，就是 disseminate：广泛传播、散布。","kind":"词根联想","original":false,"weak":false},{"method":"SEMINAR 的知识传出去","textZh":"seminar 是研讨会，字形与 disseminate 的中段接近。想象会上的知识不只留在会场，而是由听众带到各处、传给更多人：disseminate，广泛传播。这里借整词与场景记忆，不是把散会本身当作传播。","kind":"全词场景联想","original":false,"weak":false}]},"5935":{"word":"dissension","mnemonics":[{"method":"dis-SENS-ion：想法分了岔","textZh":"sens 和 sense（感觉、理解）有同源联系，dis- 在这里表示不同。大家对同一件事想法分岔，各执一词，就是 dissension：意见不合、纷争。","kind":"public_root","original":false,"weak":false},{"method":"discussion 变成 dissension","textZh":"discussion 是讨论，dissension 的整体字形与它接近。想象本来一起讨论，后来分成两派、谁也不服谁：从交换意见的 discussion，变成意见不合的 dissension。讨论本身不一定有纷争。","kind":"whole_word_contrast","original":true,"weak":false}]},"5936":{"word":"dissent","mnemonics":[{"method":"dis-SENT：不是同一个想法","textZh":"sent 在这个词的历史中与“感觉、想法”有关，也与 sense 同源；dis- 表示不同。别人这样想，你却不赞同，便是 dissent：持异议。","kind":"public_root","original":false,"weak":false},{"method":"DISS-ent：有异议，不必骂人","textZh":"常见口语 diss 是批评、贬损；dissent 开头完整包含 diss，可以借这个熟悉词提醒“我不赞同”。但 dissent 只要求意见不同，可以很有礼貌，不等于辱骂或不尊重别人。这是拼写联想，不是词源。","kind":"public_whole_word_diss_cue","original":false,"weak":false}]},"5937":{"word":"dissipate","mnemonics":[{"method":"dis-SIP-ate：把聚成一团的驱散","textZh":"dissipate 的历史构词中，dis- 表示分开，后半来自“抛散”。看到 dissipate，就把一团聚拢的雾想成被向各处撒开、越散越薄，记住“驱散”。不要把中间的 sip 当成“小口喝”。","kind":"public_verified_etymology","original":false,"weak":false},{"method":"dissipate 联结 disappear：散到看不见","textZh":"disappear 是消失，和 dissipate 开头的音形接近。想象雾不是整团搬走，而是被阳光驱散、越来越淡，最后看不见：dissipate 强调散开消退，disappear 只说不再看得见。","kind":"public_whole_word_contrast","original":false,"weak":false}]},"5938":{"word":"dissolute","mnemonics":[{"method":"dis-SOLUT-e：约束松散了","textZh":"solut 与“松开”有关，和 solve、dissolve 有同源联系。想象约束自己的绳结全松开了，任由酒乐牵着走，毫无节制：这就是 dissolute，放纵的。","kind":"public_root","original":false,"weak":false},{"method":"resolute 坚定，dissolute 放纵","textZh":"resolute 是坚定、有决心的，与 dissolute 后半音形接近。面对又一杯酒，一边坚定守住“不再喝”的决定，一边毫无节制地继续：前者 resolute，后者 dissolute。这里对照的是行为，不把两词说成任何语境都互为反义。","kind":"whole_word_contrast","original":true,"weak":false}]},"5939":{"word":"dissolve","mnemonics":[{"method":"dis-SOLVE：把糖块松散开","textZh":"solve 与 dissolve 共享历史上“松开”的词源。问题的结可以解开，糖块也可以在水里散开、进入溶液：看到 dissolve，想到水把一块糖溶开，而不是糖凭空消失。","kind":"public_root","original":false,"weak":false},{"method":"dissolve 对照 involve：溶进去，不是卷进去","textZh":"involve 可以表示牵涉、卷入，与 dissolve 的结尾音形接近。人卷进争论是 involve；糖进入水中、不再保持固体颗粒，是 dissolve。把“卷入一件事”和“溶入液体”分开记。","kind":"whole_word_contrast","original":true,"weak":true}]},"5940":{"word":"dissonance","mnemonics":[{"method":"dis + son：声音不合","textZh":"son 与声音有关，dis 表示分开。两个音各走各的、合不到一起，听来冲突刺耳，就是 dissonance。","kind":"etymology","original":false,"weak":false},{"method":"dissension：人的纷争，音符的冲突","textZh":"dissension 是人群中的纷争。把争吵的人换成互相冲突的音符：人不和是 dissension，声音不协和是 dissonance。","kind":"invented_association","original":false,"weak":false}]},"5941":{"word":"dissuade","mnemonics":[{"method":"persuade 与 dissuade","textZh":"persuade 是说服；dissuade 把劝说的方向转过来：不是劝他去做，而是劝他别做。记 dissuade someone from doing something。","kind":"word_family","original":false,"weak":false},{"method":"dissuade：地碎的，别踩","textZh":"近音联想“地碎的”：脚下地面碎裂，朋友赶紧劝你别踩上去。不是伸手硬拦，而是开口劝阻你别做，这就是 dissuade。","kind":"invented_association","original":true,"weak":false}]},"5942":{"word":"distain","mnemonics":[{"method":"diSTAIN：名誉染上污点","textZh":"distain 中直接看见 stain，意思是“弄脏、留下污点”。把污点放到名誉上，就是玷污信誉。注意这是古旧词 distain，不是表示蔑视的 disdain。","kind":"invented_association","original":false,"weak":false},{"method":"maintain 维护，distain 玷污","textZh":"maintain 是维持：守信的人 maintain 好名声，造假却会 distain 好名声。一边维护，一边玷污，用相近的 -tain 记住名誉的得失。","kind":"invented_association","original":true,"weak":false}]},"5943":{"word":"distal","mnemonics":[{"method":"DISTal：离中心有距离","textZh":"distance 是距离；看到 distal 的 dist，就想远离连接处的一端。手臂连在肩部，手指比手腕更远，因此手指相对手腕是 distal。","kind":"word_family","original":false,"weak":false},{"method":"distal / pistol：手指在远端","textZh":"pistol 是手枪，和 distal 尾部读音相近。只用手指比个手枪形状：这些手指在离肩部更远的一端。用这个手势记 distal“远端的”，不必拿真实物品。","kind":"invented_association","original":false,"weak":false}]},"5944":{"word":"distill","mnemonics":[{"method":"distill：一滴滴收集","textZh":"词源里的 still 与“滴”有关。想象液体先变成蒸气，再冷却成一滴滴液体流进另一只容器；这个蒸发再冷凝的提纯过程就是 distill。","kind":"etymology","original":false,"weak":false},{"method":"distilled water：蒸馏水的英文品名","textZh":"看到 distill，联想到屈臣氏蒸馏水的英文品名 distilled water。water 是水，distilled 表示经过蒸馏；去掉 -ed，distill 就是“蒸馏”这个动作。","kind":"word_family","original":false,"weak":false}]},"5945":{"word":"distract","mnemonics":[{"method":"dis-TRACT：注意力被拉走","textZh":"tract 在词源中表示拉，dis- 表示分开。原本专心拼图，旁边的球却把注意力拉走：distract，使分心。","kind":"public_root","original":false,"weak":false},{"method":"distract：思路脱了 track","textZh":"track 是轨道，也可比喻思路。distract 末尾听起来像 track 加上 t；借这个近音，想象思路被打岔、脱离原来的轨道，便记住“使分心”。这不是词源拆分。","kind":"sound_association","original":true,"weak":false}]},"5946":{"word":"distraught","mnemonics":[{"method":"distraught：心被扯乱了","textZh":"distraught 的历史形式与 distract 同源，都有“拉开”的背景。不是只看了一眼别处，而是忧虑把心扯得七零八落、无法镇定思考：distraught，极其焦虑不安的。","kind":"public_etymology","original":false,"weak":false},{"method":"drought 让人 distraught","textZh":"drought 是干旱。distraught 的字形让人联想到 drought：看着田地一直缺水、庄稼快枯死，农人忧心如焚。借干旱带来的强烈焦虑，记 distraught，不把两词当成同音或同源。","kind":"public_spelling_situation","original":false,"weak":false}]},"5947":{"word":"diurnal","mnemonics":[{"method":"diurnal 联结 diary 和 journal","textZh":"diary 和 journal 都可以表示日记；diurnal 的音形让人联想到它们，它们的词源也都与“日”有关。看到 diurnal，就先抓住白天的日光：diurnal animals 指白天活动的动物，不是“每天出现一次”的动物。","kind":"public_word_family","original":false,"weak":false},{"method":"diurnal 白昼，nocturnal 黑夜","textZh":"nocturnal 表示夜间活动的。把结尾相近的这对词，配在日夜两幅画上：diurnal 是日光下飞舞的蝴蝶，nocturnal 是夜间活动的猫头鹰。看到 diurnal，就选白天活动这一幅，而不是黑夜那幅。","kind":"public_opposition","original":false,"weak":true}]},"5948":{"word":"diverge","mnemonics":[{"method":"di-VERGE：朝不同方向延伸","textZh":"di- 在这个词里表示分开，verge 的词源有倾向、转向的意思。两条路从同一点向不同方向延伸，越走越开，就是 diverge，分叉、分开。","kind":"public_root","original":false,"weak":false},{"method":"divorce 人分开，diverge 路分岔","textZh":"divorce 是离婚，原本共同生活的两人分开；diverge 与它的整体音形接近，把“原本在一起，后来各走各路”移到道路上：两条路从同一点越走越开，就是 diverge。这里只借整词联想，不把两词说成同一个词根。","kind":"whole_word_semantic_transfer","original":true,"weak":false}]},"5949":{"word":"divert","mnemonics":[{"method":"di-VERT：转到一边去","textZh":"vert 在词源中表示转，di- 表示到一边。水原本直流，木板使它转进旁边的沟渠：divert，把路线改向别处。","kind":"public_root","original":false,"weak":false},{"method":"Diverted traffic：跟箭头改道","textZh":"英国的黄色临时路牌上有 Diverted traffic（改道车辆），旁边是指向另一条路的箭头。看到 divert，就想起这块牌子：原来的路不能照走，车辆跟箭头改向别处。Diverted 是 divert 的变化形式。","kind":"official_sign_visual_anchor","original":false,"weak":false}]},"5950":{"word":"divestiture","mnemonics":[{"method":"di-VEST-iture：脱去权力外衣","textZh":"vest 与衣服有关。把代表职位的外衣脱去，也失去了附着其上的权力；divestiture 就是这种权力、权利或财产被剥离的过程，不只是脱衣服。","kind":"public_root","original":false,"weak":false},{"method":"divestiture 与 invest：资产一出一进","textZh":"invest 是把资金投进去；divestiture 则可把原来拥有的资产剥离出去。抓住共同的 vest 字形，把“投入取得”与“剥离失去”放在两边，记住财产被剥离这一义；剥离既可能自愿，也可能出于强制。","kind":"public_opposition","original":false,"weak":false}]},"5951":{"word":"divulge","mnemonics":[{"method":"di-VULG-e：秘密传到众人耳中","textZh":"vulg 在词源中与大众有关。原本保密的消息传到了外人耳中，就成了 divulge：泄露秘密。这个词源画面帮助记忆；实际使用时，透露给一个人也可以叫 divulge。","kind":"public_root","original":false,"weak":false},{"method":"divulge / bulge：鼓包露了秘密","textZh":"bulge 是鼓起的包。divulge 的重读部分与 bulge 近音：把惊喜礼物藏在外套里，鼓包却暴露了秘密。由“秘密藏不住”记住 divulge。这里只借近音，不是词源。","kind":"sound_association","original":false,"weak":false}]},"5952":{"word":"dodder","mnemonics":[{"method":"dodder / toddler：脚步摇摇晃晃","textZh":"toddler 是刚学步的小孩，走路摇摇晃晃。dodder 与 toddler 的声音相近，借这幅脚步不稳的画面，记住“颤巍巍地行走”；dodder 通常说身体虚弱的人。","kind":"sound_association","original":false,"weak":false},{"method":"dodder：“抖得”走不稳","textZh":"把 dodder 的声音近似联想为“抖得”：腿抖得厉害，只能慢慢挪步，走得颤巍巍。借“抖得走不稳”记住 dodder；这是近音联想，不是准确发音。","kind":"sound_association","original":true,"weak":false}]},"5953":{"word":"dodge","mnemonics":[{"method":"dodgeball：躲避球先躲开","textZh":"dodgeball 是躲避球。看见这个球名，想起球朝自己飞来时迅速侧身避开：dodge，就是闪身躲避。","kind":"word_family","original":false,"weak":false},{"method":"dodge：“躲着”飞来的球","textZh":"把 dodge 的声音近似联想为“躲着”：球飞来，身体马上闪到一边，让球从原来的位置穿过去。用“躲着球”记住 dodge，别把它念成中文。","kind":"sound_association","original":true,"weak":false}]},"5954":{"word":"doff","mnemonics":[{"method":"doff = do off：把衣帽脱下","textZh":"doff 源于中古英语 do off 的缩合。off 提醒“离开身体”：帽子从头上摘下，外套从身上脱下，就是 doff。","kind":"public_root","original":false,"weak":false},{"method":"DOFFING：防护用品的脱卸图","textZh":"英国卫生机构的防护用品海报中，Doffing 标题下面画着摘手套、脱防护围裙和摘口罩的动作。把这个英文标题和“穿戴物离开身体”的图一起记住：doff，脱下或摘下。","kind":"semantic_image","original":false,"weak":false}]},"5955":{"word":"dogged","mnemonics":[{"method":"DOGged：咬住就不松口","textZh":"看到 dogged 里的 dog，想象狗紧咬住骨头不肯松口。人也这样咬定目标不放弃，就是 dogged；它确实源自 dog，但不表示所有狗都如此。","kind":"public_root","original":false,"weak":false},{"method":"dogged / dogmatic：坚持做，认定对","textZh":"把形近的 dogged 与已学的 dogmatic 放在一起：dogmatic 是“我说的肯定对”，dogged 是“我认准了，就不放弃”。前者强调武断地认定，后者强调固执地坚持；二者不是同一词源。","kind":"public_opposition","original":false,"weak":false}]},"5956":{"word":"doldrums","mnemonics":[{"method":"doldrums：dull drums，鼓声也沉闷","textZh":"doldrums 近似 dull drums。想象往日热闹的鼓点变得沉闷无力，整场活动陷入低迷。这里用近音联想，不把 drums 当作真实词根。","kind":"sound_association","original":false,"weak":false},{"method":"the doldrums：帆船困在无风带","textZh":"航海中 the doldrums 是赤道附近的少风海域。把这个整词和“帆垂下来，船久久走不动”的画面绑定；事情也一直没有进展，就是陷入低迷。这个航海义是真实用法，不表示低迷义一定由它先产生。","kind":"semantic_image","original":false,"weak":false}]},"5957":{"word":"dolt","mnemonics":[{"method":"dolt / dull：脑子不灵光","textZh":"把 dolt 与形音相近的 dull 放在一起。dull 可形容头脑迟钝；dolt 则是被骂作“笨蛋”的那个人。记住一个是形容词，一个是指人的名词。","kind":"public_root","original":false,"weak":false},{"method":"Dolt：竟然把数据库叫“笨蛋”","textZh":"Dolt 是一个真实数据库的名字。开发者明确说，他们故意挑了一个意为‘笨蛋’的短词来命名，还写过《Dolt：傻瓜版数据库》。看到完整的 Dolt，就想起这个反常的名字：给软件起名‘笨蛋’。这是自嘲命名，不是在说软件质量差。","kind":"semantic_image","original":false,"weak":false}]},"5958":{"word":"domicile","mnemonics":[{"method":"DOMicile / DOMestic：给一个家","textZh":"domicile 与 domestic（家庭的）都通向拉丁语 domus“家”。抓住共同的 dom，想到给人安排一个能住下来的家；这里 domicile 是动词“安置居住”。","kind":"public_root","original":false,"weak":false},{"method":"a domicile → domicile somebody","textZh":"a domicile 是“一处住所”；后面接人作宾语时，domicile somebody 就是“给某人安置住处”。把静态的住所，变成把人安顿进去的动作。","kind":"word_family","original":false,"weak":true}]},"5959":{"word":"dominant","mnemonics":[{"method":"dominant / dominate：掌控局面","textZh":"dominate 是“支配、主导”；dominant 形容处在这种地位的人或事物。看见共有的 domin，想象同一个人一直决定全局，别人按他的安排做。","kind":"word_family","original":false,"weak":false},{"method":"dominant hand：惯用手来主导","textZh":"握笔、拿球拍时，你通常更依赖的那只手叫 dominant hand。用“它负责主导动作”的熟悉体验，把 dominant 记成“占主导的”；惯用手不一定是右手。","kind":"semantic_image","original":false,"weak":false}]},"5960":{"word":"don","mnemonics":[{"method":"don：do on 缩成穿上","textZh":"don 确实由旧时的 do on 缩合而来。抓住词尾完整的 on，把帽子戴到头上、衣服穿到身上，就是 don。","kind":"public_root","original":false,"weak":false},{"method":"DONning：把防护用品穿戴上","textZh":"防护穿戴图上有 DONNING 这个标题，下面的人正在穿上防护衣、戴好口罩和手套。把 don 与这组“往身上穿戴”的动作绑定；donning 是 don 的现在分词。","kind":"semantic_image","original":false,"weak":false}]},"5961":{"word":"donor","mnemonics":[{"method":"donor / donate：捐的人","textZh":"donor 与 donate（捐赠）共享明显的 don-。把捐赠动作 donate 和做这件事的人 donor 连起来：把书送给公益书箱的人就是 donor。","kind":"word_family","original":false,"weak":false},{"method":"blood DONOR：伸出手臂献血的人","textZh":"blood donor 是献血者。看到 DONOR，想起献血椅上主动伸出手臂、把自己的血捐给需要者的人；献血、捐书、捐款，donor 都在“给出”这一边。","kind":"semantic_image","original":false,"weak":false}]},"5962":{"word":"doodle","mnemonics":[{"method":"dOOdle：笔下绕出两个圈","textZh":"盯住 doodle 中并排的 oo：像等电话时笔尖随手绕出的两个圈。没想好画什么，手却继续画圈和曲线，这就是 doodle。这里只借字母形状联想。","kind":"semantic_image","original":true,"weak":false},{"method":"Google Doodle：标志上的小涂画","textZh":"Google Doodle 是谷歌标志上的创意涂鸦，最早的一幅在字母旁加了简笔小人。用这个完整名称和小画记住 doodle 的“涂画”；日常动词 doodle 更强调心不在焉地画，不是说品牌作品都没经过设计。","kind":"semantic_image","original":false,"weak":false}]},"5963":{"word":"dormant","mnemonics":[{"method":"DORMant / dorm：像睡着一样","textZh":"dorm 是宿舍，供人睡觉；dormant 的 dorm- 也确实与“睡眠”有关。把暂时停止活动的火山想成睡着了，但以后还可能醒来。","kind":"public_root","original":false,"weak":false},{"method":"dormant / doormat：门垫静静躺着","textZh":"dormant 的形音让人联想到 doormat（门垫）：它静静躺在门口，一动不动。用这幅画面记住“不活跃”；这里只是近形近音联想，不是词源。","kind":"sound_association","original":false,"weak":false}]},"5964":{"word":"dour","mnemonics":[{"method":"dour / sour：一张冷脸","textZh":"dour 的一种读音与 sour 押韵，拼写也只差开头字母。sour 除了“酸”，也能形容不友善的神情；把那张板着的冷脸记成 dour。不是所有读音都与 sour 押韵。","kind":"sound_association","original":false,"weak":false},{"method":"dour：durus 的“硬”","textZh":"dour 源于拉丁语 durus，意为“硬”。把硬迁移到神情和态度：脸绷着、态度冷硬，不肯露笑脸，就是 dour。这里是真实词源，不把 ou 拆成别的词。","kind":"public_root","original":false,"weak":false}]},"5965":{"word":"doyen","mnemonics":[{"method":"doyen / dean：资深领头人","textZh":"doyen 与 dean（院长；资深领头人）同源，拼写首尾也相近。想到大家遇到难题会请教的资深领头人，就抓住 doyen 的“行内老前辈”。它不一定担任院长。","kind":"etymology","original":false,"weak":false},{"method":"doyen：多演多年的老戏骨","textZh":"把 doyen 近似联想到“多演”：一位演了几十年的老戏骨，积累了丰富的表演经验，是行内的老前辈。由“多演多年，经验深”记住 doyen，资深人士；这里只借近音，不是准确发音，也不是说所有演员都算元老。","kind":"invented_association","original":true,"weak":false}]},"5966":{"word":"doze","mnemonics":[{"method":"doze / snooze：再眯一会儿","textZh":"把 doze 与 snooze（打盹）并排看：两词都有醒目的 oze 结尾。想到闹钟的 Snooze 贪睡按钮，按下后再眯一会儿，就是 doze。两词的元音不同，不把它们当成同音词。","kind":"invented_association","original":false,"weak":false},{"method":"Doze：手机也打个盹","textZh":"Android 把一种闲置省电状态叫 Doze：手机放着不用、屏幕关闭后暂缓部分活动，用户唤醒它又恢复。用这部并未关机、只是暂时“打盹”的手机，记住完整单词 doze。","kind":"semantic_image","original":false,"weak":false}]},"5967":{"word":"drawl","mnemonics":[{"method":"DRAWl：把声音 draw out","textZh":"draw 有拉的意思，draw out 可表示拉长。看 drawl 中完整的 draw，想象把一句话里的元音拉成长长的声音，就是拖着长音说。词源也很可能与 draw 有关。","kind":"etymology","original":false,"weak":false},{"method":"drawl / crawl：话音慢慢爬","textZh":"drawl 与 crawl（慢慢爬行）只差第一个字母，读音押韵。想象话音像蜗牛一样慢慢爬出来，元音拖得长长的：动作慢爬是 crawl，声音拖长慢说是 drawl。","kind":"invented_association","original":false,"weak":false}]},"5968":{"word":"drench","mnemonics":[{"method":"drench / drink：让布喝饱水","textZh":"drench 与 drink（喝）确实有词源联系。把一块干布想成在喝水：水浇进去，整块布吸得湿透。这个“让布喝饱水”的画面帮助记 drench，不是说现代英语里它等于喝水。","kind":"etymology","original":false,"weak":false},{"method":"drench / trench：沟水浸透靴子","textZh":"drench 与 trench（沟壕）只差首字母，读音也很接近。想象一脚踩进积满雨水的沟壕，水灌进靴子、袜子全湿透：沟是 trench，使湿透是 drench。","kind":"invented_association","original":true,"weak":false}]},"5969":{"word":"drivel","mnemonics":[{"method":"drivel / dribble：嘴里流出的废话","textZh":"drivel 与 dribble（滴流；流口水）形音很近。想象嘴里流出的不是有用信息，而是一串“口水话”。drivel 确实有流口水的旧义，但这里要记的是毫无意义的废话。","kind":"invented_association","original":false,"weak":false},{"method":"drivel / trivial：没价值的话","textZh":"把 drivel 与 trivial（琐碎的；无价值的）放在一起看、一起读，形音相近。trivial 提醒“没价值”，drivel 把这种判断落在话语上：听来尽是无意义的废话。这里只作近形近音联想，不把两词说成同源或处处同义。","kind":"invented_association","original":false,"weak":false}]},"5970":{"word":"drollness","mnemonics":[{"method":"已学 droll + -ness：古怪逗趣的特质","textZh":"已学的 droll 是“古怪而有趣的”。看到 drollness，先认出完整的 droll，再用 -ness 把形容词变成性质名词：这种古怪逗趣、诙谐有趣的特质。","kind":"word_family","original":false,"weak":false},{"method":"dROLLness：逗得人笑到打滚","textZh":"看到 drollness 中完整的 roll（滚动），想象一本正经的荒诞表演把观众逗得笑到打滚。用 roll 的动作钩住“逗趣”，-ness 提醒这是性质名词；这只是字形联想，不是词源，也不表示每次都要大笑。","kind":"invented_association","original":false,"weak":false}]},"5971":{"word":"drone","mnemonics":[{"method":"drONE：只用 one 个调子说","textZh":"把 drone 末尾的 ONE 圈出来，想到 one tone：从头到尾只有一个平板调子，低沉地说个不停。ONE 只是字形提示，不是单词的真正构词，也不要把 drone 末尾按 one 的读音来读。","kind":"invented_association","original":true,"weak":false},{"method":"drone / groan：话声像低低的长哼","textZh":"drone 与 groan（低声呻吟）押韵，开头也相近。把一段话想成低低的、没有起伏的长哼，就抓住 drone 的单调低语。groan 常表达痛苦或不满，drone 不要求说话者有这种情绪；这里只借声音作联想。","kind":"invented_association","original":true,"weak":false}]},"5972":{"word":"drudgery","mnemonics":[{"method":"drudge + -ery：苦干的活儿","textZh":"drudge 指做辛苦、卑微或重复乏味的活儿，也可指做这种活的人。drudgery 保留 drudg-，加名词后缀 -ery，把注意力放在这些活儿本身：苦工、单调劳作。","kind":"etymology","original":false,"weak":false},{"method":"drudgery / trudge：一趟趟艰难搬运","textZh":"drudgery 前半部 drudg- 与 trudge（疲惫地艰难行走）形音接近。想象搬运工拖着沉重脚步，一趟又一趟搬同样的东西：trudge 是脚步，drudgery 是这份费力又单调的活。只是近形近音联想，不说两词同源。","kind":"invented_association","original":false,"weak":false}]},"5973":{"word":"ductile","mnemonics":[{"method":"duct-：容易被带着走","textZh":"ductile 的词源连着拉丁语 ducere（引导、带领）。抓住 duct- 的“带着走”：别人一说就跟着改变主意，容易被引导、被影响。本课把这个“容易带动”的意思用在人身上，不停留在金属拉丝。","kind":"etymology","original":false,"weak":false},{"method":"ductile / docile：都容易听人摆布","textZh":"把 ductile 与 docile（温顺的；易管教的）并排看：d 开头、c 在中间、ile 收尾，字形很近。docile 的听从引导提醒 ductile 的易受影响；两词词源不同，也不完全同义，ductile 更重观点或性格容易被塑造。","kind":"invented_association","original":false,"weak":false}]},"5974":{"word":"dulcet","mnemonics":[{"method":"dulc-：声音也能像糖一样甜","textZh":"dulcet 的 dulc- 来自拉丁语 dulcis，意思是甜。把糖的甜转给耳朵：不是嘴里吃到糖，而是耳边听到柔美甜润的声音。由“甜”直接记住“悦耳”。","kind":"etymology","original":false,"weak":false},{"method":"dulcet / duet：悦耳的二重奏","textZh":"从 dulcet 的 du…et 外框联想到 duet（二重奏）：两种乐器轻柔合奏，旋律甜美悦耳。duet 本身只表示两人演奏，不保证好听；这里借一段悦耳二重奏作近形记忆画面，联想较松，不是词源。","kind":"invented_association","original":false,"weak":true}]},"5975":{"word":"dullard","mnemonics":[{"method":"dull + -ard：把迟钝写成一个人","textZh":"已学 dull 有“迟钝、不敏锐”的意思。dullard 保留完整 dull，再加指人的 -ard：不是一件钝东西，而是脑子不灵光的笨人。想起 dull 的钝刀刃，再把这种“不敏锐”放到人的脑子上。","kind":"word_family","original":false,"weak":false},{"method":"DULLard / DOLL：问了半天，仍像个呆木偶","textZh":"看到 dullard 前面的 dull，联想到形似的 doll（玩偶）。别人把一个简单问题反复讲给他，他仍像木偶一样呆望着，没有理解过来。用“像 doll 一样反应迟钝的人”钩住 dullard。","kind":"invented_association","original":false,"weak":false}]},"5976":{"word":"dupe","mnemonics":[{"method":"dupe / dope：糊涂人信了骗局","textZh":"dupe 和 dope（笨人）词形很近。想象一个糊涂的 dope 对骗子的话照单全收，成了上当的 dupe。dope 帮你抓住“容易被糊弄的人”，但 dupe 强调受骗，并不是所有受骗者都笨。","kind":"invented_association","original":false,"weak":false},{"method":"dupe / duplicate：把复制品当真货的买家","textZh":"已学 duplicate 表示复制或复制品，开头 dupl- 与 dupe 很接近。想象商贩拿复制品冒充原件，买家信以为真，付钱后才发现被骗：这个被假货蒙住的人是 dupe。重点记买家，不是把复制品义当成这里的人物义。","kind":"invented_association","original":false,"weak":false}]},"5977":{"word":"duplicitous","mnemonics":[{"method":"已学 duplicity → duplicitous：把两面行为贴到人身上","textZh":"已学 duplicity 是“表里不一、欺骗性的两面行为”。看到 duplicitous，认出完整的 duplicit- 词干：duplicity 说这种做法，duplicitous 则形容做这种事的人或手段。嘴上答应帮你，暗中却做相反的事，这个人就是 duplicitous。","kind":"word_family","original":false,"weak":false},{"method":"duplicitous / publicity：宣传说一套，背后做一套","textZh":"duplicitous 的词形会让人想起 publicity（公开宣传）。想象一个人公开宣传时满口公平，私下却偷偷给自己人开后门。publicity 的漂亮话与暗中的相反做法并列，钩住“口是心非、两面三刀”。","kind":"invented_association","original":false,"weak":false}]},"5978":{"word":"dyspeptic","mnemonics":[{"method":"dys- + peptic：胃里不顺，脾气也不顺","textZh":"dys- 表示不良，peptic 与消化有关；dyspeptic 原本有“消化不良的”意思。用“胃里不舒服，讲话也带着火气”记住它引申的“脾气坏、易烦躁”。这里是词义联系，形容坏脾气时并不表示真有胃病。","kind":"etymology","original":false,"weak":false},{"method":"DYS / diss：见谁都要怼几句","textZh":"把 dyspeptic 开头的 dys 联想到 diss（贬损、挑刺）。想象一个坏脾气的人见谁都想 diss，旁人刚开口，他就不耐烦地怼回去。这个“总爱挑刺”的反应能帮你抓住易烦躁，但词形钩子较短。","kind":"invented_association","original":false,"weak":true}]},"5979":{"word":"earsplitting","mnemonics":[{"method":"ear + splitting：像要把耳朵震裂","textZh":"ear 是耳朵，splitting 是裂开。把 earsplitting 连起来想成“响得仿佛耳朵都要裂开”：不是一般音量大，而是大得令人难受。记住这是夸张说法，不是实际受伤。","kind":"word_structure","original":false,"weak":false},{"method":"ear + split：耳朵受不了，赶紧撤","textZh":"split 在口语里还可表示“赶紧离开”。看到 earsplitting，就想象刺耳警报一响，你一边捂住 ears，一边喊“Let’s split!”赶紧撤离。用“捂耳撤走”的反应，区别于第一条的震裂画面。","kind":"invented_association","original":true,"weak":false}]},"5980":{"word":"eavesdrop","mnemonics":[{"method":"eaves + drop：站在屋檐滴水处偷听","textZh":"eaves 是屋檐；eavesdrop 的来历连着站在屋檐滴水处的人。想象他不进屋，只藏在檐下，偷偷听屋内的私话：屋檐下的秘密听众，就把 eavesdrop 和“偷听”连起来。","kind":"etymology","original":false,"weak":false},{"method":"Eve：密码学里的窃听者","textZh":"密码学故事里，Alice 和 Bob 互相传话，名叫 Eve 的第三者偷偷截听。Eve 的发音正好钩住 eavesdrop 开头的 eaves-；想到这位躲在通信旁边的 Eve，就想到秘密窃听。这是现成角色名的近音提示，不是单词词源。","kind":"named_anchor","original":false,"weak":false}]},"5981":{"word":"eccentric","mnemonics":[{"method":"ec- + centr：偏离常规中心","textZh":"eccentric 的词源含“离开”与“中心”。把常规想成中心线，一个人偏偏走在旁边，穿着、习惯都不循常规：从“偏离中心”记住“行为古怪”。这里的古怪不等于精神失常。","kind":"etymology","original":false,"weak":false},{"method":"Eccentric Family：住进井里的怪家人","textZh":"动画的真实英文片名是 The Eccentric Family。故事里有一位狸猫兄弟把自己变成青蛙，住在井里不肯出来。把完整的 Eccentric 与这位生活方式古怪的家人绑在一起：eccentric 说的就是这种不按常规来的样子。不必记角色姓名，也不需要看过作品。","kind":"named_anchor","original":false,"weak":false}]},"5982":{"word":"éclat","mnemonics":[{"method":"éclat：一下迸发的光彩","textZh":"éclat 来自法语，连着“迸发、闪耀”的意思，后来用来表示耀眼的成功。想象一个人的成果突然大放光彩，让大家眼前一亮：这份令人瞩目的辉煌成就，就是这里的 éclat。","kind":"etymology","original":false,"weak":false},{"method":"éclat / a clap：成功换来喝彩","textZh":"把 éclat 近音联想到 a clap（一声鼓掌）：演员出色完成演出，全场用掌声肯定他的成功。用“取得辉煌成功，所以赢得喝彩”记词义，不把 éclat 只记成拍手动作。只是近音联想，éclat 末尾 t 不发音。","kind":"sound_association","original":false,"weak":false}]},"5983":{"word":"ecumenical","mnemonics":[{"method":"ecumen-：整个有人居住的世界","textZh":"ecumenical 的 ecumen- 来自希腊语“有人居住的世界”，更远连着“家”的意思。把世界想成大家共同居住的一座大房子：范围不只一村一国，而是整个世界。由这个词根画面记住“世界范围的”。","kind":"etymology","original":false,"weak":false},{"method":"Ecumenical logic：不只容纳一家逻辑","textZh":"真实论文题名 Ecumenical modal logic 把经典逻辑和直觉主义逻辑放进一个统一框架。把完整的 Ecumenical 与“两家逻辑同处一套框架”的画面相连，就能记住范围广、不拘一家的普遍包容意味。它是记忆锚，不表示该论文覆盖世界上所有逻辑，也不把本课换成教会义。","kind":"named_anchor","original":false,"weak":false}]},"5984":{"word":"edible","mnemonics":[{"method":"ed- + -ible：可以吃的","textZh":"edible 的 ed- 连着拉丁语“吃”，-ible 表示“可以……的”。把吃与可以合起来，就是可食用：不只是能咬动，而是适合拿来吃。","kind":"etymology","original":false,"weak":false},{"method":"Edible：这束花竟然能吃","textZh":"真实品牌 Edible Arrangements 会把菠萝切成花朵，把草莓等水果做成花束。看到完整的 Edible，就想起这束不是只能摆着看、而是能吃的水果花：可食用的。这里只拿水果花束记词，不表示该品牌卖的每件物品都能吃。","kind":"named_anchor","original":false,"weak":false}]},"5985":{"word":"edifice","mnemonics":[{"method":"aedis + facere：把房屋建起来","textZh":"edifice 来自拉丁语 aedis（房屋）和 facere（建造、制作）。看到 edi-fice，想起“建造房屋”，再把它想成高大宏伟、让人仰头看的建筑，就抓住了“大厦”的意思。","kind":"etymology","original":false,"weak":false},{"method":"head office：宏伟的总部大楼","textZh":"把 edifice 的读音、词形联想到 head office（总部）。不是桌边的一间小办公室，而是一整座气派的总部大楼：高大的门厅、成排的窗户，让人一眼看出这是座 edifice。","kind":"invented_association","original":false,"weak":false}]},"5986":{"word":"efface","mnemonics":[{"method":"e- + face：把表面的面貌抹去","textZh":"efface 的词源由表示“离开、去除”的 e- 和 face 组成。想象石币表面的 face 被磨平，原来的脸形和纹路逐渐看不清了：把表面的痕迹抹去，就是 efface。","kind":"etymology","original":false,"weak":false},{"method":"erase / efface：擦除的押韵搭档","textZh":"把 erase 和 efface 连着念，结尾都落在 /eɪs/；它们的词形也很接近。想象橡皮一过，刚写的字不见了：erase 擦掉，efface 也抹去。用这对同义押韵词直接互相提取，不必再编一个人物故事。","kind":"invented_association","original":false,"weak":false}]},"5987":{"word":"effervesce","mnemonics":[{"method":"ef- + ferv-：热情从心里沸腾出来","textZh":"effervesce 的词源是“向外沸腾”：ef- 表示向外，ferv- 与热、沸腾有关。把沸腾从水里移到心里：好消息一来，喜悦藏不住，从笑容和动作里冒出来，就是“兴奋、热情洋溢”。","kind":"etymology","original":false,"weak":false},{"method":"F for vest：拿到新背心，兴奋地展示","textZh":"把 effervesce 的声音联想到 F for vest。想象新背心上印着大大的 F，你兴奋地说：“F 是 fantastic，太棒了！”一边展示背心，一边兴高采烈。声音能拉住词形，但兴奋主要靠补上的情境，这条联系较弱。","kind":"invented_association","original":false,"weak":true}]},"5988":{"word":"effete","mnemonics":[{"method":"ef- + fetus：产出之后，力气耗尽","textZh":"effete 来自拉丁语 effetus，原来联系着生产后耗尽力量的状态；ef- 有“向外”的意思，fetus 与生育、产出有关。用“已经耗尽产出的活力”记住衰弱、无力，不要把这个词简单理解为女性化。","kind":"etymology","original":false,"weak":false},{"method":"effete / feet：双脚再也带不动身体","textZh":"effete 重读的 /fiːt/ 和 feet（双脚）同音。想象一个人走了漫长的路，力气耗光，双脚像灌了铅，再也走不动。用“feet 已经耗尽力量”记住 worn out、衰弱；这个声音钩子不限制它只能形容身体。","kind":"invented_association","original":false,"weak":false}]},"5989":{"word":"effluvium","mnemonics":[{"method":"已学 affluent：财富流入，臭气流出","textZh":"已学 affluent 用“财富流入”帮助记富裕；effluvium 同样有表示流动的 flu-，但 ef- 是向外。把流出的东西换成垃圾桶散出的臭气：看不见，却闻得到，这股难闻的气味就是 effluvium。","kind":"word_family","original":false,"weak":false},{"method":"flue：烟道里窜出的难闻气味","textZh":"flue /fluː/ 是烟道，和 effluvium 中间的 /fluː/ 同音。想象你刚走近一根排烟管，就被难闻的气味呛得皱眉、掩鼻：flue 是烟道，effluvium 是它排出的那股臭味。这里用近音记气味，不是把烟道当作词义。","kind":"invented_association","original":true,"weak":false}]},"5990":{"word":"effrontery","mnemonics":[{"method":"front：插到最前面还理直气壮","textZh":"看到 effrontery 中的 front（前面），想起有人公然插到队伍最前面。别人指出他插队，他不但不脸红，还要求先服务：这不是勇敢，而是厚颜无耻的放肆。","kind":"invented_association","original":false,"weak":false},{"method":"affront：冒犯了人还毫不羞愧","textZh":"effrontery 的前半段听起来很像 affront（公然冒犯、侮辱）。affront 抓“冒犯”，effrontery 再抓冒犯者毫不羞愧、仿佛自己有特权的劲头：敢这么冒犯，还觉得理所当然。两词不是完全同义。","kind":"invented_association","original":false,"weak":false}]},"5991":{"word":"effulgent","mnemonics":[{"method":"ef- + fulg：光向外闪耀","textZh":"effulgent 来自拉丁语中“向外闪耀”的词：ef- 对应 ex-（向外），fulg 对应 fulgere（发光）。抓住“光辉向外放射”，就能记住它不是普通的亮，而是光辉灿烂。","kind":"etymology","original":false,"weak":false},{"method":"full gem：亮得像一整颗宝石","textZh":"把 effulgent 中的 ful-gen 联想到 full gem（一整颗宝石）：不是一点微弱反光，而是一颗切面都在闪耀的宝石，光辉灿烂。借近似词形把词义钉在耀眼的光上。","kind":"invented_association","original":false,"weak":false}]},"5992":{"word":"egoistic","mnemonics":[{"method":"ego：心里只有“我”的利益","textZh":"ego 是拉丁语的“我、自我”。egoist 是以自己利益为中心的人，加形容词后缀 -ic 成为 egoistic：想事情总先问“我能得到什么”，不顾别人的需要。","kind":"etymology","original":false,"weak":false},{"method":"与 egotistic 对照：少一个 talk 的 t","textZh":"把 egoistic 和 egotistic 并排看：egotistic 在 ego 后多一个 t，可用 talk（说）提醒自己，可联想到爱谈论、夸耀自己。egoistic 则先记只顾自己的利益。这是帮助记忆的常见侧重点对照，不是严格界线：实际使用中，自私、自我中心和自负可以重叠。","kind":"invented_association","original":false,"weak":false}]},"5993":{"word":"elaborate","mnemonics":[{"method":"e- + labor：细细做出来的","textZh":"elaborate 的词源包含 labor（劳动、工作），原意是“精心做出来的”。想起一件下足工夫、连小细节都做得周到的作品：成品复杂而精细，就是 elaborate。这里记形容词，不是“详细阐述”的动词。","kind":"etymology","original":false,"weak":false},{"method":"lab：实验室里复杂精细的装置","textZh":"从 e-LAB-orate 抓住 lab（实验室）。想象一套实验装置，玻璃管、阀门、刻度密密麻麻，每个小部件都精细安排好了；看到 lab 就回想这套“复杂精细”的装置。","kind":"invented_association","original":false,"weak":false}]},"5994":{"word":"elastic","mnemonics":[{"method":"e-la：“一拉”还能回原样","textZh":"把 elastic 开头的 e-la 近似联想成“一拉”。想起橡皮圈：一拉就变长，拉力减小时又缩回原来的样子。关键不只是能拉长，还能恢复原状，这才是有弹性。","kind":"invented_association","original":false,"weak":false},{"method":"Elastigirl：弹力女超人","textZh":"《超人总动员》中的 Elastigirl（弹力女超人）能把身体拉长、改变形状。她的名字开头 Elasti- 与 elastic 几乎相同；把这个可伸缩的角色和弹性联系起来，再记住材料的 elastic 是拉伸后还能恢复原状。","kind":"invented_association","original":false,"weak":false}]},"5995":{"word":"eleemosynary","mnemonics":[{"method":"alms 同源短词：长词背后的一份救济","textZh":"把长长的 eleemosynary 与短词 alms 成对记：alms 就是送给困难者的救济金或物资。两词真实同源，只是 alms 在历史中大幅缩短了。看到 eleemosynary，取回这份 alms，就想到“慈善的、靠捐赠支持的”；不用再背另一串拉丁拼写。","kind":"etymology","original":false,"weak":true},{"method":"mosynary ≈ missionary：免费救助站","textZh":"把 eleemosynary 后半的 mosynary 近似联想到 missionary（传教士）。想象一位传教士办了免费救助站，把捐来的食物送给有需要的人；这里要记的是这项救助的慈善性质，不是说 eleemosynary 等于“传教的”。","kind":"invented_association","original":false,"weak":true}]},"5996":{"word":"elegy","mnemonics":[{"method":"哀礼祭：用哀歌祭奠","textZh":"把 elegy 的读音近似联想到“哀礼祭”：在追悼礼上，人们以一首哀伤的诗歌寄托思念。“哀”抓悲伤，“祭”抓悼念，合起来记住 elegy 是哀歌、挽诗。","kind":"invented_association","original":false,"weak":false},{"method":"已学 elegiac → elegy：哀婉的诗","textZh":"已学的 elegiac 表示“哀悼的、挽歌般忧伤的”。看到两词共同的 eleg-，把 elegiac 的哀婉气氛收进一首诗或一支歌里：那首承载哀思的作品就是名词 elegy，而 elegiac 描写它的性质。","kind":"learned_anchor","original":false,"weak":false}]},"5997":{"word":"elevate","mnemonics":[{"method":"elevator：给思想乘一趟上行电梯","textZh":"elevate 与 elevator（电梯）是同一家族，长长的 elevat- 几乎相同。电梯让人上楼，好书则让理解力、审美和品格上一个层次；本页记的是“思想境界向上”，不是把身体抬起来。","kind":"invented_association","original":false,"weak":false},{"method":"Educate to elevate：教育带来提升","textZh":"把 educate（教育）和 elevate 连成押韵短语 Educate to elevate：“通过教育，让人的知识与品格提高”。两词开头和词尾相呼应，读出这组节奏，就从“受教育”直接想起“提升智力与道德水平”。","kind":"invented_association","original":false,"weak":false}]},"5998":{"word":"elliptical","mnemonics":[{"method":"ellipsis：省略号藏掉了关键信息","textZh":"ellipsis 是“省略、省略号”，与 elliptical 共享 ellip-。看到 elliptical，就想一句话被“……”截走了关键内容：说话人以为你懂，听的人却不知道指什么，于是表达变得含糊难懂。不是所有省略都难懂，本页记过分省略造成的隐晦。","kind":"word_family","original":false,"weak":false},{"method":"lip：话含在嘴边，不肯说透","textZh":"抓住 el-LIP-tical 里的 lip（嘴唇）。想象有人嘴唇动了几下，只说“就是那件事，你懂的”，把关键内容含在嘴边不说透；别人只好猜。这个嘴唇里的半截话，提醒你 elliptical 是表达含糊，而不是声音太小。","kind":"invented_association","original":false,"weak":false}]},"5999":{"word":"emaciate","mnemonics":[{"method":"maci：逐渐耗损，连力量也衰弱","textZh":"emaciate 的词源包含拉丁语 macies（消瘦），原本描写身体逐渐耗损。把这个过程的“力量也被耗掉”记牢：人会变得衰弱，论证等事物的力量也可以被削弱。本页重心是使衰弱，不是健康地减重。","kind":"etymology","original":false,"weak":false},{"method":"maci- ≈ 没食：缺食耗弱气力","textZh":"抓住美音 emaciate 中重读的 maci- /ˈmeɪʃi/，近似联想“没食”（méi shí）。持续没食物补充，人就会气力衰弱，连原来拿得稳的小杯也拿不稳：缺食把力量削弱了。这只是近音助记，不是词源；要取回的是“使衰弱”，不只是一副瘦的外形。","kind":"invented_association","original":false,"weak":false}]},"6000":{"word":"emancipate","mnemonics":[{"method":"e- 向外，mancip- 掌控：从他人掌中解放","textZh":"emancipate 的词源里，e- 表示“向外”，mancip- 与手中的占有、掌控有关。把它看成一只原本被紧握的手终于松开，人从别人的掌控中走出来：不再受支配，就是获得解放。这里是词源帮助记义，不把它解释成现代英语 man 加其他零碎字母。","kind":"etymology","original":false,"weak":false},{"method":"a man escaped：一个人摆脱了束缚","textZh":"把 emancipate 的整段声音近似联想到 a man escaped（一个人逃脱了）：原先被困的人终于走出束缚、获得自由。这个近音画面帮助记住“解放”，再记清语法：emancipate 是“使某人获得自由”，不等同于不及物的“自己逃跑”。","kind":"invented_association","original":false,"weak":false}]},"6001":{"word":"embargo","mnemonics":[{"method":"bar + go：拦住货物，不准通行","textZh":"看到 embargo 中连在一起的 bar 和 go，就想 bar（阻拦）住货物的 go（通行）：港口有官方命令，货物不许进出交易。这条“拦住货物流通”的命令就是贸易禁令。这个拆看法只是记忆联想，不是完整的历史构词。","kind":"invented_association","original":false,"weak":false},{"method":"embargo 押韵 cargo：货物停运","textZh":"把 embargo 的后半 bargo 与 cargo（货物）的声音连在一起，记一组押韵搭档：embargo 一来，cargo 停运。cargo 让你立刻想到跨境运输的货物，再把 embargo 锁定为官方贸易禁令，不是普通堵车。","kind":"invented_association","original":false,"weak":false}]},"6002":{"word":"embark","mnemonics":[{"method":"em- + bark：像船出发一样启动事业","textZh":"embark 源自“进入船中”：em- 是“进入”，bark 在这个词源里指船。把一项新事业看成一段航程，登上船、迈出第一步，也就是开始从事它。本页要记 embark on a project 的“着手开展”，不把“上船”当成核心义。","kind":"etymology","original":false,"weak":false},{"method":"embark ↔ spark：为新事业点火","textZh":"embark 的重读部分与 spark（火花）押韵。spark 既指火花，也能表示“引发、使开始”：火花点起火焰，新事业也由此启动。读到 embark，就借这个“点火起步”的声音联想，记住“开始从事”；这是押韵记忆，不是说两词同源。","kind":"invented_association","original":false,"weak":false}]},"6003":{"word":"embarrass","mnemonics":[{"method":"俺爸惹事：当众让人难为情","textZh":"把 embarrass 的声音近似联想到“俺爸惹事”：爸爸在朋友面前讲出你的糗事，你脸一下红了，不知道该怎么接话。这个当众难为情的反应，帮你记住 embarrass 是“使人尴尬”，不是一般的使人生气。","kind":"invented_association","original":false,"weak":false},{"method":"barr 像 barrier：尴尬得话被堵住","textZh":"embarrass 中的 barr 和 barrier（障碍、屏障）的开头相同。想象当众叫错了别人的名字，刚想解释，话却像被一道屏障堵住，手也不知道往哪放。这个被卡住的窘态把词形 barr 接到“使尴尬”；这只是联想，不把 barrier 当作它的直接词源。","kind":"invented_association","original":false,"weak":false}]},"6004":{"word":"embezzle","mnemonics":[{"method":"俺背走：把代管公款私自带走","textZh":"把 embezzle 的声音粗略联想到“俺背走”。想象保管员把本来替大家管理的钱装进自己的包，心里盘算“俺背走，归我用”。不是普通搬运，而是受托代管的人私自占用财物，这就是盗用、侵吞。","kind":"invented_association","original":false,"weak":false},{"method":"bezz ≈ bees：管公蜜的小蜂私吞蜂蜜","textZh":"看到 embezzle 中的 bezz，就近似联想到 bees（蜜蜂）。想象一只受托管理蜂群公共蜜罐的小蜂，偷偷把大家的蜂蜜装进自己的小罐。抓住“本来替大家保管，却据为己有”，从这只管蜜的蜂记住 embezzle 的盗用义。","kind":"invented_association","original":false,"weak":false}]},"6005":{"word":"embolden","mnemonics":[{"method":"em-bold-en：让人变得 bold","textZh":"bold 是“大胆的”，embolden 把这个性质变成动作：让原本胆怯的人大胆起来。朋友一句“你能行”，使你敢于举手发言，就是 embolden you。","kind":"word_family","original":false,"weak":false},{"method":"bolden 押韵 golden：成功给人壮胆","textZh":"embolden 的后半 bolden 与 golden（金色的）押韵。想象手里那枚 golden 奖牌：一次成功让原先不敢尝试的人有信心迎接更难的挑战。从“金牌带来的底气”，记住 embolden 是“使人鼓起勇气”。","kind":"invented_association","original":false,"weak":false}]},"6006":{"word":"emboss","mnemonics":[{"method":"boss 的凸饰义：让花纹鼓出表面","textZh":"boss 除了“老板”，还可以指盾牌、皮带上凸起的装饰。emboss 的词源正与这种“凸起”有关：把表面做出能摸到的凸纹，再用它来装饰。抓住“高出表面”，就不会误记成平面的印刷。","kind":"etymology","original":false,"weak":false},{"method":"印 boss：老板名片上的凸字","textZh":"把 emboss 的声音近似联想到“印 boss”。想象给 boss（老板）印一张名片：不是普通平面油墨，而是把姓名压成手指能摸到的凸字。从这张有立体字的名片，记住 emboss 的“压印凸纹、浮凸装饰”。","kind":"invented_association","original":false,"weak":false}]},"6007":{"word":"embroider","mnemonics":[{"method":"broider 像 border：给故事添花边","textZh":"看到 embroider 里的 broider，可近似联想到 border（边框）：给一个朴素故事围上漂亮的“花边”，添进原本没有的情节，让它听起来更精彩。本页记的是给叙述添油加醋，不是做针线活；这是一种近形联想。","kind":"invented_association","original":false,"weak":false},{"method":"broider 近似 broader：故事越讲越大","textZh":"broider 的拼写和声音都接近 broader（更宽的）。讲鱼的人把两手越张越宽，小鱼被他说成了大鱼，随后又添出惊险情节。用“越讲越大”的变化，记住 embroider 是夸饰叙述；broader 只是近形近音提示，不是它的词根。","kind":"invented_association","original":false,"weak":false}]},"6008":{"word":"emigrate","mnemonics":[{"method":"e- 向外 + migrate 迁移","textZh":"migrate 是“迁移”，emigrate 的 e- 有“向外”的来源。把它想成一家人带着搬家行李，从自己的国家走出去，到另一个国家安家：重点是“迁出”，不是短期出游。","kind":"etymology","original":false,"weak":false},{"method":"近音“移民，great!”","textZh":"把 emigrate 近似联想到“移民，great!”：“移民”接住前半的声音，great 接住 -grate 的声音。想象说话的人已经收拾好家当，准备离开原居国，到国外长期生活。great 只是助记的声音挂钩，emigrate 本身并不评价移民是好是坏。","kind":"invented_association","original":false,"weak":false}]},"6009":{"word":"emollient","mnemonics":[{"method":"moll- 软：把硬话说软","textZh":"emollient 的词源中，moll- 表示“软”。把这个“软”落到说话方式上：原本强硬、刺人的话变得温和，对方的火气也慢慢降下来。这里的“软化”指缓和情绪或局面，不是在说润肤乳。","kind":"etymology","original":false,"weak":true},{"method":"近音“一摸脸”：温柔安抚下来","textZh":"把 emollient 的声音近似联想到“一摸脸”。孩子委屈得快哭了，家人轻轻摸摸他的脸，柔声安慰，他慢慢平静下来。抓住这种温柔的安抚作用，记住 emollient 是“起缓和作用的”，不是把它当成摸脸这个动作本身。","kind":"invented_association","original":false,"weak":false}]},"6010":{"word":"enact","mnemonics":[{"method":"en-act：把提案变成法令","textZh":"act 作名词可以指“法令”。看到 enact，就想象一项提案经过正式立法程序，成为一部 Act：不再只是建议，而是已经制定、颁布的法律。这里抓的是 act 的法律义，不是“演戏”。","kind":"word_family","original":false,"weak":false},{"method":"elect 选议员，enact 定法律","textZh":"elect（选举）与 enact 的整体拼写和声音相近。把两件事连起来：选民 elect 议员，议员再 enact laws，制定法律。一个选出立法者，一个说立法者做什么；这是近形近音联想，不是词源拆解。","kind":"invented_association","original":false,"weak":false}]},"6011":{"word":"enamel","mnemonics":[{"method":"enamel 联想到 melt：熔上的彩衣","textZh":"enamel 与 melt（融化）有词源联系。想起传统珐琅工艺：彩色材料受热熔融，附在器物表面，冷却后成为亮丽的外层。从这件“熔上去的彩衣”，记住 enamel 的彩饰、涂釉义。","kind":"etymology","original":false,"weak":false},{"method":"近音“因耐磨”：器物穿上亮外衣","textZh":"把 enamel 的声音近似联想到“因耐磨”。想象给金属杯披上一层光滑、彩色的搪瓷外衣，让它既好看又能保护表面。把声音挂到这层亮外衣上，记住 enamel 是给器物涂珐琅、作彩饰；不是说涂层永远不会磨损。","kind":"invented_association","original":false,"weak":false}]},"6012":{"word":"encompass","mnemonics":[{"method":"compass 画个圈：圈内都包含","textZh":"compass 可以指画圆的“圆规”。想象用圆规把几种活动圈进同一个范围，圈里的项目都被包括在内。从 en-compass 里完整的 compass，记住“纳入范围、包含”，而不是只记住外面围了一圈。","kind":"invented_association","original":false,"weak":false},{"method":"compass 近似 campus：校园包含各部分","textZh":"encompass 的后半 compass 与 campus（校园）近形近音。想象一个校园：它不只有教室，还包含图书馆、实验室和运动场。由 campus 这个由多种设施组成的整体，记住 encompass 是“包含、涵盖”。","kind":"invented_association","original":false,"weak":false}]},"6013":{"word":"enervate","mnemonics":[{"method":"e- 向外，nerv- 筋力：力量被抽走","textZh":"enervate 的 e- 有“向外”之意，nerv- 与 nerve 同源，词源中指筋腱。把它想成一个人像被抽走了筋力，身体软下来，提不起劲。记住是削弱力量，不是看到 nerv 就误以为让人兴奋。","kind":"etymology","original":false,"weak":false},{"method":"energy 被 ate：精力被吃光","textZh":"看到 enervate 的前半 ener-，联想到 energy（精力）；词尾 ate 是“吃了”。想象酷热把人的精力一口口吃掉，原本有劲的人变得疲软无力。这是近形拼读联想，不是说 enervate 真由 energy 和 ate 构成。","kind":"invented_association","original":false,"weak":false}]},"6014":{"word":"engross","mnemonics":[{"method":"en-gross：把全部注意力收进去","textZh":"gross 可以表示“总的、全部的”。把 engross 想成把注意力的总量都收进一件事：一本好书占满心思，旁边发生什么都没留意。“全部”这个入口帮助记住 engross 的全神贯注，而非一般的感兴趣。","kind":"invented_association","original":false,"weak":false},{"method":"近音 in grass：看草丛里的小世界","textZh":"engross 近似读起来像 in grass（在草丛里）。想象你蹲在草边看蚂蚁搬食物，看得入了迷，朋友叫你也没听见。由这个整段近音，联想到注意力全被草丛里的小世界吸住；grass 不是 engross 的词根。","kind":"invented_association","original":false,"weak":false}]},"6015":{"word":"enigma","mnemonics":[{"method":"enigmatic 去掉 -tic：从谜一般到一个谜","textZh":"已学 enigmatic 是“神秘难解的”。看清它前面完整的 enigma：enigmatic 用来形容“谜一般的”，enigma 则是那个让人猜不透的人或事物。把形容性质转为指认一个“谜”，就能记回这个名词。","kind":"word_family","original":false,"weak":false},{"method":"Enigma 密码机：读不懂的密文","textZh":"回想 Enigma 密码机：它把消息编成密文，外人看见了也不能直接读懂。大写 Enigma 是这台机器的名字；小写 enigma 是“难解的谜”。由这个完整同名提示，抓住看得见却难以解释的感觉。","kind":"cultural_reference","original":false,"weak":false}]},"6016":{"word":"enlighten","mnemonics":[{"method":"en-light-en：把不懂的地方照亮","textZh":"抓住中间完整的 light（光）：知识像一束光，把原来不明白的地方照亮。老师讲清原因，你才知道“原来如此”；enlighten 在这里就是提供知识，让人明白，不是把电灯打开。","kind":"word_family","original":false,"weak":false},{"method":"近音 in Latin：解释后才明白","textZh":"把 enlighten 整体近似联想到 in Latin（用拉丁文）。一段拉丁文让不懂这门语言的人摸不着头脑，老师把意思解释清楚，听者才明白。由“给不懂的人作解释”，记住 enlighten；这是整段近音联想，不是词源。","kind":"invented_association","original":false,"weak":false}]},"6017":{"word":"enmity","mnemonics":[{"method":"enemy 是敌人，enmity 是敌意","textZh":"enmity 与熟词 enemy（敌人）形音相近，而且确实同源。enemy 指敌对的人，enmity 指敌人之间那股深深的恨意。把“对方是敌人”转成“双方怀有敌意”，记住它是情感名词。","kind":"word_family","original":false,"weak":false},{"method":"近音“恨没停”：彼此仍怀恨","textZh":"把 enmity 的三音节近似联想到“恨没停”。不是刚生气就算了，而是两人见面仍互相敌视，心中的恨意一直没消。由这个直接说出持续仇恨的声音提示，记住 enmity；不要照中文读音替代英语发音。","kind":"invented_association","original":false,"weak":false}]},"6018":{"word":"ennoble","mnemonics":[{"method":"en-noble：使人变得高尚","textZh":"noble 可以指品格“高尚的”，en- 在这里表示使之成为。一个人愿意顾及他人，善举使他的品格更高尚、更值得尊敬；en+noble 便是“使高尚”。这里不把 noble 只理解为贵族身份。","kind":"word_family","original":false,"weak":false},{"method":"近形 Nobel：善举值得尊崇","textZh":"ennoble 的后半 noble 与 Nobel（诺贝尔）近形近音。联想到诺贝尔和平奖所表彰的和平贡献：帮助别人、促进和平的作为，使一个人更值得尊敬。从“善举提升人格与尊严”记 ennoble，不是说获奖就自动证明品德完美。","kind":"invented_association","original":false,"weak":false}]},"6019":{"word":"ensconce","mnemonics":[{"method":"ensCONCE / CONCEal：藏得看不见","textZh":"已学 conceal 是“隐藏、隐瞒”。看 ensconce 末尾的 CONCE，与 CONCEal 开头是同一整块拼写：把这个熟悉的隐藏动作带过来，记住 ensconce 的“把人或物藏好”。这是近形联想，不是说两词有共同词根。","kind":"invented_association","original":false,"weak":false},{"method":"abscond / ensconce：溜走，再藏好","textZh":"已学 abscond 是“潜逃”：男子瞒着众人离开客栈，躲到外侧墙角。把 abscond 和 ensconce 连读，重读部分听起来相近；再把画面分成两步：偷偷离开是 abscond，把自己藏到墙后是 ensconce oneself。由“逃离”转向“藏好”，记住本页的隐藏义。这是近音联想，不是同根词分析。","kind":"invented_association","original":false,"weak":false}]},"6020":{"word":"episodic","mnemonics":[{"method":"episode 一集一集，不是一直不停","textZh":"episode 是电视剧的一集，也是一段事件。把 episode 的词尾 e 换成 -ic，得到 episodic：像一集结束后有间隔，不是一条不间断的长片。由“分成一段段发生”，记住本页的间歇义；它不保证像电视排期那样定时。","kind":"word_family","original":false,"weak":false},{"method":"episodic / periodic：偶发不等于定期","textZh":"把这两个都以 -odic 结尾的时间词并排看：periodic 是“定期的”，如按时检修；episodic 则是一阵出现、一阵停，间隔不固定。用“定期表能排好，偶发却排不准”的对照，分清 episodic 的不连续、不规则。","kind":"whole_word_contrast","original":false,"weak":true}]},"6021":{"word":"entice","mnemonics":[{"method":"entice 与 mice 押韵：用饵引鼠","textZh":"entice 的重读结尾与 mice（老鼠的复数）押韵。想象用香食作饵，老鼠因为想吃而主动走近：不是强抓它，而是用想要的东西引它过来。由 mice 的声音和诱饵动作记住 entice。","kind":"rhyme_association","original":false,"weak":false},{"method":"entice 近音“引他试”","textZh":"把 entice /ɪnˈtaɪs/ 近似听成“引他试”：拿出让人心动的好处，引他愿意试一试。不是硬逼，而是用吸引人的条件诱使行动。中文只作近音提示，不是标准读音。","kind":"chinese_sound_association","original":false,"weak":false}]},"6022":{"word":"entrap","mnemonics":[{"method":"en-trap：把人引入圈套","textZh":"trap 是陷阱、圈套，en- 在这里表示进入。把“陷阱”从地上的坑换成一套骗人的说法：先让对方相信并采取行动，再利用这件事使他陷入麻烦。en+trap 就记作把人诱进圈套。","kind":"word_family","original":false,"weak":false},{"method":"Entrapment《偷天陷阱》：先引人，再设局","textZh":"看到 entrap，接上电影名 Entrapment《偷天陷阱》。片中保险公司派调查员接近大盗，目的不是普通交友，而是用计谋将他诱捕。把“先引人靠近，再让人落入圈套”的情节带回动词：entrap 是诱人陷入不利处境，不只是把人关住。","kind":"cultural_plot_anchor","original":false,"weak":false}]},"6023":{"word":"enunciate","mnemonics":[{"method":"proNUNCIation / eNUNCIate：把音说清","textZh":"pronunciation 是“发音”，其中清楚可见的 NUNCI 也在 enunciate 中；两词的历史来源确有联系。由熟悉的“发音”记回动作 enunciate，再加上关键要求：不含糊、不吞字，让听者分辨出你说的词。","kind":"word_family","original":false,"weak":false},{"method":"enunciate：漂浮咒课上的吐字提醒","textZh":"看到 enunciate，接上《哈利·波特与魔法石》的漂浮咒课堂：弗利维教授提醒“And enunciate.”，然后念出 Wingardium Leviosa。把这个完整单词和老师“把咒语清楚念出来”的提醒绑在一起，记住 enunciate 是清晰吐字，不是只把声音喊大。","kind":"cultural_dialogue_anchor","original":false,"weak":false}]},"6024":{"word":"epic","mnemonics":[{"method":"epic 史诗：把尺度放到英雄长卷","textZh":"epic 作名词是“史诗”，讲述英雄的重大事迹；作形容词时，把这种宏大的尺度带到现实：跨越山海的征程、超出寻常的大工程。由“史诗般的规模”记住 epic 的宏大，而不是把一切事物都当成诗。","kind":"sense_extension","original":false,"weak":false},{"method":"epic 近音“一劈开”：盘古开天地","textZh":"把 epic 近似联想到“一劈开”。想起盘古开天地的神话：不是劈一小块木头，而是劈开整个混沌世界。这个熟悉画面的巨大尺度，帮你记住 epic 的“宏大、超乎寻常”；中文只是声音联想。","kind":"chinese_sound_association","original":false,"weak":false}]},"6025":{"word":"epicure","mnemonics":[{"method":"EPIC CURRY：能把咖喱讲成史诗","textZh":"把 epicure 近似联想到 epic curry。epic 是“史诗”，curry 是“咖喱”：一盘咖喱的香料层次、滋味变化，他都能细细品出，讲得像一部长诗。不是只会吃很多，而是懂得鉴赏美食的人。这里是整词近形近音联想，不是真实构词。","kind":"invented_association","original":false,"weak":false},{"method":"Epicurus → epicure：从哲学家之名记美食家","textZh":"epicure 源自 Epicurus（伊壁鸠鲁），两者字形相近。用名字关联的“享受快乐”，记到后来“懂得享受美食的人”。这是英语词义的演变；伊壁鸠鲁本人提倡简单的快乐，并不等于贪吃。","kind":"etymology","original":false,"weak":false}]},"6026":{"word":"epigram","mnemonics":[{"method":"epi-GRAM：刻在碑上的精短妙语","textZh":"这个词原来指写刻在碑石等物件上的文字：epi 表示“在……上”，gram 与“写”有关。想象把一个巧妙观察刻成短短几行，话少却让人会心一笑。由简短铭文记到今天的机智短诗、警句；不是所有碑文都叫现代意义的 epigram。","kind":"etymology","original":false,"weak":false},{"method":"EPIC + GRAM：长诗缩成一克","textZh":"epic 是篇幅宏大的史诗，gram 是“一克”。把长诗的分量缩到“一克”，只留下几句精巧有趣的话，就抓住 epigram 的短小与机智。这是两个完整词的近形联想；克这个意思不是 epigram 的真实词根。","kind":"invented_association","original":false,"weak":false}]},"6027":{"word":"epilogue","mnemonics":[{"method":"epi-LOGUE：故事讲完，再补几句","textZh":"epilogue 的历史构词是“再加上”与“说的话”。把 -logue 连到 dialogue（对话）里的“说话”，但位置放到主要故事结束以后：再交代人物后来怎样，这段补充收束的话就是尾声。这里的历史 epi 是“附加”，不是把它死记成所有词里都表示“最后”。","kind":"etymology","original":false,"weak":false},{"method":"近音“一笔落”：写到最后的尾声","textZh":"把 epilogue 的整体声音近似联想到“一笔落”：最后一笔落下前，作者补写人物后来的生活，给故事收尾。由末尾落笔的动作，记住文学作品的尾声。近音只作提示，实际发音仍看音标。","kind":"invented_association","original":false,"weak":false}]},"6028":{"word":"epithet","mnemonics":[{"method":"epi-THET：给名字贴上特点","textZh":"epithet 的历史意思是“加在上面的东西”：epi 是“在……上”，thet 来自“放置”。把一个说明特点的小标签加到本名旁，如给爱看书的人加上“小书虫”，就成为外号。记住“附加的特点称呼”，而不是正式改掉姓名。","kind":"etymology","original":false,"weak":false},{"method":"近音“爱批他”：总叫他“小懒虫”","textZh":"把 epithet 整体近似联想到“爱批他”。别人批评一个人懒，总用“小懒虫”来叫他；这句带特点的外号就是 epithet。这个声音提示借用了批评性的称呼，不代表 epithet 一定是骂人的话。","kind":"invented_association","original":false,"weak":false}]},"6029":{"word":"epitomize","mnemonics":[{"method":"epitome 加 -ize：典型变成“体现”","textZh":"先在这里认识名词 epitome：“典型、缩影”。一个人是某种品质的 epitome，换成动词 epitomize，就是他集中体现这种品质。拼写上把 epitome 末尾的 e 换为 -ize；这是词族关系。","kind":"word_family","original":false,"weak":true},{"method":"epi-TOM-ize：切下一小块，看见整体","textZh":"tom 与“切”有关，这个词的历史起点是把长篇内容剪短、保留要点。想象切开一块多层蛋糕，小小一片就展示出整个蛋糕的层次：由“一小部分集中显出整体特点”，记住 epitomize 的典型体现义。切蛋糕是帮助理解的比喻，不是说该词专用于取样或切割。","kind":"etymology","original":false,"weak":true}]},"6030":{"word":"equity","mnemonics":[{"method":"EQU- 连到 equal：不偏向任何一边","textZh":"equal 是“平等的”，equity 与它有共同的历史词根，含“平、公平”的意思。像端平一碗水，不因一方是熟人就倾斜：由平等相待记住公平。公平未必要求每次都机械地分给完全相同的数量。","kind":"etymology","original":false,"weak":false},{"method":"equity 近音“一块地”：分地不偏心","textZh":"把 equity 的整体声音近似联想到“一块地”。两家对一块地都有合理要求，负责分配的人不偏袒亲友，按同样公正的原则处理。听到“一块地”，就想起分配时的不偏不倚；近音只是提示，不是标准发音。","kind":"invented_association","original":false,"weak":false}]},"6031":{"word":"equivocate","mnemonics":[{"method":"equi-VOC-ate：一句话，两种说法","textZh":"equi 与“相同”有关，voc 与“说、声音”有关；这个词的历史起点是用同一名称表达不同意思。想象一个人故意把话说得两边都能解释，好为自己留后路。不是声音听不清，而是有意不把真实意思说明白。","kind":"etymology","original":false,"weak":false},{"method":"equivocal 的邻居答话：由答复想起说话人","textZh":"看到 equivocate，先认出已经学过的完整熟词 equivocal（模棱两可的）。想起旧页里男孩问明天来不来，邻居只说“也许来，也许不来”的答复。如果说话人故意用这种话回避明确表态，他就在 equivocate。记的是这种说话动作；含糊的证据也能叫 equivocal，却不一定有人在故意遮掩。","kind":"word_family","original":false,"weak":false}]},"6032":{"word":"esteem","mnemonics":[{"method":"esteem 连到 estimate：评价很高","textZh":"estimate 是“估计、评估”，esteem 与它同源，历史上也从评定价值发展而来。把对一个人的评价放得很高，就自然生出敬重。这里的“高评价”是理解桥梁，现代 esteem 不等于一般地估算数字。","kind":"etymology","original":false,"weak":false},{"method":"eSTEEM 近音 steam：敬上一杯热茶","textZh":"esteem 的重读部分与 steam（蒸汽）同音。想象你双手给敬重的老师奉上一杯冒着热气的茶：steam 提醒杯上的热气，esteem 提醒心里的敬意。是近音情景，不是说 esteem 由 steam 构成。","kind":"invented_association","original":false,"weak":false}]},"6033":{"word":"etch","mnemonics":[{"method":"etch 与 eat 同源：记忆里留下刻痕","textZh":"etch 与 eat（吃）有共同的词源，早期指让表面被“吃”出痕迹。把这种不易消失的刻痕移到脑海：一幕景象深深留住，时间过去仍清晰。这页要记的是像刻在心里一样的深刻印象，不是蚀刻工艺。","kind":"etymology","original":false,"weak":false},{"method":"skETCH：把一幕画进脑海","textZh":"sketch 是“素描、速写”，末尾完整包含 etch。sketch 把景象画在纸上，etch 的记忆义则像把景象画进脑海，过了很久还能清楚回想。由纸上的画联想到心里的鲜明印象；这是近形联想，不是真实构词。","kind":"invented_association","original":false,"weak":false}]},"6034":{"word":"ethics","mnemonics":[{"method":"ETH-：品性落实为做事准则","textZh":"ethics 的历史词根与“品性、习惯”有关。把品性落到做事上：诚实就不欺骗，公平就不偏袒。这些指导行为的道德准则，就是 ethics；这里先记准则本身，不是研究它们的学科。","kind":"etymology","original":false,"weak":false},{"method":"ethics 近形 epics：英雄也要守准则","textZh":"epics 是“史诗”的复数，和 ethics 的字形、声音都相近。想象史诗英雄面临选择：能靠欺骗获胜，还是守住诺言？决定哪些事该做、哪些事不能做的道德准则，就是 ethics。借英雄的选择记意思，不是说两词同源。","kind":"invented_association","original":false,"weak":false}]},"6035":{"word":"euphonious","mnemonics":[{"method":"EU + PHON：耳朵里的“优声”","textZh":"eu 表示“好”，声音也像“优”；phon 表示声音，可连到 phone（电话）里的声音。两部分合起来就是“好的声音”：风铃清亮柔和，听着舒服，便是 euphonious。这里的“好＋声音”有真实词源依据。","kind":"etymology","original":false,"weak":false},{"method":"EUPHORIA 与 EUPHONIOUS：心悦、耳悦","textZh":"已学的 euphoria 是“狂喜、强烈的幸福感”。看到近形的 euphonious，就把“心里很愉快”转到“耳朵听着舒服”：前者是人的心情，后者形容悦耳的声音。用整词的相似外形唤回“愉悦”，再用心与耳分清两个词；悦耳不等于让人狂喜。","kind":"invented_association","original":true,"weak":false}]},"6036":{"word":"evacuate","mnemonics":[{"method":"e-VACU-ate：向外撤，让险地空下来","textZh":"vacu 与“空”有关，也出现在 vacuum（真空）中；e- 在这里有“向外”的意思。把有危险的房间里的人撤到外面，房间因此空下来，就抓住 evacuate 的撤离义。重点是让人离开危险，不是把人像灰尘一样吸走。","kind":"etymology","original":false,"weak":false},{"method":"Don’t wait, evacuate!：别等，快撤！","textZh":"把 evacuate 放进一句押韵口令：“Don’t wait, evacuate!”（别等，快撤！）。wait（等待）与 evacuate 都以 /eɪt/ 收尾；收到撤离指令，就别留在危险地点等待，赶快转移到安全处。用这句真实的应急口号，把熟悉的 wait 声音与撤离动作一起记住。","kind":"phrase_anchor","original":false,"weak":false}]},"6037":{"word":"everlasting","mnemonics":[{"method":"EVER + LASTING：永远持续下去","textZh":"ever 在这里表示“永远”，lasting 来自 last 的动词义“持续”，不是“最后一个”。两部分连起来就是“永远持续的”，常用来形容不随时间结束的爱、生命或记忆。","kind":"word_components","original":false,"weak":false},{"method":"EVERLASTING 糖：永远含不完","textZh":"《查理和巧克力工厂》里，旺卡发明了名叫 Everlasting Gobstopper 的神奇硬糖：一直含着，也不会变小。把英文名字里的 everlasting 和“永远吃不完”绑定，就能记住永恒、持久的意思。这是故事里的幻想，不是现实糖果的性质；不必另背后面的糖果名称。","kind":"phrase_anchor","original":false,"weak":false}]},"6038":{"word":"evict","mnemonics":[{"method":"e-VICT：胜过占用者，把人赶出去","textZh":"vict 与 victory（胜利）同族，e- 有“向外”的意思。这个词曾指通过法律程序夺回财产：一方取得优势，另一方被迫搬出。由“胜过对方，迫使出去”记 evict；现代也可泛指强制赶出，不一定涉及诉讼。","kind":"etymology","original":false,"weak":false},{"method":"EVICT / EJECT：从里面强制出去","textZh":"把近形的 evict 和 eject（弹出、赶出）配着记：eject 像按下弹出键，把里面的东西推出；evict 则常把占用房屋的人赶出去。一个熟悉的“弹出”动作，帮助记住强制向外的方向；evict 不要求真把人抛出去。","kind":"invented_association","original":false,"weak":false}]},"6039":{"word":"evince","mnemonics":[{"method":"EVINCE / EVIDENCE：给心情留下证据","textZh":"evidence 是“证据”。看到近形的 evince，就想到内心也能留下外在证据：一看到新书便两眼发亮，这个神情清楚表明兴趣。由“看得出的证据”记“明显表现出”；这是近形联想，不是把 evidence 直接变成动词。","kind":"invented_association","original":false,"weak":false},{"method":"eVINCE / conVINCE：先表现，再说服","textZh":"convince 是“说服，使信服”，和 evince 有共同的词源。把两个词连成一个短动作：清楚表现出（evince）自己的诚意，才可能说服（convince）别人。前者让态度显出来，后者让人相信；记联系，也记住它们不能直接互换。","kind":"word_family","original":false,"weak":false}]},"6040":{"word":"evoke","mnemonics":[{"method":"e-VOKE：把回忆“喊出来”","textZh":"e- 有“向外”的意思，voke 来自表示“呼唤”的词根。把一首旧歌想成呼唤声：本来沉在脑海里的童年回忆，被它喊了出来。这就是 evoke 的“唤起”；不要求真的有人大声叫喊。","kind":"etymology","original":false,"weak":false},{"method":"EVOKE / WOKE：沉睡的回忆醒了","textZh":"woke 是 wake（唤醒）的过去式，和 evoke 的后半段音形相近。看到 evoke，就想起 woke：旧照片让沉睡的回忆醒过来，于是记住“唤起回忆”。这是近形、近音联想，不是说 evoke 由 woke 变化而来。","kind":"invented_association","original":false,"weak":false}]},"6041":{"word":"excavate","mnemonics":[{"method":"EX + CAV：往外挖出空洞","textZh":"cav 与 cave（洞穴）同源，表示“空、洞”；ex- 表示“向外”。想象把泥土一铲铲向外挖，原处便留下空洞：由“挖出一个洞”记 excavate 的挖掘、挖空。","kind":"etymology","original":false,"weak":false},{"method":"EXCAVATE：X，可挖土","textZh":"把 excavate 的整段声音近似联想到“X，可挖土”：地上画着 X，铲子就在标记处往下挖，把土铲到一旁。由这句带 X 的挖土口令记住“挖掘”；末段只是近音，不是准确发音。","kind":"invented_association","original":true,"weak":true}]},"6042":{"word":"excrete","mnemonics":[{"method":"EX + CRETE：筛出来，排出去","textZh":"ex- 表示“向外”，crete 的词源与“筛出、分离”有关。把身体想成在做一次筛除：从体内分离出需要排走的物质，再送到体外。这个“筛出并排走”的动作，就帮助记住 excrete。","kind":"etymology","original":false,"weak":false},{"method":"EXCRETE / SECRETE：排废物，分泌供用","textZh":"把音形相近的 excrete 和 secrete（分泌）成对记：唾液腺分泌唾液供消化，是 secrete；肾把尿素随尿液排走，是 excrete。一个看“产生并释放”，一个看“把不需要的物质排走”。这是典型功能的对比，不是说所有分泌物都不是废物。","kind":"word_family","original":false,"weak":false}]},"6043":{"word":"excruciate","mnemonics":[{"method":"ex-CRUCI-ate：十字架上的剧痛","textZh":"cruci 的词源与十字架、钉十字架有关。由这种残酷刑罚所造成的剧痛，记住 excruciate 是“使人极度痛苦、折磨”。现代用法不必有刑罚，持续的牙痛、背痛也能这样折磨人。","kind":"etymology","original":false,"weak":false},{"method":"exCRUciate / CRUEL：残酷地折磨","textZh":"看到 excruciate 中显眼的 cru，就联想 cruel（残酷的）：残酷的手段使人遭受剧痛，便能记住“折磨、使极痛苦”。这里借整个熟词 cruel 的音形和意思搭桥，不是把两词说成同一个词根；现代的痛苦来源也不一定是人。","kind":"invented_association","original":true,"weak":false}]},"6044":{"word":"excursive","mnemonics":[{"method":"EX + CURS：思想跑到题外","textZh":"ex- 有“向外”的意思，curs 的词源与“跑”有关。把主题想成跑道：讲的人不沿主线走，思想一路跑到外面去了。由“思想跑出去”记 excursive 的离题、散漫。","kind":"etymology","original":false,"weak":false},{"method":"EXCURSIVE / DISCURSIVE：又从书扯到午饭","textZh":"已学的 discursive 那页，本来讲一本书，却扯到午饭，又转到动物。看到尾部同为 -cursive 的 excursive，就唤回这整段“越说越偏题”的场景；两词在离题义上相近。这里借熟悉的整词和故事检索，不需要再拆一遍词根。","kind":"word_family","original":false,"weak":false}]},"6045":{"word":"exempt","mnemonics":[{"method":"EX + EMPT：从义务名单中拿出来","textZh":"ex- 表示“向外”，empt 的词源与“拿、取”有关。想象把某人的名字从必须服役的名单中拿出来：别人仍要履行义务，他获准不用做了。由“取出名单”记 exempt 的“使免除”。","kind":"etymology","original":false,"weak":false},{"method":"exEMPT / EMPTY：免考，座位空着","textZh":"exempt 的后半段 EMPT 很像 empty（空的）。想象学校批准一名学生免考，考场里原本留给他的座位便空着：不是逃考，而是学校 exempt 了他。用“获准免考，所以座位空着”记住免除义务；empty 只是近形联想，不是词根。","kind":"invented_association","original":false,"weak":false}]},"6046":{"word":"exhaust","mnemonics":[{"method":"EX + HAUST：连最后一滴也抽干","textZh":"ex- 表示“向外”，haust 的词源与“汲水、抽干”有关。想象水泵不停往外抽水，直到桶底连最后一滴也没有。由“彻底抽干”记 exhaust：水、经费等储备被用得一点不剩。","kind":"etymology","original":false,"weak":false},{"method":"EXHAUST / EXORBITANT：贵到花光储蓄","textZh":"exhaust 和已学的 exorbitant，前半段都有接近 /ɪɡˈzɔː/ 的声音。想起 exorbitant 那颗开价一百元的普通苹果，再想象自己真按这种离谱价买了一篮，钱袋被花空了。用“离谱价把储蓄花光”接到 exhaust 的“耗尽”；两词只是近音联系，不是同一个词根。","kind":"invented_association","original":true,"weak":true}]},"6047":{"word":"exhort","mnemonics":[{"method":"exHORT / HORTATORY：再劝朋友动手","textZh":"已学的 hortatory 是“劝勉的”：男孩鼓励没精神的朋友一起收拾花园，朋友拿稳耙子准备行动。看到 exhort 中的 HORT，就把这整段劝人动手的故事唤回来：话语是 hortatory，说这番话来力劝对方，就是 exhort。","kind":"word_family","original":false,"weak":false},{"method":"EXERT / EXHORT：自己用力，力劝别人","textZh":"exert 是“用力、施加力量”，和 exhort 音形相近。推大石头的人 exert 力气；在旁认真鼓励“别放弃，再使把劲”的人 exhort 同伴。把“自己用力”和“力劝别人行动”并排记，不把 exhort 误写成 exert。","kind":"invented_association","original":false,"weak":false}]},"6048":{"word":"exodus","mnemonics":[{"method":"EX + OD：一群人走上出城路","textZh":"ex- 表示“向外”，od 来自表示“道路”的希腊词。把一整群人沿着出城道路离开的画面串起来：不是一个人出门，而是大批人一起离去，这就是 exodus。","kind":"etymology","original":false,"weak":false},{"method":"Exodus《出埃及记》：整群人离开","textZh":"Exodus 是《出埃及记》的英文书名，书中讲述以色列人离开埃及的故事。把完整的书名与“整群人离开一地”绑定：小写 exodus 就能泛指大批离去，不限于书中的宗教故事。","kind":"phrase_anchor","original":false,"weak":false}]},"6049":{"word":"exotic","mnemonics":[{"method":"EXO：从外面来的新奇东西","textZh":"exotic 的词源中，exo 表示“外面”。想象本地花圃里来了一株远方的花，花形与常见品种不同，格外新奇。由“来自外面、不同寻常”记 exotic；不必把词尾硬拆成另一个故事。","kind":"etymology","original":false,"weak":false},{"method":"Exotic：名字就叫“新奇”的圆脸猫","textZh":"有个真实猫品种就叫 Exotic：圆脑袋、圆眼睛，披着浓密的短毛。早期这类猫的银色等毛色在短毛猫中很新奇，因此得了这个名字。看到完整的 Exotic，就想起这只模样新奇的圆脸猫，抓住“不同寻常”的意思。","kind":"phrase_anchor","original":false,"weak":false}]},"6050":{"word":"expansive","mnemonics":[{"method":"EXPAND：话匣子一打开，越聊越多","textZh":"把 expansive 和 expand（展开、扩展）联在一起：朋友高兴地打开话匣子，从一句问候展开成许多有趣细节。话题越聊越丰富，人也显得开朗健谈，就是 expansive；这里不是说人的身体变大。","kind":"word_family","original":false,"weak":false},{"method":"expAnsive / expEnsive：表很贵，人很健谈","textZh":"expensive 是“昂贵的”，与 expansive 只差中间的 a、e。想象导购拿出一只昂贵的表，笑着细讲它的工艺和来历，越说越起劲：表很 expensive，导购很 expansive。用“东西贵，介绍它的人健谈”同时钩住两个近形词，不把健谈误记成昂贵。","kind":"invented_association","original":false,"weak":false}]},"6051":{"word":"expedite","mnemonics":[{"method":"EX + PED：解开绊脚绳，事情快起来","textZh":"ex- 表示“向外”，ped 的词源义是“脚”；expedite 的来历涉及把脚从束缚中解脱出来。想象解开脚上的绳结，人便能顺利往前赶。由“解除阻碍，走得更快”记 expedite：帮助事情加快完成。","kind":"etymology","original":false,"weak":false},{"method":"EXPEDITE：今天就办，不拖到明天","textZh":"传统中有一位名为 Saint Expedite 的圣人形象：面对叫着“明天”的乌鸦，他举着写有“今天”的十字架。名字就是完整的 Expedite，画面提醒“别拖，今天就推进”，帮助记住加快进程。这是传统传说，历史真实性未定，不必另背人物生平或拉丁语。","kind":"phrase_anchor","original":false,"weak":false}]},"6052":{"word":"expiate","mnemonics":[{"method":"EXPIATE 的 PI：虔诚认错，行动补过","textZh":"expiate 的词源与 pious（虔诚的）相连。抓住 PI 的“虔诚”联系：一个犯错的人认真忏悔，又亲自弥补造成的伤害。他不只是嘴上认错，而是在 expiate，为过失赎罪。这个来历带有宗教背景，现代用法不只限于宗教。","kind":"etymology","original":false,"weak":false},{"method":"EXPIATE / EX-PIRATE：前海盗来赎罪","textZh":"pirate 是海盗，ex-pirate 就是从前的海盗。把 expiate 近形联想到 ex-pirate：想象一个改过的海盗带回赃物，赔偿自己伤害过的人，为过去的罪行赎过。两者拼写很像，但 pirate 多一个 r，读音也不同；这不是词源拆分。","kind":"invented_association","original":false,"weak":false}]},"6053":{"word":"expire","mnemonics":[{"method":"EX + SPIR：最后一口气呼出","textZh":"ex- 表示“向外”，spir 的词源义是“呼吸”。把 expire 连到“呼出人生最后一口气”：不是日常吸气呼气，而是生命已经结束。由“最后的呼气”记死亡、断气。","kind":"etymology","original":false,"weak":false},{"method":"exPIRE / vamPIRE：吸血鬼夺走生命","textZh":"vampire 是故事里的吸血鬼，它与 expire 都有 PIRE，末尾也有相近的 /paɪə/ 声音。想象故事里的吸血鬼夺走了受害者的生命，对方 expired。借“吸血鬼夺走生命”的情节锁定死亡义；两词不是同源词。","kind":"invented_association","original":true,"weak":false}]},"6054":{"word":"exponent","mnemonics":[{"method":"EX + PON：把主张摆出来","textZh":"ex- 表示“向外”，pon 的词源义是“放置”。想象一个人把自己的主张摆到大家面前，认真讲解理由并争取支持：不是默默同意，而是积极倡导。这个把主张“摆出来讲”的人，就是 exponent。","kind":"etymology","original":false,"weak":false},{"method":"EXPONENT / OPPONENT：倡导与反对","textZh":"opponent 可以指反对者，与 exponent 都有醒目的 PONENT，后半读音也很接近。把辩论两边并排记：exponent 为主张发声、争取支持，opponent 提出反对理由。一个积极倡导，一个明确反对，整词对照能帮助记住 exponent 的站位。","kind":"invented_association","original":false,"weak":false}]},"6055":{"word":"exquisite","mnemonics":[{"method":"EXQUISITE：精挑出来的好作品","textZh":"exquisite 的词源有“寻求、挑选出来”的意思。想象你在一排瓷器中仔细挑选，最后看中一只线条优雅、花纹细腻的小碗：它不是随便做成的，而是值得精挑出来的精美作品。由“精挑的佳作”记精致精巧。","kind":"etymology","original":false,"weak":false},{"method":"EXQUISITE / SQUEEZE IT：这么精美，别捏坏","textZh":"把 exquisite 中 /skwɪzɪt/ 的声音近似联到 squeeze it（捏它）。眼前是一朵做工细腻的糖花，花瓣薄而优美，你赶紧提醒“别用力捏，太精巧了！”用这件精美小物钩住 exquisite；近音不等于同音，词义也不是单纯“易碎”。","kind":"invented_association","original":false,"weak":false}]},"6056":{"word":"extant","mnemonics":[{"method":"EXTANT / STAND：历经岁月，仍然站着","textZh":"extant 的词源与 stand（站立）相连，原来有“站在外面、显现出来”的意思。想象旧城其他建筑已经倒塌，一座古石门仍站在那里，保存到了今天。抓住“仍站着、仍存在”来记 extant；它也能形容并不会站立的古书、记录。","kind":"etymology","original":false,"weak":false},{"method":"extAnt / extEnt：还在不在，范围多大","textZh":"extant 与 extent（范围、程度）只差中间的 a、e。考古学家找到一段现存的古墙，再测量它延伸的范围：extant 回答“古墙还在不在”，extent 回答“范围有多大”。把“保存下来的实物”与“量出的范围”并排记，不把现存误记成范围。","kind":"invented_association","original":false,"weak":false}]},"6057":{"word":"extemporize","mnemonics":[{"method":"EX TEMPORE：就着眼前这一刻来发挥","textZh":"extemporize 来自表示“当场、临时起意”的拉丁短语 ex tempore，再加动词结尾 -ize。抓住 TEMPOR 的“时间”联系：现在就轮到你，没有提前写好的词句，只能根据这一刻的情境开口编讲。由“就着当下发挥”记即兴，不把 ex- 硬译成否定词。","kind":"etymology","original":false,"weak":false},{"method":"EXTEMPORIZE / MEMORIZE：现编，不是背稿","textZh":"memorize 是记牢、背下来，与 extemporize 都以 ORIZE 结尾，尾部声音也相近。把两种发言并排想：一种先背好稿子再复述，另一种遇到临时话题，现场组织新词句。不是照背 memorize 的稿子，而是当场 extemporize，即兴发挥。","kind":"phrase_anchor","original":false,"weak":true}]},"6058":{"word":"extinct","mnemonics":[{"method":"EXTINCT / EXTINGUISH：生命之火全熄灭","textZh":"extinct 与 extinguish（熄灭）同源，开头也很相近。把一个物种比作许多盏生命小灯：最后一盏也熄灭，再没有任何活着的个体，这个物种就是 extinct。灯火是比喻，不是说灭绝必须由火灾造成，也不是一只动物死去就算整个物种灭绝。","kind":"word_family","original":false,"weak":false},{"method":"EXTINCT / EXTANT：一个已绝，一个尚存","textZh":"把近形词 extinct 和 extant（现存的）成对记：仍有活鸟的物种是 extant，只剩模型、没有任何活体的渡渡鸟物种是 extinct。两词外形接近，意义却相反；抓住“现存与灭绝”的对照，别因博物馆里有模型就说物种还活着。","kind":"invented_association","original":false,"weak":false}]},"6059":{"word":"extort","mnemonics":[{"method":"EX + TORT：把不肯给的钱硬拧出来","textZh":"extort 的词源由“向外”与“扭、拧”相连，原义像把东西强行拧出来。想象一只紧闭的钱袋，对方不愿给，勒索者却用威胁把钱“逼出来”。由“非自愿地逼取”记勒索，不把普通索要或自愿付款混进来。","kind":"etymology","original":false,"weak":false},{"method":"exHort / exTort：劝你给，逼你给","textZh":"exhort 是力劝，extort 是勒索，两词只差中间的 h、t。想象两个人要钱：一人恳切劝你自愿捐助，是 exhort；另一人威胁不给就伤害你，逼取钱财，是 extort。把“劝人自愿做”与“威胁逼取”并排记，不能因为都很强硬就混为一谈。","kind":"invented_association","original":false,"weak":false}]},"6060":{"word":"extract","mnemonics":[{"method":"EX + TRACT：向外拉出来","textZh":"extract 的词源中，ex- 表示“向外”，tract 与“拉、牵引”相连。想象一根钉子牢牢嵌在木板里，你用工具把它向外拉，直到钉子离开木板。抓住“向外拉出”来记 extract，不只是碰一下或把表面擦干净。","kind":"etymology","original":false,"weak":false},{"method":"EXTRACT / EXTRICATE：拔出，还是解救","textZh":"把近形的 extract 与 extricate（使脱离困境或缠绕）并排记：牙医把嵌在牙床里的牙拔出来，突出“取出”，用 extract；救援者解开缠住人的绳索，突出“让人脱困”，用 extricate。两个词都可能涉及移出，但本页 extract 要抓住用力拔出，不是泛指所有解救。","kind":"invented_association","original":false,"weak":false}]},"6061":{"word":"encyclopedic","mnemonics":[{"method":"ENCYCLOPEDIA：像一部活百科","textZh":"encyclopedia 是百科全书，encyclopedic 是由它形成的形容词。想象身边有位“活百科”：问星星、动物或古代城市，他都能讲出丰富知识。看到几乎完整保留的 encyclopedia 词形，就想到百科全书般广泛全面，不是只会背一条孤零零的知识。","kind":"word_family","original":false,"weak":false},{"method":"ENCYCLOPEDIC / PEDANTIC：博学，不是抠细节","textZh":"把 encyclopedic 与已学的 pedantic（学究气、过分拘泥细节）作近形对照，两词都有 PED…IC 的轮廓。回想 pedantic 里只顾纠正恐龙玩具一个小尖角的男孩；若他能从恐龙讲到星空和古代城市，展现的则是 encyclopedic 的广博知识。前者批评对细节过分较真，后者强调知识全面；博学的人不一定迂腐。","kind":"invented_association","original":true,"weak":false}]},"6062":{"word":"extricate","mnemonics":[{"method":"EX + TRIC：从纠缠中解出来","textZh":"extricate 的词源把“向外”与“麻烦、纠缠”连在一起。想象一根绳子绕住脚踝，你先把缠结理开，再让脚顺利出来。不是只往外使劲，而是解除束缚，使人脱困，这就是 extricate。","kind":"etymology","original":false,"weak":false},{"method":"exTRICate / TRICK：脱身戏法","textZh":"看到 extricate 中的 TRIC，近音想到 trick（戏法）。想象舞台上被绳索缠住的魔术师，做完一个脱身戏法，双手终于自由了。由“trick 帮他脱身”记 extricate；这是声音联想，不是说这个词必定涉及魔术或欺骗。","kind":"invented_association","original":false,"weak":false}]},"6063":{"word":"exude","mnemonics":[{"method":"EXUDE：汗从里面冒出来","textZh":"exude 来自拉丁语“向外出汗”的说法，ex- 是向外，后面的来源表示出汗。想象跑步后，额头的汗珠一点点冒出来：液体不是从外面倒上去，而是从里面缓缓渗出。抓住“像出汗那样往外渗”来记 exude。","kind":"etymology","original":false,"weak":false},{"method":"EXUDE / EXCLUDE：渗出，不是挡在外面","textZh":"exude 与 exclude（排除、不让进入）开头结尾相似，容易看混。把两个方向并排想：雨衣把外面的雨挡住，是 exclude；皮肤却把里面的汗慢慢渗出来，是 exude。看清“阻止外物进入”和“自身液体向外渗出”的区别，不把 exude 记成排除。","kind":"invented_association","original":false,"weak":false}]},"6064":{"word":"exult","mnemonics":[{"method":"EXULT：开心得要跳起来","textZh":"exult 的词源有“向上跳起”的意思。想象得知自己获胜，你高兴得一下子跳起来，满心喜悦。用“喜得跳起来”记 exult；现代词义是强烈欢喜，安静地欣喜也可以，不要求真的跳跃。","kind":"etymology","original":false,"weak":false},{"method":"exULT / exALT：自己欢喜，别人赞扬","textZh":"exult 与 exalt（高度赞扬）只差 u、a，读音也相近但并不相同。比赛结束，观众高度赞扬冠军，是 exalt；冠军自己为胜利满心欢喜，是 exult。把赞扬的动作和欢喜的感受分清，不能把“我欢欣”误写成“我赞扬”。","kind":"invented_association","original":false,"weak":false}]},"6065":{"word":"fable","mnemonics":[{"method":"fable / “飞吧”的传说","textZh":"把 fable 的声音近似联到“飞吧”：故事里的马听见“飞吧”，便长出翅膀飞上月亮。现实中的马做不到，这是神话传说。近音只帮你想起画面，发音仍记 /ˈfeɪbəl/。","original":true,"kind":"invented_association","weak":false},{"method":"FABulous 的世界，FABLE 的故事","textZh":"fabulous 常用来夸“棒极了”，还保留“传说中的、难以置信的”意思，和 fable 同源。抓住两词共有的 fab：fabulous 的飞龙不是普通动物，而是生活在 fable 里的神话生灵。由“神奇得像传说”的形容词，倒推“神话传说”的名词。","original":false,"kind":"word_family","weak":false}]},"6066":{"word":"fabricate","mnemonics":[{"method":"FABRIC 编成布，fabricate 编成谎","textZh":"fabric 是“布料”。把编谎想成织布：把假的时间、人物和经过一条条织进说法里，编出一整套似乎可信的故事。由“编织布料”联到“编造谎言”，记 fabricate。","original":false,"kind":"invented_association","weak":false},{"method":"FABRIC＋ATE：我把布吃了","textZh":"在 fabricate 中直接看见 fabric（布）和 ate（吃了）。布料不见了，他竟编出“我把布吃了”这种荒唐借口来搪塞：说出自己明知不真的解释，就是 fabricate。这里是拼写联想，不是词源拆分。","original":false,"kind":"invented_association","weak":false}]},"6067":{"word":"facetious","mnemonics":[{"method":"FACE 不 serious","textZh":"在 facetious 开头认出 face（脸），联想本该 serious（严肃）时，脸上却还挂着嬉笑。别人认真处理漏水，他偏说“家里开鱼塘了”：不看场合地逗趣，就是 facetious。这是拼写联想，不能按 face 来读整个词。","original":false,"kind":"invented_association","weak":false},{"method":"facetia：把玩笑开错场合","textZh":"facetious 经法语追溯到拉丁语 facetia，意为“玩笑”。把这一整段词形和“玩笑”绑定：眼前是严肃问题，说出口的却是逗趣的话。由“玩笑闯进严肃场合”，记它现在常带批评意味。","original":false,"kind":"etymology","weak":true}]},"6068":{"word":"faction","mnemonics":[{"method":"FRACTION 少个 r，FACTION","textZh":"fraction 是“部分、分数”；faction 的拼写比它少一个 r。想象一个大党分成几块，其中一小块成员抱团，坚持自己的主张并反对其他人：团体中的这一“部分”就成了一个派系。","original":false,"kind":"invented_association","weak":false},{"method":"fACTION：党内一起 ACTION 的人","textZh":"在 faction 里直接看见 action（行动）。大党内部几个人私下商量、一起投票，专门推动自己的主张，甚至与其他成员唱反调。这一拨总一起 action 的人，不是整个党，而是党内的一派 faction。这里借完整熟词作拼写联想，不把 f- 当作前缀。","original":false,"kind":"invented_association","weak":false}]},"6069":{"word":"fail-safe","mnemonics":[{"method":"FAIL 了，还能 SAFE","textZh":"fail 是“失效”，safe 是“安全”。主绳已经 fail，下面的安全网却让布袋仍然 safe。把“失效后仍能保安全的东西”合起来记，就是名词 fail-safe，故障保护装置。","original":false,"kind":"word_components","weak":false},{"method":"feel safe，要有 fail-safe","textZh":"把 fail-safe 近音联到 feel safe（感到安全）。老师不只说“放心”，还指给你看已经装好的承接网；看到失手后也真有东西兜底，你才 feel safe。让安全感有实际保障的那道保险，就是 fail-safe。","original":true,"kind":"invented_association","weak":false}]},"6070":{"word":"falsehood","mnemonics":[{"method":"FALSE 加 -hood，把“假”变成名词","textZh":"false 是“假的”；-hood 可以把性质或状态变成名词。把一句话判断为 false，就抓住了 falsehood 的“虚假”；当它指一条用来骗人的假话时，就是“谎言”。","original":false,"kind":"word_components","weak":false},{"method":"falseHOOD：小红帽遇上假外婆","textZh":"小红帽的英文名是 Little Red Riding Hood。想起故事中狼冒充外婆，对小红帽说“我是你外婆”：明明是狼，却把假话当真话说给她听。借词尾 HOOD 唤起这句谎，记 falsehood；这里是故事联想，不是词源。","original":true,"kind":"invented_association","weak":false}]},"6071":{"word":"falter","mnemonics":[{"method":"FALTER，像要 FALL 下去","textZh":"falter 的开头读音让人想到 fall（跌倒）。想象腿已经累软，走一步晃一下，仿佛随时要 fall，却还没有真正倒下。用“将倒未倒、脚步不稳”的画面记 falter，不把它等同于已经摔倒。","original":false,"kind":"invented_association","weak":false},{"method":"fALTER：走一步，就得 ALTER 重心","textZh":"在 falter 里完整看见 alter（改变）。腿发软的人向前走，身体向左歪，就得往右补；下一步又失去平衡，再 alter 重心。这种不断被迫调整、无法稳稳前进的步态，就是 falter。这里借拼写联想，不是词根分析。","original":false,"kind":"invented_association","weak":false}]},"6072":{"word":"fanatic","mnemonics":[{"method":"FAN 的热情，fanatic 的狂热","textZh":"fan 是“迷、爱好者”，一般认为是 fanatic 的缩略形式。用这个熟词反向找回长词：普通 fan 很喜欢自己的队，fanatic 却可能连清楚的败局都不肯承认。把“喜欢”推到不讲道理的狂热，就抓住本页主记的词义。","original":false,"kind":"word_family","weak":false},{"method":"fanatic / 疯拿铁，迷到失去分寸","textZh":"把 fanatic 的声音近似联到“疯拿铁”：拿铁给出迷恋的对象，“疯”直接提醒你，这不是普通喜欢，而是热衷过头、迷到失去分寸。由这种狂热记 fanatic；谈咖啡爱好时可略带调侃，谈不容质疑的信念时则常有贬义。","original":false,"kind":"invented_association","weak":false}]},"6073":{"word":"fantasy","mnemonics":[{"method":"FANTASTIC 的生灵，FANTASY 的世界","textZh":"fantastic 除了常见的“极好的”，也能形容只存在于想象中的事物，和 fantasy 同源。把那头驮着城堡飞行的鲸鱼想成 fantastic 的生灵：它不是现实动物，而属于 fantasy，幻想故事。","original":false,"kind":"word_family","weak":false},{"method":"《范特西》／Fantasy，把声音连到幻想","textZh":"周杰伦专辑《范特西》的英文名就是 Fantasy。“范特西”取自整词发音，专辑概念也围绕天马行空的音乐想象。即使没听过这张专辑，也可以用这组现成的中英文名称，把整词声音直接连到“幻想”，再记由想象创造的幻想故事。","original":false,"kind":"invented_association","weak":false}]},"6074":{"word":"farce","mnemonics":[{"method":"FORCE 出来的结果，成了 FARCE","textZh":"farce 与 force（强迫）只差一个元音。会场明明挂着“自由表决”的名义，主持人却 force 大家接受早已定好的结果：有投票的形式，没有选择的实质，这场表决就成了 farce。这里只借近形联想。","original":false,"kind":"invented_association","weak":false},{"method":"FARCE：只顾 FACE，办成面子工程","textZh":"看到 farce，联到 face（脸面、外表）：为了门面好看，验收会办得隆重，验收对象却根本不能用，仍被宣布为“圆满成功”。只剩体面外观，没有实际检验，这场验收就成了 farce。记的是整场程序虚有其表，不是把一般爱面子都叫作闹剧。","original":false,"kind":"invented_association","weak":false}]},"6075":{"word":"fast","mnemonics":[{"method":"breakFAST：早餐结束了什么？","textZh":"breakfast 是“早餐”，其中的 break 是“打破、结束”，fast 则是“不进食”。睡了一夜没有吃东西，早晨第一餐把这段 fast 结束了。由熟悉的早餐，倒推 fast 的“禁食、斋戒”义；这里不是“吃得快”。","original":false,"kind":"word_family","weak":false},{"method":"FASTen 系牢，FAST 朋友不离开","textZh":"fasten 是“系牢、扣紧”，里面完整保留 fast。把忠诚的关系想成扣牢的安全带：遇到颠簸也不会突然松开。一个 fast friend 同样在你遇到困难时仍紧紧相随。此法专记形容词“忠诚的”，不解释斋戒义。","original":false,"kind":"word_family","weak":false}]},"6076":{"word":"fateful","mnemonics":[{"method":"FATE＋ful：一件事改变命运","textZh":"fate 是“命运”，-ful 使它成为形容词。想象人生像一条路，一次决定把后面整条路改了方向：这不是小事，而是影响命运的 fateful decision。抓住 fate，就能记住“有决定性后果的”。","original":false,"kind":"word_components","weak":false},{"method":"FATEFUL 的相遇，FAITHFUL 的朋友","textZh":"把近形近音的 faithful（忠实的）与 fateful 成对记：相识后，一位 faithful friend 多年不离不弃；回头看，改变人生的那次相遇就是 a fateful meeting。前者评价朋友忠不忠实，后者评价事件影响有多大。fateful 读 /t/，faithful 读 /θ/，并不同音。","original":false,"kind":"invented_association","weak":false}]},"6077":{"word":"fatuous","mnemonics":[{"method":"FATUOUS，近音“发蠢”","textZh":"把 fatuous 开头的 /fætʃu/ 近音联到“发蠢”：筛盆明明在漏水，他却得意地说“这个更会装水！”蠢办法摆在眼前，自己还觉得高明，就是 fatuous。近音只作提取线索，完整发音仍记 /ˈfætʃuəs/。","original":true,"kind":"invented_association","weak":false},{"method":"inFATUated：迷恋得犯傻","textZh":"infatuated 是“迷恋得失去清醒判断”，其中 fatu 与 fatuous 同源。想象一个人迷上偶像，对方随口一句话，他便当成绝对真理，连明显错误也看不见。把这种“脑子不清醒、判断变傻”的状态提取出来，记 fatuous；它本身不限于恋爱或追星。","original":false,"kind":"word_family","weak":false}]},"6078":{"word":"faultfinder","mnemonics":[{"method":"FAULT＋FINDER：专找毛病的人","textZh":"fault 是“毛病、缺点”，finder 是“寻找者”。把 faultfinder 想成拿着放大镜只找细小瑕疵的人：漂亮房子看不到，眼里只有一点歪斜，还总要挑出来说。整个词就是“专爱找毛病的人”，不是普通的检修人员。","original":false,"kind":"word_components","weak":false},{"method":"FAULTFINDER 的口头禅：your fault","textZh":"your fault 是“你的错”。想起那种动不动就说“你的错”的人：东西已经改好了，他还会换个细节继续责怪。让这句熟悉的抱怨声帮助你记住 faultfinder 不是偶尔指出错误，而是习惯性挑剔的人。","original":true,"kind":"phrase_anchor","weak":true}]},"6079":{"word":"fawn","mnemonics":[{"method":"FAWN，近音“逢”：逢迎讨好","textZh":"把 fawn 的声音近似联到“逢迎”的“逢”。对方说什么都点头，做什么都夸赞，为的是换来关照和好处；这种刻意顺着别人、过分奉承的行为就是 fawn。是近音提取，不把它读成汉语的 féng。","original":false,"kind":"invented_association","weak":false},{"method":"FAN 围着偶像，FAWN 过头讨好","textZh":"把 fawn 与近形的 fan（粉丝）联在一起。普通 fan 欣赏作品；若有人一见名人就堆满夸赞、不断献殷勤，只求对方多看自己一眼，便是在 fawn over the star。用“粉丝式关注过了头”记奉承义，不是说所有粉丝都谄媚。","original":false,"kind":"invented_association","weak":false}]},"6080":{"word":"faze","mnemonics":[{"method":"FACE 变了，原来被 FAZE 了","textZh":"face 是“脸”，读 /feɪs/；faze 读 /feɪz/，只在末尾清浊音上不同。想象本来神色从容的人，突然被当众追问，脸上的笑容僵住，连话也接不上。由 face 上看得见的慌乱，记 faze“使人失去镇定”。这是近音联想，不是词源。","original":false,"kind":"invented_association","weak":false},{"method":"DAZE 发蒙，FAZE 发慌","textZh":"daze 是“使发蒙、使恍惚”，和 faze 押韵，拼写也很近。被突发情况弄得 dazed，脑子一时转不过来；被它 fazed，则是镇定被打乱、心里没了底。把这一对近音的精神状态并排记：faze 不必严重到眩晕，只要让人慌了神。","original":false,"kind":"invented_association","weak":false}]},"6081":{"word":"fecund","mnemonics":[{"method":"FECUND，近音“肥垦地”","textZh":"把 fecund 的声音近似联到“肥垦地”：一片肥沃的开垦地，作物结得多，采下一篮，枝头仍硕果累累。抓住“肥沃，所以产出丰盛”这条因果，记 fecund。只是近音提示，不把词尾 -d 读成完整的“地”。","original":false,"kind":"invented_association","weak":false},{"method":"FEMALE 的生育线索，FECUND 的多产","textZh":"female 是“雌性的”，它与 fecund 都能追溯到有关哺育、产出的同源线索。想象一只 female rabbit（母兔）身边围着许多幼兔：female 只说它是雌性；fecund 才说它繁殖旺盛、后代多。借熟悉的 female 开头与生育画面提取“多产”，再扩展到土地多产、头脑多创意。","original":false,"kind":"word_family","weak":false}]},"6082":{"word":"foreshadow","mnemonics":[{"method":"FORE＋SHADOW：人未到，影先到","textZh":"fore- 表示“预先”，shadow 是“影子”。门外的人还没有走进来，长长的影子先落到地板上，让你提前察觉有人将到。事情发生前先露出一个“影子”，就是 foreshadow：以先出现的迹象预示后来的事。","original":false,"kind":"word_components","weak":false},{"method":"FORECAST 作预报，FORESHADOW 露征兆","textZh":"weather forecast 是“天气预报”：气象员根据资料告诉你将有雨。把这个熟悉的整体表达与 foreshadow 对照：气象员作 forecast，天边的乌云则 foreshadow 大雨。两者都朝向未来，但后者让“眼前迹象”替未来结果先开口。借整词对照，记“预示”，而不是正式宣布结果。","original":true,"kind":"invented_association","weak":false}]},"6083":{"word":"feral","mnemonics":[{"method":"FIERCE 的野兽气息，FERAL 的野生状态","textZh":"fierce 是“凶猛的”，与 feral 同源，都与“野兽、野性”的词源线索有关。借 fierce 的野兽形象找到 feral，再把重点从“凶不凶”移到“是否处于人的驯养之下”：野外独立生活、未经驯养的动物，可以叫 feral；不一定正在攻击谁。","original":false,"kind":"word_family","weak":false},{"method":"FERAL 近音 fear all：见生人就躲的野猫","textZh":"fear 是“害怕”，all 是“所有”。借 feral 的 /ˈfɪrəl/ 读法，近似听成 fear all：一只没有习惯与人接触的野猫，见到生人就退远，仿佛怕所有人。由这种不亲近人的野生生活状态记 feral。只是近音画面，不是说所有野生动物都胆小或危险。","original":false,"kind":"invented_association","weak":false}]},"6084":{"word":"fertilize","mnemonics":[{"method":"FERTILE＋ize：让土地肥沃起来","textZh":"fertile 是“肥沃的、能多产的”，-ize 表示“使成为”。一片地原本养分不足，施入合适的肥料来改善它的生产力，就是 fertilize。由状态 fertile 到使它变得肥沃的动作 fertilize，直接记“施肥、使肥沃”。","original":false,"kind":"word_components","weak":false},{"method":"transFER 搬运，FERtilize 给土壤送养分","textZh":"transfer 是“转移、搬运”，其中 fer 与 fertilize 的词源都可追溯到“承载、产出”的线索。把施肥想成给土壤送入一份养分：养分从肥料进入土壤，帮助它养出庄稼。借熟悉的 transFER 记住 FERtilize 的“为生长补给”动作；不是把任何搬运都叫施肥。","original":false,"kind":"word_family","weak":false}]},"6085":{"word":"fervid","mnemonics":[{"method":"从 efFERVesce 认出 FERVid","textZh":"回想 effervesce（兴奋、热情洋溢）里“情绪向外沸腾”的画面：喜悦藏不住，从笑容和动作里冒出来。fervid 与它共享表示“沸腾”的 ferv 词源线索。effervesce 说兴奋流露这个动作；fervid 形容这种热烈的情感或表达。把已有的冒泡画面接到同一段词形，记“热情强烈”。","original":false,"kind":"word_family","weak":false},{"method":"FEVER PITCH 的高涨，FERVID 的热烈","textZh":"fever 本来是“发热”；fever pitch 是真实习语，指情绪极度高涨。借 fever 与 fervid 的整体近形，想象看台在决胜一刻达到 fever pitch，观众跳起来喊叫：这种热烈的支持可以叫 fervid。此路从熟词和完整习语找回情绪强度，不需拆拉丁词根；也不把热情误说成生病。","original":false,"kind":"invented_association","weak":false}]},"6086":{"word":"forte","mnemonics":[{"method":"FORT 堡垒，FORTE 强项","textZh":"fort 是“堡垒”，让人想到坚固、能守得住的地方。它和 forte 都有“强”的同源线索。把一个人的本领想成防线：最坚固、最拿得出手的那一处，就是他的 forte。由堡垒的“强处”记人的“强项”，不是说他擅长打仗。","original":false,"kind":"word_family","weak":false},{"method":"乐谱上的 FORTE 是“强”，人的 FORTE 是“强项”","textZh":"乐谱中的 forte 表示“强奏”，常缩写为 f；这里的 f 是真实音乐记号，不是临时编出的字母暗号。先听见一段力度鲜明的强奏，再问一个人“你强在哪一项？”他的 forte 就是特别擅长的事。音乐义说力度，特长义说本领，不能把“唱得响”直接当作“唱得好”。","original":false,"kind":"phrase_anchor","weak":false}]},"6087":{"word":"fetid","mnemonics":[{"method":"FETID，想到闷久了的 FEET","textZh":"feet 是“脚”，读 /fiːt/；fetid 有 /ˈfiːtɪd/ 这一标准读法，开头正好能让你想到 feet。运动后脱下闷了很久的鞋，浓烈的脚臭让人皱眉捂鼻：由 feet 的难闻气味记 fetid。只是近音联想，不是说所有脚都臭，也不是词源解释。","original":false,"kind":"invented_association","weak":false},{"method":"FESTER 在腐烂，FETID 是臭味","textZh":"fester 可以指“腐烂”，也指伤口化脓；它与 fetid 的开头形音相近。想象垃圾桶里菜叶不断腐坏，后来一开盖就臭得人后退：fester 提醒腐坏的过程，fetid 评价散出的恶臭。借过程与嗅觉结果相连来记，不把两词当作同源词或完全同义词。","original":false,"kind":"invented_association","weak":false}]},"6088":{"word":"fetter","mnemonics":[{"method":"FOOT 连着脚镣，FETTER 限住脚步","textZh":"foot 是“脚”，复数 feet；fetter 与 foot 有词源联系，最初指套在脚上的镣铐。把脚踝上的铁环和两脚间拉紧的链条连起来：脚想迈开，却被链条拽住。由“脚被镣铐限住”记 fetter 的动作义“束缚”，再扩展到制度或责任限制人的行动。","original":false,"kind":"word_family","weak":false},{"method":"TETHER 拴在一处，FETTER 不能自由动","textZh":"tether 读 /ˈteðər/，指用绳或链把人、动物或物件系在固定点；fetter 读 /ˈfetər/，两词节奏相近。想象拴绳拉直到头，一辆小车再也无法往前：tether 强调“系住”，fetter 强调因此受到的行动限制。用整词近音和真实动作作联想，不把它们说成同源，也不认为所有安全拴系都是枷锁。","original":false,"kind":"invented_association","weak":false}]},"6089":{"word":"fiasco","mnemonics":[{"method":"FLASK 翻倒，演示变成 FIASCO","textZh":"flask 是“烧瓶、小瓶”，与 fiasco 的“瓶”义有真实词源联系。借这个形音入口，想象一场精心准备的科学演示：关键的 flask 被碰翻，全部样品流失，演示只能停下，成了一场 fiasco。翻瓶只是这里自编的记忆画面；“瓶”为什么引申为失败，词源仍不确定，不能把这个故事当历史。","original":false,"kind":"invented_association","weak":false},{"method":"把 FIASCO 固定在“彻底搞砸”的场景","textZh":"把 a complete fiasco 整体记成“彻底失败的一场事”：原本要成功展示的作品在众人面前全面垮掉，既没达到目标，又让人难堪。complete 是“完全的”。这一条用于巩固语境和强度，不提供新的词形或读音入口，记忆力度较弱。","original":false,"kind":"phrase_anchor","weak":true}]},"6090":{"word":"fictitious","mnemonics":[{"method":"FICTION 里的 FICTITIOUS 人物","textZh":"fiction 是“小说；虚构故事”。把熟悉的 science fiction（科幻小说）作为入口：作者写出从未存在过的人物和星球。fiction 与 fictitious 共有醒目的 fict，也有真实的词源联系；前者是虚构作品或内容，后者形容其中“编出来、并非真实存在”的东西。","original":false,"kind":"word_family","weak":false},{"method":"FICTITIOUS / FAKE ISSUES，凭空编出的问题","textZh":"看到 fictitious，近音想到 fake issues（编出来的问题）：机器明明完好，维修者却虚构一串故障，好让你花钱修理。这些从未存在的问题就是 fictitious。借“假的问题”记“虚构的”，不指机器真的坏了。","original":true,"kind":"invented_association","weak":false}]},"6091":{"word":"fidelity","mnemonics":[{"method":"conFIDE 托付，FIDELITY 不负信任","textZh":"confide 是“向信任的人吐露秘密”，如把心事告诉朋友。看到 confide 与 fidelity 共有的 fide，连起两端：我信任你，才愿意托付；你始终守信、不背弃，表现的就是 fidelity。两词有“信任、忠实”的真实词源联系，不是要求先死记一个陌生词根。","original":false,"kind":"word_family","weak":false},{"method":"HI-FI 的 FI，就是 FIDELITY","textZh":"音响上的 hi-fi 是 high fidelity 的简称，意思是“高保真”。好音响忠实还原原来的声音，不擅自改变它；一个人忠实于承诺，也是不改变所坚守的对象。从这个真实缩写记住 fidelity，再连起“对原声忠实”和“对人或原则忠诚”两个用法。","original":false,"kind":"phrase_anchor","weak":false}]},"6092":{"word":"filibuster","mnemonics":[{"method":"FILIBUSTER，费力把事拖","textZh":"借中文近音“费力把事拖”记整体读音和目的：议员明明可以结束发言，却不断接着讲，耗费力气也要把表决拖下去。关键不是演讲很精彩，而是故意阻碍议事。这是近音记忆句，不是逐音准确音译。","original":false,"kind":"invented_association","weak":false},{"method":"FILL 时间，BUSTER 阻断进程","textZh":"fill 是“填满”；buster 指破坏或打破某物的人或东西。把 filibuster 的开头近音连到 fill，后半直接认出 buster：用长篇讲话填满议事时间，破坏原定的表决进程。两个英文线索分别提示做法和结果；这是近音与词形联想，不是 filibuster 的真实构词来源。","original":false,"kind":"invented_association","weak":false}]},"6093":{"word":"flaccid","mnemonics":[{"method":"FLAT 瘪气球，FLACCID 软塌塌","textZh":"flat 可以形容瘪了、缺气的气球。看到 flaccid 的 fla 开头，联到这个完整熟词：原本绷紧的气球泄了气，外皮变得软塌、撑不起来。flat 提醒缺气，flaccid 描述失去紧实的状态。不是说所有平坦的东西都软，也不是词源拆分。","original":true,"kind":"invented_association","weak":false},{"method":"reLAX 放松，FLACCID 松弛","textZh":"relax 是“放松”，读 /rɪˈlæks/；flaccid 的另一标准读法 /ˈflæksɪd/ 也含有明显的 /læks/ 音。先握紧拳头，再彻底放松，让手软软垂下；由这个亲身可感的“松下来”找回 flaccid。只是近音和动作联想，不是说日常放松就等于医学上的异常无力。","original":true,"kind":"invented_association","weak":false}]},"6094":{"word":"flatter","mnemonics":[{"method":"FLATTER，嘴上“服了他”","textZh":"借中文近音“服了他”记 flatter：为了讨好对方，一点小事也夸成天大的本领，嘴上连说“真厉害，服了你了”。这不是发自内心的正常赞赏，而是夸过头来取悦别人。近音句帮助找回“奉承”，不代替正确英文发音。","original":false,"kind":"invented_association","weak":false},{"method":"FLAT 手掌顺毛，FLATTER 顺着夸","textZh":"flat 是“平的”；词史中 flatter 有用平手抚摸、讨好的线索。想象顺着毛轻轻抚摸，让小动物舒服；转到说话，就是专拣对方爱听的话，顺着自尊心夸。用“顺毛讨好”记奉承，不把 flatter 硬拆成 flat 加一个表示人的 -er。","original":false,"kind":"etymology","weak":false}]},"6095":{"word":"flaw","mnemonics":[{"method":"FLAW 近音 FLOOR，地板有裂缝","textZh":"floor 是“地板”，在不读词尾 r 的英式发音中，与 flaw 同音。想象刚铺好的地板上有一道明显裂缝：整片地板不错，偏偏这一处不完美。借 floor 上的裂缝找回 flaw“瑕疵”；这是读音联想，不是两词同源。","original":true,"kind":"invented_association","weak":false},{"method":"fLAW，法律也会有漏洞","textZh":"在 flaw 中直接看见完整熟词 law（法律）：一条规则看似周全，却漏掉一个关键情况，让人钻了空子。这处漏洞就是规则里的 flaw。用 law 的漏洞记“缺陷”，不是把 f 当成某个有真实含义的前缀。","original":false,"kind":"invented_association","weak":false}]},"6096":{"word":"fledgling","mnemonics":[{"method":"DUCKLING 小鸭，FLEDGLING 菜鸟","textZh":"duckling 是小鸭，像“丑小鸭”里的那只小家伙；fledgling 也带表示幼小的 -ling。它原本指刚长出飞羽、开始学飞的幼鸟，再比喻刚进入一个领域的人。看到这个“小家伙”的词尾，就连起刚出巢的鸟和刚入行的“菜鸟”。","original":false,"kind":"word_family","weak":false},{"method":"FLEDGLING 近音 PLEDGING，新人宣誓","textZh":"pledge 是“郑重承诺、宣誓”，pledging 读 /ˈpledʒɪŋ/，与 fledgling /ˈfledʒlɪŋ/ 近音。想象新成员刚加入社团，正在宣誓接受训练，还没有实践经验；由这位刚入门的人找回 fledgling“新手”。两个词读音并不完全相同，也没有这里所暗示的词源关系。","original":false,"kind":"invented_association","weak":true}]},"6097":{"word":"fleet","mnemonics":[{"method":"FLEE 快逃，FLEET 跑得快","textZh":"flee 是“逃离”，在 fleet 开头能完整认出来。遇到危险，一只鹿立刻轻快地逃开；用 flee 的迅速逃离，记 fleet 的“动作迅速、敏捷”。只是拼写联想：逃离不保证每次都快，fleet 也不表示一定在逃跑。","original":false,"kind":"invented_association","weak":false},{"method":"FLEET 近音 FEET，双脚飞快","textZh":"feet 是 foot 的复数，表示“双脚”，读 /fiːt/；fleet /fliːt/ 与它近音。想象赛跑者双脚轻快交替，一下就冲到前面。从 fleet 和 feet 的近音记住“脚下快、动作敏捷”，也顺便连起真实表达 fleet of foot。","original":true,"kind":"invented_association","weak":false}]},"6098":{"word":"flexible","mnemonics":[{"method":"FLEX 能弯，FLEXIBLE 能变通","textZh":"flex 是“弯曲”，比如弯动手指或让一根软管转弯；-ible 表示“能够……的”。flexible 的材料能顺着需要弯，不是一碰就断。由实物“不僵硬”连到计划或办法“不僵化、能调整”，记住原书的灵活可变义。","original":false,"kind":"word_components","weak":false},{"method":"FLEXIBLE / LEGS + ABLE，双腿弯得动","textZh":"把 flexible 的声音联到 legs（双腿）和 able（能够）：做伸展时，双腿能轻松弯动、换姿势，不是僵硬地绷着。由“双腿弯得动”记 flexible“柔韧、灵活的”，也连到计划能调整、不死板。","kind":"invented_association","original":true,"weak":false}]},"6099":{"word":"flinch","mnemonics":[{"method":"PINCH 一掐，FLINCH 一缩","textZh":"pinch 是“掐、捏”，/pɪntʃ/ 与 flinch /flɪntʃ/ 押韵。想象突然被掐了一下，身体本能地缩开：pinch 是造成疼痛的动作，flinch 是受惊或疼痛后的退缩反应。只借近音，不是说这两个动词含义相同。","original":false,"kind":"invented_association","weak":false},{"method":"flINCH，吓得退后一英寸","textZh":"inch 是“英寸”，在 flinch 里能完整看见。突然一声响，人不一定拔腿跑，只是肩头一缩、身子往后躲了一小段。用“吓得退后一 inch”的小幅退避记 flinch；一英寸只是画面线索，不是它对实际退缩距离的规定。","original":true,"kind":"invented_association","weak":false}]},"6100":{"word":"flippancy","mnemonics":[{"method":"FLIP，把严肃话题轻轻弹开","textZh":"flip 是“轻弹、翻转”。别人正认真讲自己的困难，他却像弹硬币一样把话题弹开，还随口说笑。借“把严肃的事轻轻弹开”的动作，记 flippancy 的轻率无礼。","original":false,"kind":"invented_association","weak":false},{"method":"FLIPPANCY / FLIP PANTS，翻裤兜打岔","textZh":"把 flippancy 近音联到 flip（翻）和 pants（裤子）：大家正严肃商量筹款救急，他却故意把裤兜翻出来晃，笑着打岔：“我只剩两个洞，散会吧！”大家急着想办法，他却只拿玩笑把正事打发掉；借这种轻慢的打岔，记 flippancy“轻率无礼”。","original":false,"kind":"invented_association","weak":false}]},"6101":{"word":"flirt","mnemonics":[{"method":"FLIRT 和 SHIRT 押韵","textZh":"shirt（衬衫）读 /ʃɜːt/，和 flirt /flɜːt/ 押韵。想象聚会上，有人含笑夸对方衬衫好看，接着眨眼说：“不过，还是你更好看。”从 shirt 上的俏皮赞美，记 flirt“调情”；普通的礼貌夸奖当然不一定是在调情。","original":true,"kind":"invented_association","weak":false},{"method":"只 FLIRT 不认真，对方可能 HURT","textZh":"hurt 是“使人受伤、难过”，与 flirt 押韵。想象一方只是暧昧逗趣，另一方却当成了认真的追求，结果感到 hurt。用这组押韵提醒自己：flirt 是调情，不保证想发展正式关系；并不是说调情一定会伤人。","original":false,"kind":"invented_association","weak":false}]},"6102":{"word":"flit","mnemonics":[{"method":"FLIGHT 缩短成 FLIT，轻轻一掠","textZh":"flight 是“飞行”。把拼写中的 gh 拿掉，就剩下 flit，像把一段长长的飞行缩成一只蝴蝶从花边轻轻掠过的一小下。借短短的飞行记“轻快掠过”。","original":false,"kind":"invented_association","weak":false},{"method":"别人 SIT，她却 FLIT","textZh":"sit（坐）和 flit 的词尾都读 /ɪt/。一桌客人安稳地 sit，忙碌的主人却一会儿轻快地到左边问候，一会儿又掠到右边添茶。用“大家坐住，她却一闪一闪地换地方”的对比，记 flit 的轻快移动。","original":true,"kind":"invented_association","weak":false}]},"6103":{"word":"flock","mnemonics":[{"method":"Birds of a feather FLOCK together","textZh":"谚语 Birds of a feather flock together，直译是“同样羽毛的鸟会聚在一起”，常说“物以类聚”。把整句话里的 flock 挂在“一起聚来”的画面上，记住它是成群聚集的动作，而不只是静止的一群鸟。","original":false,"kind":"phrase_anchor","weak":false},{"method":"人们 FLOCK 来，窄门被 BLOCK","textZh":"block 是“挡住”，和 flock 押韵。演出散场后，观众一群群向出口走来，窄门都被堵住了：人们 flock（成群涌来），门被 block（挡住）。用这条小因果记成群聚来的动作；这个场景借拥堵突出人多，flock 本身并不要求堵塞。","original":true,"kind":"invented_association","weak":false}]},"6104":{"word":"florid","mnemonics":[{"method":"FLOR 像 FLOWER，话里开满花","textZh":"florid 中的 flor- 与 flower（花）同源，来自拉丁语表示“花”的词。想象本来一句简单的话，被层层形容和华丽比喻包住，像花朵把整张纸都盖满。花饰多到抢过内容，就记住 florid“辞藻华丽、过分花哨”。","original":false,"kind":"etymology","weak":false},{"method":"FLORIDa 海边，晒红的脸","textZh":"Florida（佛罗里达）去掉最后的 a 就是 florid。想象海边度假后，镜子里两颊红通通；借整个地名和红脸画面，记 florid 的“面色红润、发红”义。这条记面色，第一条花饰记辞藻。","original":false,"kind":"invented_association","weak":false}]},"6105":{"word":"flounder","mnemonics":[{"method":"FLOW + UNDER，脚下水流让人站不稳","textZh":"把 flounder 看成 flow（流动）少一个 w，再接 under（在下面）。脚下水流推着鞋，想迈步却站不稳，只能张着双臂、一步一挣扎。由“脚下水流让动作变笨拙”记 flounder。","original":false,"kind":"invented_association","weak":false},{"method":"FLOUNDER 还在挣扎，FOUNDER 已经垮掉","textZh":"回想 founder 页里纸桥撑不住、计划垮掉的画面。flounder 比 founder 多一个 l：桥还没全塌，人已经手忙脚乱，补这里又顾不上那里，是 flounder；计划最终垮掉才是 founder。借这对整体近形词，分清“困境中挣扎”和“彻底失败”。","original":true,"kind":"invented_association","weak":true}]},"6106":{"word":"flabby","mnemonics":[{"method":"FLABBY / FLAP，松松地晃动","textZh":"flabby 的开头让人联想到 flap（拍动、摆动）。想象抬起手臂，松弛的皮肉跟着轻轻晃动，没有紧实的支撑感。由“松软得会晃动”记 flabby，再引到辩解没有力量、撑不住。","original":false,"kind":"invented_association","weak":false},{"method":"FATTY 的肥肉软，FLABBY 的皮肉松","textZh":"fatty 是“多脂肪的”，与 flabby 整体近形近音。想象一小片肥肉软软摊着，手指轻按就凹下，没有紧绷的支撑感。借 fatty 的软肉触感记 flabby“松弛的”，再连到辩解软弱无力。","original":true,"kind":"invented_association","weak":false}]},"6107":{"word":"fluent","mnemonics":[{"method":"FLU 像 FLOW，话语流淌出来","textZh":"fluent 的 flu- 来自表示“流动”的词根，可连到熟词 flow（流动）。想象说话像开着的水龙头，句子顺顺地流出来，不必每说几个词就停下来找词。由水流顺畅记表达流利。","original":false,"kind":"etymology","weak":false},{"method":"FLUENT / FLEW + WENT，顺口讲完旅行","textZh":"把 fluent 近音联到 flew（飞去）和 went（去了）：讲旅行时，“We flew to Beijing, then went to…”一句接一句顺口说下去，不用停下来想过去式。由 flew、went 脱口而出的连贯表达，记 fluent“流利的”。","original":true,"kind":"invented_association","weak":false}]},"6108":{"word":"fluky","mnemonics":[{"method":"FLUKY / LUCKY，运气帮了一把","textZh":"fluky 和 lucky（幸运的）整体拼写很像。想象一记踢偏的球碰到门柱，反而弹进球门：确实 lucky，但不是踢得准，而是碰巧成功。把“靠幸运碰中”记成 fluky。","original":false,"kind":"invented_association","weak":false},{"method":"FLUKY，想到“福气”","textZh":"fluky 读起来可以近音联到“福气”。随手抽一张就抽中奖券，旁人笑说“真有福气”，自己也知道不是凭本领算出来的。借“福气碰上门”的近音，记 fluky“侥幸的”。","original":true,"kind":"invented_association","weak":false}]},"6109":{"word":"flush","mnemonics":[{"method":"FLUSH / FULL，钱袋鼓起来","textZh":"看见 flush，联想到形近的 full（满的）。不是只有一两枚零钱，而是钱袋满满、买书还绰绰有余。由 full 的满当当，记 flush“手头充裕”。","original":true,"kind":"invented_association","weak":false},{"method":"FLUSH / RUSH，一股水冲过去","textZh":"rush 是“猛冲”，与 flush 押韵。按下冲水按钮，一股水 rush 过去，把污物带走。把这股急冲的水声和 flush 连起来，记“冲洗、冲水”。","original":true,"kind":"invented_association","weak":false}]},"6110":{"word":"foible","mnemonics":[{"method":"FOIBLE / FEEBLE，从无力到弱点","textZh":"foible 与 feeble（虚弱无力的）同源，字形也相近。feeble 是力量弱，foible 则把“弱”放到性格的一小处：人很好，只是总忘记带帽子。抓住这点小弱处，记“小毛病”。","original":false,"kind":"etymology","weak":false},{"method":"FOIBLE / 菲薄：小毛病，不必妄自菲薄","textZh":"把 foible 近音联到“妄自菲薄”的“菲薄”：偶尔忘带钥匙，是个小毛病，不必因此把自己说得一无是处。由“小毛病不值得全盘否定自己”，记 foible 指性格、习惯上的小缺点，而不是严重过错。","kind":"invented_association","original":true,"weak":false}]},"6111":{"word":"foil","mnemonics":[{"method":"FOIL / FAIL，让对方失败","textZh":"foil 与 fail（失败）只差中间一个字母。想象猫刚伸爪偷鱼，盘子就被盖住：男孩 foil 了它的企图，猫的计划 fail 了。记住 foil 是“使对方没能成功”。","original":false,"kind":"invented_association","weak":false},{"method":"FOIL 铝箔，包住食物挡住偷吃","textZh":"foil 也指包食物的铝箔。想到香喷喷的点心被铝箔严严包住，想偷偷尝一口的人无从下手。用“铝箔挡住偷吃”的画面，把同形名词连到动词“挫败企图”。","original":true,"kind":"invented_association","weak":false}]},"6112":{"word":"foment","mnemonics":[{"method":"FOMENT / 火猛，给火添势","textZh":"把 foment 近音联到“火猛”：本来只有一点火星，添柴、扇风后火势越来越猛；争执也是这样，有人不停挑拨，便把小分歧助长成大冲突。由“给火添势”记 foment“助长、煽动”。","original":true,"kind":"invented_association","weak":false},{"method":"FOMENT / COMMENT，一句留言把火拱大","textZh":"comment 是“评论、留言”，和 foment 后半段音形很近。两人刚有分歧，旁人留言“他就是瞧不起你，还不还手？”，不是劝和，而是在煽动冲突。借会拱火的 comment，记 foment“助长、挑起”。","original":true,"kind":"invented_association","weak":false}]},"6113":{"word":"foolproof","mnemonics":[{"method":"FOOL + PROOF，连新手也不易弄错","textZh":"fool 是“傻瓜”，-proof 表示“防……的”，像 waterproof 的防水。foolproof 就是把容易犯的操作错误也防住：插头只有一个方向能插进去，新手不用猜。","original":false,"kind":"word_components","weak":false},{"method":"FOOLPROOF / FULL ROOF，整块屋顶不易装错","textZh":"把 foolproof 近音联到 full（完整的）和 roof（屋顶）：玩具屋顶做成完整一块，卡槽又防反，初学者只要顺着槽装，方向错了就卡不进去。借这块“想装反也不行”的屋顶设计，记 foolproof“简单可靠、不易用错的”。","kind":"invented_association","original":true,"weak":false}]},"6114":{"word":"footloose","mnemonics":[{"method":"FOOT + LOOSE，脚步没有牵绊","textZh":"foot 是“脚”，loose 是“松开的、不受束缚的”。想象脚步不再被固定行程牵住，走到岔路口，想去湖边就去湖边。由“脚步自由”，记人无拘无束。","original":false,"kind":"word_components","weak":false},{"method":"FOOTLOOSE AND FANCY-FREE，一串 f 走向 FREE","textZh":"把 footloose 放进固定短语 footloose and fancy-free。foot、fancy、free 连续的 f 音让整句顺口，末尾熟悉的 free 点出自由：没有事务牵绊，背起包就能出发。","original":false,"kind":"phrase_anchor","weak":false}]},"6115":{"word":"forbearance","mnemonics":[{"method":"FORBEARANCE / BEAR，忍得住才不发作","textZh":"先抓住 bear（承受、忍受），如 bear the noise：噪声令人烦躁，但仍承受得住。forbear 把这种“忍住”落实为克制言行，后接 -ance 成为名词 forbearance：有气也不立刻发作的忍耐。","kind":"etymology","original":false,"weak":false},{"method":"FORBEARANCE / FOUR BEARS，四只熊忍住不抢","textZh":"把 forbearance 的声音联到 four bears（四只熊）：四只大熊面前只有一小罐蜂蜜，都想伸爪抢，却一个接一个收回爪子，耐着性子轮流尝。由“明明想抢，却忍住”的四只熊，记住克制、忍耐。","kind":"invented_association","original":true,"weak":false}]},"6116":{"word":"foreword","mnemonics":[{"method":"FORE + WORD，正文前的话","textZh":"fore- 表示在前，word 是话语。把整本书看成一次长谈：正式开讲前，先用几页话介绍这本书。这段“放在前面的话”就是 foreword。","kind":"word_components","original":false,"weak":false},{"method":"FOREWORD / FORWARD，往前翻先遇见序言","textZh":"把形近的 foreword 和 forward（向前）并排记：还没进入正文，先往书的前面找，就会找到 foreword。写的是书里的话，尾部保留 word；表示方向才写 forward。","kind":"invented_association","original":true,"weak":false}]},"6117":{"word":"forthright","mnemonics":[{"method":"FORTH + RIGHT，直直向前，不绕弯","textZh":"forth 是向前，right 在这个古老组合里表示径直。想象一句话沿直线走到要点，不先绕几圈客套：屋顶歪了，就直接指出哪里歪。路线直，表达也直，就是 forthright。","kind":"etymology","original":false,"weak":false},{"method":"FORTHRIGHT / FOURTH + WRITE，第四稿直写真话","textZh":"把 forthright 的声音联到 fourth（第四）和 write（写）。意见改到第四稿，终于删去绕弯的客套，直接写下“我不同意这个方案”。用这次坦白、不绕弯的表达，记住 forthright：直率、直截了当。","kind":"invented_association","original":true,"weak":false}]},"6118":{"word":"fortify","mnemonics":[{"method":"FORT + -IFY，把防线变坚固","textZh":"fort 是堡垒，-ify 表示使成为某种状态。想象给一道薄墙添上厚实支撑，把它变成像堡垒一样可靠的防线：fortify 就是加固、增强。","kind":"word_components","original":false,"weak":false},{"method":"FORTIFY / COMFORT，从安慰到有力量","textZh":"把 fortify 与 comfort（安慰）中的 fort 放在一起记，它们的词源都连着“强”。朋友的安慰不仅让人好受，还能让人鼓起勇气继续做事：comfort 安慰人，fortify 增强人的力量或信心。","kind":"etymology","original":false,"weak":false}]},"6119":{"word":"fracas","mnemonics":[{"method":"FRACAS / CRASH，争吵里传出碰撞声","textZh":"把 fracas 的整个词形与 crash（碰撞、撞击声）并排联系。想象双方越吵越响，拉扯时又撞翻椅子：不是安静讨论，而是一场吵闹冲突。","kind":"invented_association","original":true,"weak":true},{"method":"FRACAS / FREE CARS，抢免费车吵成一团","textZh":"把 fracas 的声音联到 free cars（免费汽车）：只有一辆免费车，几个人却都说归自己，争抢声盖过了喇叭声。用这场“争抢免费车”的闹剧，记住 fracas 是吵闹的争执。","kind":"invented_association","original":true,"weak":true}]},"6120":{"word":"fracture","mnemonics":[{"method":"FRACT + URE，把完整的东西折开","textZh":"fract- 这条词根表示“折断”。把 fracture 记成一根受力折开的粉笔：原本连在一起，中间出现断口。它既能指这处断裂，也能表示“使它断裂”的动作。","kind":"etymology","original":false,"weak":false},{"method":"FRACTURE / FRACTION，完整的一块分裂成几份","textZh":"把 fracture 与数学中的 fraction（分数）并排记：一整块薄饼原来是完整的，掰开后才能拿出四分之一。fraction 让你想到分出来的一份，fracture 则抓住把整体掰断、留下断口的那一下。","kind":"invented_association","original":true,"weak":false}]},"6121":{"word":"fragile","mnemonics":[{"method":"FRAG + ILE，一碰就碎的薄玻璃","textZh":"frag- 表示“打碎”，fragile 把特点落在“容易被打碎”上。想象薄玻璃杯轻轻一碰就裂开：不是说它已经碎了，而是它经不起碰撞。","kind":"etymology","original":false,"weak":false},{"method":"FRAGILE / FRIDGE，冰箱里的薄壳鸡蛋","textZh":"把 fragile 的整体形音联到 fridge（冰箱）。打开冰箱，蛋格里是一排薄壳鸡蛋，拿取时要轻轻托住，稍不留神就会碰破。用冰箱里这些需要轻拿的鸡蛋，记住 fragile：易碎、经不起碰撞。","kind":"invented_association","original":true,"weak":false}]},"6122":{"word":"frail","mnemonics":[{"method":"FRAIL / FAIL，力气撑不住","textZh":"frail 比 fail（失败、失灵）多一个 r。想象一个很虚弱的人想抬起水壶，手臂却撑不住，动作 fail 了：用这次体力不支把 frail 连到“虚弱”，而不是能力差。","kind":"invented_association","original":true,"weak":false},{"method":"FRAIL / RAIL，走路需要扶栏杆","textZh":"frail 里完整藏着 rail（栏杆）。想象一个身体虚弱的人，走几步就得扶着栏杆支撑。看到 frail，先想到这个需要搀扶的身影。","kind":"invented_association","original":true,"weak":false}]},"6123":{"word":"fraught","mnemonics":[{"method":"FRAUGHT / FOUGHT，走到哪里都得应战","textZh":"fraught 和 fought（fight 的过去式）读音相近。想象一路都在 fought：刚应付一个难题，下一个又挡住去路。一路都得“战斗”，就是 fraught with problems，充满问题。","kind":"invented_association","original":true,"weak":false},{"method":"FRAUGHT / FRIGHT，麻烦多得让人心惊","textZh":"fraught 与 fright（惊吓）形音相近。想象走一条险路，每转一个弯又有落石，心里一阵阵 fright：这段路充满危险，整趟行程都让人焦虑。用“险情不断、心惊不止”记 fraught。","kind":"invented_association","original":true,"weak":false}]},"6124":{"word":"fretful","mnemonics":[{"method":"FRETFUL / RESTFUL，睡不安稳就烦躁","textZh":"把 fretful 和 restful（让人安稳休息的）对着记，rest 就是休息。宝宝本来睡得很安稳，却不断被声音吵醒，揉眼、扭动、哼哼闹闹：没有 restful 的好觉，就变得 fretful，烦躁不安。","kind":"invented_association","original":true,"weak":false},{"method":"FRETFUL / FRIGHT，受惊后烦躁不宁","textZh":"把 fretful 的前半声音联到 fright（惊吓）。突然的砸门声吓了他一跳，之后一直担心又被惊扰，坐立不安，别人一催就不耐烦。用受惊后烦躁不宁的样子，记住 fretful。","kind":"invented_association","original":true,"weak":false}]},"6125":{"word":"friable","mnemonics":[{"method":"FRI + ABLE，轻轻一搓就碎","textZh":"fri- 来自表示“搓碎”的拉丁语，-able 表示能够。把 friable 连成一个动作：两指轻搓，原来的小块便散成细屑。重点是很容易碎，不是用力砸坏。","kind":"etymology","original":false,"weak":false},{"method":"FRY + ABLE，炸酥的外皮一碰掉渣","textZh":"friable 读起来像 fry 加 able。想到 fry（油炸）后那层干酥外皮：手指轻碰，碎渣就落下来，用这层酥皮记住“易碎成屑”。","kind":"invented_association","original":true,"weak":false}]},"6126":{"word":"friction","mnemonics":[{"method":"FRICT + ION，两面相互摩擦","textZh":"frict- 表示“摩擦”，-ion 把动作变成名词。把两只手掌贴着来回搓：接触、阻力、发热，都集中在 friction 这个词里。","kind":"etymology","original":false,"weak":false},{"method":"FRICTION / FICTION，小说翻多了也磨毛","textZh":"friction 只比 fiction（小说）多一个 r。想象一本反复翻读的小说，手指一遍遍擦过纸边，把边缘磨得起毛：书里是 fiction，书页和手指之间发生的是 friction，摩擦。","kind":"invented_association","original":true,"weak":false}]},"6127":{"word":"frigid","mnemonics":[{"method":"FRIG + ID，把温度与态度都降到冰点","textZh":"frig- 表示“冷”，-id 构成形容词。frigid 先抓住强烈的冷：天气冷得难以忍受；换到态度上，就是完全没有热情。","kind":"etymology","original":false,"weak":false},{"method":"FRIDGE → FRIGID，像打开冰箱门","textZh":"frigid 的开头读音让人想到 fridge（冰箱）。想象打开冰箱迎面一股冷气，再把这股冷气搬到一个人的眼神里：冷得让人不想靠近。","kind":"invented_association","original":true,"weak":false}]},"6128":{"word":"frivolous","mnemonics":[{"method":"FRIVOL + OUS，只把事情当小玩闹","textZh":"frivol- 来自表示“琐碎、愚蠢”的拉丁词，-ous 构成形容词。把 frivolous 记成该认真时却只顾小玩闹：人显得轻浮，事情也没什么实际分量。","kind":"etymology","original":false,"weak":true},{"method":"FRIVOLOUS / FREE，满脑子只想自由玩","textZh":"读 frivolous 的开头，借 free（自由）想到一个只想玩、把正事扔在一边的人。不是自由本身不好，而是该认真时仍把一切当儿戏，这才是 frivolous。","kind":"invented_association","original":true,"weak":true}]},"6129":{"word":"frothy","mnemonics":[{"method":"FROTHY / FLOAT，泡泡轻轻浮着","textZh":"把 frothy 的前半声音联到 float（漂浮）：饮料表面的泡泡轻轻浮着，一吹就散。再想到一部只图轻松好笑的喜剧，像这些泡泡一样轻，没有沉重的主题；这就是 frothy 的轻松、不严肃。","kind":"invented_association","original":true,"weak":false},{"method":"FROTHY / FRUIT TEA，摇出一层轻泡","textZh":"读 frothy 时联到 fruit tea（水果茶）。把杯里的水果茶摇一摇，表面起了一层轻轻的泡沫。把这种轻泡的感觉放到节目上：轻松热闹，没有沉重内容，用来记 frothy。","kind":"invented_association","original":true,"weak":false}]},"6130":{"word":"frowsy","mnemonics":[{"method":"FROWSY / EYEBROWS，眉毛头发乱成一团","textZh":"把 frowsy 的声音联到 eyebrows（眉毛）的后半。想象一个好久没收拾仪容的人，眉毛杂乱、头发乱翘，衣领也脏兮兮。由这副没整理的眉眼和外表，记住 frowsy：邋遢、不整洁。","kind":"invented_association","original":true,"weak":false},{"method":"FROWSY / TROUSERS，皱脏裤子也不换","textZh":"把 frowsy 的声音联到 trousers（裤子）。裤子已经皱巴巴，裤脚还沾着灰，他却没换就出门，整身衣服也没收拾。用这条又皱又脏的裤子，记“邋遢、不整洁”。","kind":"invented_association","original":true,"weak":false}]},"6131":{"word":"full-bodied","mnemonics":[{"method":"FULL + BODIED，内容不是空架子","textZh":"full 是充满，body 也可以指文章的主体。想到一篇报告的主体里装满扎实发现，而不是只剩漂亮标题：内容有实质，研究也就有分量。","kind":"word_components","weak":false,"original":true},{"method":"FULL-BODIED / FULL BODY，有血有肉的内容","textZh":"看到 full-bodied，想到 full body：不是只有骨架，而是有血有肉的完整身躯。中文也说叙述“有血有肉”，有具体事实和细节，内容充实、有实质。用这个熟悉的比喻，记住 full-bodied。","kind":"invented_association","original":true,"weak":false}]},"6132":{"word":"fulminate","mnemonics":[{"method":"FULMIN + ATE，批评如雷声","textZh":"fulmin- 源于表示雷电的拉丁词，-ate 构成动词。把 fulminate 连成“雷鸣般的斥责”：不是小声不满，而是怒气冲冲地猛烈批评。","kind":"etymology","weak":false,"original":false},{"method":"FULMINATE / FOOL ME?，竟敢耍我！","textZh":"把 fulminate 的前两拍联到 fool me（耍我）：发现卖家拿假货骗人，当场拍桌怒斥“你竟敢耍我！”用这声愤怒的批评记住 fulminate：大声斥责、猛烈抨击。","kind":"invented_association","original":true,"weak":false}]},"6133":{"word":"fumble","mnemonics":[{"method":"FUMBLE / TUMBLE，手一笨东西就掉","textZh":"fumble 和 tumble（滚落）只差首字母。手忙脚乱地接球，球却从指间滚落：用“笨拙地拿，结果掉下来”记 fumble。","kind":"invented_association","weak":false,"original":true},{"method":"FUMBLE / 翻包，越急越摸不到","textZh":"fumble 近音联到“翻包”。出门急着找钥匙，手在包里摸来摸去，越着急越拿不稳：这个笨拙摸索的动作就是 fumble。","kind":"invented_association","weak":false,"original":true}]},"6134":{"word":"furor","mnemonics":[{"method":"FUROR / FURIOUS，怒气汇成一片","textZh":"furor 与 furious（愤怒的）共享醒目的 fur-。想到许多人同时 furious，抗议声响成一片：个人的怒气变成了公众的愤怒骚动。","kind":"word_family","weak":false,"original":false},{"method":"FUROR / FURY + ROAR，情绪变成吼声","textZh":"把 furor 连到 fury（狂怒）与 roar（吼声）：怒气不再憋在心里，而是突然吼出来。也可想到观众兴奋地高声叫喊，用外放的喧闹记住 furor。","kind":"invented_association","weak":false,"original":false}]},"6135":{"word":"furtive","mnemonics":[{"method":"FURT + IVE，偷取时躲人耳目","textZh":"furt- 来自拉丁语中“偷窃”的词，-ive 构成形容词。小偷最怕被看见，动作和眼神都偷偷摸摸：由“偷”记住 furtive 的隐秘。","kind":"etymology","weak":false,"original":false},{"method":"FURTIVE / FUR THIEF，皮草小偷","textZh":"把 furtive 的声音联到 fur thief（偷皮草的小偷）。他把皮草悄悄塞进衣服里，眼睛还不停瞟着门口，生怕被发现。","kind":"invented_association","weak":false,"original":true}]},"6136":{"word":"fury","mnemonics":[{"method":"FURY / FURIOUS，愤怒的名词","textZh":"furious 是“愤怒的”，fury 是那股强烈的怒气。把 furious 的长尾收成 y，留下满腔怒火：不是一般不高兴，而是暴怒。","kind":"word_family","weak":false,"original":true},{"method":"FURY / FURRY，怒到炸毛","textZh":"fury 和 furry（毛茸茸的）只差一个 r。想象猫被惹怒后毛全竖起来，弓背、露牙、低吼，用“气到炸毛”记 fury。","kind":"invented_association","weak":false,"original":true}]},"6137":{"word":"fussy","mnemonics":[{"method":"FUSS + Y，小细节也放不下","textZh":"fuss 是为小事费心、操心，接 -y 得到 fussy。想象画一枚小圆点，边缘偏了一点也要仔细修好：对细节格外用心，过了头就显得挑剔。","kind":"word_components","weak":false,"original":false},{"method":"FUSSY / 费事，细活不能马虎","textZh":"把 fussy 近音联到“费事”：修手表里的小齿轮，要一点点对准、检查，稍有偏差就得重来。用这种费心的细活，记住“需要谨慎细致”。","kind":"invented_association","weak":false,"original":true}]},"6138":{"word":"gall","mnemonics":[{"method":"GALL / CALL，骚扰电话惹人烦","textZh":"gall 和 call 只差首字母。刚挂掉的骚扰电话又打来，一遍遍打断工作，把人惹得火冒三丈：用烦人的 call 记 gall。","kind":"invented_association","weak":false,"original":true},{"method":"GALL / 搞心态，故意拆台惹人恼","textZh":"把 gall 的声音联到“搞心态”中的“搞”：你刚认真讲完，对方又故意当众拆台、挑衅，越听越恼火。记住“把人心态搞坏、惹人生气”这个作用，就是 gall。","kind":"invented_association","original":true,"weak":false}]},"6139":{"word":"gallant","mnemonics":[{"method":"GALLANT / CALL + ANT，听到呼救就挺身救援","textZh":"把 gallant 联到形音相近的 call（呼救）和 ant（蚂蚁）。童话里，同伴快被水冲走，一只蚂蚁听到呼救就冒险赶去，把同伴拉上岸。用这只响应呼救、挺身救援的小蚂蚁记“英勇”。","kind":"invented_association","original":true,"weak":false},{"method":"GALLANT / 敢拦，危急时挺身而出","textZh":"把 gallant 的声音联到“敢拦”。一头狂奔的牛冲向孩子，有人敢上前把它拦住：不是逞能，而是危急时保护别人，真英勇。","kind":"invented_association","weak":false,"original":true}]},"6140":{"word":"gamble","mnemonics":[{"method":"GAMBLE / GAME，游戏加上赌注","textZh":"gamble 与 game 有词源联系。普通 game 只分输赢；把真金白银押上去，输了就拿不回来，游戏便成了赌博。","kind":"etymology","weak":false,"original":false},{"method":"GAMBLE / 敢搏，没把握也押上去","textZh":"把 gamble 的声音联到“敢搏”：结果还没把握，却敢把本钱押上去搏一次。重点是冒险押注，不是勇敢就一定会赢。","kind":"invented_association","weak":false,"original":true}]},"6141":{"word":"gambol","mnemonics":[{"method":"GAMBOL / GAME + BALL，追球蹦跳","textZh":"由 gambol 联到 game 和 ball：小狗发现滚动的球，兴奋地追过去，又跳着扑回来。记住的不是比赛输赢，而是玩耍时的欢快蹦跳。","kind":"invented_association","weak":false,"original":false},{"method":"GAMBOL / CAMEL，小骆驼撒欢跳","textZh":"把 gambol 与 camel（骆驼）并排看，两个词的整体形音很接近。想象小骆驼终于从围栏里出来，开心地蹦出去，又跳着绕回妈妈身边。借这只撒欢的小骆驼记“欢跳、雀跃”。","kind":"invented_association","original":true,"weak":false}]},"6142":{"word":"gag","mnemonics":[{"method":"GAG / 嘎嘎，听完笑出声","textZh":"把 gag 的声音接到“嘎嘎笑”：演员刚抖出一个笑话，台下就笑成一片。用这阵笑声记 gag 的“笑话”。","kind":"invented_association","weak":false,"original":true},{"method":"GAG / 尬笑话，再冷也是笑料","textZh":"把 gag 的声音联到“尬”笑话：讲笑话的人认真铺垫半天，最后一句冷得全场停了一秒。好笑也好，尴尬也好，这个拿来逗人的小笑话就是 gag。","kind":"invented_association","original":true,"weak":false}]},"6143":{"word":"garble","mnemonics":[{"method":"GARBLE / GARBAGE，话变成一堆乱码","textZh":"garble 的样子让人想到 garbage（垃圾）。原本清楚的一句话，传输后却成了杂乱无章的文字垃圾，别人再也读不懂：信息被弄乱了。","kind":"invented_association","weak":false,"original":false},{"method":"GARBLE / CABLE，线出毛病，话也乱了","textZh":"把 garble 与 cable（电缆、连接线）的字形放在一起记。通话的连接线接触不良，原本清楚的语音变得断断续续，整句话被搅乱得听不懂。由“坏线把信息弄乱”记 garble。","kind":"invented_association","original":true,"weak":false}]},"6144":{"word":"gargantuan","mnemonics":[{"method":"GARGANTUA + N，巨人的尺寸","textZh":"Gargantua 是《巨人传》中的巨人高康大，gargantuan 就从他的名字而来。看到几乎完整的巨人名字，就想到巨人尺度：普通东西被放大到惊人的程度。","kind":"etymology","weak":true,"original":false},{"method":"GARGANTUAN / 缸缸吞，胃口大得惊人","textZh":"把 gargantuan 的声音联到“缸缸吞”：童话里的大胃王不用碗，一大缸一大缸地喝汤。用这夸张的容量，记住“巨大、庞大”。","kind":"invented_association","weak":true,"original":true}]},"6145":{"word":"garish","mnemonics":[{"method":"GARISH / GLARE + ISH，颜色像强光一样刺眼","textZh":"把 garish 联到 glare（刺眼的强光）和 -ish：荧光粉、亮橙、亮绿挤在一件外套上，颜色强得让眼睛想躲开。不是普通的鲜艳，而是鲜艳过头。","kind":"invented_association","weak":false,"original":false},{"method":"GARISH / 咖喱色，浓黄撞亮红","textZh":"把 garish 的声音联到“咖喱色”：浓黄的咖喱已经十分抢眼，再想有人穿着这色的外套，配上大红裤子和荧光绿鞋，几种亮色争着跳进眼里。由这身刺眼的配色记“鲜艳过头、花哨”。","kind":"invented_association","original":true,"weak":false}]},"6146":{"word":"gauche","mnemonics":[{"method":"GAUCHE / 狗屎，饭桌上脱口说粗话","textZh":"把 gauche 的声音联到“狗屎”：正式饭局上，有人评价菜品时脱口而出这句粗话，全桌尴尬。记住的是不懂场合、说话失礼，不是动作慢。","kind":"invented_association","weak":false,"original":false},{"method":"GAUCHE / GO + SHOE，穿脏鞋踩沙发","textZh":"把 gauche 的声音联到 go（去）和 shoe（鞋）。第一次去别人家，他没看场合就穿着脏鞋踩上干净沙发，主人一脸尴尬。用这双“不懂规矩就踩上去”的鞋，记 gauche 的笨拙失礼。","kind":"invented_association","original":true,"weak":false}]},"6147":{"word":"gaudy","mnemonics":[{"method":"GAUDY / GOLD，金光堆得太满","textZh":"由 gaudy 的形音联到 gold（金色）：一只小手袋上塞满大金链、金扣和闪亮吊饰，件件抢眼，凑在一起反而俗气。用“金饰堆过头”记俗丽。","kind":"invented_association","weak":false,"original":true},{"method":"GAUDY / 高低，全身挂满装饰","textZh":"把 gaudy 的声音联到“高低”：高处的帽檐挂亮片，低处的裙摆缀彩球，身上从高到低都塞满抢眼饰物。不是高低本身俗气，而是装饰多得失去分寸。","kind":"invented_association","weak":false,"original":false}]},"6148":{"word":"gear","mnemonics":[{"method":"GEAR，换挡来适应路况","textZh":"gear 也指车的挡位。上坡不能一直硬用平路的挡位，要换到适合坡度的挡；把这个“按需要调一调”搬到课程或计划上，就是动词 gear。","kind":"word_family","weak":false,"original":false},{"method":"GEAR 里的 EAR，照听众的耳朵来调整","textZh":"在 gear 中认出完整的 ear（耳朵）：原稿满是专业术语，台下却是小学生，便把术语换成生活中的说法。让内容适合这群听众的耳朵，记“调整以配合”。","kind":"invented_association","weak":false,"original":true}]},"6149":{"word":"genteel","mnemonics":[{"method":"GENTEEL / GENTLEMAN，绅士的礼数","textZh":"看到 genteel 的 gent-，联到熟悉的 gentleman（绅士）：不抢话，先请客人落座，再把茶递过去。用绅士待客的礼数，记“有教养、文雅”。","kind":"word_family","weak":false,"original":false},{"method":"GENTEEL / GENTLE，把轻柔带进举止","textZh":"genteel 与 gentle 同源。gentle 让人想到轻柔、不粗暴；把这种轻柔放进社交举止：轻放杯碟、温声致谢，连拒绝也说得体面。由动作的温柔，连到举止的文雅。","kind":"word_family","weak":false,"original":false}]},"6150":{"word":"gibe","mnemonics":[{"method":"GIBE / 假吧？一句话挖苦人","textZh":"把 gibe 的声音联到“假吧？”：同学刚拿出奖牌，就有人撇嘴说：“你这奖牌是假的吧？”不是真心求证，而是故意用话刺人。","kind":"invented_association","weak":false,"original":true},{"method":"GIBE / GIVE，给人难堪的那句话","textZh":"gibe 和 give（给）只差一个字母。把 give 联到“给人难堪”：别人认真练完一首曲子，他却故意说“这也叫会弹？”记住这种给人难堪的挖苦话，就是 gibe。","kind":"invented_association","original":true,"weak":false}]},"6151":{"word":"gild","mnemonics":[{"method":"GILD / GOLD，镀金不等于变成真金","textZh":"gild 与 gold（金）同源，字形也只差一个元音。普通金属外面镀一层金，看起来贵重，里面却没变；把这层“金色包装”用在事实或形象上，就是粉饰。","kind":"word_family","weak":false,"original":false},{"method":"GILD / GUILT，把过错说得漂亮","textZh":"把 gild 的形音联到 guilt（罪责、内疚）：明明是失职，却把经过说成“为了团队冒险”。过错没改，措辞却漂亮了，记“粉饰、润色”。","kind":"invented_association","weak":false,"original":true}]},"6152":{"word":"gist","mnemonics":[{"method":"GIST / LIST，从长清单提取中心","textZh":"gist 和 list 只差首字母。把一段讲话列成 list（清单），再把细节划掉，留下贯穿这些内容的中心意思；那就是 gist，而不是整份清单。","kind":"invented_association","weak":false,"original":false},{"method":"GIST / 记事，只记最重要的一句","textZh":"把 gist 的声音联到“记事”：电话里交代了许多细节，你在记事本上只写“明早九点交报告”。抓住中心意思，不逐字抄录，记主旨、大意。","kind":"invented_association","weak":false,"original":true}]},"6153":{"word":"gigantic","mnemonics":[{"method":"GIGANTIC / GIANT，巨人尺度","textZh":"gigantic 和 giant（巨人）同源，gigant- 保留了巨人的词形。想象巨人的鞋像一条小船，普通人的东西放旁边都显得很小；用巨人的尺度记“巨大”。","kind":"word_family","weak":false,"original":false},{"method":"GIGANTIC / GIGA，手机容量背后的大数","textZh":"看到 giga-，联到手机容量 GB 中的 G：它对应 giga，表示十亿这一数量级。由容量标记背后的巨大数字，记 gigantic 所说的规模巨大。","kind":"word_family","weak":true,"original":false}]},"6154":{"word":"glaze","mnemonics":[{"method":"GLAZE / GLASS，给表面添一层玻璃般的光","textZh":"glaze 来自 glass（玻璃）的词族。粗糙的陶杯上釉烧好后，表面有了玻璃般光滑发亮的一层；由 glass 的质感记住“上釉、上光”。","kind":"word_family","weak":false,"original":false},{"method":"GLAZE / CLAY，泥坯还差最后一层","textZh":"把 glaze 的形音联到 clay（黏土）：泥坯杯做好了，表面还粗糙，接着刷上釉料再烧，才有光亮的外层。由做陶杯的材料，记后面的上釉工序。","kind":"invented_association","weak":false,"original":true}]},"6155":{"word":"glib","mnemonics":[{"method":"GLIB / GLIDE，话滑过去，责任不肯接","textZh":"把 glib 的形音联到 glide（滑行）：问他事情为何没做好，他的漂亮话像在冰面上滑行，顺畅得很，却滑开了该承担的责任。由“说得顺、态度滑”记油腔滑调。","kind":"invented_association","weak":false,"original":true},{"method":"GLIB / LIP，嘴上像抹了油","textZh":"把 glib 中的 lib 联到 lip（嘴唇）：想象一张像抹了油的嘴，张口就是“包在我身上”，实际根本不想兑现。借“油嘴”记说话圆滑、不真诚。","kind":"invented_association","weak":false,"original":false}]},"6156":{"word":"glisten","mnemonics":[{"method":"GLISTEN / GLASS，雨后玻璃上的亮光","textZh":"把 glisten 的开头形音联到 glass（玻璃）：雨停后，窗玻璃还挂着水珠，阳光照来，一颗颗亮起来。由玻璃与水珠的反光记 glisten。","kind":"invented_association","weak":false,"original":true},{"method":"GLISTEN / LISTEN，听流水，也看水光","textZh":"glisten 里面完整藏着 listen（听）。想象站在阳光下的小溪旁，listen to the water，耳边是哗哗流水，眼前水纹同时闪着亮光。把水声和水面闪光一起记住：listen 用耳，glisten 是水面发亮。","kind":"invented_association","original":true,"weak":false}]},"6157":{"word":"glitch","mnemonics":[{"method":"GLITCH / ITCH，机器也有小毛病","textZh":"glitch 后面完整藏着 itch（痒）。人偶尔发痒，不是全身出了大问题；把机器临时卡一下想成它的小痒处，记小故障。","kind":"invented_association","weak":false,"original":true},{"method":"GLITCH / SWITCH，按开关却没亮","textZh":"glitch 和 switch（开关）都以 itch 结尾。想象按下台灯开关，灯没亮；再按一次又恢复正常。从开关处的一次不正常反应，记 glitch：小故障。","kind":"invented_association","weak":false,"original":true}]},"6158":{"word":"gloss","mnemonics":[{"method":"GLOSS / LOSS，把亏损一笔带过","textZh":"gloss 中能直接看到 loss（损失）。汇报时只大谈成绩，碰到 loss 就用“有点小波动”匆匆带过。由不肯认真讲损失，记 gloss over：敷衍、掩饰问题。","kind":"invented_association","weak":false,"original":true},{"method":"GLOSS / GLASS，亮表面盖不住里面的问题","textZh":"把 gloss 联到 glass（玻璃）：破旧桌面盖上一块亮玻璃，看着光鲜，下面的裂缝却没修。谈问题也只盖一层漂亮话，不认真面对，就是 gloss over。","kind":"invented_association","weak":false,"original":true}]},"6159":{"word":"glossy","mnemonics":[{"method":"GLOSSY / GLASSY，像玻璃一样平滑发亮","textZh":"glossy 与 glassy（像玻璃的）只差一个元音，glass 就是玻璃。想象漆面托盘像玻璃表面一样平滑，映出一道亮光，记 glossy 的光滑有光泽。","kind":"invented_association","weak":false,"original":true},{"method":"GLOSSY / HAIR LOSS，露出亮亮的头顶","textZh":"在 glossy 里认出完整的 loss（失去），联到 hair loss（掉头发）。想象漫画里一位头顶光光的人，灯下一照，平滑的头皮上反出一道亮光。用这块亮亮的表面，记住 glossy：平滑而有光泽。","kind":"invented_association","original":true,"weak":false}]},"6160":{"word":"glutinous","mnemonics":[{"method":"GLUTINOUS / GLUE，勺子被糊黏住","textZh":"glutinous 的开头读来像 glue（胶水）。提起沾满稠糊的勺子，糊像胶一样黏着不肯落下；抓住“像 glue 一样黏”的触感。","kind":"invented_association","weak":false,"original":false},{"method":"GLUTINOUS / GLUTEN，面团的黏连","textZh":"把 glutinous 联到 gluten（面筋蛋白）：揉面时，面团会黏连、拉伸，借这种手感记“黏的”。这里记的是质地，不是说所有 glutinous 的食物都含 gluten。","kind":"word_family","weak":true,"original":false}]},"6161":{"word":"glutton","mnemonics":[{"method":"GLUTTON / 咕噜吞，吃饱还往下吞","textZh":"把 glutton 的声音联到“咕噜吞”：桌上的人已经吃饱，却仍盯着下一盘，咕噜咕噜继续往下吞。记住这个总想多吃的人，就是贪吃者。","kind":"invented_association","weak":false,"original":true},{"method":"GLUTTON / BUTTON，吃撑了还要加餐","textZh":"glutton 和 button（纽扣）的后半形音相近。想象一个人吃得腰间纽扣都绷紧了，还伸手要加一份甜点；由“撑着纽扣还要吃”记贪吃者。","kind":"invented_association","weak":false,"original":false}]},"6162":{"word":"gobble","mnemonics":[{"method":"GOBBLE / GO + BOWL，冲着饭碗开吃","textZh":"把 gobble 的形音联成 go（去）和 bowl（碗）：一开饭就冲向饭碗，端起来接连大口吃，顾不上慢慢嚼。由“冲向碗、大口吃”记狼吞虎咽。","kind":"invented_association","weak":false,"original":true},{"method":"GOBBLE / 嘎嘣嘎嘣，一口紧接一口","textZh":"把 gobble 的声音联到“嘎嘣”：饼干刚端上来，他就大口咬下去，嘎嘣嘎嘣一口接一口，别人还在慢慢尝，他已经吃完了一块。用这串急促的咬食声，记住狼吞虎咽。","kind":"invented_association","original":true,"weak":false}]},"6163":{"word":"goggle","mnemonics":[{"method":"GOGGLE / 勾勾，眼睛直勾勾","textZh":"把 goggle 的声音联到“勾勾”：看到不可思议的东西，眼睛睁得老大，直勾勾地盯着不动。记的是惊奇地瞪看，不是随便看一眼。","kind":"invented_association","weak":false,"original":false},{"method":"GOGGLE / GOOGLE，搜出结果看呆了","textZh":"goggle 与 Google（谷歌）的字形很接近。想象搜出一张意想不到的照片，你惊得瞪大眼睛，停在屏幕前看了好久；由熟悉的搜索页记“惊奇地瞪看”。","kind":"invented_association","weak":false,"original":true}]},"6164":{"word":"goldbrick","mnemonics":[{"method":"GOLDBRICK / GOLD + BRICK，镀金砖般的假忙碌","textZh":"gold（金）加 brick（砖），想到外面金灿灿、里面不值钱的假金砖。有人也是表面忙碌：反复擦同一把工具，却把分给自己的活丢在一旁。由“外面好看、不真干活”记逃避工作。","kind":"invented_association","weak":false,"original":false},{"method":"GOLDBRICK / GO + BREAK，一有活就去休息","textZh":"把 goldbrick 的整体形音联到 go（去）加 break（休息）：任务刚分下来，他就说“我去休息一下”，把该干的活留给别人。借“有活却 go for a break”记偷懒、逃避责任。","kind":"invented_association","weak":false,"original":true}]},"6165":{"word":"gorge","mnemonics":[{"method":"GORGE / 沟儿，两壁夹着一条深沟","textZh":"把 gorge 的声音联到“沟儿”：不是路边的小沟，而是两面陡峭岩壁夹着的一条巨大深沟，河水在底部流过。由“山间深沟儿”记峡谷。","kind":"invented_association","weak":false,"original":true},{"method":"GORGE / TORCH，火光照出两道峭壁","textZh":"把 gorge 的声音联到 torch（火把）：夜里沿山间深沟探路，火把一举，左右两道岩壁陡直耸起，脚下是谷底急流。用火光照出的狭深谷地，记 gorge，峡谷。","kind":"invented_association","weak":false,"original":true}]},"6166":{"word":"gourmet","mnemonics":[{"method":"GOURMET / 够美，细品才夸味道美","textZh":"把 gourmet 的声音联到“够美”：这人尝一小口，细细辨出汤的鲜味、香料和回味，再赞一句“这味道够美！”记的是会鉴赏的人，不是只管多吃的人。","kind":"invented_association","weak":false,"original":true},{"method":"GOURMET / GOOD MEAL，专会挑好饭的人","textZh":"把 gourmet 的整体形音联到 good meal（好的一餐）。同桌的人不急着吃，而是比较食材、火候和搭配，指出这顿饭究竟好在哪里；从“懂 good meal 的人”记美食家。","kind":"invented_association","weak":false,"original":true}]},"6167":{"word":"grandeur","mnemonics":[{"method":"GRANDEUR / GRAND，宏伟变成一种气势","textZh":"抓住 grandeur 里的 grand（宏伟的）。grand 描述宫殿、山川很宏伟，grandeur 则把那份令人仰望赞叹的气势作为一个名词来谈：宏伟、壮丽。","kind":"word_family","weak":false,"original":false},{"method":"GRANDEUR / GRAND DOOR，仰头看宫殿大门","textZh":"把 grandeur 的形音联到 grand door（宏大的门）：一座宫殿的大门高到要仰头才能看到顶，人站在门前显得很小。由这扇大门带来的震撼，记宏伟壮丽的气势。","kind":"invented_association","weak":false,"original":true}]},"6168":{"word":"grandiloquent","mnemonics":[{"method":"GRANDILOQUENT / GRAND + LOQU，说得大过了头","textZh":"grand 表示“大”，loqu 表示“说”。把一件很小的事讲成惊天动地的大功业，话说得格外堂皇，却远远超过实情：这就是语言浮夸。","kind":"etymology","weak":false,"original":false},{"method":"GRANDILOQUENT / GRAND + LIQUID，大话像液体涌出来","textZh":"把 grandiloquent 的形音联成 grand（宏大的）加 liquid（液体）：讲话者嘴里仿佛不断涌出“大话之水”，把一个小小成绩冲成了“改变世界的壮举”。由“大话流个不停”记浮夸的言辞。","kind":"invented_association","weak":true,"original":true}]},"6169":{"word":"grandstand","mnemonics":[{"method":"GRANDSTAND / GRAND + STAND，站出来摆大架势","textZh":"grand（盛大的）加 stand（站）：轮到做一件普通小事，他偏要站到众人面前摆足大架势，动作特别夸张，还不断看有没有人鼓掌。由“站出来做一番大表演”记哗众取宠。","kind":"invented_association","weak":false,"original":true},{"method":"GRANDSTAND / 看台，把比赛打给观众看","textZh":"grandstand 作名词是体育场的看台。想象一个球员不选稳妥有效的传球，却特意对着看台做花哨动作，只想博取欢呼；从“专演给看台看”记它的动词义：哗众取宠。","kind":"word_family","weak":false,"original":false}]},"6170":{"word":"grate","mnemonics":[{"method":"GRATE / 刮得，刮得耳朵难受","textZh":"把 grate 的声音联到“刮得”：金属椅脚拖过石地板，刮得吱啦作响，旁边的人立刻捂住耳朵。由“刮得刺耳”记刮擦发声。","kind":"invented_association","weak":false,"original":true},{"method":"GRATE / GATE，大门下沿刮着地面","textZh":"grate 比 gate（大门）多一个 r。想象大门歪斜下沉，下沿紧贴石地；每推开一点，就拖出一阵粗涩的摩擦声。把相似的字形和门底刮地的声音一起记住。","kind":"invented_association","weak":false,"original":false}]},"6171":{"word":"grieve","mnemonics":[{"method":"GRIEVE / GRAVE，在墓前悲伤","textZh":"把 grieve 的整体字形联到 grave（坟墓）：一个人把花放在亲人的墓前，想起往日相处，悲伤得说不出话。从 grave 的场景记 grieve，深感悲伤。","kind":"invented_association","weak":false,"original":true},{"method":"GRIEVE / 哥 LEAVE，哥哥离开时舍不得","textZh":"把 grieve 的声音联成“哥 leave”：哥哥要离开家去很远的地方，你站在门口送别，越想以后不能常见面，心里越难过。由“哥离开，我悲伤”记这个动词。","kind":"invented_association","weak":false,"original":true}]},"6172":{"word":"glamorous","mnemonics":[{"method":"GLAMOROUS / CAMERAS，相机都追着她","textZh":"把 glamorous 的整体声音联到 cameras（相机，复数）：她盛装走上红毯，一排相机齐刷刷转过来，闪光灯追着她，现场目光都被吸引。用让相机争相捕捉的光彩，记 glamorous，光彩迷人。","kind":"invented_association","weak":false,"original":true},{"method":"GLAMOROUS / GRAMMAR，语法书变出迷人礼服","textZh":"把 glamorous 的前半形音联到 grammar（语法），后面是形容词结尾 -ous：想象一本语法书被施了魔法，书页展开竟变成流光溢彩的晚礼服，穿上它的人立刻光彩迷人。用 grammar 书变出迷人礼服的画面，记 glamorous。","kind":"invented_association","weak":false,"original":true}]},"6173":{"word":"grin","mnemonics":[{"method":"GRIN / GREEN，一咧嘴露出绿菜叶","textZh":"把 grin 的形音联到 green（绿色）：朋友本来笑得抿着嘴，一被逗乐就咧开嘴，露出牙齿上的一小片绿菜叶。把 green 和露齿的宽大笑容连在一起。","kind":"invented_association","weak":false,"original":true},{"method":"GRIN / WIN，赢了以后咧嘴笑","textZh":"把 grin 和 win（获胜）连着念，记住它们相近的收尾音：最后一分拿下，你举起写着 WIN 的牌子，嘴角一下咧开，露着牙笑。用获胜时那张藏不住喜悦的笑脸，记 grin。","kind":"invented_association","weak":false,"original":true}]},"6174":{"word":"gripe","mnemonics":[{"method":"GRIPE / GRAPE，酸葡萄引出一串牢骚","textZh":"gripe 和 grape（葡萄）只差中间一个字母。想象买来一串号称香甜的葡萄，吃一颗酸一颗，便一路念叨：“这么贵，还这么酸！”用葡萄引出的不满牢骚记 gripe。","kind":"invented_association","weak":false,"original":false},{"method":"GRIPE / 该赔，一直念叨该赔钱","textZh":"把 gripe 的声音联到“该赔”：新买的杯子一打开就发现裂了，买家不停念叨“质量太差了，你们该赔！”从这串表达不满的话记抱怨，不把它当作正式索赔的专门术语。","kind":"invented_association","weak":false,"original":true}]},"6175":{"word":"grisly","mnemonics":[{"method":"GRISLY / 鬼戏里，转过来的脸没有五官","textZh":"把 grisly 的声音联到“鬼戏里”：想象你正在看一场鬼戏，演员慢慢转过脸，竟没有五官，只剩一片空白，观众吓得倒吸一口气。用鬼戏里这幅令人发毛的画面，记 grisly，毛骨悚然的。","kind":"invented_association","weak":false,"original":true},{"method":"GRISLY / GREY + SLEEVE，灰袖里伸出白骨","textZh":"把 grisly 的形音联到 grey（灰色）和 sleeve（袖子）：恐怖片里一截灰袖慢慢伸过来，袖口露出的不是手，而是白骨，你吓得不敢再看。由灰袖里伸出白骨的画面，记 grisly，令人毛骨悚然。","kind":"invented_association","weak":false,"original":true}]},"6176":{"word":"groove","mnemonics":[{"method":"GROOVE / MOVE，音乐一起就开心地动","textZh":"groove 的尾部形音联到 move（动起来）。想象最喜欢的歌一响，你便笑着随节拍摆动身体，越听越投入。由开心地 move 记 groove，尽情享受。","kind":"invented_association","weak":false,"original":true},{"method":"GROOVE / 鼓舞，鼓声把人带进快乐里","textZh":"把 groove 的声音联到“鼓舞”：节庆现场鼓声一阵接一阵，人们被欢乐的气氛感染，跟着拍手摇摆，舍不得离开。把鼓声带来的快活感与 groove 连起来。","kind":"invented_association","weak":false,"original":true}]},"6177":{"word":"grotesque","mnemonics":[{"method":"GROTESQUE / GROW + DESK，课桌长歪了","textZh":"把 grotesque 的整体形音联到 grow（生长）和 desk（课桌）：想象一张课桌像植物一样长起来，四条腿长短不齐，桌面扭成歪脸。记住这张长得怪模怪样、难看的桌子。","kind":"invented_association","weak":false,"original":true},{"method":"GROTESQUE / CROW + MASK，歪嘴乌鸦面具","textZh":"把 grotesque 的形音联到 crow（乌鸦）和 mask（面具）：万圣节面具做成乌鸦脸，可鸟嘴歪到一旁，眼睛一大一小，还长着人的牙。用这张比例怪异的乌鸦面具，记 grotesque，怪模怪样、奇形怪状。","kind":"invented_association","weak":false,"original":true}]},"6178":{"word":"grovel","mnemonics":[{"method":"GROVEL / GROUND + LEVEL，把自己压到地面那么低","textZh":"把 grovel 联到 ground（地面）和 level（高度）：想象一个人为了求宽恕，把腰越弯越低，头几乎到了地面的高度，还不断央求对方。用 ground level 的低姿态记卑躬屈膝。","kind":"invented_association","weak":false,"original":true},{"method":"GROVEL / 跪服了，低头央求别生气","textZh":"把 grovel 的声音联到“跪服了”：做错事的人双膝一软，低着头反复说“求您原谅，我什么都听您的”。由屈膝低头、过分顺从的求饶姿态记 grovel。","kind":"invented_association","weak":false,"original":true}]},"6179":{"word":"grueling","mnemonics":[{"method":"GRUELING / CRUEL + -ING，严酷训练让人累垮","textZh":"把 grueling 的形音联到 cruel（残酷的）再接 -ing：想象教练把冲刺、爬坡和搬重物接连排在一起，训练严酷得让人精疲力竭。由 cruel 的训练记艰苦累人。","kind":"invented_association","weak":false,"original":true},{"method":"GRUELING / 苦力 + ING，一直干重活","textZh":"把 grueling 的声音联成“苦力-ing”：搬运工正一趟接一趟地把沉重麻袋搬上楼，汗湿衣服，双腿越来越沉。用正在不停干苦力的画面记极耗体力；脑力工作同样可以 grueling。","kind":"invented_association","weak":false,"original":true}]},"6180":{"word":"gull","mnemonics":[{"method":"GULL / FULL，标着满瓶却是空的","textZh":"gull 与 full 只差开头字母。想象商家把空瓶封好，贴上 FULL（满的）标签卖给你；你信了标签，买回去才发现被骗。用假的 FULL 记 gull，欺骗。","kind":"invented_association","weak":false,"original":true},{"method":"GULL / GOAL，假球门骗你射门","textZh":"把 gull 的整体形音联到 goal（球门）：有人把一扇逼真的球门画在墙上，还招呼你快射门；你信以为真，一脚把球踢向了墙。用假 goal 让人上当的画面，记 gull，欺骗。","kind":"invented_association","weak":false,"original":true}]},"6181":{"word":"gush","mnemonics":[{"method":"GUSH / RUSH，赞美的话争着往外冲","textZh":"gush 的形音联到 rush（冲）：朋友的表演太精彩，你的赞美一句追一句冲出口，停不下来。由话语 rush 出来的样子记感情强烈外溢。","kind":"invented_association","weak":false,"original":true},{"method":"GUSH / 故事，讲到激动处收不住话","textZh":"把 gush 的声音联到“故事”：重逢时讲起小时候的故事，你越讲越激动，满心的喜爱和感激一股脑说出来。由讲故事时感情满溢、话语不停记 gush。","kind":"invented_association","weak":false,"original":true}]},"6182":{"word":"gust","mnemonics":[{"method":"GUST / 一阵风，情绪突然卷起来","textZh":"把 gust 的一阵强风想成心里突然刮起的风：刚收到重逢的消息，原本平静的人一下笑出声，喜悦猛地涌上来又渐渐平息。用短促强烈的一阵风记情感爆发。","kind":"invented_association","weak":false,"original":true},{"method":"GUST / GUEST，门口来客让喜悦突然爆发","textZh":"gust 的字形联到 guest（客人）：门一打开，久未见面的朋友突然站在眼前，你一下欢呼起来。用意外来客触发的那一阵强烈喜悦记 gust。","kind":"invented_association","weak":false,"original":true}]},"6183":{"word":"guzzle","mnemonics":[{"method":"GUZZLE / 咕滋溜，一大杯转眼喝光","textZh":"把 guzzle 的声音联成“咕滋溜”：跑完步的人举起大杯，咕咚接咕咚，滋溜一下喝见了底。用连声吞咽、大口灌下的声音记狂饮。","kind":"invented_association","weak":false,"original":true},{"method":"GUZZLE / GOOSE + ALL，大鹅把水喝个精光","textZh":"把 guzzle 的形音联到 goose（鹅）和 all（全部）：想象一只大鹅把头伸进水桶，咕咚咕咚地喝，转眼把整桶水喝光。用“大鹅把水全喝光”的画面，记 guzzle，大口狂饮。","kind":"invented_association","weak":false,"original":true}]},"6184":{"word":"hack","mnemonics":[{"method":"HACK / 黑客，键盘写手只认钱","textZh":"把 hack 的声音联到“黑客”，只借那双飞快敲键盘的手：画面里的工作却是代写文章，付钱的人要什么，他就拼凑什么，质量好坏一概不管。记住这位只认钱的键盘写手。","kind":"invented_association","weak":true,"original":true},{"method":"HACK / PACK，把文章成包卖","textZh":"hack 与 pack（包）只差开头字母。想象写手把一篇旧文章换几个名字，成包卖给不同刊物；只数卖了多少包，不管文章写得怎样。用批量打包的文章记雇佣文人。","kind":"invented_association","weak":true,"original":true}]},"6185":{"word":"hackneyed","mnemonics":[{"method":"HACKNEYED / 哈，腻了！","textZh":"把 hackneyed 的声音联到“哈，腻了”：同一个笑话讲了十遍，你连包袱都能背出来，只剩一句“听腻了”。记住反复用到没有新意，就是 hackneyed。","kind":"invented_association","weak":false,"original":true},{"method":"HACKNEYED / BACK + KNEE，还是那套单膝求婚","textZh":"把 hackneyed 的形音联到 back（回到）和 knee（膝盖）：爱情短片又回到熟悉的场面，男主捧花、单膝跪下，连求婚台词都和前几部一模一样。由这套又回来的旧桥段，记 hackneyed，陈腐、没有新意。","kind":"invented_association","weak":false,"original":true}]},"6186":{"word":"hale","mnemonics":[{"method":"HALE / PALE，换掉苍白，恢复硬朗","textZh":"hale 和 pale（苍白的）只差首字母。想象老人病愈后脸色不再 pale，步子稳、力气足；用从苍白虚弱转为硬朗的对比记 hale。","kind":"invented_association","weak":false,"original":true},{"method":"HALE / WHOLE，身体完整有力","textZh":"把 hale 的整体字形联到 whole（完整的）：体检时心、肺、四肢都状态良好，整个人完整有力。whole 的“全身都好”帮你记 hale，身体健壮。","kind":"invented_association","weak":false,"original":true}]},"6187":{"word":"half-baked","mnemonics":[{"method":"HALF + BAKED，主意还没烤熟","textZh":"half 是一半，baked 是烤过的。把一个主意想成只烤到一半就端上桌的面包：里面还生着，当然不可靠。由半生不熟记考虑不周、不明智。","kind":"invented_association","weak":false,"original":true},{"method":"HALF-BAKED / HALF-BACKED，只有一半依据","textZh":"half-baked 的形音联到 half-backed：计划只被一半证据支持，另一半关键问题还没人核实，就急着拍板。用“支持还缺一半”的画面，记下没有想周全的不明智决定。","kind":"invented_association","weak":false,"original":true}]},"6188":{"word":"hallucination","mnemonics":[{"method":"HALLUCINATION / IMAGINATION，把想象当成事实","textZh":"把 hallucination 的长词形和结尾联到 imagination（想象）：你只是在脑中想象自己已经是冠军，却当真认为奖杯必定属于自己。由把想象信以为真，记这一义的错误观念。","kind":"invented_association","weak":true,"original":true},{"method":"HALL + NATION，一个大厅装得下全国？","textZh":"看 hallucination 时联到 hall（大厅）和 nation（全国）：有人认定一个普通大厅能装下全国的人，还据此安排活动。大厅和全国之间明显不相称，提醒你这是错误信念，不是现实。","kind":"invented_association","weak":true,"original":true}]},"6189":{"word":"ham-handed","mnemonics":[{"method":"HAM + HAND，火腿手夹不起小珠子","textZh":"ham 是火腿，hand 是手。想象两只手戴上厚厚的火腿形手套，想捏起小珠子却总把它推跑；用粗厚的“火腿手”记动作不灵巧。","kind":"invented_association","weak":false,"original":true},{"method":"HAM-HANDED / HAMMER HAND，用锤子手修小表","textZh":"ham-handed 联到 hammer hand（锤子手）：修理小手表时，手像一把锤子，只会笨重地敲，拨不准小零件。由细活遇上锤子手记笨手笨脚。","kind":"invented_association","weak":false,"original":true}]},"6190":{"word":"hammer","mnemonics":[{"method":"HAMMER / 锤子把重点敲进去","textZh":"先想起 hammer 的常见意思“锤子”：钉子要一下一下敲才扎得牢，重点也要一遍一遍说才记得牢。从反复敲击转到反复强调，记住 hammer 的重申义。","kind":"invented_association","weak":false,"original":true},{"method":"HAMMER / 喊嘛，同一个重点喊到记牢","textZh":"把 hammer 的声音联到“喊嘛”：排练时，老师让大家把最重要的一句口令再喊一遍、再喊一遍，直到人人记牢。用这句口令被反复喊出的场面，记 hammer，屡次重申。","kind":"invented_association","weak":false,"original":true}]},"6191":{"word":"hangdog","mnemonics":[{"method":"HANG + DOG，耳朵垂下的小狗","textZh":"hang 是垂下，dog 是狗。小狗看着主人带别人去散步，耳朵和尾巴都垂下来；把这种失落的狗脸联到人的 hangdog expression，沮丧的表情。","kind":"invented_association","weak":false,"original":true},{"method":"HANGDOG / HANG DOWN，头低得抬不起来","textZh":"hangdog 的整体形音联到 hang down（垂下）：比赛失利后，头和肩膀都耷拉下来，不想看人。用头往下垂的身体动作，记住 hangdog 的垂头丧气。","kind":"invented_association","weak":false,"original":true}]},"6192":{"word":"hanker","mnemonics":[{"method":"HANKER / HUNGER，从肚子饿到心里想要","textZh":"hanker 的形音联到 hunger（饥饿）：肚子饿时总惦记吃的，心里 hanker for 一件事时也总惦记着它。把身体想吃东西的强烈需求，转为心里强烈的渴望。","kind":"invented_association","weak":false,"original":true},{"method":"HANKER / 喊渴，盼着喝到水","textZh":"把 hanker 的声音联到“喊渴”：跑完长路的人不停喊渴，眼睛一直望着远处的水壶。由喊着口渴、盼望喝水，记住 hanker，强烈而持续地想要。","kind":"invented_association","weak":false,"original":true}]},"6193":{"word":"harangue","mnemonics":[{"method":"HARANGUE / 还嚷，讲了半天还没完","textZh":"把 harangue 的声音联到“还嚷”：听众已经看了好几次表，台上的人还挺着胸口，滔滔不绝地讲大道理。由“怎么还在嚷着讲”，记住冗长而夸夸其谈的讲话。","kind":"invented_association","weak":false,"original":true},{"method":"HARANGUE / HER RANK，盯着名次讲个没完","textZh":"把 harangue 的声音联到 her rank（她的名次）：老师看见她的名次掉了两位，原本一句提醒，却从学习态度讲到每天作息，讲了半小时还没结束。用围着名次展开的长篇训话，记 harangue。","kind":"invented_association","weak":false,"original":true}]},"6194":{"word":"harass","mnemonics":[{"method":"HARASS / 还惹事，拒绝后还来烦","textZh":"把 harass 的声音联到‘还惹事’：你已经说了别打扰，他还一次次敲门、打电话，不肯让你清静。抓住‘被拒绝后还来烦’的反复感，记住骚扰、不断烦扰。","kind":"invented_association","weak":false,"original":true},{"method":"HARASS / HARD + ASK，硬追着问个不停","textZh":"把 harass 的形音联到 hard（强硬地）和 ask（问）：别人已经说不愿回答，提问者仍堵在身边，一遍遍追问。把硬要追着问的烦扰感，连到 harass。","kind":"invented_association","weak":false,"original":true}]},"6195":{"word":"harbinger","mnemonics":[{"method":"HARBINGER / 哈尔滨哥，先看出冬天要来","textZh":"把 harbinger 的整体形音联到“哈尔滨哥”：哈尔滨的哥哥看到窗边第一层薄霜，就提醒你冬天快来了。记住他指给你看的那层霜：它是冬天将至的预兆。","kind":"invented_association","weak":false,"original":true},{"method":"HARBINGER ↔ HARBOR，先到一步安排住处","textZh":"harbinger 与 harbor（港湾、庇护处）有共同的词源背景。想象大队人马未到，先来一人安排住处；客栈见到他，就知道后面的人快到了。由这个先到的人，记住 harbinger：预告后来之事的人或征兆。","kind":"etymology","weak":false,"original":true}]},"6196":{"word":"harbor","mnemonics":[{"method":"HARBOR / 心里的港湾，让念头停泊","textZh":"harbor 的常见名词义是港湾。把心想成一个港湾：船在那里停着不走，某个念头也在心里长久停留。由“留住船”转到“留住想法、感情”，记住 harbor 的心怀义。","kind":"invented_association","weak":false,"original":true},{"method":"HARBOR / HEART + BOX，心中的盒子","textZh":"把 harbor 的形音联到 heart（心）和 box（盒子）：一个人把对旧事的怨气锁在心中的盒子里，隔了很久仍不肯放下。由把感情藏在心里留着，记住 harbor。","kind":"invented_association","weak":false,"original":true}]},"6197":{"word":"hard-bitten","mnemonics":[{"method":"HARD + BITTEN，被生活狠狠咬过仍站着","textZh":"hard 是猛烈地，bitten 是 bite（咬）的过去分词。想象生活一次次“咬”来困难，他身上留下痕迹却仍站得稳。把经历过苦头后练出的坚韧，连到 hard-bitten。","kind":"invented_association","weak":false,"original":true},{"method":"HARD-BITTEN / HARD BEATEN，被打倒又站起","textZh":"hard-bitten 的整体形音联到 hard beaten：比赛里屡次遭到重击的老拳手，学会稳住脚步、扛住压力。由吃过败仗后练出的硬气，记住久经磨炼、经得住困境。","kind":"invented_association","weak":false,"original":true}]},"6198":{"word":"hardy","mnemonics":[{"method":"HARDY / HARD，条件再苦也扛得住","textZh":"从 hardy 一眼认出 hard（艰苦的）：同样放在寒冷庭院里，有的花蔫了，有的仍挺立。把能扛住 hard conditions 的生命力连到 hardy，而不是把花茎想成硬邦邦。","kind":"invented_association","weak":false,"original":true},{"method":"HARDY / HARD + DIE，很难死掉","textZh":"把 hardy 的整体形音联到 hard（难）和 die（死）：一株小草经风霜仍活着，想让它倒下可不容易。由“很难死掉”的顽强生命力，记住 hardy，耐寒、耐艰苦。","kind":"invented_association","weak":false,"original":true}]},"6199":{"word":"harmonious","mnemonics":[{"method":"HARMONIOUS ↔ HARMONY，把不同声音合成和声","textZh":"harmonious 联到较常见的 harmony（和声、和谐）。想起合唱里高声部和低声部：唱的音不相同，合在一起却很悦耳。由不同部分配合得好，记住 harmonious，不是所有部分必须一样。","kind":"word_family","weak":false,"original":true},{"method":"HARMONIOUS / HARM + MINUS，把伤害减下去","textZh":"把 harmonious 的整体形音联到 harm（伤害）和 minus（减）：讨论方案时，大家把互相攻击的话一句句减掉，改成你补充我、我配合你。用“伤害做减法，合作越来越协调”记 harmonious。","kind":"invented_association","weak":false,"original":true}]},"6200":{"word":"harness","mnemonics":[{"method":"HARNESS / HIRE + NURSE，让护理本领发挥作用","textZh":"把 harness 的整体形音联到 hire（聘请）和 nurse（护士）：救援队请护士加入，安排她负责伤口处理，让专业本领真正用在救人上。由把人的能力组织起来、发挥作用，记 harness，利用。","kind":"invented_association","weak":false,"original":true},{"method":"HARNESS ↔ HARDNESS，利用硬度来切玻璃","textZh":"harness 的拼写像 hardness（硬度）少了一个 d。想象玻璃刀把金刚石的硬度用在刀尖上，轻轻一划就能切割玻璃。不是只说材料硬，而是利用它的硬度办事：harness。","kind":"invented_association","weak":false,"original":true}]},"6201":{"word":"harrow","mnemonics":[{"method":"HARROW ↔ HORROR，恐怖画面折磨心神","textZh":"harrow 的形音联到 horror（恐怖）：看完恐怖片，那个画面还在眼前，躺下也心惊不安。用画面持续折磨心神的感觉，记住 harrow，使人痛苦、苦恼。","kind":"invented_association","weak":false,"original":true},{"method":"HARROW / H + ARROW，话像箭扎进心里","textZh":"harrow 里几乎完整地藏着 arrow（箭）。想象一句伤人的话像箭一样扎进心里，过了很久仍让人难受。由“话语刺痛内心”记住 harrow：折磨人的心神。","kind":"invented_association","weak":false,"original":true}]},"6202":{"word":"harry","mnemonics":[{"method":"HARRY ↔ HURRY，一遍遍催快点","textZh":"harry 与 hurry（赶快）只差中间一个字母。想象有人不停在你耳边催“hurry！hurry！”，刚停一会儿又来催，直到你烦躁不安。不是自己赶快，而是反复催扰别人：harry。","kind":"invented_association","weak":false,"original":true},{"method":"HARRY ↔ HAIRY，毛发反复蹭脖子","textZh":"harry 的形音联到 hairy（多毛的）：围巾边的一撮毛不断蹭脖子，你拨开一次，它又蹭回来。用这种一再打扰、不得安宁的感觉，记住 harry，不断烦扰。","kind":"invented_association","weak":false,"original":true}]},"6203":{"word":"hasten","mnemonics":[{"method":"HASTEN / HASTE + -EN，让进程快起来","textZh":"从 hasten 认出 haste（匆忙、迅速），-en 把它变成动词。想象把进度条往前推，原本明天才能完成的事今天就完成了。记住这里的 hasten 是使事情更快发生、加速进程。","kind":"word_family","weak":false,"original":true},{"method":"HASTEN / 还剩，倒计时催快进度","textZh":"把 hasten 的声音联到“还剩”：烘焙比赛最后还剩一分钟，助手立刻帮忙装盘，使完成时间提前。听到“还剩”的倒计时，就想到 hasten，加速完成的进程。","kind":"invented_association","weak":false,"original":true}]},"6204":{"word":"hauteur","mnemonics":[{"method":"HAUTEUR / 好头儿？抬着下巴看人","textZh":"把 hauteur 的整体声音联到“好头儿”：想象一个自称“好头儿”的主管，下巴抬得高高的，觉得人人都该听他的，连招呼也不愿回应。记住这副自认高人一等的傲慢态度。","kind":"invented_association","weak":false,"original":true},{"method":"HAUTEUR / HOT AIR，把自己吹上天","textZh":"把 hauteur 的声音联到 hot air（热空气）：想象一个人把自己吹成热气球，越升越高，低头看谁都觉得不如自己。用“把自己捧上天，把别人看得低”的姿态，记 hauteur，傲慢。","kind":"invented_association","weak":false,"original":true}]},"6205":{"word":"haven","mnemonics":[{"method":"HAVEN ↔ HEAVEN，乱世中的一小片天堂","textZh":"haven 比 heaven（天堂）少一个 e。想象外面兵荒马乱，跨进一座有热汤和床铺的小屋，终于能安心睡觉，仿佛进了小小的天堂。由这份安全感记住 haven：避难所。","kind":"invented_association","weak":false,"original":true},{"method":"HAVEN / 海湾，躲进湾里避风","textZh":"把 haven 的整体声音联到“海湾”：风浪追着小船，小船绕进有山遮挡的海湾，终于平稳下来。由能避开危险的海湾，记住 haven 是安全的地方。","kind":"invented_association","weak":false,"original":true}]},"6206":{"word":"havoc","mnemonics":[{"method":"HAVOC / 害我卡住了，整个车站乱套","textZh":"把 havoc 的声音联到“害我卡”：车站电脑突然瘫痪，闸机不开，人流堵成一团，有人急喊“害我卡在这里了！”用系统失灵、秩序乱套的场面记住 havoc。","kind":"invented_association","weak":true,"original":true},{"method":"HAVOC ↔ HACK，黑客让系统大乱","textZh":"把 havoc 的字形联到 hack（黑客入侵）：售票系统被入侵，车次和座位全错了，旅客争着找工作人员，车站一片混乱。记住这里的 havoc 是失控的大混乱。","kind":"invented_association","weak":true,"original":true}]},"6207":{"word":"headlong","mnemonics":[{"method":"HEADLONG / HEAD FIRST，头先冲，脑子没跟上","textZh":"headlong 有“头朝前”的本义。想象一个人听见抢购就头朝前冲出去，连价钱都没看：身体先动，考虑还没跟上。由一头扎进去，记住鲁莽、草率的意思。","kind":"word_family","weak":false,"original":true},{"method":"HEAD + LONG，一头扎进长队，没问卖什么","textZh":"看到 headlong，联到 head（头）和 long（长）：路边排着长长的队，他连卖什么都不问，就一头挤进去跟着抢。用“见长队就盲目跟”的画面，记住缺少考虑、贸然行动。","kind":"invented_association","weak":false,"original":true}]},"6208":{"word":"hearken","mnemonics":[{"method":"HEARKEN / HEAR，听见后认真听进去","textZh":"hearken 开头能看到 hear（听见）。想象背景里本来只有模糊人声，你忽然听见有人叫自己，便停下手里的事、转身认真听。由听见到专心听进去，记住 hearken。","kind":"word_family","weak":false,"original":true},{"method":"HEARKEN / 哈，肯听了","textZh":"把 hearken 的声音联到“哈，肯”：孩子终于放下吵闹的游戏，转过身安静听你说，你松口气：“哈，肯听了！”把肯安静听、把话听进去的动作，连到 hearken 的倾听、关注义。","kind":"invented_association","weak":false,"original":true}]},"6209":{"word":"hearten","mnemonics":[{"method":"HEART + -EN，给心添上勇气","textZh":"heart 除了心，也能表示勇气；-en 可构成动词。想象朋友快要放弃时，你说“再试一次，我陪你”，他心里重新有了勇气。把给心添力量连到 hearten：鼓舞。","kind":"word_family","weak":false,"original":true},{"method":"HEARTEN ↔ HEART + TEN，十颗红心为你加油","textZh":"把 hearten 的字形联到 heart（爱心）和 ten（十）：第一次上台唱歌很紧张，屏幕上朋友连送十颗红心，你便有信心继续唱。用十颗红心带来的鼓励，记住 hearten。","kind":"invented_association","weak":false,"original":true}]},"6210":{"word":"heartrending","mnemonics":[{"method":"HEART + ENDING，心中那段故事结束了","textZh":"heartrending 里能看到 heart（心）和 ending（结局）。想象陪你多年的小狗在故事结尾离去，最后只剩它空空的窝：这个 ending 让你的 heart 碎了。记住令人心碎、悲痛的。","kind":"invented_association","weak":false,"original":true},{"method":"HEART ↔ READING，读着信，心碎了","textZh":"把 heartrending 的后半段 rending 联到熟悉的 reading（阅读）：你捧着亲人留下的最后一封信，越读越忍不住落泪。用“读到心碎”的画面，记住 heartrending。","kind":"invented_association","weak":false,"original":true}]},"6211":{"word":"hedonism","mnemonics":[{"method":"HEDONISM / 嗨得很 + -ISM，把快乐当人生准则","textZh":"把 hedon- 的声音联到“嗨得很”，再接表示主义的 -ism。想象一个人做选择先问的总是“哪个更让我快乐？”吃喝玩乐都按这个准则安排。由把快乐放在首位，记 hedonism，享乐主义。","kind":"invented_association","weak":false,"original":true},{"method":"HEDONISM / HE + DINNER，美餐排在人生第一位","textZh":"把 hedon- 的形音联到 he（他）和 dinner（晚餐），再接表示主义的 -ism：他安排一天时，总先挑让自己最享受的一顿晚餐，其他事都围着这份快乐转。用“享受优先”的美餐安排，记 hedonism，享乐主义。","kind":"invented_association","weak":false,"original":true}]},"6212":{"word":"hegemony","mnemonics":[{"method":"HEGEMONY / 黑客命你，网络规则全由他定","textZh":"把 hegemony 的声音联到“黑客命你”：想象一名黑客控制了整片网络，别人要开网站、传文件，都得听他的指令，否则就被断开连接。用“一人定规则，其他人只能服从”的情形，记 hegemony，霸权、支配地位。","kind":"invented_association","weak":false,"original":true},{"method":"HEGEMONY / HE + GERMANY，称霸欧洲的野心","textZh":"把 hegemony 的整体形音联到 he（他）和 Germany（德国）：想起二战时期的希特勒，他企图让纳粹德国控制整个欧洲，其他国家都得服从。由一个政权企图让众国听命，记 hegemony，霸权、支配地位。","kind":"invented_association","weak":false,"original":true}]},"6213":{"word":"heinous","mnemonics":[{"method":"HEINOUS ↔ HATE，让人痛恨的恶行","textZh":"heinous 与 hate（憎恨）有词源联系。想到有人故意伤害无辜者，所有人都愤怒地说“I hate this!”：这里不是小讨厌，而是因罪行极其邪恶而痛恨。由此记住十恶不赦的。","kind":"word_family","weak":false,"original":true},{"method":"HEIN- / 害人，恶到令人发指","textZh":"把 hein- 的声音联到“害人”，再接形容词结尾 -ous：想象有人为了报复，故意放火烧掉别人的家。用这种害人至深、令人发指的恶行，记住 heinous。","kind":"invented_association","weak":false,"original":true}]},"6214":{"word":"heresy","mnemonics":[{"method":"HERESY ↔ HER SAY，只有她提出另一种说法","textZh":"把 heresy 的字形联到 her（她的）和 say（说）：大家坚持“好工作必须坐办公室”，她却主张在家也能做好工作。用她与公认观念唱反调的说法，记住 heresy 的异端、非正统观点义。","kind":"invented_association","weak":false,"original":true},{"method":"HERESY ↔ HERE, SEE!，看这里，旧信念不对","textZh":"把 heresy 的字形和声音联到“Here, see!”（看这里）：大家都相信太阳绕地球转，一个人指着观测结果说“看这里！”提出相反主张。用挑战既有信念、被当成异端的观点记住 heresy。","kind":"invented_association","weak":false,"original":true}]},"6215":{"word":"heretical","mnemonics":[{"method":"HER ARTICLE，她的文章挑战旧信条","textZh":"把 heretical 的整体读音联到 her article（她的文章）：别人坚信地球是宇宙中心，她的文章却说地球绕太阳转。这篇挑战公认信条的文章，被当时的守旧者视为 heretical。","kind":"invented_association","weak":true,"original":true},{"method":"HERE，TICK ALL：这里的神，全选","textZh":"把 heretical 联到 here、tick、all（这里、打勾、全部）：一张要求只信一位神的信仰表，她却在这里把所有神都打了勾。违反该教派的正统信条，就会被指为 heretical。","kind":"invented_association","weak":true,"original":true}]},"6216":{"word":"hermetic","mnemonics":[{"method":"HER MAGIC，她的神秘咒文","textZh":"把 hermetic 的整体声音联到 her magic（她的魔法）。她写下的咒文满是奇怪符号，外人翻了几遍仍弄不懂：由她那难以解读的 magic，记住深奥难懂的 hermetic。","kind":"invented_association","weak":false,"original":true},{"method":"HER MATH，她写的高深数学","textZh":"看到 hermetic，联到 her math（她的数学）：她在黑板上写出一整套高深证明，普通读者看不明白。用“她那套看不懂的 math”记住 hermetic，晦涩深奥的。","kind":"invented_association","weak":false,"original":true}]},"6217":{"word":"hie","mnemonics":[{"method":"HIE ↔ HI，招呼只说一声","textZh":"hie 和 hi（嗨）同音。想象你急着赶车，迎面碰到朋友，只来得及喊一声 hi，脚下不停就跑远了：记住 hie，匆匆赶去。","kind":"invented_association","weak":false,"original":true},{"method":"HIE ↔ HIDE，赶快躲起来","textZh":"把 hie 的字形联到熟悉的 hide（躲藏）：捉迷藏时，听见朋友快数完了，你立刻朝藏身处赶去。用‘赶快去躲’记住 hie：疾行、赶去。","kind":"invented_association","weak":false,"original":true}]},"6218":{"word":"humbug","mnemonics":[{"method":"HUMBUG ↔ HAMBURGER，假汉堡卖家","textZh":"把 humbug 的样子联到 hamburger（汉堡）：小贩把两块面包夹纸板，冒充牛肉汉堡卖给你。记住这个拿假汉堡骗人的 humbug，骗子。","kind":"invented_association","weak":false,"original":true},{"method":"HUM + BUG，哼着歌遮住漏洞","textZh":"把 humbug 分成 hum（哼唱）和熟悉的 bug（漏洞）。骗子推销时哼着轻快的小曲，装得若无其事，却用手遮住产品上的大 bug。哼唱掩盖破绽的，是个虚伪的骗子。","kind":"invented_association","weak":false,"original":true}]},"6219":{"word":"hilarious","mnemonics":[{"method":"HILARIOUS / 嘿，乐死！","textZh":"把 hilarious 的声音联到“嘿，乐死！”：朋友模仿老师一本正经的口吻，却说出离谱的笑话，你笑得直拍桌子：“嘿，乐死我了！”记住非常好笑的。","kind":"invented_association","weak":false,"original":true},{"method":"HILARIOUS ↔ HE LAUGHS，他笑个不停","textZh":"把 hilarious 的前半声音联到 he laughs（他笑了），词尾接上常见的形容词尾 -ous。电视里的小品让他笑得停不下来：能让人如此大笑的，就是 hilarious。","kind":"invented_association","weak":false,"original":true}]},"6220":{"word":"hive","mnemonics":[{"method":"HIVE ↔ FIVE，五个窗口全开工","textZh":"hive 和 five（五）只差开头一个字母，读音也相近。想象邮局五个窗口全开：这边收件，那边打包，工作人员来回穿梭。用忙个不停的 five 个窗口，记住 hive，忙碌之地。","kind":"invented_association","weak":false,"original":true},{"method":"HIVE ↔ LIVE，直播间忙开了","textZh":"hive 和 live（直播）只差首字母。把画面拉到直播间幕后：主播介绍商品，助手递货，客服不停回复。一个小小的 live 直播间，成了忙碌的 hive。","kind":"invented_association","weak":false,"original":true}]}});
